/** Re-read the viewport palette from CSS tokens (keeps 3D in sync with theme). */
function syncColorsFromCss() {
    if (typeof getComputedStyle !== 'function') return;
    const css = getComputedStyle(document.documentElement);
    const hex = (name, fallback) => {
        const raw = (css.getPropertyValue(name) || '').trim();
        if (!raw) return fallback;
        const m = raw.match(/^#([0-9a-f]{6})$/i);
        return m ? parseInt(m[1], 16) : fallback;
    };
    colors.bg     = hex('--viewport-bg', colors.bg);
    colors.line   = hex('--brand',       colors.line);
    colors.point  = hex('--brand',       colors.point);
    colors.z      = hex('--brand',       colors.z);
    colors.y      = hex('--ok',          colors.y);
    colors.x      = hex('--danger',      colors.x);
    colors.start  = hex('--warning',     colors.start);
    colors.selected = colors.start;
}
