function initSidebarResize() {
    const minSidebarWidth = 320;
    const maxSidebarWidth = 760;
    const saved = Number(localStorage.getItem('cleaningPathEditor.sidebarWidth'));
    if (Number.isFinite(saved) && saved > 0) setSidebarWidth(saved);
    const handle = document.getElementById('sidebarResizeHandle');
    if (!handle) return;  // ribbon layout has no sidebar resize handle
    const start = event => { event.preventDefault(); state.draggingSidebar = true; handle.classList.add('dragging'); document.body.classList.add('resizing'); };
    const move = event => { if (state.draggingSidebar) setSidebarWidth(event.clientX); };
    const stop = () => { state.draggingSidebar = false; handle.classList.remove('dragging'); document.body.classList.remove('resizing'); };
    function setSidebarWidth(width) {
        const maxWidth = Math.min(maxSidebarWidth, Math.max(minSidebarWidth, window.innerWidth - 420));
        const clamped = clamp(width, minSidebarWidth, maxWidth);
        document.documentElement.style.setProperty('--sidebar-width', `${clamped}px`);
        localStorage.setItem('cleaningPathEditor.sidebarWidth', String(clamped));
        onResize();
    }
    handle.addEventListener('pointerdown', start);
    window.addEventListener('pointermove', move);
    window.addEventListener('pointerup', stop);
    window.addEventListener('pointercancel', stop);
}

// Unified transport controls: DAC and Schedule share ONE markup template so
// the two playback UIs can never drift apart. Per-tab IDs are preserved, so
// the existing wiring (scheduleInit / dacInit) is untouched.
function renderPlaybackBlock(containerId, ids, labels) {
    const container = document.getElementById(containerId);
    if (!container || container.childElementCount) return;
    // Optional per-instance extra: a play-one button (Schedule uses it to play
    // only the selected step; DAC has no equivalent and passes no id).
    const playOne = ids.playStep
        ? `<button id="${ids.playStep}" disabled title="${labels.playStepTip}">${labels.playStep}</button>` : '';
    container.innerHTML = `
        <div class="button-row">
            <button id="${ids.play}" disabled>${labels.play}</button>
            ${playOne}
            <button id="${ids.stop}" disabled>■ Stop</button>
            <button id="${ids.prev}" disabled title="${labels.prevTip}">${labels.prev}</button>
            <button id="${ids.next}" disabled title="${labels.nextTip}">${labels.next}</button>
        </div>
        <input id="${ids.slider}" type="range" min="0" max="0" value="0" step="1" disabled>
        <div id="${ids.info}" class="dac-frame"><span>${labels.frame}</span> <code>${labels.hint}</code></div>`;
}

// ── Bootstrap wiring (row 32) ──────────────────────────────────────────────
// `initUi` was 133 lines and ~90 bindings inside ONE try/catch step, and ~65 of
// those dereferenced `document.getElementById(...)` without a guard. A single
// renamed or deleted id threw on the spot and abandoned everything after it:
// the dropzone, all 11 visibility toggles, the keyboard shortcuts, both docks,
// the tooltips and the command palette — with one status line as the only
// signal, on a page that otherwise looked completely normal.
//
// Two changes. `bind()` makes a missing id a reported fact rather than a
// crash, and the wiring is split into eight named steps that fail
// independently through the same runner the top-level bootstrap uses.

const missingIds = [];

// Bind a listener by element id. A missing id is COLLECTED, not thrown: one
// dead control must not cost you the other 89.
function bind(id, event, handler, options) {
    const el = document.getElementById(id);
    if (!el) { missingIds.push(id); return null; }
    el.addEventListener(event, handler, options);
    return el;
}

// For the handful of elements needed as objects rather than as an event
// target. Same reporting, same non-throwing contract.
function need(id) {
    const el = document.getElementById(id);
    if (!el) missingIds.push(id);
    return el;
}

// Run named steps in isolation, reporting the ones that failed. Shared with
// the top-level bootstrap at the end of this file so both report identically.
function runSteps(steps, label) {
    const failed = [];
    steps.forEach(([name, fn]) => {
        try { fn(); }
        catch (error) {
            failed.push(name);
            console.error(`[ALIX Studio] ${label} step "${name}" failed:`, error);
        }
    });
    return failed;
}

