function initUi() {
    missingIds.length = 0;
    const failed = runSteps([
        ['playback and modes', wirePlaybackAndModes],
        ['edit actions', wireEditActions],
        ['IK calibration', wireIkCalibration],
        ['region painting', wireRegionPainting],
        ['file actions', wireFileActions],
        ['overlays', wireOverlays],
        ['poses and gates', wirePosesAndGates],
        ['shell and chrome', wireShellAndChrome],
        ['generate path', wireGeneratePath],
    ], 'initUi');
    // Say it once, naming everything — rather than 90 separate console throws,
    // or the silence that a guarded-but-unreported lookup would give you.
    if (missingIds.length) {
        console.warn('[ALIX Studio] controls not found in the DOM:', missingIds.join(', '));
    }
    if (failed.length || missingIds.length) {
        const parts = [];
        if (failed.length) parts.push(`wiring failed: ${failed.join(', ')}`);
        if (missingIds.length) parts.push(`${missingIds.length} control(s) missing: ${missingIds.slice(0, 6).join(', ')}${missingIds.length > 6 ? '…' : ''}`);
        try { setStatus(`UI setup incomplete — ${parts.join('; ')} (see console).`, true); } catch (_) {}
    }
}

// ---------------------------------------------------------------------------
// Server mode (ALIX Studio): when served by alix_taskgen.server,
// the Generate panel + Validate/Deploy come alive so the whole workflow lives
// in the GUI. When opened as a static file these endpoints are absent and the
// editor stays a viewer/editor only.
// ---------------------------------------------------------------------------
const studio = {enabled: false, fixtures: [], regions: [], arm: 'right', lastTask: null};

async function api(path, options) {
    const response = await fetch(path, options);
    const data = await response.json();
    // The {error, hint} convention: an expected refusal comes back as HTTP 200
    // with both keys, and the hint is the half that says what to do about it.
    // Dropping it here turned "declare cleaning_line_speed_mps; every radius
    // derived from the 0.45 default is fictional" into a bare error string.
    if (!response.ok || data.error) {
        const failure = new Error(data.error || `HTTP ${response.status}`);
        failure.hint = data.hint || null;
        failure.payload = data;
        failure.busy = Boolean(data.generationBusy);
        if (failure.busy) watchGenerationBusy(data);
        throw failure;
    }
    return data;
}

// ── The one busy contract (server `ROUTE_NEEDS` / `_busy_contract`) ──────────
// While a generation runs, every task-config read and write in the server is
// refused (the guard is process-wide). Every route now answers that the same
// way — `generationBusy`, the holder, `pollUrl` — so the page answers it the
// same way too: one status line naming what holds the configs, one poll of
// /api/session, and one resume when it frees. The board's own cell/table
// messages stay; this is the part no individual caller should re-implement.
const generationBusyWatch = { timer: null, owner: null };

function watchGenerationBusy(payload) {
    const owner = payload.owner && payload.owner.label ? payload.owner.label : 'a generation';
    generationBusyWatch.owner = owner;
    setStatus(`Paused: ${owner} owns the task configs — reads resume when it finishes.`);
    if (generationBusyWatch.timer) return;
    const poll = async () => {
        let session = null;
        try {
            // Plain fetch, not api(): a failure here must not re-enter this watcher.
            session = await (await fetch(payload.pollUrl || '/api/session')).json();
        } catch (e) {
            session = null;
        }
        if (session && session.generation && !session.generation.busy) {
            generationBusyWatch.timer = null;
            setStatus(`${generationBusyWatch.owner} finished — task configs are readable again.`);
            if (document.body.dataset.tab === 'board' && typeof loadBoard === 'function') loadBoard();
            return;
        }
        generationBusyWatch.timer = setTimeout(poll, 3000);
    };
    generationBusyWatch.timer = setTimeout(poll, 3000);
}

// Fixture <select> options grouped by category (commode, urinal, …) so multiple
// fixture families are clearly separated.
function buildFixtureOptions(fixtures) {
    const byCat = {};
    (fixtures || []).forEach(f => { (byCat[f.category || 'other'] = byCat[f.category || 'other'] || []).push(f); });
    return Object.keys(byCat).sort().map(cat =>
        `<optgroup label="${cat}">`
        + byCat[cat].map(f => `<option value="${f.name}">${f.name}</option>`).join('')
        + '</optgroup>').join('');
}

async function initStudioServer() {
    // Only probe for the API when served over http(s); a static file:// page
    // has no server, and fetching would log a console error.
    const showViewerHint = () => { const h = document.getElementById('generateModeHint'); if (h) h.style.display = ''; };
    if (!String(location.protocol).startsWith('http')) { showViewerHint(); return; }
    let fixtures;
    try {
        fixtures = (await api('/api/fixtures')).fixtures;
    } catch (error) {
        showViewerHint();
        return; // served, but API absent — stay in viewer/editor mode
    }
    studio.enabled = true;
    studio.fixtures = fixtures;
    document.getElementById('generatePanel').style.display = '';
    const badge = document.getElementById('modeBadge');
    badge.textContent = 'Generator (server)';
    badge.title = 'Generator mode: served by alix-studio. The Generate Task panel + Validate/Deploy are active.';
    const finishPanel = document.getElementById('finishPanel');
    if (finishPanel) finishPanel.style.display = '';
    document.getElementById('finishValidateButton')?.addEventListener('click', validateFromServer);
    document.getElementById('finishDeployButton')?.addEventListener('click', deployToConfig);
    const fixtureOptions = buildFixtureOptions(fixtures);
    const fixtureSelect = document.getElementById('genFixture');
    fixtureSelect.innerHTML = fixtureOptions;
    fixtureSelect.addEventListener('change', async () => {
        // Generate's picker changes THE fixture, not just its own view of it.
        if (!(await setFixture(fixtureSelect.value, { loadMeshes: false }))) return;
    });
    fetchMechOps();
    document.getElementById('genRegion').addEventListener('change', updateGenStandoffPlaceholder);
    // Binding a target changes what the panel should be SHOWING — the empty
    // states, the dimming, and whether TARGET folds so the start pose is next.
    // The renderer existed and simply was not called here, so the panel kept
    // its unbound face after the operator had bound one.
    ['genRegion', 'genFixture'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.addEventListener('change', () => {
            // THE REGION GENERATE WILL RUN IS THE TASK. Generate reads this
            // select, and the strip, the destination and Deploy read
            // `state.task` — so a change here that did not rebind left them
            // naming different regions. MEASURED on Newton's 2026-09-15 runs:
            // the strip said bowl_inside_back while the run (ledger rows
            // d38b947af618 / a79878ef26fe) generated side. With a file open this
            // is an EDIT session and the strip names the file; Generate rebinds
            // after it closes it (generateFromServer).
            if (id === 'genRegion' && !state.config && el.value
                    && (!state.task || state.task.region !== el.value
                        || state.task.fixture !== currentFixture())) {
                bindTask(el.value, activeArm() || 'right', {silent: true});
            }
            genRenderEmptyStates();
            // BINDING A TARGET IS THE MOMENT THE SCENE IS KNOWN. It used to
            // appear only when *Pick on mesh* was pressed, so a bound region
            // showed an empty viewport — nothing to pick on, and no way to see
            // whether the target was the intended one.
            showTaskScene().catch(err => console.warn('[ALIX Studio] task scene:', err));
        });
    });
    document.getElementById('genUgvStandoff')?.addEventListener('change', updateGenStandoffPlaceholder);
    filterGenIkFrames();
    document.getElementById('genArmRight').addEventListener('click', () => setStudioArm('right'));
    document.getElementById('genArmLeft').addEventListener('click', () => setStudioArm('left'));
    document.getElementById('generateButton').addEventListener('click', generateFromServer);
    // wireGeneratePath ran inside initUi, which is BEFORE this function sets
    // studio.enabled — so the pipeline switch read "no server", disabled
    // Auto-generate and told the operator it was running the legacy raster.
    // Re-resolve it now that the server is known to be there.
    genRefreshPanel();

    // Default to the first fixture that has a region manifest / paintable
    // meshes (others, e.g. commode_a, use a different mesh layout).
    const defaultFixture = (fixtures.find(f => f.hasRegions) || fixtures[0] || {}).name;
    // Regions tab gets its own fixture selector so component meshes can be
    // loaded and painted before any task is generated (regions come first).
    const paintFixture = document.getElementById('paintFixture');
    paintFixture.innerHTML = fixtureOptions;
    paintFixture.style.display = '';
    paintFixture.dataset.prev = paintFixture.value || '';
    paintFixture.addEventListener('change', async () => {
        if (!(await setFixture(paintFixture.value))) {   // kept unsaved paint
            paintFixture.value = paintFixture.dataset.prev || state.fixture;
            return;
        }
        paintFixture.dataset.prev = paintFixture.value;
    });
    if (defaultFixture) syncFixtureSelectors(defaultFixture);   // seeds state.fixture

    await loadStudioRegions();
    if (state.activeTab === 'regions' && defaultFixture) await loadFixtureForRegions(defaultFixture);
    try {
        const saved = (await api('/api/ik-frames')).ikFrames || {};
        Object.entries(saved).forEach(([name, frame]) => { ikFrames[name] = frame; });
        if (Object.keys(ikFrames).length) { activeIkFrameName = Object.keys(ikFrames)[0]; updateIkPanel(); }
    } catch (error) { /* no saved frames yet */ }
    try {
        gloveFramesData = await api('/api/glove-frames');   // gizmo footprint source of truth
        buildGizmo();                                       // refresh with correct footprint
        renderHandStates();   // hand_state lives in the same payload; nothing to show before it lands
        populateReachFrames();                              // workspace IK-frame selector
    } catch (error) { /* fall back to defaults */ }
}

function setStudioArm(arm) {
    studio.arm = arm;
    document.getElementById('genArmRight').classList.toggle('active', arm === 'right');
    document.getElementById('genArmLeft').classList.toggle('active', arm === 'left');
    // The BOUND TASK follows the toggle. Without this the breadcrumb kept
    // printing the old side while the panel showed the new one, and everything
    // reading `state.task.arm` stayed on the arm just switched away from.
    if (state.task && state.task.arm !== arm) {
        state.task.arm = arm;
        if (typeof renderTaskHeader === 'function') renderTaskHeader();
        if (typeof refreshTaskDestination === 'function') refreshTaskDestination();
    }
    filterGenIkFrames();   // only the selected arm's glove frames stay selectable
    renderHandStates();    // the arm decides WHICH frame the viewer's base name means
    syncViewerToTask({quiet: true});   // pole + frame follow the side too
    buildStartPoseMarker();            // and so do the gizmos
}

// Keep the Generate and Regions fixture pickers in sync so the same fixture is
// selected whichever tab you are on.
// ── the current fixture ────────────────────────────────────────────────────
// Read through currentFixture(), never straight off a <select>. The selects
// are VIEWS of state.fixture; setFixture is the only writer.
function currentFixture() {
    if (state.fixture) return state.fixture;
    // Migration fallback for the first read before any select is populated.
    return (document.getElementById('genFixture') || {}).value
        || (document.getElementById('paintFixture') || {}).value
        || '';
}

function fixtureSelects() {
    return ['genFixture', 'paintFixture', 'schFixture']
        .map(id => document.getElementById(id)).filter(Boolean);
}

// Set the fixture and bring every view of it into line. Returns false when the
// change was refused (unsaved paint the operator chose to keep), so callers can
// roll their control back.
async function setFixture(name, opts = {}) {
    if (!name || name === state.fixture) { syncFixtureSelectors(name || state.fixture); return true; }
    if (opts.loadMeshes !== false) {
        const loaded = await loadFixtureForRegions(name);
        if (loaded === false) { syncFixtureSelectors(state.fixture); return false; }
    }
    state.fixture = name;
    syncFixtureSelectors(name);
    await loadStudioRegions();
    fetchMechOps();               // fixture-scoped mechanism ops
    schSetStatus('Fixture changed — click Load Schedule.');
    renderTaskHeader();           // the strip crumb names the fixture — it was
                                  // showing the boot fixture after a change here
    return true;
}

function syncFixtureSelectors(fixture) {
    if (!fixture) return;
    state.fixture = fixture;
    // All THREE, including Schedule — it was omitted, which is how the tab
    // could load a schedule for a different fixture than the one on screen.
    fixtureSelects().forEach(sel => {
        if (sel.value !== fixture && [...sel.options].some(o => o.value === fixture)) {
            sel.value = fixture;
        }
    });
}

// Unsaved paint strokes are destroyed when a new manifest loads
// (applyServerManifest resets paintState) — never silently.
function confirmDiscardPaintEdits() {
    if (!paintDirty()) return true;
    return window.confirm(
        'You have unsaved painted regions (not yet exported to OBJ/regions.yaml). '
        + 'Loading another fixture discards them. Continue?');
}

async function loadFixtureForRegions(fixture) {
    if (!fixture) return false;
    if (!confirmDiscardPaintEdits()) return false;
    try {
        setLoading(true, `Loading ${fixture} meshes…`);
        const result = await api(`/api/manifest?fixture=${encodeURIComponent(fixture)}`);
        applyServerManifest(result.manifest);
        if (state.activeTab === 'regions' && canUseMode('paint')) setMode('paint');
        else updatePaintPanel();
        setStatus(`${fixture} meshes loaded — pick a component and brush regions.`);
    } catch (error) {
        setStatus(`Failed to load ${fixture} meshes: ${error.message}`, true);
    } finally {
        setLoading(false);
    }
}

async function loadStudioRegions() {
    const fixture = currentFixture();
    let regions;
    try {
        regions = (await api(`/api/regions?fixture=${encodeURIComponent(fixture)}`)).regions;
    } catch (error) {
        setStatus(`Failed to list regions: ${error.message}`, true);
        return;
    }
    // A STALE answer: the fixture changed while this request was out. Applying
    // it put the previous fixture's regions under the new one (measured in the
    // headless run: commode_c bound, crumb showing commode_a's `commode_front`).
    if (currentFixture() !== fixture) return;
    studio.regions = regions;
    // Keep the BOUND task's region selected. Re-rendering reset the select to
    // its first option, and Generate reads the select — so a region list that
    // arrived after the task was bound made the next Generate run a different
    // region from the one the breadcrumb named.
    renderGenRegionOptions(state.task && state.task.fixture === fixture ? state.task.region : undefined);
    renderCombineList();   // keep the Combine popover's choices current
}

function renderGenRegionOptions(keepKey) {
    const select = document.getElementById('genRegion');
    select.innerHTML = (studio.regions || []).map(r => {
        const comps = r.components || [r.component];
        const compTag = comps.length > 1 ? ` • ${comps.join('+')}` : '';
        const openParts = Object.entries(r.states || {}).filter(([, s]) => s !== 'closed').map(([p]) => p);
        const stateTag = openParts.length ? ` • ${openParts.join('+')} open`
            : (r.seatState === 'open' ? ' • lid+seat open' : (r.lidState === 'open' ? ' • lid open' : ''));
        // The server has always shipped `provenance` per region and the client
        // has never read it, so the only cue that a row's surface was GUESSED
        // rather than painted was the ABSENCE of " • labeled" — in an
        // alphabetically interleaved list, which is no cue at all. Say it.
        const guessTag = (r.provenance && r.provenance !== 'labeled') ? ' • guessed' : '';
        return `<option value="${r.key}">${r.key} — ${r.armCoverage}${compTag}${stateTag}${r.labeled ? ' • labeled' : ''}${guessTag}</option>`;
    }).join('');
    if (keepKey && (studio.regions || []).some(r => r.key === keepKey)) select.value = keepKey;
    updateGenStandoffPlaceholder();
}

// The Generate tab's Standoff field placeholder shows what (auto) resolves to:
// the selected region's declared authoring default, else the fleet default.
// Also re-poses any displayed pick-on-mesh surface to the effective standoff,
// so the preview (and the start pose picked on it) matches the task.
function updateGenStandoffPlaceholder() {
    const input = document.getElementById('genUgvStandoff');
    if (!input) return;
    const key = document.getElementById('genRegion')?.value;
    const spec = (studio.regions || []).find(r => r.key === key);
    const fallback = viewerManifest?.defaultUgvStandoffM ?? 0.25;
    const value = spec?.ugvStandoffM ?? fallback;
    input.placeholder = `(auto: ${Number(value).toFixed(3)})`;
    if (!state.config && meshObject) {   // Generate preview only — loaded tasks follow their stamped value
        applyMeshPlacementMode();
        rebuildCompanionMeshes();
        renderScene();
    }
}

// Only the selected arm's glove frames are offered in the Generate tab —
// an R_ frame in a left task (or vice versa) is always a mistake.
function filterGenIkFrames() {
    const sel = document.getElementById('genIkFrame');
    if (!sel) return;
    const prefix = armPrefix();          // the ONE side authority, not studio.arm alone
    [...sel.options].forEach(option => {
        if (!option.value) return;                       // (auto) always available
        const matches = option.value.startsWith(prefix);
        option.hidden = !matches;
        option.disabled = !matches;
    });
    // ...and the OPTGROUPS. Hiding the options left their group LABELS behind,
    // so a Left task still listed "Right - glove pads", "Right - fingertips" and
    // "Right - no tool" as headers with nothing under them (Newton's screencast,
    // 2026-09-10). An empty group heading is not a smaller offer, it is the same
    // offer with the items removed - it reads as a list that failed to load.
    [...sel.querySelectorAll('optgroup')].forEach(group => {
        const live = [...group.querySelectorAll('option')].some(o => !o.hidden);
        group.hidden = !live;
        group.disabled = !live;
    });
    if (sel.value && !sel.value.startsWith(prefix)) sel.value = '';   // reset to (auto)
}

async function generateFromServer() {
    const region = document.getElementById('genRegion').value;
    // Generate replaces the scene: applyServerManifest() clears paintState.regions
    // and loadYamlText() clears the undo stack. Neither asked. Paint region B,
    // switch to tab 2 to generate region A, and B's strokes are gone with no
    // trace and no undo. The two guards below already existed and were simply
    // never called from here — loadFixtureForRegions and loadMechExemplar both
    // use them.
    if (!confirmDiscardPaintEdits()) return;
    // An open file is a different session: it is closed (Save / Discard) before a
    // generation starts, never silently replaced (Newton, 2026-09-15).
    if (!(await requireGenerateSession('generate'))) return;
    // The task IS what runs: the strip, the destination and Deploy name the
    // region this request carries, never the one a Board click bound earlier.
    if (region && (!state.task || state.task.region !== region
                   || state.task.fixture !== currentFixture())) {
        bindTask(region, activeArm() || 'right', {silent: true});
    }
    // Standoff is the one field the panel sanity-checks itself: METRES, not
    // millimetres. The check used to live on the legacy raster branch only, so
    // a 380 that meant 0.380 reached the C-space pipeline unchallenged — the
    // request body is built by `autoPathRequestBody`, which forwards the field
    // verbatim. Everything else the panel sends is validated server-side
    // against `_POLICY_VALUE_RULES` before a runId is minted.
    const ugvStandoff = document.getElementById('genUgvStandoff')?.value;
    if (ugvStandoff !== '' && ugvStandoff !== undefined && ugvStandoff !== null) {
        const standoff = Number(ugvStandoff);
        const soMin = viewerManifest?.constants?.ugvStandoffMinM ?? 0.25;
        const soMax = viewerManifest?.constants?.ugvStandoffMaxM ?? 2.0;
        if (!(standoff >= soMin && standoff <= soMax)) {   // metres sanity — catches mm slips (380 → 0.38); floor = the 250 mm fleet rule
            setStatus(`Standoff must be in METRES between ${soMin} and ${soMax} (got ${ugvStandoff}`
                + (standoff > 2 ? ` — did you mean ${(standoff / 1000).toFixed(3)}?)` : ')'), true);
            return;
        }
    }
    // Generation is a SINGLE in-process job on a threaded server, and a
    // pathological region takes ~13 minutes. Nothing disabled the button, so a
    // second click started a second generation alongside the first and the two
    // crashed the process — setLoading only toggles a spinner class, which is
    // not a lock. Disabling for the duration is the cheapest change that
    // removes the trigger.
    const generateBtn = document.getElementById('generateButton');
    let elapsedTimer = null;
    try {
        if (generateBtn) generateBtn.disabled = true;
        const startedAt = Date.now();
        const runLabel = `Generating ${region} [${activeArm()}]`;
        setLoading(true, `${runLabel}…`);
        // …and SAY it is still running. A silent 13-minute request is
        // indistinguishable from a hang, which is what provoked the second
        // click in the first place; a ticking clock is the difference between
        // "slow" and "dead".
        elapsedTimer = setInterval(() => {
            const secs = Math.round((Date.now() - startedAt) / 1000);
            setStatus(`${runLabel}… ${Math.floor(secs / 60)}:${String(secs % 60).padStart(2, '0')}`);
        }, 1000);
        // The C-space path pipeline runs as a BACKGROUND JOB — measured end to
        // end at 64-83 s over the commode_c regions that complete (2026-09-10)
        // — so it is started, polled and cancelled rather than awaited on one
        // socket; the server sets no protocol_version, so every response is
        // HTTP/1.0 with the connection closed and there is no request timeout
        // protecting a ten-minute socket.
        //
        // There is ONE pipeline behind this button now (Newton, 2026-09-16).
        // The legacy raster branch that used to live here — `/api/generate`,
        // chosen by a `#genPipelineNew` toggle — is gone from the panel: the
        // two generators sent disjoint bodies, so half the fields on screen
        // applied to whichever branch the toggle happened to be on. The route
        // and `server.do_generate` still exist for the Board's reference sweep
        // and for `/api/coverage`, which rebuilds the region surface with it.
        const run = await runAutoPathJob(autoPathRequestBody(region), runLabel);
        if (!run) return;                       // cancelled; runAutoPathJob said so
        adoptAutoPathRun(run);
        return;
    } catch (error) {
        // The HINT is the half of the {error, hint} convention that says what
        // to do about it, and it was being dropped exactly when it matters
        // most: every /api/auto-path VALIDATION refusal (unknown region,
        // unknown policy key, an out-of-band strokePasses, an unknown channel,
        // write:true) throws straight out of runAutoPathJob into this catch,
        // which never reached state 'failed' and so never reached
        // genSetFailure -- so the sentence that says WHICH knob was wrong was
        // discarded exactly when the operator needed it. The refusal this was
        // originally written for (Studio-D8, "declare cleaning_line_speed_mps")
        // no longer exists: Newton reversed it on 2026-09-07 (R7). The
        // mechanism stays, because the other refusals do.
        genReportRequestFailure(error);
        // The PANEL carries the account; the top bar carries a POINTER. Printing
        // the same paragraph in both put one failure on screen twice, and the
        // longer it was the more of the viewport it took — the operator read it
        // twice and learned nothing the second time. When the panel is not on
        // screen the bar still has to stand alone, so it keeps a first line.
        const oneLine = String(error.message || 'the request was refused')
            .replace(/\s+/g, ' ').trim();
        const brief = oneLine.length > 110 ? `${oneLine.slice(0, 108)}…` : oneLine;
        setStatus(`Generate failed: ${brief}${genPanelOnScreen() ? ' — full detail in the Generate panel.' : ''}`, true);
    } finally {
        // Unconditional and exception-safe: if the button stayed disabled after
        // a failure the whole panel would be dead until the page was reloaded,
        // which is a worse outcome than the double-click this guards against.
        clearInterval(elapsedTimer);
        if (generateBtn) generateBtn.disabled = false;
        setLoading(false);
    }
}

function applyServerManifest(manifest) {
    const hadConfig = Boolean(state.config) && state.points.length;
    // Dispose the OLD fixture's geometry BEFORE viewerManifest is reassigned —
    // disposal decisions must be judged by the fixture that built the meshes,
    // not the one replacing it (F75: commode_c lid/seat surviving a switch to
    // commode_a / urinal_a). companionGroup and the active surface belong to
    // the old fixture too; without a config to re-resolve they'd stack under
    // the new one the moment paint mode ends.
    disposePaintMesh();
    if (companionGroup) clearGroup(companionGroup);
    if (meshObject) {
        scene.remove(meshObject);
        disposeObject(meshObject);
        meshObject = null;
    }
    state.activeRegion = null;
    state.activeMeshKey = null;
    viewerManifest = manifest;
    renderFixturePartToggles();   // the part set may differ per fixture
    buildStaticReferenceFrames();
    if (washroomGroup) { clearGroup(washroomGroup); updateWallsVisibility(); }
    paintState.component = '';
    paintState.regions = [];
    paintState.activeRegion = -1;
    // If a config was already loaded (e.g. before the fixture meshes arrived),
    // re-resolve its mesh and re-place its points under the new manifest so the
    // surface, points and any coverage overlay stay in one consistent frame.
    if (hadConfig) {
        loadMeshForRegion(state.activeRegion || detectRegionKey(state.originalYamlText || '', state.fileName || ''));
        state.points = recoverPoints(state.config);
        updateAll();
        if (lastCoverage && document.getElementById('coveragePaintToggle')?.checked) renderCoveragePaint(lastCoverage);
    }
}

// --- Coverage & path optimality ---
// Coverage gate: the footer stat is judged against a >=95% target
// (green >=95, amber >=85, red below) so shortfalls read at a glance.
const COVERAGE_TARGET_PCT = viewerManifest?.constants?.coveragePassPct ?? 95;   // constants.py via the manifest (F73); fallback pinned by test_constants_contract
// THE REGION'S OWN TARGET ([N-11] RULED, Newton 2026-09-22; plan/P16 S4b): 95/85
// stay the default contract, and a config whose requirement block carries a
// target (provenance.stroke.requirements.coverageTarget, a FRACTION of the task:
// single = the arm's share = the whole region, paired = the union of both arms
// over the whole region; [N-1]: the hardware figure rounded down to 0.05) is
// judged against THAT. The amber band keeps the contract's margin under
// whichever target is in force (95 -> 85: 10 points). Advisory, like the
// contract: coverage refuses nothing ([N-9], R6).
function coverageTargetOf(cfg) {
    const reqs = cfg?.provenance?.stroke?.requirements;
    const t = reqs?.coverageTarget;
    const fallbackWarn = viewerManifest?.constants?.coverageWarnPct ?? 85;
    if (typeof t === 'number' && isFinite(t) && t > 0 && t <= 1) {
        const pct = Math.round(t * 1000) / 10;
        return {pct, warnPct: pct - (COVERAGE_TARGET_PCT - fallbackWarn), fromBlock: true,
                source: reqs.coverageTargetSource || null, citation: reqs.coverageTargetCitation || null,
                taskType: reqs.taskType || null};
    }
    return {pct: COVERAGE_TARGET_PCT, warnPct: null, fromBlock: false, source: null, citation: null, taskType: null};
}
// the target the LOADED config is judged against
function coverageTarget() { return coverageTargetOf(state.config); }
// one line for a tooltip: where the number came from
function coverageTargetNote(t) {
    if (!t.fromBlock) return `the default ${COVERAGE_TARGET_PCT}% contract (no requirement block on this config)`;
    const scope = t.taskType === 'paired' ? ' — a paired task\'s target is judged on the UNION of both arms' : '';
    return `the region's ${t.pct}% target (${t.source || 'requirement block'}${t.citation ? ': ' + t.citation : ''})${scope}`;
}
// WHAT A COVERAGE FIGURE MAY BE JUDGED AS ([N-1] + [N-11]; S4b fix pass 2026-09-23).
// The Studio's coverage_pct (server do_coverage, the board arm cell) is ONE ARM'S
// SHARE of the region (`half_ref`), and a PAIRED task's coverageTarget is a UNION
// figure (both arms over the whole region) -- not comparable: plan/P16 section 7's
// own pairs read "below" per share while their union meets (hinge L 0.765 vs 0.80
// with union 0.8248; lid_seat_hinge L 0.613 vs 0.65 with union 0.6588). So:
//   * no requirement block -> the 95/85 contract, as before ([N-11]);
//   * single / serial      -> the share IS the task: share vs target, as before;
//   * paired               -> NO met/not-met on the share. When the loaded config
//     carries the pair artefact's mirror block (provenance.stroke.coverage.pair)
//     and is unedited since load (the block's union was measured on these bytes),
//     that UNION is judged; otherwise the state is 'info' (neutral) and the text
//     says the target belongs to the pair's union (the Board's pair cell).
// Returns {state: 'pass'|'warn'|'info', met: true|false|null, judgedPct, scope:
// 'contract'|'task'|'union'|'share', text, note}. Advisory, like the contract ([N-9]).
function coverageVerdict(sharePct, t, cfg, opts = {}) {
    if (!t.fromBlock || t.taskType !== 'paired') {
        const met = sharePct >= t.pct;
        return {state: met ? 'pass' : 'warn', met, judgedPct: sharePct, scope: t.fromBlock ? 'task' : 'contract',
                text: met ? 'meets target' : 'below target', note: coverageTargetNote(t)};
    }
    const pair = cfg?.provenance?.stroke?.coverage?.pair;
    if (!opts.edited && pair && typeof pair.coveredFractionOfRegion === 'number') {
        const u = Math.round(pair.coveredFractionOfRegion * 1000) / 10;
        const met = typeof pair.meetsTarget === 'boolean' ? pair.meetsTarget : u >= t.pct;
        return {state: met ? 'pass' : 'warn', met, judgedPct: u, scope: 'union',
                text: `∪ ${u}% ${met ? 'meets' : 'below'} ${t.pct}%`,
                note: `the pair artefact's union ${u}% of the whole region vs ${coverageTargetNote(t)}`
                    + ` — recorded by ${pair.artefact || 'the pair step'} with the ${pair.partnerArm || 'partner'} config`
                    + ` ${String(pair.partnerConfigSha256 || '').slice(0, 12)} (its freshness is the Board pair cell's);`
                    + ` this arm's share reads ${sharePct}%`};
    }
    return {state: 'info', met: null, judgedPct: null, scope: 'share', text: "this arm's share",
            note: `this arm's share ${sharePct}% — the ${t.pct}% target is the pair's UNION`
                + ` (see the region's pair cell on the Board)`
                + (pair && opts.edited ? '; the recorded union no longer describes the edited config' : '')};
}
function setCoverageStat(pct) {
    const stat = document.getElementById('statCoverage');
    if (!stat) return;
    stat.classList.remove('cov-good', 'cov-warn', 'cov-bad');
    stat.style.color = '';
    if (pct === null || pct === undefined) { stat.textContent = '--'; stat.title = ''; return; }
    stat.textContent = `${pct}%`;
    const t = coverageTarget();
    const v = coverageVerdict(pct, t, state.config, {edited: state.dirty});
    if (v.state === 'info') { stat.title = `Coverage ${v.note}`; return; }   // neutral: no colour verdict on a share
    const judged = v.judgedPct;
    stat.classList.add(judged >= t.pct ? 'cov-good' : judged >= (t.warnPct ?? viewerManifest?.constants?.coverageWarnPct ?? 85) ? 'cov-warn' : 'cov-bad');
    stat.title = `Coverage target ≥${t.pct}% — ${v.met ? 'met' : 'NOT met'} (${v.note})`;
}

function renderCoverage(report) {
    lastCoverage = report || null;
    renderGates();
    if (!report) {
        setCoverageStat(null);
        ['coverageInfo', 'genCoverageInfo'].forEach(id => { const el = document.getElementById(id); if (el) el.innerHTML = ''; });
        clearCoveragePaint();
        return;
    }
    setCoverageStat(report.coverage_pct);
    // The headline the approved frame leads with: the number at a size you can
    // read across a desk, the target it is judged against, and a bar whose
    // marker is the 95% gate — so "how far off am I" is a glance, not a
    // subtraction. State is carried by the word AND the colour, never colour
    // alone (~8% of a male-skewed operator population is red-green deficient).
    const pct = report.coverage_pct;
    const tgt = coverageTarget();            // [N-11]: the region's target when the config carries one
    const covVerdict = coverageVerdict(pct, tgt, state.config, {edited: state.dirty});   // [N-1]: a paired target is the union's
    const pill = covVerdict.state === 'info' ? 'ⓘ this arm\'s share — target is the union'
        : covVerdict.scope === 'union' ? `${covVerdict.met ? '✓' : '!'} ${covVerdict.text}`
        : covVerdict.met ? '✓ meets target' : '! below target';
    const headline =
        `<div class="cov-head" data-state="${covVerdict.state}" title="${escapeHtml(covVerdict.note)}">`
      + `<div class="cov-top"><span class="cov-pct">${pct}%</span>`
      + `<span class="cov-pill">${pill}</span></div>`
      + `<div class="cov-bar"><i style="width:${Math.max(0, Math.min(100, pct))}%"></i>`
      + `<b style="left:${tgt.pct}%"></b></div>`
      + `<div class="cov-scale"><span>0%</span><span>▲ ${tgt.pct}% ${tgt.fromBlock ? 'region target' : 'target'}</span></div>`
      + `</div>`;
    const rows = [
        ['Coverage', `${report.coverage_pct}% of region (${report.samples} samples)`],
        ['Region area', `${(report.region_area_m2 * 1e4).toFixed(0)} cm²`],
        ['Glove footprint', `${report.footprint_cm[0]} × ${report.footprint_cm[1]} cm`],
        ['Redundancy', `×${report.redundancy} (swept ${(report.swept_area_m2 * 1e4).toFixed(0)} cm²)`],
    ];
    // Passes per point (plan/P16 section 3): how many times the pad visited
    // each covered point of this arm's share, the seam it shares with the
    // partner arm reported apart. Display only — the target above is the
    // region's own when the config carries one, else the 95 contract ([N-11]);
    // nothing here judges the run.
    const pp = report.passesPerPoint;
    if (pp && pp.mean != null) {
        rows.push(['Passes per point',
            `${pp.mean} mean · p10 ${pp.p10} · p90 ${pp.p90} · min ${pp.min}`
            + ` · ${Math.round(pp.shareAtLeastTarget * 100)}% of covered points at ≥ ${report.passesTarget}`
            + (report.seamPassesMean != null ? ` · seam ${report.seamPassesMean} (${report.seamSamples} samples)` : '')]);
    }
    const passesNote = report.over_covered_passes
        ? ` ⚠ Over-passed: ${(report.overPassedShare * 100).toFixed(0)}% of the share is visited ≥ ${report.passesTarget + 2} times (passes rule, [N-7]).`
        : (pp && pp.mean != null ? ` Passes per point ${pp.mean} (p10 ${pp.p10}).` : '');
    const degenerate = report.redundancy > 20 || report.region_area_m2 < 0.001;
    const verdict = degenerate
        ? `⚠ Region mesh looks degenerate (area ${(report.region_area_m2 * 1e4).toFixed(1)} cm², redundancy ×${report.redundancy}). The labeled region may be (almost) un-painted — re-paint it in Region Labels. Coverage % is unreliable here.`
        : (report.coverage_pct >= 99
        ? (report.over_covered ? '⚠ Full coverage but over-covered — likely unnecessary/overlapping moves (redundancy > 1.25).' : '✓ Full coverage, efficient path.')
        : `△ ${(100 - report.coverage_pct).toFixed(1)}% of the region is not reached — add points or widen the path.`) + passesNote;
    const html = headline
        + rows.map(([k, v]) => `<div class="info-row"><span>${k}</span><code>${v}</code></div>`).join('')
        + `<div class="info-row"><span>Verdict</span><code>${verdict}</code></div>`;
    ['coverageInfo', 'genCoverageInfo'].forEach(id => { const el = document.getElementById(id); if (el) el.innerHTML = html; });
    // Refresh the coverage-paint overlay if it is currently enabled (honours the
    // current point selection for sequence-driven coverage).
    if (document.getElementById('coveragePaintToggle')?.checked) refreshCoveragePaint();
}

// Coverage-paint overlay: a point cloud over the region surface, green where the
// glove path covers it and red where it is missed — a visual span of the
// cleaning sequence's reach. Sample points come from the coverage report in
// ref-frame coordinates; map them to base frame for the scene.
function clearCoveragePaint() {
    if (!coverageGroup) return;
    clearGroup(coverageGroup);
    coverageGroup.visible = false;
}

// Sequence step to show coverage up to: the selected point's position in the
// cleaning sequence, or the last point when nothing is selected (full path).
function coverageStepForSelection(report) {
    const order = report?.order;
    if (!order || !order.length) return Infinity;          // no sequence info -> full
    if (state.selectedIndex < 0) return order.length - 1;   // none selected -> last point
    const name = state.points[state.selectedIndex]?.name;
    const k = name ? order.indexOf(name) : -1;
    return k >= 0 ? k : order.length - 1;
}

function renderCoveragePaint(report, uptoStep) {
    if (!coverageGroup) return;
    clearGroup(coverageGroup);
    const pts = report?.samplePoints;
    const steps = report?.sampleCoveredStep;
    const cov = report?.sampleCovered;
    if (!pts || !pts.length) { coverageGroup.visible = false; return; }
    if (uptoStep === undefined) uptoStep = coverageStepForSelection(report);
    const stepAware = Array.isArray(steps) && steps.length === pts.length;
    const positions = new Float32Array(pts.length * 3);
    const colorsArr = new Float32Array(pts.length * 3);
    for (let i = 0; i < pts.length; i++) {
        const base = refPointToBase(pts[i]);
        positions[i * 3] = base[0]; positions[i * 3 + 1] = base[1]; positions[i * 3 + 2] = base[2];
        // covered up to the chosen step = green (#3fb950), otherwise red (#f85149)
        const isCov = stepAware ? (steps[i] >= 0 && steps[i] <= uptoStep) : !!(cov && cov[i]);
        const c = isCov ? [0.247, 0.725, 0.314] : [0.973, 0.318, 0.286];
        colorsArr[i * 3] = c[0]; colorsArr[i * 3 + 1] = c[1]; colorsArr[i * 3 + 2] = c[2];
    }
    const geom = new THREE.BufferGeometry();
    geom.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geom.setAttribute('color', new THREE.BufferAttribute(colorsArr, 3));
    // Draw the overlay on top of the (opaque) surface mesh — depthTest off so the
    // dots aren't hidden behind the surface they sit on; high renderOrder so they
    // paint last.
    const material = new THREE.PointsMaterial({size: 0.009, vertexColors: true, sizeAttenuation: true, depthTest: false, depthWrite: false});
    const cloud = new THREE.Points(geom, material);
    cloud.renderOrder = 999;
    coverageGroup.add(cloud);
    coverageGroup.visible = true;
    renderScene();
}

// Re-render the coverage paint for the current selection (no server call) and
// reflect the selected point's cumulative coverage in the badge/status.
function refreshCoveragePaint() {
    if (!document.getElementById('coveragePaintToggle')?.checked) return;
    if (!lastCoverage || !lastCoverage.samplePoints) return;
    const step = coverageStepForSelection(lastCoverage);
    renderCoveragePaint(lastCoverage, step);

    const byStep = lastCoverage.coverageByStep;
    if (Array.isArray(byStep) && byStep.length && step !== Infinity && step >= 0 && step < byStep.length) {
        const pct = byStep[step];
        const name = lastCoverage.order?.[step];
        setCoverageStat(pct);
        setStatus(`Coverage up to ${name}: ${pct}% (full path ${lastCoverage.coverage_pct}%).`);
    }
}

// Aim the camera at the densest cluster of MISSED coverage samples (the
// largest gap), so a failing recompute lands the user on the work to do.
function focusLargestCoverageGap(report) {
    const pts = report?.samplePoints;
    if (!pts || !pts.length) return;
    const steps = report.sampleCoveredStep;
    const cov = report.sampleCovered;
    const stepAware = Array.isArray(steps) && steps.length === pts.length;
    const binSize = 0.04;
    const bins = new Map();
    for (let i = 0; i < pts.length; i++) {
        const covered = stepAware ? steps[i] >= 0 : !!(cov && cov[i]);
        if (covered) continue;
        const b = refPointToBase(pts[i]);
        const key = `${Math.round(b[0] / binSize)},${Math.round(b[1] / binSize)},${Math.round(b[2] / binSize)}`;
        const bin = bins.get(key) || {n: 0, x: 0, y: 0, z: 0};
        bin.n += 1; bin.x += b[0]; bin.y += b[1]; bin.z += b[2];
        bins.set(key, bin);
    }
    if (!bins.size) return;
    let best = null;
    for (const bin of bins.values()) if (!best || bin.n > best.n) best = bin;
    controls.target.set(best.x / best.n, best.y / best.n, best.z / best.n);
    controls.update();
    renderScene();
}

// ===== Workspace analysis overlays (reachability + safety zones) =============
// Server returns points in the reachability "root" frame, which for the example
// config coincides with base_link (the viewer's world frame), so they render
// directly with no extra transform.
const REACH_COLORS = {left: [0.25, 0.45, 1.0], right: [0.25, 0.85, 0.35], 'left&right': [0.0, 0.85, 1.0]};

function renderReachability(data) {
    if (!reachabilityGroup) return;
    clearGroup(reachabilityGroup);
    const chains = data?.chains || {};
    const res = data?.grid?.resolution_m || 0.05;
    for (const [name, pts] of Object.entries(chains)) {
        if (!pts || !pts.length) continue;
        const col = REACH_COLORS[name] || [0.85, 0.85, 0.2];
        const positions = new Float32Array(pts.length * 3);
        for (let i = 0; i < pts.length; i++) {
            positions[i * 3] = pts[i][0]; positions[i * 3 + 1] = pts[i][1]; positions[i * 3 + 2] = pts[i][2];
        }
        const geom = new THREE.BufferGeometry();
        geom.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        const material = new THREE.PointsMaterial({
            size: res * 0.6, color: new THREE.Color(col[0], col[1], col[2]),
            sizeAttenuation: true, transparent: true, opacity: name === 'left&right' ? 0.95 : 0.5,
        });
        reachabilityGroup.add(new THREE.Points(geom, material));
    }
    setReachabilityInfo(data);
    reachabilityGroup.visible = document.getElementById('reachabilityToggle')?.checked ?? true;
    renderScene();
}

// Venue walls from viewerManifest.washroom (placed server-side from
// washroom_scene.yaml's washroom_structure). depthWrite off so the shell
// never occludes the fixture/robot it encloses.
function buildWashroomWalls() {
    if (!washroomGroup) return;
    clearGroup(washroomGroup);
    const w = viewerManifest?.washroom;
    if (!w || !w.mesh) return;
    const opacity = parseFloat(document.getElementById('wallsOpacity')?.value || '0.5');
    const mesh = meshFromPayload(w.mesh, 0x8b949e, opacity);
    mesh.material.depthWrite = false;
    mesh.name = `washroom ${w.meshFile || ''}`;
    washroomGroup.add(mesh);
}

function updateWallsVisibility() {
    if (!washroomGroup) return;
    const on = document.getElementById('showWallsToggle')?.checked ?? false;
    if (on && !washroomGroup.children.length) buildWashroomWalls();
    if (on && !washroomGroup.children.length) {
        setStatus('No venue walls: washroom_scene.yaml has no resolvable washroom_structure mesh.', true);
    }
    washroomGroup.visible = on;
    renderScene();
}

function renderSafetyZones(zones) {
    if (!safetyZonesGroup) return;
    clearGroup(safetyZonesGroup);
    if (!zones) return;
    const colors = {stall_entry: STATE_COLOR.unreachable, human_retract: STATE_COLOR.orientBad,
                    caution: STATE_COLOR.zoneCaution,
                    base_exclusion: STATE_COLOR.zoneExclusion};
    for (const [name, r] of Object.entries(zones)) {
        if (!r) continue;
        const curve = new THREE.EllipseCurve(0, 0, r, r, 0, 2 * Math.PI);
        const pts = curve.getPoints(96).map(p => new THREE.Vector3(p.x, p.y, 0.005));
        const geom = new THREE.BufferGeometry().setFromPoints(pts);
        safetyZonesGroup.add(new THREE.LineLoop(geom, new THREE.LineBasicMaterial({color: colors[name] || 0xffffff})));
    }
    safetyZonesGroup.visible = document.getElementById('safetyZonesToggle')?.checked ?? true;
    renderScene();
}

function setReachabilityInfo(data) {
    const el = document.getElementById('reachabilityInfo');
    if (!el) return;
    const rows = [];
    for (const [name, pts] of Object.entries(data?.chains || {})) {
        rows.push(`<div class="info-row"><span>${name}</span><code>${pts.length} voxels</code></div>`);
    }
    if (data?.grid?.resolution_m) rows.push(`<div class="info-row"><span>voxel</span><code>${data.grid.resolution_m} m</code></div>`);
    el.innerHTML = rows.join('') || '<div class="info-row"><span>Reachability</span><code>no voxels</code></div>';
}

// ── The viewer follows the TASK, not the other way round ──────────────────
// The Browser's tool frame and pole drive the reach test, the robot overlay and
// the collision checks; the Generate panel's drive what is WRITTEN to the task.
// They were two independent stores that happened to agree, so a start pose could
// be picked, judged and shown against a hand and a pole the generated task will
// not use — and the hand is not incidental: the server derives the finger joints
// from the tool frame through `glove_frames.yaml` (`_hand_joint_values`), so a
// different frame is a different hand in the world the collision test runs in.
//
// One direction only, deliberately: the TASK is the intent and the viewer is the
// view of it. `(auto)` states nothing, so the viewer keeps whatever it had.
function syncViewerToTask(opts = {}) {
    // The two lists do not speak the same dialect. `genIkFrame` carries the
    // FULL name (`L_glove_frame_2`) because that is what is written to the
    // task; `reachFrameSelect` is populated by `populateReachFrames`, which
    // strips `R_`/`L_` so one entry serves both arms. Copying the value across
    // verbatim meant the `has` guard never matched and the frame sync did
    // NOTHING, silently — the pole moved and the frame did not. And the frame
    // is not cosmetic: the server derives the finger joints from it through
    // `glove_frames.yaml` (`_hand_joint_values`), so an unsynced frame is an
    // unsynced HAND, and the start pose was being judged against a hand the
    // generated task will not use.
    const pairs = [
        ['genIkFrame', 'reachFrameSelect', v => v.replace(/^[RL]_/, '')],
        ['genPoleState', 'poleStateSelect', v => v],
    ];
    const moved = [];
    pairs.forEach(([fromId, toId, toViewerDialect]) => {
        const from = document.getElementById(fromId);
        const to = document.getElementById(toId);
        if (!from || !to) return;
        const raw = (from.value || '').trim();
        if (!raw) return;                        // `(auto)`: the task states nothing
        const want = toViewerDialect(raw);
        // the viewer's list is the VIEWER's — only follow a value it actually has
        const has = Array.from(to.options || []).some(o => o.value === want);
        if (!has || to.value === want) return;
        to.value = want;
        to.dispatchEvent(new Event('change', {bubbles: true}));
        moved.push(`${toId} → ${want}`);
    });
    renderHandStates();
    if (moved.length && !opts.quiet) {
        setStatus(`Viewer follows the task: ${moved.join(', ')}.`);
    }
    return moved;
}

// The arm the viewer's frame belongs to. `reachFrameSelect` is arm-agnostic by
// construction, so the arm comes from whatever DID state one: the Generate
// panel's arm toggle first (it is the task's intent), then the loaded config's
// own ik_frame prefix.
function viewerArmPrefix() { return armPrefix(); }

// The SRDF group_state the hand takes to PRESENT a frame's pad
// (`glove_frames.yaml: hand_state`). It is derived, never chosen: the server
// reads the same field in `_hand_joint_values`, so offering it as an editable
// control would be offering a value nothing downstream reads.
function handStateFor(frameName) {
    if (!frameName) return null;
    const frames = (gloveFramesData || {}).frames || {};
    const entry = frames[frameName] || frames[`${viewerArmPrefix()}${frameName}`] || null;
    return entry ? (entry.hand_state || null) : null;
}

function renderHandStates() {
    const viewerFrame = document.getElementById('reachFrameSelect')?.value || '';
    const taskFrame = document.getElementById('genIkFrame')?.value || '';
    const viewerFull = viewerFrame ? `${viewerArmPrefix()}${viewerFrame}` : '';
    const pairs = [['reachHandState', viewerFull], ['genHandState', taskFrame]];
    pairs.forEach(([id, frame]) => {
        const el = document.getElementById(id);
        if (!el) return;
        const st = handStateFor(frame);
        // A frame with no `hand_state` is not an error — the four non-glove
        // frames (tip/arm_tip/ConnectorLink) present no pad at all.
        el.textContent = st || (frame ? '— (no pad on this frame)' : '—');
        el.classList.toggle('is-muted', !st);
    });
    // Disagreement is the thing worth showing: it means the pose is being
    // judged against a different hand from the one the task will run.
    const warn = document.getElementById('handStateMismatch');
    if (warn) {
        const a = handStateFor(viewerFull), b = handStateFor(taskFrame);
        const clash = Boolean(a && b && a !== b);
        warn.hidden = !clash;
        if (clash) warn.textContent = `viewer ${a} vs task ${b}`;
    }
}

function reachTipFrame() { return document.getElementById('reachFrameSelect')?.value || undefined; }

// Populate the IK-frame selector from glove_frames.yaml (base names, R_/L_ stripped).
function populateReachFrames() {
    const sel = document.getElementById('reachFrameSelect');
    if (!sel || !gloveFramesData?.frames) return;
    const bases = [...new Set(Object.keys(gloveFramesData.frames).map(n => n.replace(/^[RL]_/, '')))].sort();
    if (!bases.length) return;
    const prev = sel.value;
    sel.innerHTML = bases.map(b => `<option value="${b}">${b}</option>`).join('');
    // Default to glove_frame_2 (the usual contact frame) if present.
    sel.value = (prev && bases.includes(prev)) ? prev : (bases.includes('glove_frame_2') ? 'glove_frame_2' : bases[0]);
}

async function computeReachability() {
    const btn = document.getElementById('reachabilityButton');
    const tipFrame = reachTipFrame();
    try {
        if (btn) btn.disabled = true;
        setStatus(`Computing reachability for ${tipFrame || 'default frame'} (URDF sweep, may take a few seconds)...`);
        const data = await api('/api/reachability', {
            method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({tipFrame}),
        });
        lastReachability = data;
        const rt = document.getElementById('reachabilityToggle'); if (rt) rt.checked = true;
        const st = document.getElementById('safetyZonesToggle'); if (st) st.checked = true;
        renderReachability(data);
        renderSafetyZones(data.safetyZones);
        setStatus(`Reachability computed (tip: ${data.tipFrame || tipFrame || 'default'}).`);
        if (document.getElementById('unreachableToggle')?.checked) await updateUnreachableOverlay();
    } catch (e) {
        setStatus('Reachability failed: ' + e.message, true);
    } finally {
        if (btn) btn.disabled = false;
    }
}

// ===== Space-path authoring (mechanism / free-space tasks) ===================
// Select reachability voxels with a transformable cuboid, order them along a
// box axis, and draft an editor point path with interpolated rotation deltas.
// The draft lands in the NORMAL editing pipeline (per-point gizmo, analysis,
// coverage, save/deploy), so everything downstream applies unchanged.
let spaceBox = null, spaceBoxGizmo = null;
const SPACE_BOX_MODES = ['translate', 'rotate', 'scale'];

function ensureSpaceBox() {
    if (spaceBox) return spaceBox;
    const geom = new THREE.BoxGeometry(1, 1, 1);   // unit box; gizmo scale sizes it
    spaceBox = new THREE.Mesh(geom, new THREE.MeshBasicMaterial({
        color: STATE_COLOR.selectionBox, transparent: true, opacity: 0.12, depthWrite: false}));
    spaceBox.add(new THREE.Mesh(geom.clone(), new THREE.MeshBasicMaterial({
        color: 0x39c5cf, wireframe: true, transparent: true, opacity: 0.55})));
    spaceBox.scale.set(0.3, 0.3, 0.3);
    // Default placement: in front of the fixture (fitSpaceBoxToPoints overrides
    // whenever a task with points is loaded).
    const fx = viewerManifest?.sagittalPlane?.origin;
    spaceBox.position.set(fx ? fx[0] - 0.15 : 0.6, fx ? fx[1] : 0.0, fx ? fx[2] + 0.15 : 0.45);
    scene.add(spaceBox);
    spaceBoxGizmo = new THREE.TransformControls(camera, renderer.domElement);
    spaceBoxGizmo.setSize(0.8);
    // Rebuild the pickable candidate cloud when a drag ENDS (not per-frame).
    spaceBoxGizmo.addEventListener('dragging-changed', e => {
        controls.enabled = !e.value;
        if (!e.value) rebuildSpaceCloud();
    });
    spaceBoxGizmo.addEventListener('objectChange', updateSpaceSelectionInfo);
    spaceBoxGizmo.attach(spaceBox);
    scene.add(spaceBoxGizmo);
    return spaceBox;
}

function setSpaceBoxVisible(on) {
    if (!spaceBox) {
        if (!on) return;
        ensureSpaceBox();
    }
    spaceBox.visible = on;
    spaceBoxGizmo.enabled = on;
    spaceBoxGizmo.visible = on;
    rebuildSpaceCloud();
}

function toggleSpaceBox() {
    setSpaceBoxVisible(!(spaceBox && spaceBox.visible));
}

// Segmented Move / Rotate / Scale control (key B cycles for keyboard flow).
function setSpaceBoxMode(mode) {
    ensureSpaceBox();
    spaceBoxGizmo.setMode(mode);
    [['spaceBoxMove', 'translate'], ['spaceBoxRotate', 'rotate'], ['spaceBoxScale', 'scale']]
        .forEach(([id, m]) => document.getElementById(id)?.classList.toggle('active', m === mode));
    renderScene();
}

// Auto-fit the box around the loaded task's points (pad metres per side).
function fitSpaceBoxToPoints(pad = 0.08) {
    if (!state.points.length) return;
    ensureSpaceBox();
    const box3 = new THREE.Box3();
    state.points.forEach(p => box3.expandByPoint(vec(p.xyz)));
    const size = box3.getSize(new THREE.Vector3());
    const center = box3.getCenter(new THREE.Vector3());
    spaceBox.position.copy(center);
    spaceBox.rotation.set(0, 0, 0);
    spaceBox.scale.set(Math.max(0.15, size.x + 2 * pad),
                       Math.max(0.15, size.y + 2 * pad),
                       Math.max(0.15, size.z + 2 * pad));
    setSpaceBoxVisible(true);
}

function spaceReachPoints() {
    const chains = lastReachability?.chains || {};
    const want = document.getElementById('spaceChainSelect')?.value || 'right';
    return chains[want] || [];
}

// Reachability computes AUTOMATICALLY on entering mechanism mode — no
// Workspace-tab detour. The Workspace button remains for manual recomputes
// with a different tip frame.
let autoReachInFlight = false;
async function autoComputeReachability() {
    if (lastReachability || autoReachInFlight) return;
    autoReachInFlight = true;
    try {
        await computeReachability();
        rebuildSpaceCloud();
    } finally {
        autoReachInFlight = false;
    }
}

// ---- Visible, CLICK-SELECTABLE candidates inside the box -------------------
// The in-box reachability voxels are decimated to a ~3 cm grid and rendered as
// a dedicated cloud; clicking a dot adds it to the path IN CLICK ORDER
// (clicking again removes it). Mechanism points live in empty space — there is
// no mesh to pick on — so the cloud IS the pickable surface.
const SPACE_GRID_M = 0.03;
let spaceCloud = null;
let spaceCandidates = [];   // [[x,y,z], ...] decimated candidates
let spaceClicked = [];      // indices into spaceCandidates, in click order

function disposeSpaceCloud() {
    if (spaceCloud) {
        scene.remove(spaceCloud);
        disposeObject(spaceCloud);
        spaceCloud = null;
    }
}

function spaceSelectedVoxels() {
    const pts = spaceReachPoints();
    if (!spaceBox || !spaceBox.visible || !pts.length) return [];
    spaceBox.updateMatrixWorld(true);
    const inv = spaceBox.matrixWorld.clone().invert();
    const out = [];
    const v = new THREE.Vector3();
    for (const p of pts) {
        v.set(p[0], p[1], p[2]).applyMatrix4(inv);
        if (Math.abs(v.x) <= 0.5 && Math.abs(v.y) <= 0.5 && Math.abs(v.z) <= 0.5) out.push(p);
    }
    return out;
}

function rebuildSpaceCloud() {
    disposeSpaceCloud();
    spaceCandidates = [];
    spaceClicked = [];
    if (!spaceBox || !spaceBox.visible || state.taskMode !== 'mechanism') {
        updateSpaceSelectionInfo();
        renderScene();
        return;
    }
    const seen = new Set();
    for (const p of spaceSelectedVoxels()) {
        const key = `${Math.round(p[0] / SPACE_GRID_M)},${Math.round(p[1] / SPACE_GRID_M)},${Math.round(p[2] / SPACE_GRID_M)}`;
        if (seen.has(key)) continue;
        seen.add(key);
        spaceCandidates.push(p);
    }
    if (spaceCandidates.length) {
        const positions = new Float32Array(spaceCandidates.length * 3);
        const colors = new Float32Array(spaceCandidates.length * 3);
        spaceCandidates.forEach((p, i) => { positions.set(p, i * 3); });
        const geom = new THREE.BufferGeometry();
        geom.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        geom.setAttribute('color', new THREE.BufferAttribute(colors, 3));
        spaceCloud = new THREE.Points(geom, new THREE.PointsMaterial({
            size: 0.02, vertexColors: true, sizeAttenuation: true, depthTest: false}));
        spaceCloud.renderOrder = 997;
        scene.add(spaceCloud);
        refreshSpaceCloudColors();
    }
    updateSpaceSelectionInfo();
    renderScene();
}

function refreshSpaceCloudColors() {
    if (!spaceCloud) return;
    const colors = spaceCloud.geometry.getAttribute('color');
    const order = new Map(spaceClicked.map((idx, i) => [idx, i]));
    for (let i = 0; i < spaceCandidates.length; i++) {
        if (order.has(i)) {
            // Clicked: warm gradient encoding the path order (yellow -> red).
            const t = spaceClicked.length > 1 ? order.get(i) / (spaceClicked.length - 1) : 0;
            colors.setXYZ(i, 1.0, 0.85 - 0.7 * t, 0.1);
        } else {
            colors.setXYZ(i, 0.22, 0.77, 0.81);   // candidate cyan
        }
    }
    colors.needsUpdate = true;
    renderScene();
}

function onSpaceCloudClick(event) {
    if (!spaceCloud || !spaceCandidates.length || event.button !== 0) return;
    updatePointer(event);
    raycaster.setFromCamera(pointer, camera);
    const prev = raycaster.params.Points;
    raycaster.params.Points = {threshold: SPACE_GRID_M * 0.5};
    const hit = raycaster.intersectObject(spaceCloud, false)[0];
    raycaster.params.Points = prev;
    if (!hit || hit.index === undefined) return;
    const at = spaceClicked.indexOf(hit.index);
    if (at >= 0) spaceClicked.splice(at, 1);       // toggle off
    else spaceClicked.push(hit.index);             // append in click order
    refreshSpaceCloudColors();
    updateSpaceSelectionInfo();
}

function updateSpaceSelectionInfo() {
    const el = document.getElementById('spaceSelInfo');
    if (!el) return;
    if (!spaceBox || !spaceBox.visible) { el.textContent = 'No selection box placed.'; return; }
    if (!spaceReachPoints().length) {
        el.textContent = autoReachInFlight
            ? 'Computing reachability…'
            : 'No reachability cloud for this arm yet.';
        return;
    }
    const s = spaceBox.scale;
    el.textContent = `${spaceCandidates.length} pickable point(s) (3 cm grid) inside the `
        + `${(s.x * 100).toFixed(0)}×${(s.y * 100).toFixed(0)}×${(s.z * 100).toFixed(0)} cm box`
        + (spaceClicked.length ? ` — ${spaceClicked.length} clicked in order.` : ' — click dots to order the path.');
}

// ---------------------------------------------------------------------------
// Reroute: re-thread the LOADED task's path through the clicked dots (click
// order), or auto-order the in-box candidates along a box axis. One explicit
// commit — clean undo, no accidental destruction of the exemplar path.
// ---------------------------------------------------------------------------
function rerouteThroughClickedDots() {
    if (spaceCandidates.length < 2) {
        setStatus('The box holds fewer than 2 pickable dots — move/scale it first.', true);
        return;
    }
    let picked;
    if (spaceClicked.length >= 2) {
        picked = spaceClicked.map(idx => spaceCandidates[idx]);
    } else {
        const n = Math.max(2, Math.min(50, parseInt(document.getElementById('spaceNumPoints')?.value || '8', 10)));
        const axisIdx = {x: 0, y: 1, z: 2}[document.getElementById('spaceOrderSelect')?.value || 'x'] ?? 0;
        spaceBox.updateMatrixWorld(true);
        const inv = spaceBox.matrixWorld.clone().invert();
        const scored = spaceCandidates.map(p => ({
            p, t: new THREE.Vector3(p[0], p[1], p[2]).applyMatrix4(inv).getComponent(axisIdx),
        })).sort((a, b) => a.t - b.t);
        const lo = scored[0].t, hi = scored[scored.length - 1].t;
        picked = [];
        for (let i = 0; i < n; i++) {
            const target = lo + (hi - lo) * (n > 1 ? i / (n - 1) : 0);
            let best = scored[0];
            for (const s of scored) if (Math.abs(s.t - target) < Math.abs(best.t - target)) best = s;
            if (!picked.some(q => q === best.p)) picked.push(best.p);
        }
    }
    ensureConfigForEditing();
    pushHistory();
    const poses = activeConfigBlock().cartesian_poses = activeConfigBlock().cartesian_poses || {};
    const oldPoints = state.points;
    // start_pose position moves to the first routed dot (orientation kept),
    // so point1 stays the [0,0,0] anchor exactly as the runtime expects.
    const oldStart = poses.start_pose || [0, 0, 0, 0, 0, 0, 1];
    const firstRef = basePointToRef(picked[0]);
    poses.start_pose = [...roundVector(firstRef, 4), ...oldStart.slice(3)];
    // Rotation seeding: nearest outgoing point's orientation (mechanism swings
    // are rotation-critical); zero-delta start orientation when none existed.
    const startAbsQuat = quatToArray(refQuatToBase(startQuatRef()));
    const nearestQuat = xyz => {
        if (!oldPoints.length) return [...startAbsQuat];
        let best = oldPoints[0], bestD = Infinity;
        for (const p of oldPoints) {
            const d = vec(p.xyz).distanceToSquared(vec(xyz));
            if (d < bestD) { bestD = d; best = p; }
        }
        return [...(best.absoluteQuat || startAbsQuat)];
    };
    state.points = picked.map((p, i) => (
        {name: `point${i + 1}`, idx: i, xyz: [...p], translation: [0, 0, 0],
         rotation: [0, 0, 0], absoluteQuat: nearestQuat(p), normal: null,
         manualRotation: true, source: 'space'}));
    state.selectedIndex = 0;
    buildSequenceFromPointOrder();
    refreshGeneratedDeltas();
    buildStartPoseMarker();
    const viaClicks = spaceClicked.length >= 2;
    spaceClicked = [];
    refreshSpaceCloudColors();
    markDirty(true, `Path rerouted through ${state.points.length} dot(s)`
        + `${viaClicks ? ' (your click order)' : ' (auto-ordered)'} — orient with the pose gizmo, then Save/Deploy.`);
    updateAll();
}

// ---------------------------------------------------------------------------
// Discovered mechanism ops (server scans mechanism_tasks/, glove_tasks/,
// bin_tasks/ — new task files appear here automatically).
// ---------------------------------------------------------------------------
const SHAPE_LABELS = {single: '', compound: ' — compound', dual_sync: ' — dual sync',
                      dual_joint: ' — joint-space ⚙'};

async function fetchMechOps() {
    if (!studio.enabled) return;
    const fixture = currentFixture();
    try {
        studio.mechOps = await api(`/api/mechanism-ops?fixture=${encodeURIComponent(fixture)}`);
    } catch (error) {
        studio.mechOps = null;
        console.warn('mechanism op discovery failed:', error);
    }
    renderMechOpOptions();
}

function renderMechOpOptions() {
    const sel = document.getElementById('genMechOp');
    if (!sel) return;
    const prev = sel.value;
    sel.innerHTML = '';
    const ops = studio.mechOps?.ops || [];
    if (!ops.length) {
        sel.innerHTML = '<option value="">(no ops discovered)</option>';
        return;
    }
    const groups = {mechanism: 'Fixture mechanisms', glove: 'Glove (robot)', bin: 'Bin (robot)'};
    for (const [category, label] of Object.entries(groups)) {
        const catOps = ops.filter(o => o.category === category);
        if (!catOps.length) continue;
        const group = document.createElement('optgroup');
        group.label = label;
        for (const op of catOps) {
            // One entry per SHAPE (single collapses to one arm-agnostic entry;
            // the Arm select picks the side).
            const shapes = [...new Set(op.variants.map(v => v.shape))];
            for (const shape of shapes) {
                const opt = document.createElement('option');
                opt.value = `${category}|${op.fixture || ''}|${op.id}|${shape}`;
                opt.textContent = `${op.label}${SHAPE_LABELS[shape] ?? ` — ${shape}`}`;
                opt.dataset.category = category;
                opt.dataset.op = op.id;
                opt.dataset.shape = shape;
                if (op.fixture) opt.dataset.fixture = op.fixture;
                if (op.variants.some(v => v.shape === shape && v.stageOnly)) opt.dataset.stageOnly = '1';
                group.appendChild(opt);
            }
        }
        sel.appendChild(group);
    }
    if (prev && [...sel.options].some(o => o.value === prev)) sel.value = prev;
}

function currentMechSelection() {
    const opt = document.getElementById('genMechOp')?.selectedOptions?.[0];
    if (!opt || !opt.dataset.op) return null;
    return {category: opt.dataset.category, op: opt.dataset.op, shape: opt.dataset.shape,
            fixture: opt.dataset.fixture || null, stageOnly: opt.dataset.stageOnly === '1',
            arm: document.getElementById('spaceChainSelect')?.value || 'right'};
}

// Selecting an op LOADS its calibrated exemplar as the working config —
// edit-in-place instead of authoring from empty space.
async function loadMechExemplar() {
    const selection = currentMechSelection();
    if (!selection || state.taskMode !== 'mechanism') return;
    if (paintDirty() && !window.confirm(
        'Unsaved region paint will be replaced by the selected exemplar. Continue?')) return;
    if (!(await requireEditSession(`the ${selection.op} exemplar`))) return;
    const params = new URLSearchParams({category: selection.category, op: selection.op,
        shape: selection.shape, arm: selection.arm});
    if (selection.fixture) params.set('fixture', selection.fixture);
    // [N-8]: an opposite-arm exemplar is mirrored server-side in THIS venue
    const venue = document.getElementById('atlasVenue')?.value;
    if (venue) params.set('venue', venue);
    try {
        const result = await api(`/api/mechanism-exemplar?${params}`);
        if (result.error) {
            // No exemplar: generate the fallback skeleton from current points.
            const gen = await api('/api/generate-mechanism', {method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({category: selection.category, op: selection.op,
                    shape: selection.shape, arm: selection.arm, fixture: selection.fixture,
                    points: state.points.length ? state.points.map(p => (
                        {position: p.xyz, orientation: p.absoluteQuat || [0, 0, 0, 1]}))
                        : [{position: [0.6, selection.arm === 'left' ? 0.2 : -0.2, 0.4],
                            orientation: [0, 0, 0, 1]}]})});
            const file = gen.files?.[0];
            if (!file) { setStatus('No exemplar and generation returned nothing.', true); return; }
            loadYamlText(file.yamlText, file.name, null, 'generated');
            state.deployPath = file.path;
            setStatus(`${file.name}: no exemplar existed — fallback skeleton loaded `
                + `(${(gen.warnings || []).join('; ') || 'review stages'}).`, true);
            return;
        }
        loadYamlText(result.yamlText, result.name);
        state.loadedMtimeNs = result.mtimeNs;
        state.deployPath = result.deployPath;
        state.mechSelection = selection;
        setStatus(`${result.name} loaded${result.mirrored ? ' (mirrored from the ' + result.sourceArm + ' exemplar)' : ''}`
            + `${selection.stageOnly ? ' — joint-space stage-only task (no cartesian path)' : ' — reroute dots or edit points, then Deploy.'}`);
    } catch (error) {
        if (error.payload?.reflectionRefused) {
            await showMirrorRefusal(error.payload);        // [N-8]: the mirrored exemplar is refused
            return;
        }
        setStatus(`Exemplar load failed: ${error.message}`, true);
    }
}

// Map a LOADED mechanism config back to the studio controls (op / shape / arm)
// so reopening a file restores the mechanism UI.
function applyMechUiFromConfig(config, fileName) {
    const tp = config?.task_parameters || {};
    const sel = document.getElementById('genMechOp');
    const stem = String(fileName || '').replace(/\.ya?ml$/i, '');
    const shape = tp.compound || (config?.right && config?.left) ? 'compound'
        : /_dual_joint$/.test(stem) ? 'dual_joint' : 'single';
    let arm = 'right';
    if (/_left$/.test(stem)) arm = 'left';
    else if (String(tp.ik_frame || '').startsWith('L_')) arm = 'left';
    const chain = document.getElementById('spaceChainSelect');
    if (chain) chain.value = arm;
    if (sel) {
        const opStem = stem.replace(/_(right|left|dual_joint)$/, '');
        const match = [...sel.options].find(o =>
            o.dataset.op === opStem && o.dataset.shape === shape);
        if (match) sel.value = match.value;
    }
    state.mechSelection = currentMechSelection();
}

// ---------------------------------------------------------------------------
// Task-mode axis: the Task type selection decides which features exist,
// ACROSS tabs. CSS does the hiding (body[data-task-mode] + data-task-modes
// tags); this function owns the state + scene objects + refreshes.
// ---------------------------------------------------------------------------
function setTaskMode(mode) {
    mode = mode === 'mechanism' ? 'mechanism' : 'cleaning';
    if (state.taskMode === mode) return;
    state.taskMode = mode;
    document.body.dataset.taskMode = mode;
    const typeSel = document.getElementById('genTaskType');
    if (typeSel && typeSel.value !== mode) typeSel.value = mode;
    if (mode === 'mechanism') {
        renderMechOpOptions();
        autoComputeReachability();
        if (state.activeTab === 'regions') switchTab('workbench');
        if (state.points.length) fitSpaceBoxToPoints();
    } else {
        state.compoundArm = null;
        state.mechSelection = null;
        state.deployPath = null;
        if (spaceBox) setSpaceBoxVisible(false);
        disposeSpaceCloud();
    }
    updateDockPanels(state.activeTab);
    updateVisibilityBar(state.activeTab);
    updateEditorAvailability();
    renderLegend(state.activeTab);
    updateDockEmptiness();   // task-mode switches hide panels too (data-task-modes)
    updatePoseGizmo();
}

function onTaskTypeChange() {
    const type = document.getElementById('genTaskType')?.value || 'cleaning';
    setTaskMode(type);
    if (type === 'mechanism') {
        setStatus('Mechanism mode: pick an op — its calibrated exemplar loads for editing. '
            + 'The box + reachability dots author/reroute the free-space path.');
        loadMechExemplar();
    }
}

function initSpacePathControls() {
    document.body.dataset.taskMode = state.taskMode;   // CSS gating baseline
    document.getElementById('spaceBoxToggle')?.addEventListener('click', toggleSpaceBox);
    document.getElementById('spaceBoxMove')?.addEventListener('click', () => setSpaceBoxMode('translate'));
    document.getElementById('spaceBoxRotate')?.addEventListener('click', () => setSpaceBoxMode('rotate'));
    document.getElementById('spaceBoxScale')?.addEventListener('click', () => setSpaceBoxMode('scale'));
    document.getElementById('spaceRerouteButton')?.addEventListener('click', rerouteThroughClickedDots);
    document.getElementById('spaceChainSelect')?.addEventListener('change', () => {
        if (state.taskMode !== 'mechanism') return;
        if (state.compoundArm) {   // compound: the Arm select swaps the edited block
            swapCompoundArm(document.getElementById('spaceChainSelect').value);
            return;
        }
        loadMechExemplar();
        rebuildSpaceCloud();
    });
    document.getElementById('genMechOp')?.addEventListener('change', loadMechExemplar);
    renderer?.domElement?.addEventListener('pointerdown', onSpaceCloudClick);
    document.getElementById('genTaskType')?.addEventListener('change', onTaskTypeChange);
    // B cycles the box gizmo mode while the box is up (keyboard-first sizing).
    window.addEventListener('keydown', event => {
        if ((event.key === 'b' || event.key === 'B') && spaceBox?.visible
            && !isTypingTarget(event.target)) {
            const next = SPACE_BOX_MODES[(SPACE_BOX_MODES.indexOf(spaceBoxGizmo?.mode || 'translate') + 1) % SPACE_BOX_MODES.length];
            setSpaceBoxMode(next);
        }
    });
}

// Compound files carry right:/left: blocks; the Arm select swaps which block
// the editor works on (state.compoundArm routes the whole edit pipeline via
// activeConfigBlock()).
function swapCompoundArm(arm) {
    if (!state.config || !state.config[arm]) {
        setStatus(`This compound file has no '${arm}' block.`, true);
        return;
    }
    if (state.dirty && !window.confirm(
        `Switch to the ${arm} block? Unsaved edits to the ${state.compoundArm} block stay in memory until Save.`)) return;
    state.compoundArm = arm;
    state.points = recoverPoints(activeConfigBlock());
    state.selectedIndex = state.points.length ? 0 : -1;
    buildStartPoseMarker();
    updateAll();
    setStatus(`Editing the ${arm} block of ${state.fileName || 'the compound task'}.`);
}

// #3: paint the fixture-surface areas that fall OUTSIDE the reach envelope.
// Samples the visible fixture meshes (active + companions, already in base_link),
// asks the server which points are reachable, and dots the unreachable ones red.
function fixtureSurfacePoints(maxPoints = 4000) {
    const meshes = [];
    if (meshObject && meshObject.visible && meshObject.geometry) meshes.push(meshObject);
    if (companionGroup) companionGroup.children.forEach(m => { if (m.geometry) meshes.push(m); });
    const pts = [];
    meshes.forEach(m => {
        const pos = m.geometry.getAttribute('position');
        if (pos) for (let i = 0; i < pos.count; i++) pts.push([pos.getX(i), pos.getY(i), pos.getZ(i)]);
    });
    if (pts.length <= maxPoints) return pts;
    const step = Math.ceil(pts.length / maxPoints);
    return pts.filter((_, i) => i % step === 0);
}

async function updateUnreachableOverlay() {
    if (!unreachableGroup) return;
    clearGroup(unreachableGroup);
    const pts = fixtureSurfacePoints();
    if (!pts.length) { setStatus('No fixture mesh visible to evaluate — enable a mesh (View tab).', true); return; }
    let data;
    try {
        data = await api('/api/reachable-mask', {method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({points: pts, tipFrame: reachTipFrame()})});
    } catch (e) { setStatus('Unreachable check failed: ' + e.message, true); return; }
    const reach = data.reachable || [];
    const positions = [];
    for (let i = 0; i < pts.length; i++) if (!reach[i]) positions.push(...pts[i]);
    const total = pts.length, unreach = positions.length / 3;
    if (positions.length) {
        const geom = new THREE.BufferGeometry();
        geom.setAttribute('position', new THREE.BufferAttribute(new Float32Array(positions), 3));
        const mat = new THREE.PointsMaterial({size: 0.012, color: 0xf85149, sizeAttenuation: true, depthTest: false});
        const cloud = new THREE.Points(geom, mat); cloud.renderOrder = 998;
        unreachableGroup.add(cloud);
    }
    unreachableGroup.visible = document.getElementById('unreachableToggle')?.checked ?? false;
    setStatus(`Unreachable on fixtures: ${unreach}/${total} sampled points (red) for ${reachTipFrame() || 'default'}.`);
    renderScene();
}

function toggleUnreachable(on) {
    if (on) { updateUnreachableOverlay(); }
    else if (unreachableGroup) { unreachableGroup.visible = false; renderScene(); }
}

function toggleReachability(on) { if (reachabilityGroup) { reachabilityGroup.visible = on; renderScene(); } }
function toggleSafetyZones(on) { if (safetyZonesGroup) { safetyZonesGroup.visible = on; renderScene(); } }

// ===== Manipulability heatmap (dexterity per voxel) =========================
let lastManipulability = null;

// Map normalized dexterity [0..1] to a red(low)->yellow->green(high) hue.
function manipColor(v) { return new THREE.Color().setHSL(Math.max(0, Math.min(1, v)) * 0.33, 0.95, 0.5); }

function renderManipulability(data) {
    if (!manipulabilityGroup) return;
    clearGroup(manipulabilityGroup);
    const res = data?.grid?.resolution_m || 0.04;
    for (const chain of Object.values(data?.chains || {})) {
        const pts = chain.points || [], vals = chain.values || [];
        if (!pts.length) continue;
        const positions = new Float32Array(pts.length * 3);
        const colorsArr = new Float32Array(pts.length * 3);
        for (let i = 0; i < pts.length; i++) {
            positions[i * 3] = pts[i][0]; positions[i * 3 + 1] = pts[i][1]; positions[i * 3 + 2] = pts[i][2];
            const c = manipColor(vals[i] ?? 0);
            colorsArr[i * 3] = c.r; colorsArr[i * 3 + 1] = c.g; colorsArr[i * 3 + 2] = c.b;
        }
        const geom = new THREE.BufferGeometry();
        geom.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        geom.setAttribute('color', new THREE.BufferAttribute(colorsArr, 3));
        const material = new THREE.PointsMaterial({size: res * 0.7, vertexColors: true, sizeAttenuation: true, transparent: true, opacity: 0.85});
        manipulabilityGroup.add(new THREE.Points(geom, material));
    }
    const el = document.getElementById('manipulabilityInfo');
    if (el) {
        const wmax = Math.max(0, ...Object.values(data?.chains || {}).map(c => c.wMax || 0));
        el.innerHTML = `<div class="info-row"><span>w max</span><code>${wmax.toFixed(4)}</code></div><div class="info-row"><span>scale</span><code>red=low → green=high</code></div>`;
    }
    manipulabilityGroup.visible = document.getElementById('manipulabilityToggle')?.checked ?? true;
    renderScene();
}

async function computeManipulability() {
    const btn = document.getElementById('manipulabilityButton');
    const tipFrame = reachTipFrame();
    try {
        if (btn) btn.disabled = true;
        setStatus(`Computing manipulability for ${tipFrame || 'default frame'} (URDF sweep; first run may take a few seconds)…`);
        const data = await api('/api/manipulability', {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({tipFrame})});
        if (data.error) { setStatus('Manipulability: ' + data.error, true); return; }
        lastManipulability = data;
        const t = document.getElementById('manipulabilityToggle'); if (t) t.checked = true;
        renderManipulability(data);
        setStatus(`Manipulability computed (tip: ${data.tipFrame || tipFrame || 'default'}).`);
    } catch (e) {
        setStatus('Manipulability failed: ' + e.message, true);
    } finally {
        if (btn) btn.disabled = false;
    }
}

function toggleManipulability(on) {
    if (on && !lastManipulability) { computeManipulability(); return; }
    if (manipulabilityGroup) { manipulabilityGroup.visible = on; renderScene(); }
}

// ===== Redundancy Atlas ====================================================
// The configurations BEHIND a stroke. `/api/reachability` and
// `/api/manipulability` both reduce over configurations — the envelope records
// that SOME joint solution reaches a voxel and the dexterity map records the
// BEST one — so neither can say that the configuration which reaches a point
// is the one that puts the elbow through a cubicle wall. This panel sweeps the
// coordinate they reduced over (the elbow swivel) across the whole stroke and
// draws it as swivel against arc length, with the corridor a continuous motion
// could actually follow.
//
// Reading the picture: one COLUMN per waypoint, one ROW per swivel angle. A
// stroke is feasible when a continuous line crosses from the left edge to the
// right edge without entering a blocked cell — which is a connectivity
// question, not a per-point reachability one.
let lastAtlas = null;

// Block codes come from alix_workspace.redundancy; the server ships the LABELS
// with the payload so this table never drifts from the module's own numbering,
// and the colours are CSS tokens read back at paint time — the same way
// syncColorsFromCss keeps the 3D palette in step with the theme. A canvas
// painted from literals would be the one unthemed island in the panel.
const ATLAS_TOKENS = {
    0: '--atlas-free-high',   // free (shaded by margin between low and high)
    1: '--atlas-reach',       // beyond the wrist ball — geometry, not a solver verdict
    2: '--atlas-noseed',      // IK did not converge
    3: '--atlas-nobranch',    // branch does not exist
    4: '--atlas-limit',       // joint limit
    5: '--atlas-singular',    // singular set
    6: '--atlas-self',        // self-collision
    7: '--atlas-wall',        // wall
    8: '--atlas-fixture',     // fixture
    9: '--atlas-partner',     // the other arm
};

function atlasPalette() {
    const css = getComputedStyle(document.documentElement);
    const get = (name, fallback) => (css.getPropertyValue(name) || '').trim() || fallback;
    const pal = {codes: {}};
    for (const [code, token] of Object.entries(ATLAS_TOKENS)) pal.codes[code] = get(token, '#888888');
    pal.freeLow = get('--atlas-free-low', '#cccccc');
    pal.freeHigh = get('--atlas-free-high', '#2f9e6d');
    pal.axis = get('--atlas-axis', 'rgba(128,128,128,0.55)');
    pal.grid = get('--atlas-grid', 'rgba(128,128,128,0.15)');
    pal.corridor = get('--atlas-corridor', '#b26b00');
    pal.blocked = get('--atlas-blocked', '#c0392b');
    return pal;
}

// Free cells are shaded low -> high by margin so the WIDTH of the corridor is
// visible, not just its existence: a cell 45 degrees clear of every singular
// set is not the same offer as one at 21.
// The viewport ground is dark in BOTH themes (--viewport-bg), while the panel
// ground follows the theme. The dark palette's free-ramp floor sits close to
// that ground, so a low-margin cell drawn there would read as absence rather
// than as "free, but only just". Floor the ramp for the 3-D layers.
const ATLAS_VP_RAMP_FLOOR = 0.28;

function atlasMix(a, b, t) {
    const rgb = h => {
        const m = String(h).trim().match(/^#?([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i);
        return m ? [parseInt(m[1], 16), parseInt(m[2], 16), parseInt(m[3], 16)] : [128, 128, 128];
    };
    const [r1, g1, b1] = rgb(a), [r2, g2, b2] = rgb(b);
    const k = Math.max(0, Math.min(1, t));
    return `rgb(${Math.round(r1 + (r2 - r1) * k)},${Math.round(g1 + (g2 - g1) * k)},${Math.round(b1 + (b2 - b1) * k)})`;
}

// THE GATE A READOUT JUDGES AT (review D5, 2026-09-29): the loaded config's
// RECORDED gate (provenance.stroke.requirements.singularMarginDeg -- the gate its
// map was certified at), else the bound region, which the server resolves to its
// declared gate, else 15 (server.display_gate). The atlas and the IK badge used to
// judge at the vendor's 20 while maps are certified at 15 / declared, so a cell
// the map certified at 15-20 deg read as sub-gate. The vendor 20 is still shown,
// as a second, labelled threshold -- never the verdict.
function readoutGateBody() {
    const reqs = activeConfigBlock()?.provenance?.stroke?.requirements
        || state.config?.provenance?.stroke?.requirements;
    const recorded = Number(reqs?.singularMarginDeg);
    const out = {region: (state.task && state.task.region) || undefined};
    if (Number.isFinite(recorded) && recorded > 0) {
        out.gateDeg = recorded;
        out.gateSource = `config (recorded, ${reqs.singularMarginSource || 'source unrecorded'})`;
    }
    return out;
}

function atlasBody() {
    const pole = parseFloat(document.getElementById('atlasPole')?.value);
    return {
        ...readoutGateBody(),
        yamlText: editedYamlText(),
        fixture: currentFixture(),
        tipFrame: reachTipFrame(),
        swivelStepDeg: Number(document.getElementById('atlasSwivelStep')?.value) || 5,
        gammaDeg: Number(document.getElementById('atlasGamma')?.value) || 0,
        poleM: Number.isFinite(pole) ? pole : undefined,
        maxSwivelStepDeg: Number(document.getElementById('atlasMaxStep')?.value) || 15,
        resampleMm: Number(document.getElementById('atlasResample')?.value) || 15,
        includeCollision: !!document.getElementById('atlasCollision')?.checked,
        venue: document.getElementById('atlasVenue')?.value || undefined,
        tiltPolicy: atlasTiltPolicy(),
    };
}

// The contact tolerance is a property of the SURFACE, so it is asked for rather
// than assumed. Zero limits still produce a report — "no tilt is needed here" is
// an answer worth having, and it costs a microsecond per waypoint. The two
// numbers are ROLL (about the wipe axis) and PITCH (about the lateral axis) of
// the pad itself — not rotations about the reference frame, which on a face
// whose normal lies along ref X were a spin of the pad, not a tilt.
function atlasTiltPolicy() {
    const x = Number(document.getElementById('atlasTiltX')?.value) || 0;
    const z = Number(document.getElementById('atlasTiltZ')?.value) || 0;
    const apply = document.getElementById('atlasTiltApply')?.value || 'none';
    if (!x && !z) return undefined;
    // Pad-local since 2026-08-27: roll about the wipe axis, pitch about the
    // lateral axis (the server clamps both to the contract ceiling).
    return {maxRollDeg: x, maxPitchDeg: z, stepDeg: 2.5, apply, forGate: true, maxStepDeg: 5};
}

// Populate the venue picker from the scene files that actually exist, so a new
// cubicle becomes selectable by dropping a yaml in, not by editing markup.
async function loadAtlasEnvironment() {
    const sel = document.getElementById('atlasVenue');
    if (!sel || sel.dataset.loaded) return;
    try {
        const d = await api('/api/atlas-environment');
        (d.venues || []).forEach(v => {
            const o = document.createElement('option');
            o.value = v;
            o.textContent = v.replace('washroom_', '').replace('_wide_scene.yaml', '').replace('.yaml', '');
            if (v === d.defaultVenue) o.textContent += ' (default)';
            sel.appendChild(o);
        });
        if (d.tiltDefaults) {
            const tx = document.getElementById('atlasTiltX');
            const tz = document.getElementById('atlasTiltZ');
            const cap = d.tiltDefaults.contractCeilingDeg || d.tiltDefaults.maxRollDeg || d.tiltDefaults.maxXDeg;
            if (tx) tx.max = cap;
            if (tz) tz.max = cap;
        }
        sel.dataset.loaded = '1';
    } catch (e) { /* the picker keeps its default entry */ }
}

async function computeRedundancyAtlas() {
    const btn = document.getElementById('atlasButton');
    if (!editedYamlText()) { setStatus('Redundancy atlas: load a task config first.', true); return; }
    try {
        if (btn) btn.disabled = true;
        const withCollision = !!document.getElementById('atlasCollision')?.checked;
        await loadAtlasEnvironment();
        setStatus(`Computing redundancy atlas${withCollision ? ' with collision (walls, fixture, self) — this takes a while' : ''}…`);
        const data = await api('/api/redundancy-atlas', {
            method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify(atlasBody())});
        if (data.error) { setStatus('Redundancy atlas: ' + data.error, true); renderAtlasInfo(data); return; }
        lastAtlas = data;
        renderAtlas(data);
        const t3 = document.getElementById('atlas3dToggle');
        if (t3) t3.checked = true;
        renderAtlas3D(data);
        const c = data.corridor || {};
        setStatus(c.found
            ? `Atlas: corridor found, worst margin ${c.minMarginDeg}° over ${data.names.length} waypoints (swivel range ${c.swivelRangeDeg}°).`
            : `Atlas: no corridor — blocked at ${data.names[c.blockedAt] ?? ('waypoint ' + c.blockedAt)}.`,
            !c.found);
    } catch (e) {
        setStatus('Redundancy atlas failed: ' + e.message, true);
    } finally {
        if (btn) btn.disabled = false;
    }
}

function renderAtlas(data) {
    const canvas = document.getElementById('atlasCanvas');
    if (!canvas) return;
    const S = data.names.length, P = data.psiDeg.length;
    const ctx = canvas.getContext('2d');
    const pal = atlasPalette();
    const padL = 46, padB = 26, padT = 8, padR = 8;
    const W = canvas.width - padL - padR, H = canvas.height - padT - padB;
    const cw = W / S, ch = H / P;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // Cells. Row 0 is the LOWEST swivel angle, so the image is drawn bottom-up
    // and +psi reads upward the way the axis label promises.
    for (let s = 0; s < S; s++) {
        for (let p = 0; p < P; p++) {
            const code = data.code[s * P + p];
            ctx.fillStyle = pal.codes[code] || pal.codes[3];
            if (code === 0) {
                const m = data.marginDeg[s * P + p];
                ctx.fillStyle = atlasMix(pal.freeLow, pal.freeHigh, (m - data.gateDeg) / 45);
            }
            ctx.fillRect(padL + s * cw, padT + H - (p + 1) * ch, Math.ceil(cw), Math.ceil(ch));
        }
    }

    // Axes
    ctx.strokeStyle = pal.axis;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padL, padT); ctx.lineTo(padL, padT + H); ctx.lineTo(padL + W, padT + H);
    ctx.stroke();
    ctx.fillStyle = pal.axis;
    ctx.font = '10px system-ui, sans-serif';
    ctx.textAlign = 'right';
    [-180, -90, 0, 90, 180].forEach(v => {
        const y = padT + H - ((v + 180) / 360) * H;
        ctx.fillText(v + '°', padL - 5, y + 3);
        ctx.strokeStyle = pal.grid;
        ctx.beginPath(); ctx.moveTo(padL, y); ctx.lineTo(padL + W, y); ctx.stroke();
    });
    ctx.save();
    ctx.translate(11, padT + H / 2); ctx.rotate(-Math.PI / 2);
    ctx.textAlign = 'center'; ctx.fillText('elbow swivel ψ', 0, 0);
    ctx.restore();
    ctx.textAlign = 'center';
    ctx.fillText('waypoints along the stroke →', padL + W / 2, canvas.height - 6);

    // The corridor, or the column that killed it.
    const c = data.corridor || {};
    if (c.found && c.psiDeg?.length === S) {
        ctx.strokeStyle = pal.corridor;
        ctx.lineWidth = 2;
        ctx.beginPath();
        c.psiDeg.forEach((psi, s) => {
            const x = padL + (s + 0.5) * cw;
            const y = padT + H - ((psi + 180) / 360) * H;
            s ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
        });
        ctx.stroke();
    } else if (c.blockedAt >= 0) {
        ctx.strokeStyle = pal.blocked;
        ctx.lineWidth = 2;
        const x = padL + (c.blockedAt + 0.5) * cw;
        ctx.beginPath(); ctx.moveTo(x, padT); ctx.lineTo(x, padT + H); ctx.stroke();
    }
    canvas.dataset.geom = JSON.stringify({padL, padT, W, H, cw, ch, S, P});
    renderAtlasLegend(data);
    renderAtlasInfo(data);
}

function renderAtlasLegend(data) {
    const el = document.getElementById('atlasLegend');
    if (!el) return;
    const pal = atlasPalette();
    const present = new Set(data.code);
    el.innerHTML = [...present].sort((a, b) => a - b).map(code =>
        `<span class="atlas-key"><i style="background:${pal.codes[code] || pal.codes[3]}"></i>${
            (data.codeLabels || {})[code] || ('code ' + code)}</span>`).join('');
}

function renderAtlasInfo(data) {
    const el = document.getElementById('atlasInfo');
    if (!el) return;
    if (data.error) {
        el.innerHTML = `<div class="info-row"><span>Atlas</span><code class="bad">${data.error}</code></div>`;
        return;
    }
    const s = data.summary || {}, c = data.corridor || {}, g = data.geometry || {};
    const rows = [];
    const push = (k, v, cls) => rows.push(
        `<div class="info-row"><span>${k}</span><code${cls ? ' class="' + cls + '"' : ''}>${v}</code></div>`);

    push('corridor', c.found
        ? `found — worst margin ${c.minMarginDeg}°`
        : `none — blocked at ${data.names[c.blockedAt] ?? c.blockedAt}`, c.found ? 'ok' : 'bad');
    if (!c.found && c.blockedReason) push('why', c.blockedReason, 'bad');
    if (!c.found && c.blockedKind) {
        push('fix class', c.blockedKind === 'step'
            ? `continuity — free swivel exists on both sides, but no step reaches it${
                c.requiredJointStepDeg ? ` (needs ~${c.requiredJointStepDeg}° joint step)` : ''}`
            : 'geometry — that waypoint has no free swivel at all; standoff, pole or the other arm',
            'bad');
    }
    if (c.found) {
        push('swivel range', `${c.swivelRangeDeg}° (max step ${c.maxSwivelStepDeg}°)`);
        push('branches used', [...new Set(c.branch || [])].join(', '));
    }
    push('free cells', `${s.freeCells} of ${(s.waypoints || 0) * (s.swivelSamples || 0) * (s.branches || 0)} (${Math.round(100 * (s.freeFraction || 0))}%)`);
    push('pole', `${data.poleM} m — from ${data.poleSource}`);
    push('wipe yaw', `${data.gammaDeg}°`);
    push('singularity gate', `${data.gateDeg}° — ${data.gateSource || 'source not reported'}`);
    // review D5: the vendor's 20 is a SECOND threshold, labelled, never the verdict
    if (data.vendorGateDeg != null) {
        push('vendor gate (2nd threshold)', `${data.vendorGateDeg}° — shown, not judged`
             + (data.vendorGateLabel ? ` (${data.vendorGateLabel})` : ''));
    }
    // The straight-elbow set is a DISTANCE, so an overshoot is reported in mm
    // and named as unfixable by redundancy: it is a standoff / pole / arm
    // decision, and telling an operator to "tune the path" there wastes a day.
    if (s.overshootMm?.length) {
        push('beyond reach', `${s.overshootMm.length} waypoint(s), up to ${Math.max(...s.overshootMm).toFixed(1)} mm past the ${s.maxReachMm} mm wrist ball — no swivel, wipe yaw or wrist branch reaches these`, 'bad');
    }
    if (s.seedErrorMm != null) push('seed error', `${s.seedErrorMm} mm`);

    // The two fixes for a reach failure, each with its number. Without these the
    // atlas says "beyond reach" and stops, which is the least actionable place
    // to stop: the operator still has to guess whether 25 mm of standoff fixes
    // it or 250 mm does, and whether tilting is even allowed.
    const tr = data.tilt?.report;
    if (tr) {
        const uni = tr.uniformForGate || tr.uniformForReach;
        const need = (tr.waypointsNeedingTilt || []).length;
        const hard = (tr.waypointsNoTiltCanFix || []).length;
        push('contact tilt', need
            ? (uni ? `${need} waypoint(s) need a tilt; one tilt fixes all: x${uni[0] >= 0 ? '+' : ''}${uni[0]}° z${uni[1] >= 0 ? '+' : ''}${uni[1]}°`
                   : `${need} waypoint(s) need a tilt; no single tilt fixes all${hard ? `, and ${hard} cannot be fixed at all` : ' — try the smooth profile'}`)
            : 'none needed at the authored normal', need ? (uni ? 'ok' : 'bad') : 'ok');
    }
    if (data.tilt?.applied) {
        const a = data.tilt.applied;
        push('tilt applied', `x${a.xDeg >= 0 ? '+' : ''}${a.xDeg}° z${a.zDeg >= 0 ? '+' : ''}${a.zDeg}° about the ref frame`, 'ok');
    }
    const pl = data.placement;
    if (pl && !pl.error && !pl.feasibleNow) {
        const mr = pl.minimalForGate || pl.minimalForReach;
        if (mr) {
            push('placement fix', `standoff ${mr.standoffDeltaMm >= 0 ? '+' : ''}${mr.standoffDeltaMm} mm`
                + (mr.poleDeltaMm ? `, pole ${mr.poleDeltaMm >= 0 ? '+' : ''}${mr.poleDeltaMm} mm` : ' (pole unchanged)')
                + ` — binding waypoint ${pl.bindingWaypointName || pl.bindingWaypoint}`, 'bad');
        } else {
            push('placement fix', 'no standoff or pole within range reaches every waypoint', 'bad');
        }
        // The instinctive fix, answered explicitly. Raising the pole lifts the
        // shoulder and SPENDS the wrist ball on vertical offset, so on a low
        // surface it makes reach worse — saying so is the point.
        push('pole alone', pl.minimalPoleOnlyForReach
            ? `pole ${pl.minimalPoleOnlyForReach.poleM} m works at this standoff`
            : 'no pole height fixes it at this standoff', pl.minimalPoleOnlyForReach ? 'ok' : 'bad');
    }
    if (data.environment?.venue) push('venue', data.environment.venue);
    if (s.collisionChecked) push('collision', `${s.collisionChecked} cells checked`);
    const pairs = Object.entries(s.blockingPairs || {}).slice(0, 4);
    if (pairs.length) push('top blocking pairs', pairs.map(([k, n]) => `${k} ×${n}`).join('<br>'));
    push('arm', `S-R-S, a=${(g.upperArmM * 1000).toFixed(0)} mm, b=${(g.forearmM * 1000).toFixed(0)} mm, wrist ball ${(g.maxWristReachM * 1000).toFixed(1)} mm`);
    const sp = data.sampling || {};
    if (sp.samples) {
        push('sampling', `${sp.authoredWaypoints} authored → ${sp.samples} samples at ${sp.resampleMm} mm`);
    }
    el.innerHTML = rows.join('');
}

// ===== Corpus sweep: the atlas across a whole fixture ======================
// One config answers "is this stroke feasible". The corpus question — which
// regions have a corridor, which need the contact tilted, which need the robot
// moved — was only answerable by running the panel once per config and writing
// the answers down. The FIX CLASS is the column that makes the table worth
// reading: it sorts by what to DO, cheapest fix last.
const ATLAS_FIX_ORDER = ['unreachable', 'branch', 'placement', 'tilt', 'swivel', 'sampling', 'ok', 'error'];
const ATLAS_FIX_TOKEN = {
    unreachable: '--atlas-reach', branch: '--atlas-nobranch', placement: '--atlas-reach',
    tilt: '--atlas-fixture', swivel: '--atlas-singular', sampling: '--atlas-limit',
    ok: '--atlas-free-high', error: '--atlas-blocked',
};

async function sweepFixture() {
    const btn = document.getElementById('atlasSweepButton');
    const el = document.getElementById('atlasSweep');
    const fixture = currentFixture();
    if (!fixture) { setStatus('Sweep: no fixture selected.', true); return; }
    try {
        if (btn) btn.disabled = true;
        if (el) el.innerHTML = `<div class="hint">Sweeping every config of ${fixture}…</div>`;
        setStatus(`Sweeping the atlas across every ${fixture} config — kinematics only, this takes ~15 s…`);
        const body = {
            fixture,
            swivelStepDeg: Number(document.getElementById('atlasSwivelStep')?.value) || 10,
            venue: document.getElementById('atlasVenue')?.value || undefined,
            tiltPolicy: atlasTiltPolicy(),
        };
        const d = await api('/api/atlas-sweep', {method: 'POST', headers: {'Content-Type': 'application/json'},
                                                 body: JSON.stringify(body)});
        if (d.error) { setStatus('Sweep: ' + d.error, true); if (el) el.innerHTML = ''; return; }
        renderAtlasSweep(d);
        const s = d.summary;
        setStatus(`Sweep: ${s.withCorridor} of ${s.configs} configs have a corridor at `
                  + `${d.settings.resampleMm} mm sampling.`);
    } catch (e) {
        setStatus('Sweep failed: ' + e.message, true);
    } finally {
        if (btn) btn.disabled = false;
    }
}

function renderAtlasSweep(d) {
    const el = document.getElementById('atlasSweep');
    if (!el) return;
    const css = getComputedStyle(document.documentElement);
    const tok = name => (css.getPropertyValue(name) || '').trim() || '#888888';
    // A row that errored may carry no fixClass at all. Without this fallback
    // `indexOf(undefined)` is -1, which sorts error rows ABOVE the most severe
    // real class, and `ATLAS_FIX_TOKEN[undefined]` falls through to the same
    // grey the "branch" class uses — so a failed config renders as a top-priority
    // branch discontinuity labelled "undefined".
    const cls = r => r.fixClass || (r.error ? 'error' : 'ok');
    const rows = (d.rows || []).slice().sort((a, b) => {
        const ai = ATLAS_FIX_ORDER.indexOf(cls(a)), bi = ATLAS_FIX_ORDER.indexOf(cls(b));
        return ai !== bi ? ai - bi : String(a.region).localeCompare(String(b.region));
    });
    const detail = r => {
        if (r.error) return String(r.error).slice(0, 60);
        switch (cls(r)) {
        case 'tilt': return r.tiltUniform ? `tilt x${r.tiltUniform[0] >= 0 ? '+' : ''}${r.tiltUniform[0]}° z${r.tiltUniform[1] >= 0 ? '+' : ''}${r.tiltUniform[1]}°` : 'a tilt exists';
        case 'placement': {
            // A pole-only fix has standoffDeltaMm == -0.0; printing "standoff
            // -0.0 mm" would send an operator to the wrong control entirely.
            const move = [];
            if (r.standoffDeltaMm) move.push(`standoff ${r.standoffDeltaMm > 0 ? '+' : ''}${r.standoffDeltaMm} mm`);
            if (r.poleDeltaMm) move.push(`pole ${r.poleDeltaMm > 0 ? '+' : ''}${r.poleDeltaMm} mm`);
            return move.length ? move.join(', ') : 'already placed correctly';
        }
        case 'branch': return `${r.requiredJointStepDeg}° needed at every resolution`;
        case 'sampling': return r.probe?.corridor ? 'halving the spacing fixes it'
                                                  : `needs ${r.requiredJointStepDeg}° joint step`;
        case 'swivel': return `ring dead at ${r.blockedAt}`;
        case 'unreachable': return `${r.beyondReach} samples, ${r.beyondReachMaxMm} mm beyond`;
        default: return r.minMarginDeg != null && r.minMarginDeg < 5
            ? `margin ${r.minMarginDeg}° — tight` : `margin ${r.minMarginDeg}°`;
        }
    };
    const counts = Object.entries(d.summary?.byFixClass || {})
        .sort((a, b) => ATLAS_FIX_ORDER.indexOf(a[0]) - ATLAS_FIX_ORDER.indexOf(b[0]))
        .map(([k, n]) => `<span class="atlas-key"><i style="background:${tok(ATLAS_FIX_TOKEN[k] || '--atlas-nobranch')}"></i>${k} ${n}</span>`).join('');
    el.innerHTML = `<div class="atlas-legend">${counts}</div>`
        + `<div class="scrollx"><table class="atlas-sweep-table"><thead><tr>`
        + `<th>region</th><th>arm</th><th class="n">free</th><th class="n">margin</th>`
        + `<th>fix</th><th>what to do</th></tr></thead><tbody>`
        + rows.map(r => `<tr data-region="${r.region}" data-arm="${r.arm}">`
            + `<td>${r.region}</td><td>${r.arm}</td>`
            + `<td class="n">${r.freePct == null ? '—' : r.freePct + '%'}</td>`
            + `<td class="n">${r.minMarginDeg == null ? '—' : r.minMarginDeg + '°'}</td>`
            + `<td><span class="atlas-key"><i style="background:${tok(ATLAS_FIX_TOKEN[cls(r)] || '--atlas-nobranch')}"></i>${cls(r)}</span></td>`
            + `<td>${detail(r)}</td></tr>`).join('')
        + `</tbody></table></div>`
        + `<div class="hint">${d.summary.configs} configs at ${d.settings.resampleMm} mm sampling`
        + `${d.settings.includeCollision ? ', collision on' : ', kinematics only'}`
        + `. A "sampling" row is a continuity limit, not geometry; "branch" means finer sampling was tried and did not help.</div>`;
}

// ===== Redundancy Atlas in the viewport ====================================
// The swivel angle is an abstract axis; the ELBOW is where it lives. At each
// waypoint the elbow travels a ring about the shoulder->wrist axis, and every
// point of that ring is one value of psi — so the 2-D chart's vertical axis,
// drawn in space, is a ring hanging between the shoulder and the wrist.
//
// That is why this belongs in the viewport: a wall does not block the contact
// point, it blocks an ARC of this ring, and here you can see which arc and see
// the wall doing it. The rings also shrink to nothing as the arm straightens,
// which is the redundancy running out — a fact no voxel envelope has a
// coordinate for.
//
// elbow(psi) = centre + cos(psi)*A + sin(psi)*B, from per-waypoint vectors sent
// by /api/redundancy-atlas. Verified against forward kinematics to 3 um
// (alix_workspace.srs.SelfMotionFibre.orbit).
//
// WHAT IS DRAWN, and what was tried first. The obvious rendering — every
// (waypoint, swivel) cell as a dot — was built and rejected: 17,000 dots at
// 0.8 opacity bury the free volume inside their own blocked shell, so the one
// thing the operator needs to see is the one thing hidden. What is drawn
// instead is the ANSWER (a swept band of the free swivel run, hemmed on each
// side by whatever closes it) with the evidence available behind a separate
// toggle (the ring cage). Everything is anchored to real geometry — the ring,
// the shoulder, the wall, the porcelain. Nothing has a waypoint-index axis;
// an (s, psi) plot in space would just be the 2-D chart, floating.
const ATLAS_BAND_SAMPLES = 13;        // across the free run; the band is tessellated
const ATLAS_HEM_DEG = 12;             // fixed hem width — it carries colour, not size
const ATLAS_HEM_SAMPLES = 3;
const ATLAS_MAX_CAGE_RINGS = 48;
const ATLAS_CORRIDOR_RADIUS = 0.005;
const ATLAS_LINK_RADIUS = 0.006;
const ATLAS_CURSOR_HALF_WIDTH = 0.004;  // annulus half-thickness, in the ring plane
const ATLAS_COLLAPSE_MM = 12;           // below this the ring is a dot, and that IS the finding

let atlasCursor = 0;                  // which sample the cursor layer is on

function atlasWrap(i, n) { return ((i % n) + n) % n; }

// Signed shortest angular difference, degrees.
function atlasDeltaDeg(a, b) { return ((b - a + 540) % 360) - 180; }

function atlasElbow(data, s, psiDeg) {
    const C = data.orbit?.centre?.[s], A = data.orbit?.a?.[s], B = data.orbit?.b?.[s];
    if (!C || C[0] === null || !A || A[0] === null) return null;
    const t = psiDeg * Math.PI / 180, ct = Math.cos(t), st = Math.sin(t);
    return new THREE.Vector3(C[0] + ct * A[0] + st * B[0],
                             C[1] + ct * A[1] + st * B[1],
                             C[2] + ct * A[2] + st * B[2]);
}

function atlasOrbitRadius(data, s) {
    const A = data.orbit?.a?.[s];
    if (!A || A[0] === null) return null;
    return Math.hypot(A[0], A[1], A[2]);
}

// The renderer outputs sRGB (editor.js sets renderer.outputEncoding), so a hex
// pushed straight into a vertex colour renders LIGHTER than the same hex in the
// legend swatch beside it. Same conversion the fixture materials do.
function atlasToLinear(color) {
    if (color.convertSRGBToLinear) color.convertSRGBToLinear();
    return color;
}

function atlasCellColor(data, s, p, pal, target) {
    const P = data.psiDeg.length;
    const code = data.code[s * P + p];
    const css = code === 0
        ? atlasMix(pal.freeLow, pal.freeHigh,
                   ATLAS_VP_RAMP_FLOOR + (1 - ATLAS_VP_RAMP_FLOOR)
                   * (data.marginDeg[s * P + p] - data.gateDeg) / 45)
        : (pal.codes[code] || pal.codes[3]);
    return atlasToLinear(target.set(css));
}

// The maximal circularly-contiguous run of free swivel at one waypoint, found by
// walking outward from a seed. Returns the run plus the codes that CLOSE it on
// each side — those two codes are the whole diagnosis, and they are what the
// hems are coloured with.
function atlasFreeRun(data, s, seedPsiDeg) {
    const P = data.psiDeg.length, base = s * P;
    let seed = 0, best = 1e9;
    for (let p = 0; p < P; p++) {
        const d = Math.abs(atlasDeltaDeg(data.psiDeg[p], seedPsiDeg));
        if (d < best) { best = d; seed = p; }
    }
    if (data.code[base + seed] !== 0) {          // seed landed in a blocked cell
        let found = -1;
        for (let k = 1; k <= P / 2 && found < 0; k++) {
            if (data.code[base + atlasWrap(seed - k, P)] === 0) found = atlasWrap(seed - k, P);
            else if (data.code[base + atlasWrap(seed + k, P)] === 0) found = atlasWrap(seed + k, P);
        }
        if (found < 0) return null;              // the whole ring is blocked
        seed = found;
    }
    let lo = seed, hi = seed, n = 1;
    while (n < P && data.code[base + atlasWrap(lo - 1, P)] === 0) { lo = atlasWrap(lo - 1, P); n++; }
    while (n < P && data.code[base + atlasWrap(hi + 1, P)] === 0) { hi = atlasWrap(hi + 1, P); n++; }
    let maxMargin = -1;
    for (let k = 0; k < n; k++) maxMargin = Math.max(maxMargin, data.marginDeg[base + atlasWrap(lo + k, P)]);
    return {
        lo, hi, count: n,
        loPsi: data.psiDeg[lo], hiPsi: data.psiDeg[hi],
        widthDeg: n >= P ? 360 : ((data.psiDeg[hi] - data.psiDeg[lo] + 360) % 360),
        loCode: data.code[base + atlasWrap(lo - 1, P)],
        hiCode: data.code[base + atlasWrap(hi + 1, P)],
        maxMargin, centrePsi: data.psiDeg[lo] + ((n >= P ? 360 : ((data.psiDeg[hi] - data.psiDeg[lo] + 360) % 360)) / 2),
        full: n >= P,
    };
}

// Chain the runs along the stroke, seeding each from the one before rather than
// taking the widest. Taking the widest lets the run hop between two disjoint
// free bands at adjacent waypoints, which then draws a TEAR that is an artefact
// of the selection rule and not a property of the stroke.
function atlasChainRuns(data) {
    const S = data.names.length;
    const corr = data.corridor || {};
    let seed = corr.found && corr.psiDeg?.length ? corr.psiDeg[0] : 0;
    if (!corr.found) {                       // no corridor: seed from the widest run at s=0
        let widest = null;
        for (let p = 0; p < data.psiDeg.length; p++) {
            const r = atlasFreeRun(data, 0, data.psiDeg[p]);
            if (r && (!widest || r.widthDeg > widest.widthDeg)) widest = r;
        }
        if (widest) seed = widest.centrePsi;
    }
    const runs = new Array(S).fill(null);
    for (let s = 0; s < S; s++) {
        const r = atlasFreeRun(data, s, corr.found ? corr.psiDeg[s] : seed);
        runs[s] = r;
        if (r) seed = r.centrePsi;
    }
    return runs;
}

// Do two adjacent runs overlap once each is opened by the swivel step? If not,
// no continuous choice of swivel crosses that gap and the band must break there.
function atlasRunsConnect(a, b, stepDeg) {
    if (!a || !b) return false;
    if (a.full || b.full) return true;
    const open = Math.max(0, stepDeg);
    // Circular interval [a.loPsi - open, a.hiPsi + open] vs [b.loPsi, b.hiPsi].
    const inA = psi => {
        const d = (psi - (a.loPsi - open) + 720) % 360;
        return d <= a.widthDeg + 2 * open + 1e-9;
    };
    const inB = psi => ((psi - b.loPsi + 720) % 360) <= b.widthDeg + 1e-9;
    return inA(b.loPsi) || inA(b.hiPsi) || inB(a.loPsi) || inB(a.hiPsi);
}

// A tube with EXACT station->waypoint mapping and per-station colour. Not
// THREE.TubeGeometry: that samples the curve by arc length, so its stations do
// not line up with the waypoints the colours belong to, and it bunches them
// worst near a singularity — precisely the cinch the colour is there to find.
function atlasTubeRibbon(points, radius, colors, sides) {
    sides = sides || 6;
    const n = points.length;
    const pos = [], col = [];
    const tangents = [], normals = [];
    for (let i = 0; i < n; i++) {
        const a = points[Math.max(0, i - 1)], b = points[Math.min(n - 1, i + 1)];
        const t = new THREE.Vector3().subVectors(b, a);
        if (t.lengthSq() < 1e-18) t.set(0, 0, 1);
        tangents.push(t.normalize());
    }
    let ref = new THREE.Vector3(0, 0, 1);
    if (Math.abs(ref.dot(tangents[0])) > 0.9) ref = new THREE.Vector3(1, 0, 0);
    let nrm = new THREE.Vector3().crossVectors(tangents[0], ref).normalize();
    for (let i = 0; i < n; i++) {
        if (i > 0) {
            // Parallel transport: rotate the frame by the tangent-to-tangent turn,
            // so the tube does not spin about its own axis between stations.
            const axis = new THREE.Vector3().crossVectors(tangents[i - 1], tangents[i]);
            const sinA = axis.length();
            if (sinA > 1e-9) {
                const ang = Math.atan2(sinA, tangents[i - 1].dot(tangents[i]));
                nrm = atlasRotateAbout(nrm, axis.normalize(), ang);
            }
            nrm = nrm.sub(tangents[i].clone().multiplyScalar(nrm.dot(tangents[i]))).normalize();
        }
        const bin = new THREE.Vector3().crossVectors(tangents[i], nrm).normalize();
        const ring = [];
        for (let k = 0; k < sides; k++) {
            const th = (k / sides) * Math.PI * 2;
            ring.push(new THREE.Vector3()
                .copy(points[i])
                .add(nrm.clone().multiplyScalar(Math.cos(th) * radius))
                .add(bin.clone().multiplyScalar(Math.sin(th) * radius)));
        }
        normals.push(ring);
    }
    for (let i = 0; i + 1 < n; i++) {
        for (let k = 0; k < sides; k++) {
            const k2 = (k + 1) % sides;
            const p00 = normals[i][k], p01 = normals[i][k2];
            const p10 = normals[i + 1][k], p11 = normals[i + 1][k2];
            const c0 = colors[i], c1 = colors[i + 1];
            [[p00, c0], [p10, c1], [p11, c1], [p00, c0], [p11, c1], [p01, c0]].forEach(([v, cc]) => {
                pos.push(v.x, v.y, v.z); col.push(cc.r, cc.g, cc.b);
            });
        }
    }
    const geom = new THREE.BufferGeometry();
    geom.setAttribute('position', new THREE.BufferAttribute(new Float32Array(pos), 3));
    geom.setAttribute('color', new THREE.BufferAttribute(new Float32Array(col), 3));
    return geom;
}

function atlasRotateAbout(v, axis, ang) {
    const c = Math.cos(ang), s = Math.sin(ang);
    const cross = new THREE.Vector3().crossVectors(axis, v);
    return v.clone().multiplyScalar(c)
        .add(cross.multiplyScalar(s))
        .add(axis.clone().multiplyScalar(axis.dot(v) * (1 - c)));
}

// --- A. the whole stroke: the free band, hemmed by what closes it -----------
function buildAtlasBand(data, pal) {
    if (!atlasBandGroup) return;
    clearGroup(atlasBandGroup);
    const S = data.names.length;
    const runs = atlasChainRuns(data);
    const step = data.corridor?.maxSwivelStepDeg || 15;
    const pos = [], col = [];
    const cFree = new THREE.Color(), cHem = new THREE.Color();

    // One column of samples per waypoint: the free run tessellated onto the true
    // ring (never chorded), so the band lies ON the orbit family and foreshortens
    // honestly instead of floating inside it.
    const column = s => {
        const r = runs[s];
        if (!r) return null;
        const out = {pts: [], loHem: [], hiHem: [], run: r};
        for (let k = 0; k < ATLAS_BAND_SAMPLES; k++) {
            const psi = r.loPsi + (r.widthDeg * k) / (ATLAS_BAND_SAMPLES - 1);
            const e = atlasElbow(data, s, psi);
            if (!e) return null;
            out.pts.push(e);
        }
        for (let k = 0; k < ATLAS_HEM_SAMPLES; k++) {
            const t = k / (ATLAS_HEM_SAMPLES - 1);
            out.loHem.push(atlasElbow(data, s, r.loPsi - ATLAS_HEM_DEG * (1 - t)));
            out.hiHem.push(atlasElbow(data, s, r.hiPsi + ATLAS_HEM_DEG * t));
        }
        if (out.loHem.some(p => !p) || out.hiHem.some(p => !p)) return null;
        return out;
    };

    const quad = (a, b, c, d, ca, cb) => {
        [[a, ca], [b, cb], [c, cb], [a, ca], [c, cb], [d, ca]].forEach(([v, cc]) => {
            pos.push(v.x, v.y, v.z); col.push(cc.r, cc.g, cc.b);
        });
    };

    let prev = column(0);
    for (let s = 1; s < S; s++) {
        const cur = column(s);
        // A tear: no continuous choice of swivel gets from one waypoint to the
        // next. Drawn by simply not emitting the quads, so the gap sits exactly
        // where the stroke loses continuity.
        if (prev && cur && atlasRunsConnect(prev.run, cur.run, step)) {
            atlasToLinear(cFree.set(atlasMix(pal.freeLow, pal.freeHigh,
                (prev.run.maxMargin - data.gateDeg) / 45)));
            const cFree2 = atlasToLinear(new THREE.Color(atlasMix(pal.freeLow, pal.freeHigh,
                (cur.run.maxMargin - data.gateDeg) / 45)));
            for (let k = 0; k + 1 < ATLAS_BAND_SAMPLES; k++) {
                quad(prev.pts[k], cur.pts[k], cur.pts[k + 1], prev.pts[k + 1], cFree, cFree2);
            }
            // The hems carry the diagnosis: the colour of whatever closes the run
            // on that side. Their 12 deg width is fixed on purpose — it is not a
            // measurement, and a finer swivel step must not make it thinner.
            [['loHem', 'loCode'], ['hiHem', 'hiCode']].forEach(([key, codeKey]) => {
                atlasToLinear(cHem.set(pal.codes[prev.run[codeKey]] || pal.codes[3]));
                const cHem2 = atlasToLinear(new THREE.Color(pal.codes[cur.run[codeKey]] || pal.codes[3]));
                for (let k = 0; k + 1 < ATLAS_HEM_SAMPLES; k++) {
                    quad(prev[key][k], cur[key][k], cur[key][k + 1], prev[key][k + 1], cHem, cHem2);
                }
            });
        }
        prev = cur;
    }

    if (pos.length) {
        const geom = new THREE.BufferGeometry();
        geom.setAttribute('position', new THREE.BufferAttribute(new Float32Array(pos), 3));
        geom.setAttribute('color', new THREE.BufferAttribute(new Float32Array(col), 3));
        const mesh = new THREE.Mesh(geom, new THREE.MeshBasicMaterial({
            vertexColors: true, side: THREE.DoubleSide, transparent: true,
            opacity: 0.4, depthWrite: false,
        }));
        // depthTest stays ON — unlike most overlays in this file. The whole
        // argument for putting the atlas in the viewport is that you can watch a
        // wall eat the arc it blocks; drawing the band through the wall would
        // throw exactly that away.
        mesh.material.depthTest = true;
        mesh.renderOrder = 990;
        mesh.name = 'atlas free band';
        atlasBandGroup.add(mesh);
    }

    buildAtlasCorridor(data, pal);
    atlasBandGroup.visible = document.getElementById('atlas3dToggle')?.checked ?? true;
}

// The corridor: where the elbow will actually be. Coloured per station by its
// own margin, so the place it CINCHES is visible, and cut into separate runs at
// every branch change — a branch flip is a discontinuous joint motion and must
// never be drawn as a smooth curve through space.
function buildAtlasCorridor(data, pal) {
    const S = data.names.length;
    const corr = data.corridor || {};
    if (!corr.found || corr.psiDeg?.length !== S) {
        if (corr.blockedAt >= 0 && corr.blockedAt < S) {
            const tp = data.toolPos?.[corr.blockedAt];
            if (tp && tp[0] !== null) {
                const mark = new THREE.Mesh(
                    new THREE.SphereGeometry(0.012, 16, 12),
                    new THREE.MeshBasicMaterial({color: atlasToLinear(new THREE.Color(pal.blocked))}));
                mark.position.set(tp[0], tp[1], tp[2]);
                mark.renderOrder = 992;
                mark.name = `atlas: corridor blocked at ${data.names[corr.blockedAt]}`;
                atlasBandGroup.add(mark);
            }
        }
        return;
    }
    const P = data.psiDeg.length;
    let run = [], runCol = [], runStart = 0;
    const flush = (endS) => {
        if (run.length > 1) {
            const mesh = new THREE.Mesh(
                atlasTubeRibbon(run, ATLAS_CORRIDOR_RADIUS, runCol, 6),
                new THREE.MeshBasicMaterial({vertexColors: true}));
            mesh.renderOrder = 992;
            mesh.name = `atlas corridor (elbow path) ${data.names[runStart]}..${data.names[endS]}`;
            atlasBandGroup.add(mesh);
        }
        run = []; runCol = [];
    };
    for (let s = 0; s < S; s++) {
        const e = atlasElbow(data, s, corr.psiDeg[s]);
        if (!e) { flush(s - 1); runStart = s + 1; continue; }
        const branchChanged = s > 0 && corr.branch && corr.branch[s] !== corr.branch[s - 1];
        if (branchChanged) {
            flush(s - 1);
            runStart = s;
            const notch = new THREE.Mesh(
                new THREE.SphereGeometry(0.009, 12, 8),
                new THREE.MeshBasicMaterial({color: atlasToLinear(new THREE.Color(pal.codes[3]))}));
            notch.position.copy(e);
            notch.renderOrder = 993;
            notch.name = `atlas branch flip at ${data.names[s]} (${corr.branch[s - 1]} -> ${corr.branch[s]})`;
            atlasBandGroup.add(notch);
        }
        if (!run.length) runStart = s;
        run.push(e);
        // Margin of the cell the corridor actually sits in, so the tube reddens
        // where the corridor is about to close.
        let p = 0, best = 1e9;
        for (let k = 0; k < P; k++) {
            const d = Math.abs(atlasDeltaDeg(data.psiDeg[k], corr.psiDeg[s]));
            if (d < best) { best = d; p = k; }
        }
        const m = data.marginDeg[s * P + p];
        runCol.push(atlasToLinear(new THREE.Color(
            atlasMix(pal.blocked, pal.corridor, (m - data.gateDeg) / 30))));
    }
    flush(S - 1);
}

// --- B. the evidence behind the band: every ring, hairline, opt-in ----------
// One merged LineSegments for the whole stroke: chords between consecutive
// swivel samples, both ends of a chord carrying the same colour so cell
// boundaries stay hard (the 2-D canvas paints hard rects; a gradient here would
// be a different claim). Hairline on purpose — r128 has no Line2, `linewidth`
// is a no-op, and a fat cage would hide the band it is evidence for.
function buildAtlasRings(data, pal) {
    if (!atlasRingGroup) return;
    clearGroup(atlasRingGroup);
    const S = data.names.length, P = data.psiDeg.length;
    const stride = Math.max(1, Math.ceil(S / ATLAS_MAX_CAGE_RINGS));
    const forced = new Set([atlasCursor, data.corridor?.blockedAt]);
    (data.summary?.deadWaypoints || []).forEach(s => forced.add(s));
    const pos = [], col = [], c = new THREE.Color();
    let drawn = 0;
    for (let s = 0; s < S; s++) {
        if (s % stride !== 0 && !forced.has(s)) continue;
        if (atlasOrbitRadius(data, s) === null) continue;
        drawn++;
        for (let p = 0; p < P; p++) {
            const a = atlasElbow(data, s, data.psiDeg[p]);
            const b = atlasElbow(data, s, data.psiDeg[atlasWrap(p + 1, P)]);
            if (!a || !b) continue;
            atlasCellColor(data, s, p, pal, c);
            pos.push(a.x, a.y, a.z, b.x, b.y, b.z);
            col.push(c.r, c.g, c.b, c.r, c.g, c.b);
        }
    }
    if (pos.length) {
        const geom = new THREE.BufferGeometry();
        geom.setAttribute('position', new THREE.BufferAttribute(new Float32Array(pos), 3));
        geom.setAttribute('color', new THREE.BufferAttribute(new Float32Array(col), 3));
        const cage = new THREE.LineSegments(geom, new THREE.LineBasicMaterial({
            vertexColors: true, transparent: true, opacity: 0.5, depthWrite: false,
        }));
        cage.material.depthTest = true;
        cage.renderOrder = 994;
        cage.name = `atlas ring cage (${drawn} of ${S} rings)`;
        atlasRingGroup.add(cage);
    }
    // A ring that has shrunk to a dot is not a small ring — it is the redundancy
    // exhausted because the arm straightened, and it must not read as "no data".
    const beadMat = new THREE.MeshBasicMaterial({color: atlasToLinear(new THREE.Color(pal.codes[5]))});
    for (let s = 0; s < S; s += stride) {
        const r = atlasOrbitRadius(data, s);
        if (r === null || r * 1000 >= 8) continue;
        const e = atlasElbow(data, s, 0);
        if (!e) continue;
        const bead = new THREE.Mesh(new THREE.SphereGeometry(0.006, 10, 8), beadMat);
        bead.position.copy(e);
        bead.name = `${data.names[s]}: orbit ${(r * 1000).toFixed(1)} mm — swivel moves the elbow almost nowhere`;
        atlasRingGroup.add(bead);
    }
    atlasRingGroup.visible = document.getElementById('atlasRingsToggle')?.checked ?? false;
}

// --- C. the cursor waypoint, drawn as the mechanism it is -------------------
function atlasFixClass(data, s) {
    const P = data.psiDeg.length;
    const maxReach = data.summary?.maxReachMm;
    const d = data.wristDistanceMm?.[s];
    if (maxReach != null && d != null && d > maxReach) return 'reach';
    let free = 0;
    for (let p = 0; p < P; p++) if (data.code[s * P + p] === 0) free++;
    if (!free) return 'ring-dead';
    const corr = data.corridor || {};
    // The server says WHICH failure. "dead" and "step" need opposite fixes —
    // a standoff/pole/other-arm decision versus a sampling or continuity-limit
    // one — and inferring it from the prose reason would be guessing.
    if (!corr.found && s === corr.blockedAt) {
        return corr.blockedKind === 'step' ? 'continuity' : 'ring-dead';
    }
    return 'clear';
}

// Which waypoint the operator most needs to look at.
function atlasCulprit(data) {
    const corr = data.corridor || {};
    if (!corr.found && corr.blockedAt >= 0) return corr.blockedAt;
    const S = data.names.length, P = data.psiDeg.length;
    if (!corr.found || corr.psiDeg?.length !== S) return 0;
    let best = 1e9, at = 0;
    for (let s = 0; s < S; s++) {
        let p = 0, d0 = 1e9;
        for (let k = 0; k < P; k++) {
            const d = Math.abs(atlasDeltaDeg(data.psiDeg[k], corr.psiDeg[s]));
            if (d < d0) { d0 = d; p = k; }
        }
        const m = data.marginDeg[s * P + p];
        if (m < best) { best = m; at = s; }
    }
    return at;
}

function buildAtlasCursor(data, pal, s) {
    if (!atlasSelGroup) return;
    clearGroup(atlasSelGroup);
    const S = data.names.length, P = data.psiDeg.length;
    if (s < 0 || s >= S) return;
    const radius = atlasOrbitRadius(data, s);
    const corr = data.corridor || {};
    const psi = (corr.found && corr.psiDeg?.length === S) ? corr.psiDeg[s] : null;

    if (radius !== null && radius * 1000 >= ATLAS_COLLAPSE_MM) {
        // The ring at full swivel resolution, as an ANNULUS in the ring's own
        // plane: scaling A and B keeps it exactly in that plane, so it needs no
        // normal and cannot tilt out of the orbit. Width is what lets it survive
        // being seen edge-on, which a line cannot do without Line2.
        const A = data.orbit.a[s], B = data.orbit.b[s], C = data.orbit.centre[s];
        const kIn = (radius - ATLAS_CURSOR_HALF_WIDTH) / radius;
        const kOut = (radius + ATLAS_CURSOR_HALF_WIDTH) / radius;
        const at = (p, k) => {
            const t = data.psiDeg[p] * Math.PI / 180, ct = Math.cos(t) * k, st = Math.sin(t) * k;
            return new THREE.Vector3(C[0] + ct * A[0] + st * B[0],
                                     C[1] + ct * A[1] + st * B[1],
                                     C[2] + ct * A[2] + st * B[2]);
        };
        const pos = [], col = [], c = new THREE.Color();
        for (let p = 0; p < P; p++) {
            const q = atlasWrap(p + 1, P);
            const i0 = at(p, kIn), o0 = at(p, kOut), i1 = at(q, kIn), o1 = at(q, kOut);
            atlasCellColor(data, s, p, pal, c);   // one colour for the whole arc: hard cell edges
            [i0, o0, o1, i0, o1, i1].forEach(v => { pos.push(v.x, v.y, v.z); col.push(c.r, c.g, c.b); });
        }
        const geom = new THREE.BufferGeometry();
        geom.setAttribute('position', new THREE.BufferAttribute(new Float32Array(pos), 3));
        geom.setAttribute('color', new THREE.BufferAttribute(new Float32Array(col), 3));
        const ring = new THREE.Mesh(geom, new THREE.MeshBasicMaterial({
            vertexColors: true, side: THREE.DoubleSide, transparent: true, opacity: 0.95,
            depthTest: false, depthWrite: false,
        }));
        ring.renderOrder = 999;
        ring.name = `atlas ring at ${data.names[s]}`;
        atlasSelGroup.add(ring);
    } else if (radius !== null) {
        const e = atlasElbow(data, s, 0);
        if (e) {
            const disc = new THREE.Mesh(
                new THREE.SphereGeometry(0.0075, 14, 10),
                new THREE.MeshBasicMaterial({color: atlasToLinear(new THREE.Color(pal.codes[5])),
                                             depthTest: false}));
            disc.position.copy(e);
            disc.renderOrder = 999;
            disc.name = `${data.names[s]}: orbit ${(radius * 1000).toFixed(1)} mm — redundancy exhausted`;
            atlasSelGroup.add(disc);
        }
    }

    // shoulder -> elbow -> wrist -> TOOL. The last segment is what stops the ring
    // being a hoop floating 300 mm off the shoulder with no visible relation to
    // the spot on the porcelain being cleaned.
    const sh = data.shoulder, wc = data.wristCentre?.[s], tp = data.toolPos?.[s];
    const elbow = psi === null ? null : atlasElbow(data, s, psi);
    if (elbow && sh && wc && wc[0] !== null) {
        const mat = new THREE.MeshBasicMaterial({
            color: atlasToLinear(new THREE.Color(pal.corridor)), depthTest: false});
        const nodes = [new THREE.Vector3(sh[0], sh[1], sh[2]), elbow,
                       new THREE.Vector3(wc[0], wc[1], wc[2])];
        if (tp && tp[0] !== null) nodes.push(new THREE.Vector3(tp[0], tp[1], tp[2]));
        const radii = [ATLAS_LINK_RADIUS, ATLAS_LINK_RADIUS, ATLAS_LINK_RADIUS * 0.65];
        const names = ['upper arm', 'forearm', 'wrist to tool'];
        for (let i = 0; i + 1 < nodes.length; i++) {
            const cc = [atlasToLinear(new THREE.Color(pal.corridor)),
                        atlasToLinear(new THREE.Color(pal.corridor))];
            const seg = new THREE.Mesh(
                atlasTubeRibbon([nodes[i], nodes[i + 1]], radii[i], cc, 8),
                new THREE.MeshBasicMaterial({vertexColors: true, depthTest: false}));
            seg.renderOrder = 999;
            seg.name = `atlas ${names[i]}`;
            atlasSelGroup.add(seg);
        }
        const bead = new THREE.Mesh(new THREE.SphereGeometry(ATLAS_LINK_RADIUS * 1.8, 14, 10), mat);
        bead.position.copy(elbow);
        bead.renderOrder = 1000;
        bead.name = `atlas elbow at psi ${psi.toFixed(0)} deg`;
        atlasSelGroup.add(bead);
    }

    // The fix class, as a disc lying on the fixture: which DAY of work this is.
    if (tp && tp[0] !== null) {
        const cls = atlasFixClass(data, s);
        const token = {reach: 1, 'ring-dead': 5, continuity: 3, clear: 0}[cls];
        const css = cls === 'clear' ? pal.freeHigh : (pal.codes[token] || pal.blocked);
        const pin = new THREE.Mesh(
            new THREE.SphereGeometry(0.007, 14, 10),
            new THREE.MeshBasicMaterial({color: atlasToLinear(new THREE.Color(css)), depthTest: false}));
        pin.position.set(tp[0], tp[1], tp[2]);
        pin.renderOrder = 1000;
        pin.name = `${data.names[s]}: ${cls}`;
        atlasSelGroup.add(pin);
    }

    // Beyond reach: a stub whose LENGTH is the millimetres. Not "blocked" —
    // too short, which is a standoff / pole / other-arm decision and no amount
    // of path geometry touches it.
    const R = (data.geometry?.maxWristReachM) || (data.summary?.maxReachMm || 466) / 1000;
    const d = data.wristDistanceMm?.[s];
    if (sh && wc && wc[0] !== null && d != null && d > R * 1000) {
        const S3 = new THREE.Vector3(sh[0], sh[1], sh[2]);
        const W3 = new THREE.Vector3(wc[0], wc[1], wc[2]);
        const u = new THREE.Vector3().subVectors(W3, S3).normalize();
        const from = S3.clone().add(u.clone().multiplyScalar(R));
        const cc = [atlasToLinear(new THREE.Color(pal.codes[1])),
                    atlasToLinear(new THREE.Color(pal.codes[1]))];
        const stub = new THREE.Mesh(
            atlasTubeRibbon([from, W3], 0.005, cc, 8),
            new THREE.MeshBasicMaterial({vertexColors: true, depthTest: false}));
        stub.renderOrder = 1000;
        stub.name = `${data.names[s]}: +${(d - R * 1000).toFixed(1)} mm beyond the wrist ball`;
        atlasSelGroup.add(stub);
    }
}

// --- D. the reach dome ------------------------------------------------------
// A CAP, not a sphere. A full 466 mm wireframe ball centred on the shoulder
// encloses the camera as well as the work, so it reads as fog over the whole
// scene rather than as a boundary. The cap covers the directions the stroke
// actually visits, which is where the boundary means anything.
function buildAtlasDome(data) {
    if (!atlasBallGroup) return;
    clearGroup(atlasBallGroup);
    const sh = data?.shoulder;
    if (!sh) return;
    const pal = atlasPalette();
    const S3 = new THREE.Vector3(sh[0], sh[1], sh[2]);
    // The arm's OWN radius, from the geometry it reported — never a literal.
    const R = data.geometry?.maxWristReachM || (data.summary?.maxReachMm || 466) / 1000;
    // And the gate shell from the gate that was actually used: d(theta) =
    // sqrt(a^2 + b^2 + 2ab cos theta). Subtracting a hard-coded 7.01 mm bakes in
    // the 20 deg answer and silently lies whenever gateDeg is set to anything else.
    // The server always reports gateDeg (review D5 dropped the dead `|| 20`); a
    // reply without one draws no shell rather than the vendor's.
    const a = data.geometry?.upperArmM, b = data.geometry?.forearmM;
    const gateDeg = Number(data.gateDeg);
    const gateR = (a && b && Number.isFinite(gateDeg))
        ? Math.sqrt(a * a + b * b + 2 * a * b * Math.cos(gateDeg * Math.PI / 180))
        : null;

    const dirs = (data.wristCentre || [])
        .filter(w => w && w[0] !== null)
        .map(w => new THREE.Vector3(w[0], w[1], w[2]).sub(S3).normalize());
    let axis = new THREE.Vector3(1, 0, 0), half = Math.PI / 2;
    if (dirs.length) {
        axis = dirs.reduce((acc, d) => acc.add(d), new THREE.Vector3()).normalize();
        const spread = dirs.reduce((m, d) => Math.max(m, Math.acos(Math.min(1, Math.max(-1, d.dot(axis))))), 0);
        half = Math.min(Math.PI / 2, Math.max(Math.PI / 6, spread + 20 * Math.PI / 180));
    }
    const orient = mesh => {
        if (mesh.quaternion?.setFromUnitVectors) {
            mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), axis);
        }
        mesh.position.copy(S3);
    };

    const cap = new THREE.Mesh(
        new THREE.SphereGeometry(R, 48, 24, 0, Math.PI * 2, 0, half),
        new THREE.MeshBasicMaterial({color: atlasToLinear(new THREE.Color(pal.codes[1])),
                                     transparent: true, opacity: 0.10, side: THREE.DoubleSide,
                                     depthWrite: false}));
    orient(cap);
    cap.name = `wrist ball (${(R * 1000).toFixed(1)} mm)`;
    atlasBallGroup.add(cap);

    if (gateR !== null) {
        const shell = new THREE.Mesh(
            new THREE.SphereGeometry(gateR, 48, 24, 0, Math.PI * 2, 0, half),
            new THREE.MeshBasicMaterial({color: atlasToLinear(new THREE.Color(pal.codes[5])), wireframe: true,
                                         transparent: true, opacity: 0.18}));
        orient(shell);
        shell.name = `straight-elbow gate shell at ${gateDeg} deg (${data.gateSource || 'gate'}) `
                   + `(${(gateR * 1000).toFixed(2)} mm, ${((R - gateR) * 1000).toFixed(2)} mm inside)`;
        atlasBallGroup.add(shell);
    }

    // The INNER shell: the wrist centre cannot get closer to the shoulder than
    // |a - b| either (the elbow is fully folded there). Rarely the binding
    // constraint, but a shell drawn with only one surface invites the reading
    // that everything inside it is reachable.
    if (a && b) {
        const inner = Math.abs(a - b);
        const fold = new THREE.Mesh(
            new THREE.SphereGeometry(inner, 24, 16),
            new THREE.MeshBasicMaterial({color: atlasToLinear(new THREE.Color(pal.codes[4])),
                                         wireframe: true, transparent: true, opacity: 0.22}));
        fold.position.copy(S3);
        fold.name = `folded-elbow shell (${(inner * 1000).toFixed(1)} mm — the wrist cannot come closer)`;
        atlasBallGroup.add(fold);
    }

    // --- the placement shells: where the shoulder would have to be -----------
    // The reach failure's fix class is "standoff, pole or the other arm", and
    // these two objects turn that into something you can look at. The LINE is
    // where the shoulder can actually go (the pole's 315 mm of travel, at this
    // standoff), coloured by whether the whole stroke reaches from there. The
    // BALL is where it would have to be for the binding waypoint. If the line
    // misses the ball, the pole cannot fix it and the robot has to move — which
    // is exactly the case on toplid_right, and exactly the thing an operator
    // otherwise spends a day discovering.
    const place = data.placement;
    if (place && !place.error) {
        const line = place.poleLine || [];
        const avail = line.filter(x => x.available);
        if (avail.length > 1) {
            const baseZ = sh[2] - (data.poleM || 0);
            const pts = [], cols = [];
            avail.forEach(x => {
                pts.push(new THREE.Vector3(sh[0], sh[1], baseZ + x.poleM));
                cols.push(atlasToLinear(new THREE.Color(x.ok ? pal.freeHigh : pal.blocked)));
            });
            const poleTube = new THREE.Mesh(
                atlasTubeRibbon(pts, 0.006, cols, 8),
                new THREE.MeshBasicMaterial({vertexColors: true}));
            poleTube.renderOrder = 995;
            const okCount = avail.filter(x => x.ok).length;
            poleTube.name = `pole travel — shoulder positions available (${okCount} of `
                          + `${avail.length} reach the whole stroke)`;
            atlasBallGroup.add(poleTube);
        }
        const bw = place.bindingWrist;
        if (bw && bw.length === 3) {
            const need = new THREE.Mesh(
                new THREE.SphereGeometry(R, 40, 26),
                new THREE.MeshBasicMaterial({color: atlasToLinear(new THREE.Color(pal.corridor)),
                                             wireframe: true, transparent: true, opacity: 0.14}));
            need.position.set(bw[0], bw[1], bw[2]);
            need.name = `shoulder must be inside this to reach ${place.bindingWaypointName || 'the binding waypoint'}`;
            atlasBallGroup.add(need);
            const mark = new THREE.Mesh(
                new THREE.SphereGeometry(0.008, 12, 8),
                new THREE.MeshBasicMaterial({color: atlasToLinear(new THREE.Color(pal.corridor))}));
            mark.position.copy(need.position);
            mark.name = `${place.bindingWaypointName || 'binding'}: wrist centre — the constraint`;
            atlasBallGroup.add(mark);
        }
    }

    const mat = new THREE.MeshBasicMaterial({color: atlasToLinear(new THREE.Color(pal.codes[1]))});
    (data.wristCentre || []).forEach((w, s) => {
        if (!w || w[0] === null) return;
        const dd = data.wristDistanceMm?.[s];
        if (dd == null || dd <= R * 1000) return;
        const m = new THREE.Mesh(new THREE.SphereGeometry(0.009, 12, 8), mat);
        m.position.set(w[0], w[1], w[2]);
        m.name = `${data.names[s]}: wrist centre ${dd.toFixed(1)} mm — `
               + `${(dd - R * 1000).toFixed(1)} mm beyond reach`;
        atlasBallGroup.add(m);
    });
    atlasBallGroup.visible = document.getElementById('atlasBallToggle')?.checked ?? false;
}

// --- orchestration ----------------------------------------------------------
function renderAtlas3D(data) {
    if (!atlasBandGroup) return;
    if (!data || !data.orbit) { clearGroup(atlasBandGroup); renderScene(); return; }
    const pal = atlasPalette();
    atlasCursor = atlasCulprit(data);
    buildAtlasBand(data, pal);
    buildAtlasRings(data, pal);
    buildAtlasCursor(data, pal, atlasCursor);
    buildAtlasDome(data);
    renderScene();
}

// Which atlas sample belongs to the point the operator has selected. The atlas
// resamples the stroke to even arc length, so a sample index is NOT a point
// index — each sample carries the name of its nearest authored waypoint. When
// the selected point is not in the analysed stroke at all (a different band, or
// a point added since Compute) fall back to the nearest sample by position,
// rather than letting the cursor silently vanish.
function atlasSamplesForSelection(data) {
    const sel = state.points?.[state.selectedIndex];
    if (!sel || !data?.names) return [];
    const out = [];
    if (sel.name) data.names.forEach((n, s) => { if (n === sel.name) out.push(s); });
    if (out.length) return out;
    const xyz = sel.world || sel.position || null;
    if (!xyz || !data.toolPos) return [];
    let best = 1e9, at = -1;
    data.toolPos.forEach((t, s) => {
        if (!t || t[0] === null) return;
        const d = (t[0] - xyz[0]) ** 2 + (t[1] - xyz[1]) ** 2 + (t[2] - xyz[2]) ** 2;
        if (d < best) { best = d; at = s; }
    });
    return at >= 0 ? [at] : [];
}

// Selection moved: only the cursor layer changes, so the band and the cage —
// which are the whole stroke and much larger — are left alone.
function refreshAtlasSelection() {
    if (!lastAtlas || !atlasBandGroup?.visible) return;
    const samples = atlasSamplesForSelection(lastAtlas);
    if (!samples.length) return;
    atlasCursor = samples[Math.floor(samples.length / 2)];
    buildAtlasCursor(lastAtlas, atlasPalette(), atlasCursor);
    renderScene();
}

function toggleAtlas3D(on) {
    if (on && !lastAtlas) { computeRedundancyAtlas(); return; }
    if (atlasBandGroup) atlasBandGroup.visible = on;
    if (atlasSelGroup) atlasSelGroup.visible = on;
    renderScene();
}

function toggleAtlasRings(on) {
    if (on && !lastAtlas) { computeRedundancyAtlas(); return; }
    if (on && lastAtlas && !atlasRingGroup?.children.length) buildAtlasRings(lastAtlas, atlasPalette());
    if (atlasRingGroup) atlasRingGroup.visible = on;
    renderScene();
}

function toggleAtlasBall(on) {
    if (on && !lastAtlas) { computeRedundancyAtlas(); return; }
    if (on && lastAtlas && !atlasBallGroup?.children.length) buildAtlasDome(lastAtlas);
    if (atlasBallGroup) atlasBallGroup.visible = on;
    renderScene();
}

// Clicking a cell poses the robot overlay in exactly that configuration — the
// atlas already knows the joint values, so nothing is re-solved. This is the
// point of the panel being inside the Studio rather than a report: a blocked
// cell becomes a robot you can look at from any angle.
async function atlasCellFromEvent(event) {
    const canvas = document.getElementById('atlasCanvas');
    if (!canvas || !lastAtlas || !canvas.dataset.geom) return null;
    const geom = JSON.parse(canvas.dataset.geom);
    const rect = canvas.getBoundingClientRect();
    const x = (event.clientX - rect.left) * (canvas.width / rect.width);
    const y = (event.clientY - rect.top) * (canvas.height / rect.height);
    const s = Math.floor((x - geom.padL) / geom.cw);
    const p = Math.floor((geom.padT + geom.H - y) / geom.ch);
    if (s < 0 || s >= geom.S || p < 0 || p >= geom.P) return null;
    return {s, p};
}

async function onAtlasClick(event) {
    const cell = await atlasCellFromEvent(event);
    if (!cell || !lastAtlas) return;
    const {s, p} = cell;
    const code = lastAtlas.code[s * lastAtlas.psiDeg.length + p];
    const label = (lastAtlas.codeLabels || {})[code] || ('code ' + code);
    const name = lastAtlas.names[s] ?? ('waypoint ' + s);
    const psi = lastAtlas.psiDeg[p];
    if (code !== 0) {
        setStatus(`${name} at ψ=${psi}°: ${label}. Nothing to pose — no configuration exists there.`, true);
        return;
    }
    // Only the corridor carries joint values (the full cube would be a
    // megabyte of JSON per layer), so a click off the corridor reports the cell
    // rather than pretending to pose it.
    const c = lastAtlas.corridor || {};
    if (!c.found || !lastAtlas.corridorJointsDeg?.length) {
        setStatus(`${name} at ψ=${psi}°: free (margin ${lastAtlas.marginDeg[s * lastAtlas.psiDeg.length + p]}°).`);
        return;
    }
    try {
        const r = await api('/api/atlas-pose', {method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jointsDeg: lastAtlas.corridorJointsDeg[s], arm: lastAtlas.arm,
                                  tipFrame: lastAtlas.ikFrame, poleM: lastAtlas.poleM})});
        if (r.error) { setStatus('Atlas pose: ' + r.error, true); return; }
        if (!robotGeometryLoaded) await loadRobotGeometry('visual');
        robotGroup.visible = true;
        applyRobotPose(r.pose);
        setStatus(`${name}: posed at the corridor's ψ=${c.psiDeg[s]}° (branch ${c.branch[s]}). Clicked ψ=${psi}°.`);
    } catch (e) {
        setStatus('Atlas pose failed: ' + e.message, true);
    }
}

async function resetAtlasPose() {
    try {
        const d = await api('/api/robot-geometry?set=visual');
        if (!d.error) applyRobotPose(d.homePose);
        setStatus('Robot overlay returned to its home pose.');
    } catch (e) { setStatus('Reset pose failed: ' + e.message, true); }
}

// ===== Kinematics solver: per-point IK feasibility + robot/fixture collision ==
// Reuses the ROS/MoveIt-free alix_workspace IK + collision (/api/ik). The
// selected cleaning point's world pose (base_link) is the IK target; the result
// tints the point marker and paints colliding fixture faces red.
const collisionPaintedMeshes = new Set();   // mesh objects currently red-painted

// ===== THE SIDE, decided in ONE place =================================
// Newton 2026-09-10: "a left side task will only use the left side states (pole
// position, hand poses) and the left side frames, and left side gizmos".
//
// It did not. The side was answered independently in four places - `studio.arm`
// (the Generate toggle), `state.task.arm` (the bound task and the breadcrumb),
// `ikArmFromFrame()` (the loaded FILENAME, then the config's ik_frame) and
// `viewerArmPrefix()` - and they were free to disagree. Measured consequence,
// from Newton's screenshot: a right-arm config loaded, the panel switched to
// Left with `L_glove_frame_2` selected, and every IK call still went to the
// RIGHT arm because `state.fileName` still said "..._right". Verify then
// reported "start NOT reachable" - a true answer to a question nobody asked.
//
// `state.task.arm` is the authority because it is the one the operator can SEE:
// it is what the breadcrumb prints. The Generate toggle now writes it (see
// `setStudioArm`), so the header, the frames, the hand state and the gizmos
// move together or not at all.
function activeArm() {
    if (state.task && state.task.arm) return state.task.arm;
    if (typeof studio !== 'undefined' && studio && studio.arm) return studio.arm;
    return ikArmFromFile();
}

function armPrefix() { return activeArm() === 'left' ? 'L_' : 'R_'; }

// The old resolution, kept as the LAST resort: with no task bound and no panel
// state, a loaded config's filename is still the best signal there is (a `_left`
// task analyses on the left even if an `R_` frame was left in it by a bad
// mirror). A fallback now, not the answer.
function ikArmFromFile() {
    const name = (state.fileName || '').toLowerCase();
    if (name.includes('_left')) return 'left';
    if (name.includes('_right')) return 'right';
    const f = ikFrameName();
    if (/^L_/.test(f)) return 'left';
    if (/^R_/.test(f)) return 'right';
    return null;
}

function ikArmFromFrame() {
    // The filename (*_left / *_right) is the unambiguous "which arm is this task"
    // signal, so a left task always analyses on the LEFT arm even if its ik_frame
    // is stale/mis-mirrored (e.g. an R_ frame left in a *_left config). Fall back
    // to the ik_frame prefix, then to "both arms".
    // Defer to the ONE authority; the filename heuristic lives in
    // `ikArmFromFile` and is consulted only when nothing states a side.
    const arm = activeArm();
    if (arm === 'left' || arm === 'right') return arm;
    return undefined;   // unknown -> server tries both arms
}

// Mesh keys currently shown in the viewer (active + visible companions), so the
// server only collision-checks what the user sees and face indices line up.
function visibleMeshKeys() {
    const keys = [];
    if (meshObject && meshObject.visible && meshObject.userData.meshKey) keys.push(meshObject.userData.meshKey);
    if (companionGroup) companionGroup.children.forEach(m => { if (m.visible && m.userData.meshKey) keys.push(m.userData.meshKey); });
    return [...new Set(keys)];
}

function meshObjectsByKey(meshKey) {
    const out = [];
    if (meshObject && meshObject.userData.meshKey === meshKey) out.push(meshObject);
    if (companionGroup) companionGroup.children.forEach(m => { if (m.userData.meshKey === meshKey) out.push(m); });
    return out;
}

// Paint the listed faces of each mesh red (geometry is non-indexed: face f owns
// vertices 3f,3f+1,3f+2). A 'color' attribute + vertexColors does the tint
// without disturbing the mesh's base material colour elsewhere.
function paintCollisionFaces(collisionFaces) {
    clearCollisionPaint();
    const red = new THREE.Color(STATE_COLOR.collision);
    for (const [meshKey, faces] of Object.entries(collisionFaces || {})) {
        if (!faces || !faces.length) continue;
        meshObjectsByKey(meshKey).forEach(obj => {
            const geom = obj.geometry;
            const pos = geom.getAttribute('position');
            if (!pos) return;
            let color = geom.getAttribute('color');
            if (!color || color.count !== pos.count) {
                color = new THREE.Float32BufferAttribute(new Float32Array(pos.count * 3), 3);
                geom.setAttribute('color', color);
            }
            const base = obj.material.color;
            for (let i = 0; i < pos.count; i++) color.setXYZ(i, base.r, base.g, base.b);
            faces.forEach(f => { for (let k = 0; k < 3; k++) color.setXYZ(f * 3 + k, red.r, red.g, red.b); });
            color.needsUpdate = true;
            obj.material.vertexColors = true;
            obj.material.needsUpdate = true;
            collisionPaintedMeshes.add(obj);
        });
    }
    renderScene();
}

function clearCollisionPaint() {
    collisionPaintedMeshes.forEach(obj => {
        if (!obj.material) return;
        obj.material.vertexColors = false;
        obj.material.needsUpdate = true;
        if (obj.geometry?.getAttribute('color')) obj.geometry.deleteAttribute('color');
    });
    collisionPaintedMeshes.clear();
}

function setIKInfo(rows) {
    const el = document.getElementById('ikInfo');
    if (el) el.innerHTML = rows.length ? rows.join('') : '<div class="info-row"><span>IK</span><code>—</code></div>';
}

// Solve IK for an arbitrary pose (base_link), posing the robot + marking
// collisions. ``opts.point`` (optional) gets badged; ``opts.label`` names it in
// status. Stale responses (superseded by a newer click) are dropped.
let ikRequestSeq = 0;
async function runIK(position, orientation, opts = {}) {
    const body = {
        ...readoutGateBody(),      // review D5: the badge judges at the config's / region's gate
        position, orientation,
        tipFrame: reachTipFrame(), arm: ikArmFromFrame(),
        fixture: viewerManifest?.fixtureName,
        meshKeys: visibleMeshKeys(),
        wantRobotPose: robotOverlayOn(),
        poleState: poleStateValue(),
        // Collision checks test against the fixture at the task's standoff.
        ugvStandoff: effectiveTaskStandoff() ?? undefined,
    };
    const seq = ++ikRequestSeq;
    try {
        const d = await api('/api/ik', {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(body)});
        if (seq !== ikRequestSeq) return;   // a newer request started — drop this one
        if (d.error) { setIKInfo([`<div class="info-row"><span>IK</span><code>${d.error}</code></div>`]); setStatus('IK failed: ' + d.error, true); return; }
        applyIKResult(d, opts);
        return d;
    } catch (e) {
        if (seq === ikRequestSeq) setStatus('IK request failed: ' + e.message, true);
    }
}

function checkSelectedPointIK() {
    const point = state.points[state.selectedIndex];
    if (!point) { setStatus('Select a cleaning point first.', true); return; }
    return runIK(point.xyz, point.absoluteQuat || [0, 0, 0, 1], {point, label: point.name});
}

function applyIKResult(d, opts = {}) {
    const point = opts.point;
    const best = d.best ? d.arms[d.best] : null;
    const status = d.reachable ? (best && best.orientationOk ? 'ok' : 'orient') : 'bad';
    if (point) point.ikStatus = status;
    const rows = [];
    for (const [arm, a] of Object.entries(d.arms || {})) {
        const tag = !a.inEnvelope ? 'out of envelope'
            : a.reachable ? (a.orientationOk ? 'reachable' : 'pos-only')
            : 'unreachable';
        const detail = a.posErrMm != null ? ` (${a.posErrMm} mm, ${a.rotErrDeg}°)` : '';
        rows.push(`<div class="info-row"><span>${arm}</span><code>${tag}${detail}</code></div>`);
        if (a.inEnvelope && a.manipulability != null) {
            rows.push(`<div class="info-row"><span>${arm} dexterity</span><code>w=${a.manipulability} · cond=${a.conditionNumber}</code></div>`);
        }
        // review D5: the verdict at the config's / region's gate, and the vendor's 20
        // beside it as a SECOND, labelled threshold
        const sg = a.singularity;
        if (sg && sg.marginDeg != null) {
            const verdict = sg.clear ? 'clear' : 'SUB-GATE';
            const vendor = sg.vendorGateDeg != null
                ? ` · vendor ${sg.vendorGateDeg}° (2nd threshold, not the verdict): ${sg.clearOfVendorGate ? 'clear' : 'under'}`
                : '';
            rows.push(`<div class="info-row"><span>${arm} singularity</span><code${sg.clear ? '' : ' class="bad"'}>`
                      + `margin ${sg.marginDeg}° · gate ${sg.gateDeg}° (${sg.gateSource || 'source not reported'}): `
                      + `${verdict}${vendor}</code></div>`);
        }
    }
    if (d.collision) {
        const n = Object.values(d.collisionFaces || {}).reduce((s, f) => s + f.length, 0);
        rows.push(`<div class="info-row"><span>collision</span><code>${n} face(s) red</code></div>`);
        paintCollisionFaces(d.collisionFaces);
    } else {
        rows.push(`<div class="info-row"><span>collision</span><code>${d.collisionError ? d.collisionError : 'none'}</code></div>`);
        clearCollisionPaint();
    }
    if (d.robotPose && robotOverlayOn()) applyRobotPose(d.robotPose);
    setIKInfo(rows);
    renderSelectedPointAnalysis(d, point);
    const verdict = d.reachable ? (status === 'ok' ? 'reachable at orientation' : 'position reachable, orientation infeasible') : 'unreachable';
    const label = opts.label || 'pose';
    setStatus(`${label}: ${verdict}${d.best ? ` (best: ${d.best} arm)` : ''}${d.collision ? ' — collision' : ''}.`);
    if (point) updateSceneObjects();
}

function clearIKResult() {
    state.points.forEach(p => { delete p.ikStatus; });
    clearCollisionPaint();
    setIKInfo([]);
    renderSelectedPointAnalysis(null);
    updateSceneObjects();
    setStatus('IK badges and collision paint cleared.');
}

// Jacobian condition number → readable dexterity quality.
function condQuality(cond) {
    const c = Number(cond);
    if (!isFinite(c)) return ' · singular';
    if (c < 10) return ' · good';
    if (c < 30) return ' · moderate';
    return ' · near-singular';
}

// Detailed, readable reachability / dexterity / manipulability for the selected
// point, shown in the Workspace tab (next to the Kinematics Solver). Arms are
// laid out side-by-side to use the width and keep within the ribbon height.
function renderSelectedPointAnalysis(d, point) {
    const el = document.getElementById('selectedPointAnalysis');
    if (!el) return;
    if (!d) {
        el.innerHTML = '<div class="spa-empty">Select a point and <b>Check Selected Point</b> (or enable check-on-click / the robot overlay) to see reachability, dexterity &amp; manipulability here.</div>';
        return;
    }
    const name = point ? point.name : 'pose';
    const armBlock = (arm, a) => {
        const [text, cls] = !a.inEnvelope ? ['out of envelope', 'bad']
            : a.reachable ? (a.orientationOk ? ['reachable at orientation', 'ok'] : ['position reachable, orientation infeasible', 'warn'])
            : ['unreachable / no IK', 'bad'];
        const rows = [`<div class="spa-arm-head"><span class="spa-dot ${cls}"></span><b>${arm} arm</b>${d.best === arm ? '<span class="spa-best">best</span>' : ''}</div>`,
            `<div class="spa-row"><span>status</span><code>${text}</code></div>`];
        if (a.posErrMm != null) rows.push(`<div class="spa-row"><span>position error</span><code>${a.posErrMm} mm</code></div>`);
        if (a.rotErrDeg != null) rows.push(`<div class="spa-row"><span>orientation error</span><code>${a.rotErrDeg}°</code></div>`);
        if (a.manipulability != null) {
            rows.push(`<div class="spa-row"><span>dexterity w</span><code>${a.manipulability}</code></div>`);
            rows.push(`<div class="spa-row"><span>condition</span><code>${a.conditionNumber}${condQuality(a.conditionNumber)}</code></div>`);
        }
        return `<div class="spa-arm">${rows.join('')}</div>`;
    };
    const arms = Object.entries(d.arms || {}).map(([arm, a]) => armBlock(arm, a)).join('');
    const coll = d.collision
        ? `<span class="spa-dot bad"></span>${Object.values(d.collisionFaces || {}).reduce((s, f) => s + f.length, 0)} fixture face(s) in collision`
        : `<span class="spa-dot ok"></span>${d.collisionError ? d.collisionError : 'no collision'}`;
    el.innerHTML = `<div class="spa-title">${name}</div><div class="spa-arms">${arms || '<div class="spa-empty">no arm result</div>'}</div><div class="spa-coll">${coll}</div>`;
}

// Robot-assisted collection is active when the auto-IK toggle is on OR the robot
// overlay is shown (default) — so adding/moving a point live-poses the robot and
// reports reachability/collision without a separate Check step.
function assistEnabled() {
    return document.getElementById('ikAutoToggle')?.checked || robotOverlayOn();
}

function maybeAutoCheckIK() {
    if (assistEnabled() && state.selectedIndex >= 0) checkSelectedPointIK();
}

function robotOverlayOn() { return document.getElementById('showRobotToggle')?.checked; }

function poleStateValue() { return document.getElementById('poleStateSelect')?.value || undefined; }

// ── the point in each arm's CONTROLLER base frame ──────────────────────────
// base_link -> arm base, one 4x4 per pole state per side, from the server (see
// server._arm_base_frames). It is a TABLE because the arm base rides the pole,
// and it is fetched once so the readout can follow a drag with no round trip.
let armBaseFrames = null;

// Populate the pole-length selector from the SRDF (via /api/joint-presets).
async function populatePoleStates() {
    const sel = document.getElementById('poleStateSelect');
    if (!sel) return;
    try {
        const d = await api('/api/joint-presets');
        const states = d.poleStates || [];
        if (!states.length) { sel.innerHTML = '<option value="">(no SRDF pole states)</option>'; return; }
        sel.innerHTML = states.map(s => `<option value="${s.name}">${s.name} (${s.value} m)</option>`).join('');
        sel.value = d.default || states[0].name;
        armBaseFrames = d.armBaseFrames || null;
        // The presets land asynchronously; a point selected before they arrive
        // would otherwise sit showing "SDK oracle unavailable" until reselected.
        if (state.selectedIndex >= 0) updateInfo();
    } catch (e) { /* SRDF not available — leave empty */ }
}

// `rm_pose_t` is R = Rz.Ry.Rx, which scipy writes as extrinsic "xyz" and
// three.js as Euler order 'ZYX' reading (.x, .y, .z) — the SAME triple, checked
// against 2000 random rotations to 1.2e-15. Reading it with three.js's default
// 'XYZ' would silently give a different pose for every non-trivial rotation.
const CONTROLLER_EULER_ORDER = 'ZYX';

function armBaseMatrix(side, frame) {
    const rows = armBaseFrames?.[poleStateValue()]?.[side]?.[frame];
    if (!rows || rows.length !== 16) return null;
    // Row-major from Python; Matrix4.set takes row-major, fromArray does not.
    return new THREE.Matrix4().set(...rows);
}

// {xyz_mm, rpy_rad} for a base_link pose seen from one of the arm's controller
// frames, or null. Units are the PENDANT's: millimetres and radians.
function poseInArmFrame(position, quaternion, side, frame) {
    const m = armBaseMatrix(side, frame);
    if (!m) return null;
    const pose = new THREE.Matrix4().compose(
        position, quaternion, new THREE.Vector3(1, 1, 1));
    const inArm = new THREE.Matrix4().multiplyMatrices(m, pose);
    const t = new THREE.Vector3(), q = new THREE.Quaternion(), sc = new THREE.Vector3();
    inArm.decompose(t, q, sc);
    const e = new THREE.Euler().setFromQuaternion(q, CONTROLLER_EULER_ORDER);
    return {xyz_mm: [t.x * 1000, t.y * 1000, t.z * 1000], rpy_rad: [e.x, e.y, e.z]};
}

// One row per (arm, frame), laid out the way the teach pendant's Position&Pose
// panel does: X/Y/Z in mm, RX/RY/RZ in rad, 3 decimals each.
function armFrameRow(label, r) {
    if (!r) return '';
    const mm = r.xyz_mm.map(v => v.toFixed(3));
    const rad = r.rpy_rad.map(v => v.toFixed(3));
    return `<div class="info-row"><span>${label}</span><code class="two-line">`
         + `X ${mm[0]}  Y ${mm[1]}  Z ${mm[2]} mm\n`
         + `RX ${rad[0]}  RY ${rad[1]}  RZ ${rad[2]} rad</code></div>`;
}

// Both arms, both controller frames.
//
//   World  the level frame at the arm origin, and the one `rm_movel` receives
//   Base   the arm's own URDF *_base_link, and what the pendant shows by
//          default — checked against a pendant screenshot by running FK on its
//          own joints and tool: 0.003 mm, 0.0005 rad.
//
// They differ by the 90 deg mount pitch the controller reports as install pose
// (0, 90, 0), so the SAME pose reads 266/139/438 mm in Base and 438/139/-266
// in World. Showing one and labelling it the other is the mix-up that once
// left 98 % of a stroke with no IK solution, which is why both are here and
// both are named.
function workFrame() { return document.getElementById('workFrameSelect')?.value || 'ref'; }

function armBaseRows(point) {
    const wanted = workFrame();
    if (wanted === 'ref') return '';        // the YAML's own frame — already shown above
    const pos = vec(point.xyz);
    const quat = quatFromArray(point.absoluteQuat || [0, 0, 0, 1]);
    const pole = poleStateValue();
    if (!armBaseFrames || !armBaseFrames[pole]) {
        return `<div class="info-row"><span>arm controller frames</span><code>`
             + `${armBaseFrames ? `no transform for pole ${pole || '(none selected)'}`
                                : 'SDK oracle unavailable'}</code></div>`;
    }
    const rows = [];
    for (const side of ['right', 'left']) {
        const cap = side === 'right' ? 'Right' : 'Left';
        const name = wanted === 'world' ? 'World' : 'Base';
        rows.push(armFrameRow(`${cap} arm · ${name}`, poseInArmFrame(pos, quat, side, wanted)));
    }
    rows.push(`<div class="info-row is-weak"><span>arm frames at pole</span>`
            + `<code>${pole}</code></div>`);
    return rows.join('');
}

// What the picker changes, and — just as important — what it does not.
//
// It is a READOUT frame. The gizmo still drags along alix_ref_frame axes, and
// the YAML is still written in alix_ref_frame, because neither of those is a
// display choice: `TransformControls` offers world or pose-local space and
// nothing else, so arbitrary-frame handles need the drag delta resolved through
// the frame rather than a flag; and every offline gate — verify_task_motion,
// sdk_reach, coverage — reads a config AS alix_ref without consulting
// `task_parameters.reference_frame`, so a config saved in another frame would
// dispatch correctly and be mis-verified by all of them.
const WORK_FRAME_NOTES = {
    ref: 'Readout in <code>alix_ref_frame</code>. <b>Save Copy</b> exports as authored.',
    base: 'Readout in each arm\'s URDF <code>*_base_link</code>, in mm and rad — what '
        + 'the RealMan pendant shows under &quot;Base&quot;. <b>Save Copy</b> exports '
        + 'in this frame, with 6-value <code>[x y z rx ry rz]</code> poses.',
    world: 'Readout in each arm\'s level <code>World</code> frame, in mm and rad — '
         + 'pitched 90&deg; from Base by the mount the controller reports as install '
         + 'pose (0,&nbsp;90,&nbsp;0), and the frame <code>rm_movel</code> receives. '
         + '<b>Save Copy</b> exports in it, with 6-value poses.',
};

//: Appended whenever an export would differ from the authored file, so the
//: difference between the two save buttons is never a surprise.
const EXPORT_NOTE = ' Gizmo axes stay in <code>alix_ref_frame</code>, and '
    + '<b>Save Changes</b> always writes the authored form.';

function applyWorkFrame() {
    const note = document.getElementById('workFrameNote');
    const tool = document.getElementById('exportIkFrame')?.value || '';
    if (note) {
        const retargets = workFrame() !== 'ref' || tool || exportAbsolutePoints;
        note.innerHTML = (WORK_FRAME_NOTES[workFrame()] || '')
            + (tool ? ` Tool retargeted to <code>${tool}</code>, holding the flange `
                    + `trajectory — same motion.` : '')
            + (exportAbsolutePoints
                 ? ' Points export as ABSOLUTE poses in this frame, not offsets from '
                   + '<code>start_pose</code>.' : '')
            + (retargets ? EXPORT_NOTE : '');
    }
    // The Reference Frame group has no flyout to open, so the note that used to
    // sit inside it would be written and never read. The ⓘ on the group's
    // bottom rail carries it: the static explanation, then what is true NOW.
    // Base text is captured once — appending to the live attribute would grow
    // it on every change.
    const ico = document.getElementById('rfInfoIco');
    if (ico && note) {
        if (ico.dataset.tipBase === undefined) {
            ico.dataset.tipBase = ico.getAttribute('data-tip') || '';
        }
        ico.setAttribute('data-tip', ico.dataset.tipBase
            + (note.innerHTML ? `<br><br><b>Now:</b> ${note.innerHTML}` : ''));
    }
    if (state.selectedIndex >= 0) updateInfo();
    renderScene();
}

// Build a URDF robot mesh SET once (the SAME way the solid fixture mesh is built —
// meshFromPayload, opaque). 'visual' carries real material colours (default ON);
// 'collision' is the geometry the FCL check tests (lazy, loaded only when toggled
// on). Each mesh's vertices are in its link frame; the per-link world transform is
// applied as position/quaternion/scale (matrixAutoUpdate on, like the fixture).
// Meshes from both sets share robotMeshes[link] so posing/highlighting hit both.
async function loadRobotGeometry(set = 'visual') {
    if (robotSetLoaded[set]) return true;
    try {
        setStatus(`Loading robot ${set} meshes…`);
        const d = await api('/api/robot-geometry?set=' + encodeURIComponent(set));
        if (d.error) { setStatus('Robot meshes: ' + d.error, true); return false; }
        // Visual: real per-mesh material colours, opaque. Collision: a single
        // semi-transparent orange proxy (MoveIt-style) so it reads as "the tested
        // geometry" and stays distinct when overlaid on the coloured visual mesh.
        const isCol = set === 'collision';
        d.meshes.forEach(m => {
            if (isCol) delete m.color;
            const mesh = meshFromPayload(m, isCol ? 0xff8c42 : 0x9fb3c8, isCol ? 0.5 : 1.0, true);  // indexed
            if (!isCol) {
                // Indoor-matte robot look. CAD materials are often pure 1.0
                // white — no real paint reflects that much, and under the
                // studio light rig (hemi 0.55 + key 1.35 + fill/back) it
                // clips to a glow. Clamp LINEAR albedo to 0.62 (~sRGB 0.82,
                // real white paint) preserving hue, and go fully matte so the
                // specular sheen stops adding on top. Robot visual set only —
                // fixtures/paint meshes are untouched.
                const c = mesh.material.color;
                const mx = Math.max(c.r, c.g, c.b);
                if (mx > 0.62) c.multiplyScalar(0.62 / mx);
                mesh.userData.baseColor = c.getHex();   // keep DAC-restore in sync
                mesh.material.roughness = 0.9;
                mesh.material.metalness = 0.0;
            }
            mesh.userData.meshSet = set;
            mesh.visible = robotSetVisible(set);
            robotMeshes[m.link] = robotMeshes[m.link] || [];
            robotMeshes[m.link].push(mesh);
            robotGroup.add(mesh);
        });
        applyRobotPose(d.homePose);
        robotSetLoaded[set] = true;
        if (set === 'visual') robotGeometryLoaded = true;
        setStatus(`Robot ${set} meshes loaded (${d.count}).`);
        return true;
    } catch (e) {
        setStatus('Robot meshes failed: ' + e.message, true);
        return false;
    }
}

// Is a given mesh set requested visible by its checkbox? (visual defaults on.)
function robotSetVisible(set) {
    const id = set === 'collision' ? 'robotCollisionToggle' : 'robotVisualToggle';
    const el = document.getElementById(id);
    return el ? el.checked : (set === 'visual');
}

// Show/hide one mesh set; lazily loads it the first time it is switched on.
async function setRobotSet(set, on) {
    if (on && !robotSetLoaded[set]) {
        // Make sure the robot overlay is on, then load the set.
        if (!(await loadRobotGeometry(set))) {
            const el = document.getElementById(set === 'collision' ? 'robotCollisionToggle' : 'robotVisualToggle');
            if (el) el.checked = false;
            return;
        }
        // Re-pose to the currently selected point's config (if any) so a freshly
        // loaded set isn't stuck at home while the other set is posed elsewhere.
        if (state.selectedIndex >= 0) checkSelectedPointIK();
    }
    Object.values(robotMeshes).forEach(arr => arr.forEach(m => {
        if (m.userData.meshSet === set) m.visible = on;
    }));
    renderScene();
}

// poseMap: link -> 16-float row-major world transform (base_link). Decomposed
// into position/quaternion/scale so the meshes use the normal (auto-update)
// transform path, matching the fixture mesh.
const _rpM = new THREE.Matrix4(), _rpP = new THREE.Vector3(), _rpQ = new THREE.Quaternion(), _rpS = new THREE.Vector3();
function applyRobotPose(poseMap) {
    if (!poseMap) return;
    for (const [link, arr] of Object.entries(poseMap)) {
        const meshes = robotMeshes[link];
        if (!meshes || arr.length !== 16) continue;
        _rpM.set(...arr);                 // .set() takes row-major args
        _rpM.decompose(_rpP, _rpQ, _rpS);
        meshes.forEach(mesh => { mesh.position.copy(_rpP); mesh.quaternion.copy(_rpQ); mesh.scale.copy(_rpS); });
    }
    renderScene();
}

// ===== Dual-Arm Collisions tab ============================================
// Loads two single-arm plans, asks the server for the inter-arm FCL sweep, and
// plays the ±window samples on the robot overlay (reusing applyRobotPose), with
// colliding links flashed red and a Plotly collision timeline.
const dac = { inited: false, res: null, frameIdx: [], pos: 0, playing: false,
              timer: null, hitByIndex: {}, recolored: [], plans: [],
              fixtureStates: null };   // last articulation shown (for toggle re-render)
const DAC_ROBOT_COLOR = 0x9fb3c8, DAC_HIT_COLOR = 0xff4d4d;
// Pre-converted to linear so the red highlight reads correctly under sRGB output.
const DAC_HIT_LINEAR = new THREE.Color(DAC_HIT_COLOR);
if (DAC_HIT_LINEAR.convertSRGBToLinear) DAC_HIT_LINEAR.convertSRGBToLinear();

// ============================================================================
//  SCHEDULE & RUN TAB — whole-fixture process visualization
//  Loads the orchestrator execution schedule for a fixture, resolves each
//  step's plan(s), and plays the assembled cleaning run end-to-end. Reuses the
//  DAC robot-overlay + fixture-articulation machinery, extended across steps.
// ============================================================================
const schState = {
    inited: false,
    fixture: null,
    steps: [],              // resolved steps from /api/schedule(-preview)
    checkpoints: [],        // glove / inspection markers for the timeline
    // Inter-arm sweep verdicts keyed by the row's CELL TEXT ("10R,3L"), not the
    // step position: a reorder moves the same plans (verdict still true), a
    // re-pair changes the cells (verdict gone -> the pairing reads as
    // unchecked/stale until swept again). Absence of a key IS the stale state.
    collisions: {},         // cellKey -> {count} | {error}
    hinges: {},             // {lid|seat: {origin, axis, closedDeg, openDeg}}
    fixturePose: null,      // [x,y,z] fixture position in base_link
    rows: [],               // editable CSV cells [[col1, col2|null], ...]
    guards: null,           // tier 1+2 verdicts from the server engine
    regionsMeta: {},        // regionId -> {key, armCoverage, description, partStates}
    csvPath: null,          // repo-relative schedule CSV (the save target)
    csvMtimeNs: null,       // conflict guard baseline for save
    taskDelaySec: null,     // orchestrator inter-row settling delay
    dirty: false,           // rows differ from the loaded CSV
    savedRows: [],          // rows as loaded (for the save modal's diff chips)
    stepIdx: 0,
    playing: false,
    playMode: null,         // 'all' | 'step' while playing (which button drives)
    // Monotonic run token, bumped on every playback start AND every stop. The
    // frame fetches are not abortable, so an await that straddles a Stop must
    // detect its run is dead (token moved on) instead of resuming as a zombie
    // alongside the run the user started next — two intervals fighting over
    // schState.timer and the two play modes interleaving.
    playRun: 0,
    // Soloed plan file (repo-relative path) from the Step detail chips, or null.
    // Scoped to the selected step: cleared on step change and on every payload
    // re-resolution (plan paths may change under an edit).
    soloPlan: null,
    playT: 0,               // playback position (fraction within current step)
    // Live frame cursor while playing: {stepIdx, segIdx, pos} for schedule
    // modes, {plan, pos} for the file player. schPause() snapshots it into
    // `resume` so the SAME ▶ continues from the paused frame; schStop() (and
    // any navigation/edit, which route through it) discards both.
    playPos: null,
    resume: null,           // {mode, ...playPos} written by schPause only
    planFile: null,         // selected path in the Plan File list, or null
    planCatalog: [],        // /api/plans payload for the Plan File list
    modeTouched: false,     // the operator picked a mode; stop following the plan files
    timer: null,            // active playback interval
    frameCache: new Map(),  // request-body JSON -> /api/plan-frames payload
};

// Playback tuning: server FK is sampled at SCH_DT; play at SCH_SPEED× real time.
const SCH_DT = 0.1;
const SCH_SPEED = 2;

// Plan filename mode suffixes (mirrors the orchestrator --cleaning-path-mode arg);
// the schedule resolver globs `{keyword}_{arm}_{mode}.json`, so a mode is just a
// filename suffix — nothing here needs the orchestrator to know the string.
//
// `ruckig_pro_only` is the RETIRED smoothing path (ruckig_on_s replaced it as the
// C++ default, 2026-08-25) — but its plans are recorded, on disk and still valid
// trajectories. Newton, 2026-09-16: "they are already generated and reusing them
// is not a crime at all". So it stays SELECTABLE for loading and replay, labelled
// deprecated so nobody authors new plans against it. Dropping it from this list is
// what made 17 of commode_c's 34 schedule combinations read "(plan missing)" while
// their plans sat in Resource/plans.
const PLAN_MODES = [
    { value: 'toppra', label: 'toppra' },
    { value: 'ruckig_on_s', label: 'ruckig_on_s' },
    { value: 'totg_ruckig', label: 'totg_ruckig' },
    { value: 'ruckig_pro_only', label: 'ruckig_pro_only (deprecated)' },
];

// Schedule & Run opens where the recorded plans ARE, decided from the plan files
// on disk rather than named here. Measured 2026-09-16 on commode_c's 25-step
// schedule: ruckig_on_s resolves 0, totg_ruckig 5, ruckig_pro_only 22 — so the
// old hard-coded `ruckig_on_s` opened the tab with every plan missing, every time
// (Newton approved changing it the same day). Hard-coding the retired mode
// instead would steer every operator to it by default, which the retired-name
// guard exists to refuse; following the files steers nobody, and moves on its own
// the day current-mode plans are recorded. SCH_MODE_FALLBACK is only for when
// there is no catalog to count (static page, server down) or nothing matches.
// Newton 2026-10-05: toppra is THE default mode — wherever the catalog holds
// any toppra plan for the fixture + plan set, the tab opens on toppra and the
// count only decides among the others when there is none.
const PLAN_MODE_DEFAULT = 'toppra';
const SCH_MODE_FALLBACK = PLAN_MODE_DEFAULT;
const DAC_MODE_DEFAULT = PLAN_MODE_DEFAULT;

// toppra when any toppra plan is recorded under `<fixture>/<planSet>/`; otherwise
// the mode with the most recorded plans there; ties and an empty count keep the
// fallback, so a tie never lands on the retired mode.
function planModeWithMostPlans(plans, fixture, planSet) {
    const counts = Object.fromEntries(PLAN_MODES.map(m => [m.value, 0]));
    const dir = `/${fixture}/${planSet}/`;
    for (const p of plans || []) {
        if (!fixture || !String(p.path).includes(dir)) continue;
        for (const m of PLAN_MODES) {
            if (String(p.name).endsWith(`_${m.value}.json`)) counts[m.value]++;
        }
    }
    if (counts[PLAN_MODE_DEFAULT] > 0) return PLAN_MODE_DEFAULT;
    let best = SCH_MODE_FALLBACK;
    for (const m of PLAN_MODES) {
        if (counts[m.value] > counts[best]) best = m.value;
    }
    return best;
}

// <option> markup for the mode pickers, with `selected` pre-chosen.
function planModeOptions(selected) {
    return PLAN_MODES.map(m => `<option value="${m.value}"`
        + `${m.value === selected ? ' selected' : ''}>${m.label}</option>`).join('');
}

async function scheduleOnEnter() {
    if (!schState.inited) scheduleInit();
    // Playback drives the robot overlay — make sure it is loaded + visible (as DAC does).
    const t = document.getElementById('showRobotToggle');
    if (t && !t.checked) { t.checked = true; await toggleRobot(true); }
    else if (!robotGeometryLoaded) { await loadRobotGeometry('visual'); }
    await schPopulateFixtures();
    await schPopulatePlanFiles();
    schAdoptPlanMode();
}

function scheduleInit() {
    schState.inited = true;
    schPopulateModes();
    document.getElementById('schLoadButton')?.addEventListener('click', scheduleLoad);
    document.getElementById('schCheckCollisionsButton')?.addEventListener('click', schCheckCollisions);
    document.getElementById('schSaveButton')?.addEventListener('click', schSave);
    document.getElementById('schAddStepButton')?.addEventListener('click', () => schEditStep(null));
    document.getElementById('schFixture')?.addEventListener('change', async e => {
        await setFixture(e.target.value, { loadMeshes: false });
        schAdoptPlanMode();
    });
    document.getElementById('schPlanSet')?.addEventListener('change', schAdoptPlanMode);
    document.getElementById('schPlayButton')?.addEventListener('click', schPlay);
    document.getElementById('schPlayStepButton')?.addEventListener('click', schPlayStep);
    document.getElementById('schStepDetail')?.addEventListener('click', schPlanChipClick);
    document.getElementById('schPlayPlanButton')?.addEventListener('click', schPlayPlanFile);
    document.getElementById('schPlanFilter')?.addEventListener('input', schRenderPlanList);
    document.getElementById('schPlanList')?.addEventListener('click', schPlanItemClick);
    document.getElementById('schStopButton')?.addEventListener('click', schStop);
    document.getElementById('schPrevStepButton')?.addEventListener('click', () => schGotoStep(schState.stepIdx - 1));
    document.getElementById('schNextStepButton')?.addEventListener('click', () => schGotoStep(schState.stepIdx + 1));
    document.getElementById('schSlider')?.addEventListener('input',
        e => schGotoStep(parseInt(e.target.value, 10)));
}

function schSetStatus(msg, isErr) {
    const el = document.getElementById('schStatus');
    if (el) el.innerHTML = `<div class="info-row"><span>Status</span>`
        + `<code${isErr ? ' style="color:var(--danger)"' : ''}>${escapeHtml(msg)}</code></div>`;
}

async function schPopulateFixtures() {
    const sel = document.getElementById('schFixture');
    if (!sel) return;
    let fixtures = studio.fixtures || [];
    if (!fixtures.length) {
        try { fixtures = (await api('/api/fixtures')).fixtures || []; studio.fixtures = fixtures; }
        catch (e) { /* static/file:// — leave empty */ }
    }
    if (fixtures.length && !sel.options.length) {
        sel.innerHTML = buildFixtureOptions(fixtures);
        // Populated late (first visit to the tab), so adopt the global fixture
        // now that this select finally has options to hold it.
        syncFixtureSelectors(currentFixture());
    }
}

function schPopulateModes() {
    const sel = document.getElementById('schMode');
    if (!sel || sel.options.length) return;
    sel.innerHTML = planModeOptions(SCH_MODE_FALLBACK);
    // An operator's pick is final: once touched, nothing re-chooses for them.
    sel.addEventListener('change', () => { schState.modeTouched = true; });
}

// Point the mode picker at the recorded plans for the current fixture + plan set,
// unless the operator has already chosen. Needs the plan catalog, so it runs after
// schPopulatePlanFiles and again when the fixture or plan set changes.
function schAdoptPlanMode() {
    const sel = document.getElementById('schMode');
    if (!sel || schState.modeTouched || !schState.planCatalog.length) return;
    const planSet = document.getElementById('schPlanSet')?.value || 'hardware';
    sel.value = planModeWithMostPlans(schState.planCatalog, currentFixture(), planSet);
}

async function scheduleLoad() {
    const fixture = currentFixture();
    const planSet = document.getElementById('schPlanSet')?.value || 'hardware';
    const mode = document.getElementById('schMode')?.value || '';
    if (!fixture) { schSetStatus('Pick a fixture first.', true); return; }
    schSetStatus('Loading schedule…');
    let data;
    try {
        data = await api(`/api/schedule?fixture=${encodeURIComponent(fixture)}`
            + `&planSet=${encodeURIComponent(planSet)}&mode=${encodeURIComponent(mode)}`);
    } catch (e) { schSetStatus('Schedule load failed: ' + e.message, true); return; }
    if (data.warning) schSetStatus(`⚠ ${data.warning}`, true);   // e.g. family CSV missing
    schState.fixture = fixture;
    schState.collisions = {};
    schState.stepIdx = 0;
    schState.dirty = false;
    schState.savedRows = (data.rows || []).map(r => r.slice());
    schState.csvMtimeNs = data.csvMtimeNs ?? null;
    schState.frameCache.clear();
    // Load this fixture's manifest so per-step lid/seat states + articulation
    // resolve (same region → commode_fixture_type source the DAC tab uses).
    try { await loadFixtureForRegions(fixture); } catch (e) { /* articulation degrades to none */ }
    schApplyPayload(data);
    const n = schState.steps.length;
    if (n) schGotoStep(0);   // render the first step's starting pose + fixture
    const missing = schState.steps.filter(s => s.missing).length;
    // Report where plans were actually FOUND, not just the preferred root.
    // Naming only the (usually absent) generated directory made the tab read
    // "plans dir not found" while the committed plans were resolving fine.
    const searched = data.plansSearched || (data.plansDirExists ? [data.plansDir] : []);
    const where = searched.length ? searched.join(' + ')
                                  : `${data.plansDir} (not found)`;
    schSetStatus(`${n} step${n === 1 ? '' : 's'} · plans from ${where}`
        + (missing ? ` · ${missing} step(s) have no plan yet` : ''),
        missing > 0 || !searched.length);
}

// Adopt a /api/schedule or /api/schedule-preview payload into schState and
// re-render everything that shows it. One entry point for load AND edits, so
// the editor can never show a picture the orchestrator's loader disagrees with.
function schApplyPayload(data, opts = {}) {
    schState.steps = data.steps || [];
    schState.checkpoints = data.checkpoints || [];
    schState.hinges = data.hinges || {};
    schState.fixturePose = data.fixturePose || null;
    schState.rows = (data.rows || []).map(r => r.slice());
    schState.guards = data.guards || null;
    schState.regionsMeta = data.regionsMeta || {};
    schState.csvPath = data.csvPath || schState.csvPath;
    schState.taskDelaySec = data.taskDelaySec ?? null;
    const n = schState.steps.length;
    if (!opts.keepStep) schState.stepIdx = 0;
    schState.stepIdx = Math.max(0, Math.min(n - 1, schState.stepIdx));
    schState.soloPlan = null;   // plan paths were just re-resolved
    schState.resume = null;     // …so a paused frame cursor no longer maps to them
    schState.playPos = null;
    ['schPlayButton', 'schPlayStepButton', 'schPrevStepButton', 'schNextStepButton', 'schSlider', 'schCheckCollisionsButton'].forEach(id => {
        const el = document.getElementById(id); if (el) el.disabled = n === 0;
    });
    // The blanket enable above ignores playback mode; re-impose it so an edit
    // landing mid-play cannot re-enable the non-driving play button.
    schSetPlaying(schState.playing, schState.playMode);
    const addBtn = document.getElementById('schAddStepButton');
    if (addBtn) addBtn.disabled = !Object.keys(schState.regionsMeta).length;
    const saveBtn = document.getElementById('schSaveButton');
    if (saveBtn) saveBtn.disabled = !schState.dirty || !schState.rows.length;
    const slider = document.getElementById('schSlider');
    if (slider) { slider.max = Math.max(0, n - 1); slider.value = schState.stepIdx; }
    schRenderSteps();
    schRenderStepDetail(schState.stepIdx);
    schRenderGuardInfo();
    schRenderRunInfo();
}

// ---- Sequence editing (F69) ------------------------------------------------
// The editable artefact is schState.rows — the CSV's data cells. Every edit
// round-trips through POST /api/schedule-preview so the steps/guards shown are
// the orchestrator loader's own resolution of the edit, never a client guess.

function schCellKey(rowIdx) {
    const r = schState.rows[rowIdx];
    return r ? `${r[0] || ''}|${r[1] || ''}` : null;
}

async function schPreviewRows(newRows, opts = {}) {
    const fixture = schState.fixture || currentFixture();
    const planSet = document.getElementById('schPlanSet')?.value || 'hardware';
    const mode = document.getElementById('schMode')?.value || '';
    schSetStatus('Checking edit…');
    let data;
    try {
        data = await api('/api/schedule-preview', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ fixture, planSet, mode, rows: newRows }),
        });
    } catch (e) { schSetStatus('Edit rejected: ' + e.message, true); return false; }
    if (data.error) { schSetStatus('Edit rejected: ' + data.error, true); return false; }
    schState.dirty = true;
    schState.frameCache.clear();   // carry-joints shift when the order changes
    schApplyPayload(data, { keepStep: true });
    schSetStatus(opts.message || 'Edit applied (unsaved — Save Schedule writes the CSV).');
    return true;
}

function schMoveRow(fromRow, toRow) {
    if (fromRow === toRow || fromRow == null || toRow == null) return;
    const rows = schState.rows.map(r => r.slice());
    const [moved] = rows.splice(fromRow, 1);
    rows.splice(toRow > fromRow ? toRow - 1 : toRow, 0, moved);
    schPreviewRows(rows, { message: `Moved row ${fromRow} to position ${toRow > fromRow ? toRow - 1 : toRow}.` });
}

function schRemoveRow(rowIdx) {
    const rows = schState.rows.map(r => r.slice());
    if (rowIdx < 0 || rowIdx >= rows.length || rows.length === 1) return;
    rows.splice(rowIdx, 1);
    schPreviewRows(rows, { message: `Removed row ${rowIdx}.` });
}

function schReplaceRow(rowIdx, cells) {
    const rows = schState.rows.map(r => r.slice());
    if (rowIdx == null) rows.push(cells);
    else rows[rowIdx] = cells;
    return schPreviewRows(rows,
        { message: rowIdx == null ? 'Step added (unsaved).' : `Row ${rowIdx} updated (unsaved).` });
}

// One-line "which plans this step runs" summary for the step list.
function schStepPlansSummary(s) {
    const names = [];
    const add = slot => {
        if (!slot) return;
        if (slot.plan) names.push(slot.plan.split('/').pop());
        else names.push(`${slot.regionKey || '?'} (no plan)`);
    };
    if (s.type === 'compound') add(s.compound);
    else if (s.type === 'chained') { (s.leftChain || []).forEach(add); (s.rightChain || []).forEach(add); }
    else { add(s.left); add(s.right); }
    return names.join('  ·  ') || '—';
}

// A step's plan slots in playback order, with UI labels — same slot walk as
// schStepPlansSummary, kept as data so the Step detail chips and the solo
// validation agree on what "this step's plans" means.
function schStepPlanSlots(step) {
    const slots = [];
    const add = (slot, label) => {
        if (!slot) return;
        slots.push({ plan: slot.plan || null, label,
            name: slot.plan ? slot.plan.split('/').pop() : `${slot.regionKey || '?'} (no plan)` });
    };
    if (step.type === 'compound') add(step.compound, 'compound');
    else if (step.type === 'chained') {
        (step.leftChain || []).forEach((sl, i) => add(sl, `L${i + 1}`));
        (step.rightChain || []).forEach((sl, i) => add(sl, `R${i + 1}`));
    } else { add(step.left, 'L'); add(step.right, 'R'); }
    return slots;
}

// Clickable plan-file chips for the Step detail "Plans" row. Clicking a chip
// SOLOS that plan file: ▶ Play step then plays only it (click again, or move
// to another step, to clear). Slots with no recorded plan render inert —
// there is nothing to play.
function schStepPlanChips(step) {
    const chips = schStepPlanSlots(step).map(sl => {
        const text = `${escapeHtml(sl.label)} · ${escapeHtml(sl.name)}`;
        if (!sl.plan) return `<span class="sch-plan-chip missing" title="No plan recorded for this slot">${text}</span>`;
        const on = schState.soloPlan === sl.plan;
        const tip = on ? 'Soloed — ▶ Play step plays only this plan file. Click to clear.'
                       : 'Click to solo this plan file for ▶ Play step';
        return `<button type="button" class="sch-plan-chip${on ? ' solo' : ''}" data-plan="${escapeHtml(sl.plan)}" title="${tip}">${text}</button>`;
    });
    return chips.join('') || '<code>—</code>';
}

// Toggle a chip's solo state. Re-enters through schGotoStep so the static
// preview snaps to the first frame of what ▶ Play step would now play.
function schPlanChipClick(e) {
    const chip = e.target.closest('.sch-plan-chip[data-plan]');
    if (!chip || !schState.steps.length) return;
    schState.soloPlan = schState.soloPlan === chip.dataset.plan ? null : chip.dataset.plan;
    schGotoStep(schState.stepIdx);
}

// The segments ▶ Play step runs: the soloed plan file if one is selected (and
// still belongs to this step — payload edits invalidate paths), else the
// step's full segment set.
function schSoloSegments(step) {
    const solo = schState.soloPlan;
    if (solo && schStepPlanSlots(step).some(sl => sl.plan === solo))
        return [{ body: { plans: [solo] }, label: 'solo' }];
    return schStepSegments(step);
}

// Concurrent plan pairs a step implies — MUST mirror the server's
// _row_collision_pairs derivation, so "checked in the UI" is exactly what the
// save gate finds in the sweep cache (same pairs, same dt/window defaults).
function schStepPairs(step) {
    if (step.type === 'paired') {
        const l = step.left && step.left.plan, r = step.right && step.right.plan;
        return l && r ? [[l, r]] : [];
    }
    if (step.type === 'chained') {
        const lc = step.leftChain || [], rc = step.rightChain || [], pairs = [];
        for (let i = 0; i < Math.min(lc.length, rc.length); i++) {
            if (lc[i].plan && rc[i].plan) pairs.push([lc[i].plan, rc[i].plan]);
        }
        return pairs;
    }
    if (step.type === 'compound') {
        const p = step.compound && step.compound.plan;
        return p ? [[p, p]] : [];
    }
    return [];
}

// Guard verdicts recorded for a step (tier 1+2, from the server engine).
function schStepGuards(step) {
    if (step.index == null || !schState.guards) return [];
    const row = (schState.guards.rows || []).find(r => r.index === step.index);
    return row ? [...row.logical, ...row.reality] : [];
}

// Aggregate step verdict for pills/bars. Collision is SUPREME: a recorded hit
// blocks regardless of the other tiers, and an unswept checkable pairing shows
// as unchecked — stale is not passing (Newton, F69).
function schStepVerdict(step) {
    if (step.index == null) return { cls: 'p-locked', glyph: '🔒', word: 'session', level: 'locked' };
    const verdicts = schStepGuards(step);
    const colV = schState.collisions[schCellKey(step.index)];
    if (colV && colV.count > 0)
        return { cls: 'p-bad', glyph: '⛔', word: `${colV.count} collision${colV.count > 1 ? 's' : ''}`, level: 'error' };
    if (verdicts.some(v => v.level === 'error'))
        return { cls: 'p-bad', glyph: '⛔', word: 'blocked', level: 'error' };
    if (schStepPairs(step).length && (!colV || colV.error))
        return { cls: 'p-stale', glyph: '↻', word: 'unchecked', level: 'stale' };
    if (verdicts.some(v => v.level === 'warning'))
        return { cls: 'p-warn', glyph: '⚠', word: 'warning', level: 'warning' };
    return { cls: 'p-ok', glyph: '✓', word: 'ok', level: 'ok' };
}

function schRenderSteps() {
    const el = document.getElementById('schStepList');
    if (!el) return;
    if (!schState.steps.length) {
        el.innerHTML = '<div class="info-row"><code>No steps.</code></div>';
        schRenderTimeline();
        return;
    }
    el.innerHTML = schState.steps.map((s, i) => {
        const cls = 'sch-step' + (i === schState.stepIdx ? ' active' : '');
        const editable = s.index != null;
        const v = schStepVerdict(s);
        const miss = s.missing ? ' <span class="sch-step-missing">⚠ plan missing</span>' : '';
        const arm = s.type === 'serial' && s.firstArm ? ` (${escapeHtml(s.firstArm)} first)` : '';
        const dur = s.durationSec ? ` · ${s.durationSec.toFixed(1)}s` : '';
        const grip = editable
            ? `<button type="button" class="sch-grip" data-row="${s.index}" title="Drag to reorder" aria-label="Drag to reorder row ${s.index}">⠿</button>`
            : '<span class="sch-lock" title="Session phase — defined in session_phases.py, not a CSV row">🔒</span>';
        const actions = (editable && i === schState.stepIdx)
            ? ` <button type="button" class="sch-row-edit" data-row="${s.index}" title="Edit this row (type, regions, arms)">✎ edit</button>`
              + `<button type="button" class="sch-row-del" data-row="${s.index}" title="Remove this row from the sequence">✕ remove</button>`
            : '';
        return `<div class="${cls}" data-step="${i}">${grip}`
            + `<div class="sch-step-title">${i}. ${escapeHtml(s.description || s.type)}`
            + ` <span class="sch-step-tag">${escapeHtml(s.type)}${arm}</span>${miss}</div>`
            + `<span class="sch-pill ${v.cls}">${v.glyph} ${escapeHtml(v.word)}</span>`
            + `<div class="sch-step-meta">${escapeHtml(schStepPlansSummary(s))}${dur}${actions}</div>`
            + `</div>`;
    }).join('');
    el.querySelectorAll('.sch-step').forEach(node =>
        node.addEventListener('click', () => schGotoStep(parseInt(node.dataset.step, 10))));
    el.querySelectorAll('.sch-row-edit').forEach(btn =>
        btn.addEventListener('click', e => { e.stopPropagation(); schEditStep(parseInt(btn.dataset.row, 10)); }));
    el.querySelectorAll('.sch-row-del').forEach(btn =>
        btn.addEventListener('click', e => { e.stopPropagation(); schRemoveRow(parseInt(btn.dataset.row, 10)); }));
    el.querySelectorAll('.sch-grip').forEach(gripEl =>
        schWireRowDrag(gripEl, parseInt(gripEl.dataset.row, 10), gripEl.closest('.sch-step')));
    schRenderTimeline();
}

// Pointer-based drag-to-reorder shared by the list grips and the track bars.
// The drop target is a ROW boundary; session phases bracket the rows and are
// not valid targets. A 5px threshold keeps plain clicks selecting, not dragging.
function schWireRowDrag(handle, rowIdx, ghostEl) {
    handle.addEventListener('pointerdown', down => {
        if (down.button !== 0) return;
        down.preventDefault();
        let dragging = false;
        let target = null;                 // row index the drop inserts BEFORE
        const steps = [...document.querySelectorAll('#schStepList .sch-step')]
            .filter(n => schState.steps[+n.dataset.step] && schState.steps[+n.dataset.step].index != null);
        const clear = () => steps.forEach(n => n.classList.remove('drop-before', 'drop-after'));
        const move = ev => {
            if (!dragging && Math.abs(ev.clientY - down.clientY) < 5) return;
            dragging = true;
            if (ghostEl) ghostEl.classList.add('drag-src');
            clear();
            target = null;
            for (const n of steps) {
                const r = n.getBoundingClientRect();
                if (ev.clientY < r.top + r.height / 2) {
                    n.classList.add('drop-before');
                    target = schState.steps[+n.dataset.step].index;
                    return;
                }
            }
            const last = steps[steps.length - 1];
            if (last) { last.classList.add('drop-after'); target = schState.rows.length; }
        };
        const up = () => {
            document.removeEventListener('pointermove', move);
            document.removeEventListener('pointerup', up);
            clear();
            if (ghostEl) ghostEl.classList.remove('drag-src');
            if (dragging && target != null) schMoveRow(rowIdx, target);
        };
        document.addEventListener('pointermove', move);
        document.addEventListener('pointerup', up);
    });
}

// Rich readout for the active step — shown in the Properties dock.
function schRenderStepDetail(i) {
    const el = document.getElementById('schStepDetail');
    if (!el) return;
    const s = schState.steps[i];
    if (!s) { el.innerHTML = '<div class="info-row"><span>&mdash;</span><code>Load a schedule, then pick a step.</code></div>'; return; }
    const rows = [`<div class="info-row"><span>Step ${i} · ${escapeHtml(s.type)}</span><code>${escapeHtml(s.description || '')}</code></div>`];
    if (s.index != null && schState.rows[s.index])
        rows.push(`<div class="info-row"><span>Row ${s.index}</span><code>${escapeHtml(schState.rows[s.index].filter(Boolean).join(' , '))}</code></div>`);
    if (s.durationSec) rows.push(`<div class="info-row"><span>Duration</span><code>${s.durationSec.toFixed(1)} s</code></div>`);
    const { starts, durs } = schTimelineLayout();
    if (starts[i] != null)
        rows.push(`<div class="info-row"><span>Window</span><code>${starts[i].toFixed(1)} – ${(starts[i] + durs[i]).toFixed(1)} s</code></div>`);
    rows.push(`<div class="info-row"><span>Plans</span><span class="sch-plan-chips">${schStepPlanChips(s)}</span></div>`);
    const fx = schStepFixtureState(s);
    if (fx) rows.push(`<div class="info-row"><span>Fixture</span><code>${combinedFixture()
        ? escapeHtml(fx.fixtureType)
        : Object.entries(fx.states).map(([p, st]) => `${p} ${st}`).join(' · ')}</code></div>`);
    if (s.index != null) {
        const colV = schState.collisions[schCellKey(s.index)];
        const checkable = schStepPairs(s).length > 0;
        const word = !checkable ? 'n/a (no inter-arm overlap)'
            : !colV ? '↻ unchecked — run Check Collisions'
            : colV.error ? `error: ${colV.error}`
            : colV.count > 0 ? `⛔ ${colV.count} contact sample(s)` : '✓ clear';
        rows.push(`<div class="info-row"><span>Collision</span><code>${escapeHtml(word)}</code></div>`);
    }
    if (s.missing) rows.push('<div class="info-row"><span style="color:var(--warning)">⚠</span><code>plan(s) missing for this step</code></div>');
    el.innerHTML = rows.join('');
    schRenderGuardInfo();
}

// The Guards panel: aggregate chips for the three tiers plus the selected
// row's sentences. Every verdict is a sentence — the reader should never have
// to decode a color.
function schRenderGuardInfo() {
    const el = document.getElementById('schGuardInfo');
    if (!el) return;
    if (!schState.guards || !schState.steps.length) {
        el.innerHTML = '<div class="info-row"><span>&mdash;</span><code>Load a schedule to evaluate the guards.</code></div>';
        return;
    }
    const rowsG = schState.guards.rows || [];
    const count = (tier, level) => rowsG.reduce((n, r) => n + r[tier].filter(v => v.level === level).length, 0);
    const seqWarn = (schState.guards.sequence || []).filter(v => v.level === 'warning').length;
    const rowSteps = schState.steps.filter(s => s.index != null);
    const checkable = rowSteps.filter(s => schStepPairs(s).length);
    const swept = checkable.filter(s => { const c = schState.collisions[schCellKey(s.index)]; return c && !c.error; });
    const hits = swept.filter(s => schState.collisions[schCellKey(s.index)].count > 0);
    const chip = (label, err, warn, extra) => {
        const cls = err ? 'g-bad' : warn ? 'g-warn' : 'g-ok';
        const glyph = err ? '⛔' : warn ? '⚠' : '✓';
        return `<span class="axm-chip ${cls}">${glyph} ${label} <span class="val">${extra}</span></span>`;
    };
    const colErr = hits.length > 0;
    const colStale = swept.length < checkable.length;
    const colExtra = colErr ? `${hits.length} hit` : `${swept.length}/${checkable.length} swept`;
    const chips = [
        chip('logical', count('logical', 'error') > 0, count('logical', 'warning') > 0,
             `${count('logical', 'error')}⛔ ${count('logical', 'warning')}⚠`),
        chip('reality', count('reality', 'error') > 0, count('reality', 'warning') + seqWarn > 0,
             `${count('reality', 'error')}⛔ ${count('reality', 'warning') + seqWarn}⚠`),
        colStale && !colErr
            ? `<span class="axm-chip g-stale">↻ collision <span class="val">${colExtra}</span></span>`
            : chip('collision', colErr, false, colExtra),
    ].join(' ');
    const s = schState.steps[schState.stepIdx];
    const verdicts = s ? schStepGuards(s) : [];
    const sentences = verdicts.length
        ? verdicts.map(v => `<div class="info-row"><span class="${v.level === 'error' ? 'sch-step-missing' : ''}">`
            + `${v.level === 'error' ? '⛔' : v.level === 'warning' ? '⚠' : '·'}</span>`
            + `<code>${escapeHtml(v.sentence)}</code></div>`).join('')
        : (s && s.index != null ? '<div class="info-row"><span>✓</span><code>No findings for this row.</code></div>' : '');
    const seq = (schState.guards.sequence || []).map(v =>
        `<div class="info-row"><span>⚠</span><code>${escapeHtml(v.sentence)}</code></div>`).join('');
    el.innerHTML = `<div class="info-row"><span>Tiers</span><code class="axm-chips">${chips}</code></div>`
        + sentences + seq;
}

// Execution status (Properties dock). HONEST: the studio has no execution
// channel — the orchestrator runs sessions ROS-side and nothing here commands
// hardware — so this panel reports the offline preview playback and says so.
function schRenderRunInfo() {
    const el = document.getElementById('schRunInfo');
    if (!el) return;
    const n = schState.steps.length;
    if (!n) {
        el.innerHTML = '<div class="info-row"><span>Run</span><code>idle — offline preview (arms not connected)</code></div>';
        return;
    }
    const { starts, durs, total } = schTimelineLayout();
    const i = schState.stepIdx;
    const t = starts[i] + Math.max(0, Math.min(1, schState.playT || 0)) * durs[i];
    const state = schState.playing ? '▶ playing' : 'idle';
    el.innerHTML =
        `<div class="info-row"><span>Run</span><code>${state} — offline preview (arms not connected)</code></div>`
        + `<div class="info-row"><span>Step</span><code>${i + 1} / ${n}</code></div>`
        + `<div class="info-row"><span>t</span><code>${t.toFixed(1)} / ${total.toFixed(1)} s</code></div>`
        + (schState.dirty ? '<div class="info-row"><span>⚠</span><code>unsaved sequence edits — Save Schedule writes the CSV</code></div>' : '');
}

// The concurrent-motion segments to play for a step, in order. Most steps are a
// single segment; a SERIAL step is two (first arm, then the other). Each segment
// is a /api/plan-frames request body: {plans} for concurrent motion, or {tracks}
// for chained steps (per-arm plan sequences). Missing-plan slots are skipped.
function schStepSegments(step) {
    const P = slot => (slot && slot.plan) ? slot.plan : null;
    const segs = [];
    if (step.type === 'compound') {
        const p = P(step.compound); if (p) segs.push({ body: { plans: [p] }, label: 'compound' });
    } else if (step.type === 'chained') {
        const L = (step.leftChain || []).map(P).filter(Boolean);
        const R = (step.rightChain || []).map(P).filter(Boolean);
        const tracks = [];
        if (L.length) tracks.push({ plans: L, start: 0 });
        if (R.length) tracks.push({ plans: R, start: 0 });
        if (tracks.length) segs.push({ body: { tracks }, label: 'chain' });
    } else if (step.type === 'serial') {
        const first = step.firstArm === 'right' ? step.right : step.left;
        const second = step.firstArm === 'right' ? step.left : step.right;
        [first, second].forEach((slot, k) => {
            const p = P(slot); if (p) segs.push({ body: { plans: [p] }, label: k === 0 ? 'first arm' : 'second arm' });
        });
    } else { // paired / single
        const ps = [P(step.left), P(step.right)].filter(Boolean);
        if (ps.length) segs.push({ body: { plans: ps }, label: step.type });
    }
    return segs;
}

// Fixture (lid/seat) articulation for a step, from its region's
// commode_fixture_type — the SAME source of truth the DAC tab uses.
function schStepFixtureState(step) {
    let key = null;
    if (step.type === 'compound') key = step.compound && step.compound.regionKey;
    else if (step.type === 'chained') key = (step.leftChain && step.leftChain[0] && step.leftChain[0].regionKey)
        || (step.rightChain && step.rightChain[0] && step.rightChain[0].regionKey);
    else key = (step.left && step.left.regionKey) || (step.right && step.right.regionKey);
    const reg = key && viewerManifest && viewerManifest.regions && viewerManifest.regions[key];
    if (!reg) return null;
    const fixtureType = reg.commodeFixtureType || 'closed';
    return { states: fixtureStatesFromType(fixtureType), fixtureType };
}

function schRenderFixture(states, fixtureType = null) {
    const specs = states ? fixtureMeshSpecs(states, {fixtureType}) : [];
    renderFixtureCompanions(specs, 0.7, null);
    renderScene();
}

// Mechanism steps actuate the fixture: instead of snapping, animate the part
// swinging about its hinge, synced to the step's playback progress. Any
// articulated part in the registry with a "<part>_open" / "<part>_close"
// mechanism region key qualifies (lid_open, seat_open, a washtub cover_open…).
// The other parts sit in the states implied by the mechanism's END state
// (commode: seat_open ends seat open ⇒ lid open; lid_open/close leave the
// seat closed).
function schStepMechanism(step) {
    const key = (step.compound && step.compound.regionKey)
        || (step.left && step.left.regionKey) || (step.right && step.right.regionKey);
    const match = key && /^(.+)_(open|close)$/.exec(key);
    if (!match) return null;
    const part = articulatedFixtureParts().find(p => p.name === match[1]);
    if (!part) return null;
    const opening = match[2] === 'open';
    const endStates = applyPartImplies({...defaultFixtureStates(),
        [part.name]: opening ? 'open' : 'closed'});
    const others = {};
    Object.entries(endStates).forEach(([name, st]) => { if (name !== part.name) others[name] = st; });
    return { key, comp: part.name, from: opening ? 'closed' : 'open',
             to: opening ? 'open' : 'closed', others };
}

// Add the animating component's CLOSED base mesh to the companion group, rotated
// about the EXACT world hinge (pivotWorld, axisWorld — computed server-side by the
// same resolver the manifest bakes with, mirroring the C++ ArticulatedSceneBuilder)
// by deltaDeg from closed. The baked *_closed mesh is the base at 0°, so this
// reproduces *_open at openDeg for any fixture orientation.
function schRenderHingedComponent(comp, hinge, deltaDeg) {
    const payload = viewerManifest && viewerManifest.meshes && viewerManifest.meshes[`${comp}_closed`];
    if (!payload || !companionGroup || !window.THREE || !hinge.pivotWorld || !hinge.axisWorld) return;
    if (!partToggleChecked(comp)) return;
    const mesh = meshFromPayload(payload, colors.companion, 0.7);
    mesh.name = `fixture ${comp}_hinged`;
    const P = new THREE.Vector3(hinge.pivotWorld[0], hinge.pivotWorld[1], hinge.pivotWorld[2]);
    const A = new THREE.Vector3(hinge.axisWorld[0], hinge.axisWorld[1], hinge.axisWorld[2]).normalize();
    const m = new THREE.Matrix4().makeTranslation(P.x, P.y, P.z)
        .multiply(new THREE.Matrix4().makeRotationAxis(A, deltaDeg * Math.PI / 180))
        .multiply(new THREE.Matrix4().makeTranslation(-P.x, -P.y, -P.z));
    mesh.matrixAutoUpdate = false;
    mesh.matrix.copy(m);
    companionGroup.add(mesh);
}

// Render the fixture mid-mechanism at an ABSOLUTE hinge angle: body +
// non-animating parts static, animating part swung to angleDeg.
function schRenderFixtureHingedAngle(mech, hinge, angleDeg) {
    const specs = manifestParts()
        .filter(part => part.name !== mech.comp)
        .map(part => ({ component: part.name, meshKey: partMeshKey(part, mech.others || {}) }));
    renderFixtureCompanions(specs, 0.7, null);                             // clears + draws static parts
    schRenderHingedComponent(mech.comp, hinge, angleDeg - hinge.closedDeg); // adds swung part
    renderScene();
}

// Linear fallback: part swung by playback progress. Returns false if no hinge
// (caller snaps). The EE-driven timeline (schMechTimeline) is preferred when it
// can be derived from the step's traced path.
function schRenderFixtureHinged(mech, t01) {
    const hinge = schState.hinges && schState.hinges[mech.comp];
    if (!hinge) return false;
    const ang = s => (s === 'open' ? hinge.openDeg : hinge.closedDeg);
    const a = Math.max(0, Math.min(1, t01 == null ? 0 : t01));
    schRenderFixtureHingedAngle(mech, hinge, ang(mech.from) + (ang(mech.to) - ang(mech.from)) * a);
    return true;
}

// ===== Path-driven mechanism articulation ==================================
// The lid/seat angle timeline is computed SERVER-side (/api/plan-frames with
// body.mech = {fixture, regionKey} → payload.hinge_angles): the IK frame of the
// arm doing each configured trace_trajectory stage is tracked along the task's
// cleaning path (start_pose → sequence points, alix_ref_frame), and its
// signed sweep about the hinge axis — pivot/axis resolved exactly as the C++
// ArticulatedSceneBuilder in cleaning_tasks — gives the part angle, landing on
// each trace's update_fixture_scene target (e.g. seat_open: right arm 0→-30°,
// hand-off, left arm -30→-110°). Outside trace windows the part holds still.
function schMechBody(step, segBody) {
    const body = Object.assign({}, segBody);
    if (step.carryJoints) body.initial = step.carryJoints;
    const mech = schStepMechanism(step);
    if (mech && schState.hinges && schState.hinges[mech.comp] && schState.fixture)
        body.mech = { fixture: schState.fixture, regionKey: mech.key };
    return body;
}

// Articulate the scene for a step at playback progress t01 (0 = step start).
// Mechanism steps with hinge data animate; everything else snaps to its state.
function schArticulateStep(step, t01) {
    const mech = schStepMechanism(step);
    if (mech && schState.hinges && schState.hinges[mech.comp]) schRenderFixtureHinged(mech, t01);
    else { const fx = schStepFixtureState(step); schRenderFixture(fx && fx.states, fx && fx.fixtureType); }
}

async function schFetchFrames(body) {
    const key = JSON.stringify(body);
    if (schState.frameCache.has(key)) return schState.frameCache.get(key);
    const payload = await api('/api/plan-frames', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(Object.assign({ dt: SCH_DT }, body)),
    });
    schState.frameCache.set(key, payload);
    return payload;
}

function schFrameInfo(stepIdx, pos, n) {
    const info = document.getElementById('schFrameInfo');
    const s = schState.steps[stepIdx];
    if (info) info.innerHTML = `<span>Step ${stepIdx}/${schState.steps.length - 1} · ${pos}/${Math.max(0, n - 1)}</span> `
        + `<code>${escapeHtml(s ? (s.description || s.type) : '')}</code>`;
}

function schSetPlaying(on, mode) {
    if (on) schState.playMode = mode || 'all';
    const play = document.getElementById('schPlayButton');
    const one = document.getElementById('schPlayStepButton');
    const file = document.getElementById('schPlayPlanButton');
    const stop = document.getElementById('schStopButton');
    const has = schState.steps.length > 0;
    // F75: the DRIVING play button stays ENABLED while playing and becomes
    // Pause — halting at the current FRAME; the same ▶ resumes from it
    // (schPause/schState.resume). Stop remains the hard halt. The other play
    // buttons are disabled while playing so the modes cannot interleave.
    if (play) {
        play.disabled = !has || (on && schState.playMode !== 'all');
        play.textContent = on && schState.playMode === 'all' ? '⏸ Pause' : '▶ Play all';
    }
    if (one) {
        one.disabled = !has || (on && schState.playMode !== 'step');
        one.textContent = on && schState.playMode === 'step' ? '⏸ Pause' : '▶ Play step';
    }
    if (file) {
        // Needs a picked file, NOT a loaded schedule — direct plan playback
        // works with the schedule empty (that is its point).
        file.disabled = !schState.planFile || (on && schState.playMode !== 'file');
        file.textContent = on && schState.playMode === 'file' ? '⏸ Pause' : '▶ Play plan file';
    }
    if (stop) stop.disabled = !on;
    if (!on) schState.playMode = null;
}

// Move the selection to step i, keeping the solo only when the step is
// unchanged. EVERY stepIdx write goes through here — solo is per-step, and a
// write that bypasses the clear leaves a stale solo armed on a step the user
// never soloed (playback advancing was exactly such a bypass).
function schSelectStep(i) {
    if (i !== schState.stepIdx) schState.soloPlan = null;
    schState.stepIdx = i;
}

// Jump to a step: stop playback, snap the fixture, and show the step's starting pose.
async function schGotoStep(i) {
    if (!schState.steps.length) return;
    schStop();
    i = Math.max(0, Math.min(schState.steps.length - 1, i));
    schSelectStep(i);
    schState.playT = 0;
    schUpdatePlayhead();
    schRenderRunInfo();
    const slider = document.getElementById('schSlider');
    if (slider) { slider.max = schState.steps.length - 1; slider.value = i; }
    schRenderSteps();
    const step = schState.steps[i];
    schArticulateStep(step, 0);   // snap (or mechanism 'from' state) at step start
    schFrameInfo(i, 0, 0);
    schRenderStepDetail(i);
    const segs = schSoloSegments(step);
    if (!segs.length) return;   // all plans missing — fixture-only preview
    // schStop() above bumped playRun, so this token also expires the pending
    // preview of any EARLIER goto/chip-click — rapid toggling would otherwise
    // let a slow fetch resolve last and paint a pose for a stale solo state.
    const run = schState.playRun;
    try {
        const payload = await schFetchFrames(schMechBody(step, segs[0].body));
        if (run !== schState.playRun) return;   // superseded while fetching
        if (payload && payload.frames) { applyRobotPose(payload.frames['0']); schFrameInfo(i, 0, payload.num_samples); }
    } catch (e) { schSetStatus('Render failed: ' + e.message, true); }
}

// Play one segment's frames to completion (or until stopped). onFrame(pos, n)
// is called each frame (used to drive the hinge on mechanism steps).
// `startPos` resumes mid-segment; each shown frame updates the cursor
// schPause() snapshots.
function schPlaySegment(payload, stepIdx, onFrame, segIdx = 0, startPos = 0) {
    return new Promise(resolve => {
        const n = (payload && payload.num_samples) || 0;
        if (!n) { resolve(); return; }
        const stepMs = Math.max(16, ((payload.dt || SCH_DT) * 1000) / SCH_SPEED);
        let pos = Math.max(0, Math.min(n - 1, startPos));
        schState.timer = setInterval(() => {
            if (!schState.playing || pos >= n) {
                clearInterval(schState.timer); schState.timer = null; resolve(); return;
            }
            schState.playPos = { stepIdx, segIdx, pos };
            applyRobotPose(payload.frames[String(pos)]);
            schFrameInfo(stepIdx, pos, n);
            schState.playT = n > 1 ? pos / (n - 1) : 1;
            schUpdatePlayhead();
            schRenderRunInfo();
            if (onFrame) onFrame(pos, n);
            pos++;
        }, stepMs);
    });
}

// Render and play ONE step's segments in order: fixture articulation at the
// step start, hinge timeline on mechanism steps, joint carry across the step's
// own segments. Enters from the step's server-computed carry-in state
// (step.carryJoints — what all previous steps' plans leave the robot in), so a
// step plays identically whether reached by ▶ Play all or ▶ Play step. `segs`
// is passed in so Play step can substitute the soloed single-plan segment.
async function schPlayOneStep(si, segs, run, start) {
    const step = schState.steps[si];
    schSelectStep(si);   // clears a solo armed on a DIFFERENT step
    const slider = document.getElementById('schSlider'); if (slider) slider.value = si;
    schRenderSteps();
    schRenderStepDetail(si);   // keep the chips/detail honest as playback advances
    const mech = schStepMechanism(step);
    const hinge = mech && schState.hinges && schState.hinges[mech.comp];
    schArticulateStep(step, 0);   // fixture at step start (snap, or mechanism 'from')
    let carry = step.carryJoints || null;   // joint state entering this segment
    for (let k = 0; k < segs.length; k++) {
        const seg = segs[k];
        if (!schState.playing || run !== schState.playRun) break;
        // Set the cursor BEFORE the fetch: pausing while "Rendering…" resumes
        // at this segment's start instead of losing the position entirely.
        schState.playPos = { stepIdx: si, segIdx: k,
                             pos: start && k === start.segIdx ? start.pos || 0 : 0 };
        let payload;
        const body = Object.assign({}, seg.body);
        if (carry) body.initial = carry;
        if (hinge) body.mech = { fixture: schState.fixture, regionKey: mech.key };
        try { schSetStatus(`Rendering step ${si} (${seg.label})…`); payload = await schFetchFrames(body); }
        catch (e) {
            if (run !== schState.playRun) break;
            schSetStatus(`Step ${si} render failed: ${e.message}`, true); continue;
        }
        // Re-check AFTER the await: a Stop during the fetch bumps playRun, and
        // a successor run may already own schState.timer — resuming here would
        // interleave the two (the fetch itself cannot be aborted).
        if (!schState.playing || run !== schState.playRun) break;
        if (!payload) continue;
        if (start && k < start.segIdx) {
            // Segment finished before the pause: fold its end state into the
            // carry (cache hit — it was fetched during the paused run) and
            // move on without replaying it.
            if (payload.final_joints) carry = Object.assign({}, carry || {}, payload.final_joints);
            continue;
        }
        let onFrame = null;
        if (hinge) {
            // Server-derived angle timeline from the traced path (see
            // schMechBody); linear progress only if it couldn't be derived.
            const angles = payload.hinge_angles;
            onFrame = (pos, cnt) => {
                if (angles && angles.length) schRenderFixtureHingedAngle(mech, hinge, angles[Math.min(pos, angles.length - 1)]);
                else schRenderFixtureHinged(mech, cnt > 1 ? pos / (cnt - 1) : 1);
            };
        }
        await schPlaySegment(payload, si, onFrame, k,
                             start && k === start.segIdx ? start.pos || 0 : 0);
        if (payload.final_joints) carry = Object.assign({}, carry || {}, payload.final_joints);
    }
}

// Play the whole process from the current step to the end, snapping the fixture at
// each step boundary and playing every segment in order. Joint state is carried
// across segments/steps (server `initial`), so un-driven joints hold their pose
// instead of snapping back to ready between rows.
async function schPlay() {
    if (!schState.steps.length) return;
    if (schState.playing) { schPause(); return; }   // F75: Play toggles to pause
    // Consume a matching pause point: same mode, still on the paused step.
    const rz = (schState.resume && schState.resume.mode === 'all'
                && schState.resume.stepIdx === schState.stepIdx) ? schState.resume : null;
    schState.resume = null;
    if (!rz && schState.stepIdx >= schState.steps.length - 1) schSelectStep(0);
    schState.playing = true;
    const run = ++schState.playRun;
    schSetPlaying(true, 'all');
    let completed = false;
    for (let si = schState.stepIdx; si < schState.steps.length; si++) {
        if (!schState.playing || run !== schState.playRun) break;
        await schPlayOneStep(si, schStepSegments(schState.steps[si]), run,
                             rz && si === rz.stepIdx ? rz : null);
        completed = si === schState.steps.length - 1 && run === schState.playRun;
    }
    if (run !== schState.playRun) return;   // superseded — schStop/schPause reported it
    schState.playing = false;
    schSetPlaying(false);
    schSetStatus(completed ? 'Playback complete.' : 'Stopped.');
}

// ▶ Play step — play ONLY the selected step (or its soloed plan file), then
// stop, so a single saved plan can be introspected without rolling on into the
// rest of the sequence. Missing plans elsewhere in the schedule are irrelevant
// here; a step whose own plans are all missing has nothing to animate.
async function schPlayStep() {
    if (!schState.steps.length) return;
    if (schState.playing) { schPause(); return; }   // toggles to pause, like Play all
    const si = schState.stepIdx;
    const segs = schSoloSegments(schState.steps[si]);
    if (!segs.length) { schSetStatus(`Step ${si}: no plan recorded — nothing to play.`, true); return; }
    // What ACTUALLY plays, not what is armed — schSoloSegments may have
    // rejected a stale solo and fallen back to the full step.
    const soloPlayed = segs.length === 1 && segs[0].label === 'solo' ? segs[0].body.plans[0] : null;
    // Consume a matching pause point (same mode, same step; a solo change in
    // between routed through schGotoStep → schStop, which cleared it).
    const rz = (schState.resume && schState.resume.mode === 'step'
                && schState.resume.stepIdx === si) ? schState.resume : null;
    schState.resume = null;
    schState.playing = true;
    const run = ++schState.playRun;
    schSetPlaying(true, 'step');
    await schPlayOneStep(si, segs, run, rz);
    if (run !== schState.playRun) return;   // superseded — schStop/schPause reported it
    schState.playing = false;
    schSetPlaying(false);
    schSetStatus(soloPlayed ? `Played ${soloPlayed.split('/').pop()} (solo).`
                            : `Step ${si} playback complete.`);
}

// ===== Direct plan-file playback ===========================================
// Play ANY saved plan JSON under the plan roots — no schedule loaded, no
// orchestrator filename contract. The resolver only decides what a SCHEDULE
// step maps to; a plan it cannot name (e.g. bin_*_dual_joint_* vs the
// contract's dual_bin_* stems) is still a valid trajectory, and /api/plans +
// /api/plan-frames accept anything under the allowed roots. Robot motion
// only: the fixture stays as currently shown.

async function schPopulatePlanFiles() {
    if (schState.planCatalog.length) return;   // already loaded
    let plans = [];
    try { plans = (await api('/api/plans')).plans || []; }
    catch (e) { plans = []; }   // static/file:// — list renders its empty note
    schState.planCatalog = plans
        .map(p => ({ path: p.path, name: p.name,
                     dir: p.path.slice(0, -(p.name.length + 1)) }))
        .sort((a, b) => a.name.localeCompare(b.name) || a.dir.localeCompare(b.dir));
    schRenderPlanList();
}

// The filter input: every whitespace-separated token must match somewhere in
// the repo-relative path — "bin totg" narrows 105 files to the bin plans.
function schRenderPlanList() {
    const list = document.getElementById('schPlanList');
    if (!list) return;
    const tokens = (document.getElementById('schPlanFilter')?.value || '')
        .toLowerCase().split(/\s+/).filter(Boolean);
    const shown = schState.planCatalog.filter(p =>
        tokens.every(t => p.path.toLowerCase().includes(t)));
    if (!shown.length) {
        list.innerHTML = `<div class="sch-plan-empty">${schState.planCatalog.length
            ? 'No plan matches the filter.' : 'No plans found under the plan roots.'}</div>`;
        return;
    }
    list.innerHTML = shown.map(p =>
        `<button type="button" class="sch-plan-item${p.path === schState.planFile ? ' selected' : ''}"`
        + ` data-plan="${escapeHtml(p.path)}" title="${escapeHtml(p.path)}">`
        + `<span class="name">${escapeHtml(p.name)}</span>`
        + `<span class="dir">${escapeHtml(p.dir)}</span></button>`).join('');
}

// Click selects (click again to clear); the robot snaps to the plan's first
// sample so the pick is immediately inspectable, and a structurally
// unsupported file reports its load error right here.
async function schPlanItemClick(e) {
    const item = e.target.closest('.sch-plan-item[data-plan]');
    if (!item) return;
    const plan = item.dataset.plan === schState.planFile ? null : item.dataset.plan;
    schState.planFile = plan;
    schStop();               // also bumps playRun — expires older previews
    schSetPlaying(false);    // re-evaluate the ▶ button for the new pick
    schRenderPlanList();
    if (!plan) return;
    const run = schState.playRun;
    const name = plan.split('/').pop();
    try {
        const payload = await schFetchFrames({ plans: [plan] });
        if (run !== schState.playRun) return;
        if (payload && payload.frames) {
            applyRobotPose(payload.frames['0']);
            schSetStatus(`${name}: ${payload.num_samples} samples · `
                + `${(payload.num_samples * (payload.dt || SCH_DT)).toFixed(1)} s — ▶ plays it.`);
        }
    } catch (e2) {
        if (run === schState.playRun) schSetStatus(`${name}: load failed — ${e2.message}`, true);
    }
}

// Frame loop for a standalone plan. Deliberately NOT schPlaySegment: that one
// narrates step indices and drives the step playhead, none of which exist
// without a schedule.
function schPlayFileFrames(payload, plan, run, startPos = 0) {
    return new Promise(resolve => {
        const n = (payload && payload.num_samples) || 0;
        if (!n) { resolve(); return; }
        const stepMs = Math.max(16, ((payload.dt || SCH_DT) * 1000) / SCH_SPEED);
        const info = document.getElementById('schFrameInfo');
        const name = plan.split('/').pop();
        let pos = Math.max(0, Math.min(n - 1, startPos));
        schState.timer = setInterval(() => {
            if (!schState.playing || run !== schState.playRun || pos >= n) {
                clearInterval(schState.timer); schState.timer = null; resolve(); return;
            }
            schState.playPos = { plan, pos };
            applyRobotPose(payload.frames[String(pos)]);
            if (info) info.innerHTML = `<span>${pos}/${n - 1}</span> <code>${escapeHtml(name)}</code>`;
            pos++;
        }, stepMs);
    });
}

async function schPlayPlanFile() {
    const plan = schState.planFile;
    if (!plan) return;
    if (schState.playing) { schPause(); return; }   // toggles to pause, like the others
    // Consume a matching pause point (same mode, same file).
    const rz = (schState.resume && schState.resume.mode === 'file'
                && schState.resume.plan === plan) ? schState.resume : null;
    schState.resume = null;
    const name = plan.split('/').pop();
    schState.playing = true;
    const run = ++schState.playRun;
    schSetPlaying(true, 'file');
    schState.playPos = { plan, pos: rz ? rz.pos || 0 : 0 };   // pause-during-fetch cursor
    let payload = null;
    try { schSetStatus(`Rendering ${name}…`); payload = await schFetchFrames({ plans: [plan] }); }
    catch (e) {
        if (run !== schState.playRun) return;
        schState.playing = false;
        schSetPlaying(false);
        schSetStatus(`${name}: render failed — ${e.message}`, true);
        return;
    }
    if (!schState.playing || run !== schState.playRun) return;
    await schPlayFileFrames(payload, plan, run, rz ? rz.pos || 0 : 0);
    if (run !== schState.playRun) return;   // superseded — schStop/schPause reported it
    schState.playing = false;
    schSetPlaying(false);
    schSetStatus(`Played ${name}.`);
}

// Hard halt: discards the frame cursor, so the next ▶ starts fresh. Every
// navigation/selection change routes through here — a pause point does not
// survive the context it was taken in changing under it.
function schStop() {
    const wasPlaying = schState.playing;
    schState.playing = false;
    schState.playRun++;   // invalidate any run suspended in an await
    schState.resume = null;
    schState.playPos = null;
    if (schState.timer) { clearInterval(schState.timer); schState.timer = null; }
    schSetPlaying(false);
    // The interrupted run's epilogue is token-guarded (it must not clobber a
    // successor run's UI state), so the interruption is reported from here.
    if (wasPlaying) schSetStatus('Stopped.');
}

// Soft halt (the ⏸ face of the driving play button): snapshots the frame
// cursor so the SAME ▶ continues from the paused frame instead of replaying
// the step/plan from its start.
function schPause() {
    if (!schState.playing) { schStop(); return; }
    schState.resume = Object.assign({ mode: schState.playMode }, schState.playPos || {});
    schState.playing = false;
    schState.playRun++;
    if (schState.timer) { clearInterval(schState.timer); schState.timer = null; }
    schSetPlaying(false);
    schSetStatus('Paused — the same ▶ resumes from this frame.');
}

// Proportional master timeline (F69) — a DOM track of textured bar buttons.
// Plotly is gone from this tab: bars are buttons, so the timeline can be
// EDITED (drag to reorder) and every state is a CSS class, not a re-plot.
// Step TYPE reads as texture + 2-letter code + word; the SCH_TYPE_COLOR hue
// survives only on the bcode chip border as a redundant cue (and it still
// feeds the legend swatches).
const SCH_TYPE_COLOR = { paired: '#00d4ff', serial: '#f0a020', single: '#7ee787',
                        chained: '#a371f7', compound: '#ff6b9d' };
const SCH_TYPE_TEXTURE = { paired: 't-pa', serial: 't-se', single: '', chained: 't-ch', compound: 't-co' };
const SCH_TYPE_CODE = { paired: 'PA', serial: 'SE', single: 'SI', chained: 'CH', compound: 'CO' };

// Timeline geometry shared with the playhead: starts/durations include the
// orchestrator's inter-row settling delay (task_delay) so the axis is the
// honest wall clock, not just the sum of trajectories.
function schTimelineLayout() {
    const delay = schState.taskDelaySec || 0;
    let acc = 0; const starts = [], durs = [];
    schState.steps.forEach((s, i) => {
        starts.push(acc);
        const d = Math.max(0.4, s.durationSec || 0.4);
        durs.push(d);
        acc += d + (i < schState.steps.length - 1 ? delay : 0);
    });
    return { starts, durs, total: acc || 1 };
}

function schRenderTimeline() {
    const track = document.getElementById('schTrack');
    const ruler = document.getElementById('schRuler');
    if (!track || !ruler) return;
    const steps = schState.steps;
    if (!steps.length) { track.innerHTML = ''; ruler.innerHTML = ''; return; }
    const { starts, durs, total } = schTimelineLayout();

    track.innerHTML = steps.map((s, i) => {
        const locked = s.index == null;
        const v = schStepVerdict(s);
        const cls = ['sch-bar', SCH_TYPE_TEXTURE[s.type] || '',
            locked ? 't-ph is-locked' : '',
            i === schState.stepIdx ? 'is-now' : '',
            v.level === 'error' ? 'is-bad' : '',
            v.level === 'warning' ? 'is-warn' : '',
            v.level === 'stale' ? 'is-stale' : ''].filter(Boolean).join(' ');
        const color = SCH_TYPE_COLOR[s.type] || '#8b949e';
        const label = `${i}. ${s.description || s.type} — ${durs[i].toFixed(1)}s`
            + ` (${s.type}${locked ? ', session phase' : `, row ${s.index}`}`
            + `${v.level === 'ok' ? '' : `, ${v.word}`})`;
        return `<button type="button" class="${cls}" data-step="${i}" data-row="${locked ? '' : s.index}"`
            + ` style="flex:1 1 ${(durs[i] / total * 100).toFixed(3)}%"`
            + ` title="${escapeHtml(label)}" aria-label="${escapeHtml(label)}">`
            + `<span class="bcode" style="border-color:${color}">${locked ? 'PH' : SCH_TYPE_CODE[s.type] || '?'}</span>`
            + `<span class="bname">${escapeHtml(s.description || s.type)}</span></button>`;
    }).join('') + '<div class="sch-playhead" id="schPlayhead" style="display:none"></div>';

    // Ruler lane: glove/inspection markers at their row boundaries + the mono
    // total. Checkpoint rows are CSV row indices — map them to step positions.
    const stepForRow = r => steps.findIndex(s => s.index === r);
    const marks = [];
    (schState.checkpoints || []).forEach(cp => {
        let x = null;
        if (cp.kind === 'glove' && cp.row != null) {
            const si = stepForRow(cp.row);
            if (si >= 0) x = cp.position === 'after' ? starts[si] + durs[si] : starts[si];
        } else if (cp.kind === 'inspection') {
            if (cp.afterRow == null) {
                const si = steps.findIndex(s => s.index != null);
                if (si >= 0) x = starts[si];
            } else {
                const si = stepForRow(cp.afterRow);
                if (si >= 0) x = starts[si] + durs[si];
            }
        }
        if (x == null) return;
        marks.push(`<button type="button" class="sch-mk" style="left:${(x / total * 100).toFixed(2)}%"`
            + ` title="${escapeHtml(cp.label || cp.kind)}" aria-label="${escapeHtml(cp.label || cp.kind)}">`
            + `${cp.kind === 'glove' ? '🧤' : '🔍'}</button>`);
    });
    const nRows = schState.rows.length;
    ruler.innerHTML = marks.join('')
        + `<span class="sch-tick">${total.toFixed(0)} s · ${nRows} row${nRows === 1 ? '' : 's'}`
        + `${schState.dirty ? ' · unsaved' : ''}</span>`;

    track.querySelectorAll('.sch-bar').forEach(bar => {
        bar.addEventListener('click', () => schGotoStep(parseInt(bar.dataset.step, 10)));
        if (bar.dataset.row !== '') schWireBarDrag(bar, parseInt(bar.dataset.row, 10), track);
    });
    schUpdatePlayhead();
}

// Horizontal drag on a track bar reorders its row; a 5px threshold keeps
// clicks selecting. The drop mark snaps to the nearest row-bar boundary.
function schWireBarDrag(bar, rowIdx, track) {
    bar.addEventListener('pointerdown', down => {
        if (down.button !== 0) return;
        let dragging = false;
        let target = null;
        let mark = null;
        const rowBars = [...track.querySelectorAll('.sch-bar')].filter(b => b.dataset.row !== '');
        const move = ev => {
            if (!dragging && Math.abs(ev.clientX - down.clientX) < 5) return;
            if (!dragging) { dragging = true; bar.classList.add('drag-src'); ev.preventDefault(); }
            const tr = track.getBoundingClientRect();
            target = null;
            let markX = null;
            for (const b of rowBars) {
                const r = b.getBoundingClientRect();
                if (ev.clientX < r.left + r.width / 2) {
                    target = parseInt(b.dataset.row, 10);
                    markX = r.left - tr.left;
                    break;
                }
            }
            if (target == null && rowBars.length) {
                const last = rowBars[rowBars.length - 1].getBoundingClientRect();
                target = schState.rows.length;
                markX = last.right - tr.left;
            }
            if (!mark) { mark = document.createElement('div'); mark.className = 'sch-drop-mark'; track.appendChild(mark); }
            if (markX != null) mark.style.left = `${Math.max(0, Math.min(tr.width - 2, markX))}px`;
        };
        const up = () => {
            document.removeEventListener('pointermove', move);
            document.removeEventListener('pointerup', up);
            bar.classList.remove('drag-src');
            if (mark) mark.remove();
            if (dragging && target != null) schMoveRow(rowIdx, target);
        };
        document.addEventListener('pointermove', move);
        document.addEventListener('pointerup', up);
    });
}

// Playhead: a 2px line at the playback position (step start + in-step progress).
function schUpdatePlayhead() {
    const ph = document.getElementById('schPlayhead');
    if (!ph) return;
    if (!schState.steps.length) { ph.style.display = 'none'; return; }
    const { starts, durs, total } = schTimelineLayout();
    const i = schState.stepIdx;
    const t = starts[i] + Math.max(0, Math.min(1, schState.playT || 0)) * durs[i];
    ph.style.left = `${(t / total * 100).toFixed(3)}%`;
    ph.style.display = 'block';
}

// Run the inter-arm FCL sweep on every CONCURRENT row — paired steps, each
// chained leg, and compound duals (the dual plan against itself) — the same
// pair derivation the save gate consults in the sweep cache, so a row checked
// here is exactly a row the gate will find swept. Verdicts key on the row's
// CELL TEXT: reordering keeps them, re-pairing invalidates them.
async function schCheckCollisions() {
    const checkable = schState.steps
        .filter(s => s.index != null)
        .map(s => ({ s, pairs: schStepPairs(s), key: schCellKey(s.index) }))
        .filter(x => x.pairs.length && x.key);
    if (!checkable.length) { schSetStatus('No concurrent rows with plans to check.'); return; }
    const btn = document.getElementById('schCheckCollisionsButton'); if (btn) btn.disabled = true;
    let done = 0;
    for (const { s, pairs, key } of checkable) {
        schSetStatus(`Checking inter-arm collisions… row ${s.index} (${++done}/${checkable.length})`);
        let count = 0, failed = null;
        for (const [leftPlan, rightPlan] of pairs) {
            try {
                const r = await api('/api/dual-arm-collisions', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ leftPlan, rightPlan, dt: 0.05 }),
                });
                count += (r.collisions || []).length;
            } catch (e) { failed = e.message; break; }
        }
        schState.collisions[key] = failed ? { error: failed } : { count };
        schRenderSteps();
        schRenderStepDetail(schState.stepIdx);
    }
    if (btn) btn.disabled = false;
    // A row whose check ERRORED stores {error} with no `count`, and
    // `undefined > 0` is false — so it fell into the same bucket as "checked,
    // clean" and the summary read "✓ No inter-arm collisions found". A
    // collision check that failed to run must never report clear.
    const results = checkable.map(x => schState.collisions[x.key]).filter(Boolean);
    const hits = results.filter(c => c.count > 0).length;
    const errored = results.filter(c => c.error).length;
    const checked = results.filter(c => typeof c.count === 'number').length;
    let message;
    if (hits) {
        message = `⚠ ${hits} row(s) show inter-arm collisions — see badges.`;
    } else if (errored) {
        message = `⚠ ${errored} of ${checkable.length} row(s) could not be checked `
                + `(${checked} checked, clean). NOT a clean result — see badges.`;
    } else {
        message = `✓ No inter-arm collisions in ${checked} concurrent row(s).`;
    }
    schSetStatus(message, hits > 0 || errored > 0);
}

// ===== Styled confirmation modal (F69) ======================================
// The simulate-deploy card: scrim + centered panel, structure = title →
// resolved destination (displayed, never typed) → chips → sentences → note →
// Cancel / primary. Promise<boolean>; Esc and Cancel resolve false. Replaces
// window.confirm wherever a decision deserves its evidence restated.
function showStudioModal(opts) {
    return new Promise(resolve => {
        const overlay = document.createElement('div');
        overlay.className = 'cmd-overlay show';
        const box = document.createElement('div');
        box.className = 'cmd-box';
        box.setAttribute('role', 'dialog');
        box.setAttribute('aria-modal', 'true');
        box.setAttribute('aria-label', opts.title || 'Confirm');
        const chips = (opts.chips || []).map(c =>
            `<span class="axm-chip ${c.cls || ''}">${c.glyph || ''} ${escapeHtml(c.label || '')}`
            + (c.val != null ? ` <span class="val">${escapeHtml(String(c.val))}</span>` : '') + '</span>').join(' ');
        const lines = (opts.lines || []).map(l =>
            `<li class="lv-${l.level || 'note'}">${l.level === 'error' ? '⛔' : l.level === 'warning' ? '!' : '·'} ${escapeHtml(l.text)}</li>`).join('');
        box.innerHTML = `
            <div class="axm-head"><span class="axm-title">${escapeHtml(opts.title || 'Confirm')}</span>
                <button type="button" class="axm-close" aria-label="Close">&times;</button></div>
            <div class="axm-body">
                ${opts.destFile ? `<div class="axm-f"><span class="axm-lbl">${escapeHtml(opts.destLabel || 'Writes to')}</span>
                    <div class="axm-dest"><span class="dir">${escapeHtml(opts.destDir || '')}</span><span class="file">${escapeHtml(opts.destFile)}</span></div></div>` : ''}
                ${chips ? `<div class="axm-f"><span class="axm-lbl">${escapeHtml(opts.chipsLabel || 'Gates')}</span>
                    <div class="axm-chips">${chips}</div></div>` : ''}
                ${lines ? `<ul class="axm-lines">${lines}</ul>` : ''}
            </div>
            <div class="axm-foot">
                <p class="axm-note">${escapeHtml(opts.note || '')}</p>
                <button type="button" class="axm-cancel">${escapeHtml(opts.cancelLabel || 'Cancel')}</button>
                <button type="button" class="axm-primary">${escapeHtml(opts.confirmLabel || 'Confirm')}</button>
            </div>`;
        overlay.appendChild(box);
        document.body.appendChild(overlay);
        const done = ok => {
            document.removeEventListener('keydown', onKey, true);
            overlay.remove();
            resolve(ok);
        };
        const onKey = e => {
            if (e.key === 'Escape') { e.stopPropagation(); done(false); }
        };
        document.addEventListener('keydown', onKey, true);
        overlay.addEventListener('pointerdown', e => { if (e.target === overlay) done(false); });
        box.querySelector('.axm-close').addEventListener('click', () => done(false));
        box.querySelector('.axm-cancel').addEventListener('click', () => done(false));
        box.querySelector('.axm-primary').addEventListener('click', () => done(true));
        box.querySelector('.axm-primary').focus();
    });
}

// ===== Row editor dialog (add / re-pair / re-arm a schedule row) ============
// A persistent .cmd-dialog built programmatically (a band panel tagged
// data-cmd="dialog" would flip the whole tab into grouped mode). Offers only
// what the region registry allows: arm choices follow arm_coverage, compound
// lists only RL_compound mechanisms — the dialog can't author what tier 1
// would refuse. The chained shape keeps raw cells (its grammar IS the editor).
function schEditStep(rowIdx) {
    document.getElementById('schRowDialog')?.remove();
    const meta = schState.regionsMeta || {};
    const ids = Object.keys(meta).map(Number).sort((a, b) => a - b);
    if (!ids.length) { schSetStatus('No region registry — load a schedule first.', true); return; }
    const cells = rowIdx != null ? (schState.rows[rowIdx] || ['', null]) : null;

    const dlg = document.createElement('div');
    dlg.id = 'schRowDialog';
    dlg.className = 'cmd-dialog';
    dlg.setAttribute('role', 'dialog');
    dlg.setAttribute('aria-label', rowIdx != null ? `Edit row ${rowIdx}` : 'Add step');
    const bar = document.createElement('div');
    bar.className = 'cmd-dialog-head';
    bar.innerHTML = `<span class="cmd-dialog-title">${rowIdx != null ? `Edit row ${rowIdx}` : 'Add step'}</span>`;
    const closeBtn = document.createElement('button');
    closeBtn.className = 'cmd-dialog-close';
    closeBtn.setAttribute('aria-label', 'Close');
    closeBtn.innerHTML = '&times;';
    bar.appendChild(closeBtn);
    dlg.appendChild(bar);
    makeDialogDraggable(dlg, bar);

    const armed = ids.filter(id => (meta[id].armCoverage || '') !== 'RL_compound');
    const compounds = ids.filter(id => (meta[id].armCoverage || '') === 'RL_compound');
    const regionOpts = (list, sel) => list.map(id =>
        `<option value="${id}"${String(id) === String(sel) ? ' selected' : ''}>`
        + `${id} — ${escapeHtml(meta[id].key || '?')} (${escapeHtml(meta[id].description || '')})</option>`).join('');
    const legalArms = id => {
        const cov = (meta[id] && meta[id].armCoverage) || '';
        return cov === 'R' ? ['R'] : cov === 'L' ? ['L'] : ['R', 'L'];
    };

    // Parse existing cells into an initial shape for the form.
    const cellRe = /^(>?)(\d+)([RLC])$/i;
    const parse = raw => { const m = cellRe.exec((raw || '').trim()); return m ? { serial: !!m[1], id: +m[2], arm: m[3].toUpperCase() } : null; };
    const c1 = cells ? parse(cells[0]) : null;
    const c2 = cells && cells[1] ? parse(cells[1]) : null;
    const chained = cells && ((cells[0] || '').includes('>') || (cells[1] || '').includes('>'));
    const initType = !cells ? 'single'
        : chained ? 'chained'
        : c1 && c1.arm === 'C' ? 'compound'
        : c2 ? (c2.serial ? 'serial' : 'paired') : 'single';

    const body = document.createElement('div');
    body.className = 'cmd-dialog-body sch-row-form';
    body.innerHTML = `
        <label class="field-label">Step type</label>
        <select id="schRowType" class="select-field" aria-label="Step type">
            ${['single', 'paired', 'serial', 'chained', 'compound'].map(t =>
                `<option value="${t}"${t === initType ? ' selected' : ''}>${t}</option>`).join('')}
        </select>
        <div data-shape="arm1">
            <label class="field-label">Region</label>
            <select id="schRowR1" class="select-field" aria-label="First region">${regionOpts(armed, c1 && c1.arm !== 'C' ? c1.id : armed[0])}</select>
            <label class="field-label">Arm</label>
            <select id="schRowA1" class="select-field" aria-label="First arm"></select>
        </div>
        <div data-shape="arm2">
            <label class="field-label">Second region</label>
            <select id="schRowR2" class="select-field" aria-label="Second region">${regionOpts(armed, c2 ? c2.id : armed[0])}</select>
            <label class="field-label">Second arm <span class="info-ico" data-tip="Always the opposite arm — one arm cannot run two concurrent tasks, and the loader would merge same-arm serial cells into one slot.">&#9432;</span></label>
            <input id="schRowA2" class="readonly-field" type="text" readonly aria-label="Second arm (opposite)">
        </div>
        <div data-shape="compound">
            <label class="field-label">Mechanism (compound — one node, both arms)</label>
            <select id="schRowRC" class="select-field" aria-label="Compound mechanism">${regionOpts(compounds, c1 && c1.arm === 'C' ? c1.id : compounds[0])}</select>
        </div>
        <div data-shape="chained">
            <label class="field-label">Chain cells <span class="info-ico" data-tip="Raw cell grammar, one per column: same arm within a chain (0R>1R), opposite arms across columns (1L>0L). The preview re-resolves through the orchestrator loader and the guards check it.">&#9432;</span></label>
            <input id="schRowC1" class="select-field" type="text" placeholder="0R>1R" value="${chained ? escapeHtml(cells[0] || '') : ''}" aria-label="Chain column 1">
            <input id="schRowC2" class="select-field" type="text" placeholder="1L>0L" value="${chained ? escapeHtml(cells[1] || '') : ''}" aria-label="Chain column 2">
        </div>
        <div class="button-row">
            <button type="button" id="schRowApply" class="primary">${rowIdx != null ? 'Apply' : 'Add'}</button>
            <button type="button" id="schRowCancel">Cancel</button>
        </div>`;
    dlg.appendChild(body);
    document.body.appendChild(dlg);
    dlg.style.left = `${Math.max(8, window.innerWidth / 2 - 180)}px`;
    dlg.style.top = '120px';

    const typeSel = body.querySelector('#schRowType');
    const armSel = body.querySelector('#schRowA1');
    const arm2Box = body.querySelector('#schRowA2');
    const r1Sel = body.querySelector('#schRowR1');
    const syncArms = () => {
        const arms = legalArms(parseInt(r1Sel.value, 10));
        const keep = (c1 && arms.includes(c1.arm)) ? c1.arm : arms[0];
        armSel.innerHTML = arms.map(a =>
            `<option value="${a}"${a === keep ? ' selected' : ''}>${a === 'R' ? 'right (R)' : 'left (L)'}</option>`).join('');
        arm2Box.value = armSel.value === 'R' ? 'left (L)' : 'right (R)';
    };
    const syncShape = () => {
        const t = typeSel.value;
        body.querySelectorAll('[data-shape]').forEach(div => {
            const shape = div.dataset.shape;
            div.style.display =
                (shape === 'arm1' && ['single', 'paired', 'serial'].includes(t))
                || (shape === 'arm2' && ['paired', 'serial'].includes(t))
                || (shape === 'compound' && t === 'compound')
                || (shape === 'chained' && t === 'chained') ? '' : 'none';
        });
    };
    typeSel.addEventListener('change', syncShape);
    r1Sel.addEventListener('change', syncArms);
    armSel.addEventListener('change', () => { arm2Box.value = armSel.value === 'R' ? 'left (L)' : 'right (R)'; });
    syncArms();
    syncShape();

    const close = () => { document.removeEventListener('keydown', onKey, true); dlg.remove(); };
    const onKey = e => { if (e.key === 'Escape') { e.stopPropagation(); close(); } };
    document.addEventListener('keydown', onKey, true);
    closeBtn.addEventListener('click', close);
    body.querySelector('#schRowCancel').addEventListener('click', close);
    body.querySelector('#schRowApply').addEventListener('click', async () => {
        const t = typeSel.value;
        let newCells;
        if (t === 'compound') {
            newCells = [`${body.querySelector('#schRowRC').value}C`, null];
        } else if (t === 'chained') {
            const a = body.querySelector('#schRowC1').value.trim();
            const b = body.querySelector('#schRowC2').value.trim();
            if (!a) { schSetStatus('Chain column 1 is required.', true); return; }
            newCells = [a, b || null];
        } else {
            const arm1 = armSel.value;
            const cell1 = `${r1Sel.value}${arm1}`;
            if (t === 'single') newCells = [cell1, null];
            else {
                const other = arm1 === 'R' ? 'L' : 'R';
                const cell2 = `${body.querySelector('#schRowR2').value}${other}`;
                newCells = t === 'serial' ? [cell1, `>${cell2}`] : [cell1, cell2];
            }
        }
        if (await schReplaceRow(rowIdx, newCells)) close();
    });
}

// ===== Save (guard-gated) ===================================================
// The modal restates the three tiers at the moment of commit — including the
// rows the collision gate says NOTHING about — and the server re-checks
// everything (errors and cached collision hits refuse server-side too, so the
// client cannot save past the supreme decider by construction).
async function schSave() {
    if (!schState.rows.length || !schState.csvPath) return;
    const fixture = schState.fixture || currentFixture();
    const planSet = document.getElementById('schPlanSet')?.value || 'hardware';
    const mode = document.getElementById('schMode')?.value || '';

    const rowsG = (schState.guards && schState.guards.rows) || [];
    const flat = tier => rowsG.flatMap(r => r[tier]);
    const errors = [...flat('logical'), ...flat('reality')].filter(v => v.level === 'error');
    const warnings = [...flat('logical'), ...flat('reality'),
                      ...((schState.guards && schState.guards.sequence) || [])]
        .filter(v => v.level === 'warning');
    const rowSteps = schState.steps.filter(s => s.index != null);
    const hitRows = rowSteps.filter(s => { const c = schState.collisions[schCellKey(s.index)]; return c && c.count > 0; });
    const staleRows = rowSteps.filter(s => schStepPairs(s).length
        && (!schState.collisions[schCellKey(s.index)] || schState.collisions[schCellKey(s.index)].error));

    const savedKey = rows => rows.map(r => `${r[0]}|${r[1] || ''}`);
    const before = savedKey(schState.savedRows), after = savedKey(schState.rows);
    const added = after.filter(k => !before.includes(k)).length;
    const removed = before.filter(k => !after.includes(k)).length;
    const moved = after.filter((k, i) => before.includes(k) && before[i] !== k).length;

    const chips = [
        { cls: errors.length ? 'g-bad' : (flat('logical').length || flat('reality').length) && warnings.length ? 'g-warn' : 'g-ok',
          glyph: errors.length ? '⛔' : warnings.length ? '⚠' : '✓',
          label: 'logical+reality', val: `${errors.length}⛔ ${warnings.length}⚠` },
        hitRows.length
            ? { cls: 'g-bad', glyph: '⛔', label: 'collision', val: `${hitRows.length} row(s) hit` }
            : staleRows.length
            ? { cls: 'g-stale', glyph: '↻', label: 'collision', val: `${staleRows.length} unswept` }
            : { cls: 'g-ok', glyph: '✓', label: 'collision', val: 'all swept clear' },
        { cls: '', glyph: '±', label: 'diff', val: `${moved} moved · ${added} added · ${removed} removed` },
    ];
    const lines = [];
    errors.slice(0, 4).forEach(v => lines.push({ level: 'error', text: v.sentence }));
    warnings.slice(0, 4).forEach(v => lines.push({ level: 'warning', text: v.sentence }));
    if (staleRows.length) lines.push({ level: 'warning',
        text: `The collision gate says NOTHING about row(s) ${staleRows.map(s => s.index).join(', ')} — `
            + `they have not been swept since this pairing. Saving anyway trusts unproven pairings.` });
    if (hitRows.length) lines.push({ level: 'error',
        text: `Row(s) ${hitRows.map(s => s.index).join(', ')} have recorded inter-arm collisions — the save will be refused.` });

    const parts = (schState.csvPath || '').split('/');
    const ok = await showStudioModal({
        title: 'Save schedule',
        destDir: parts.slice(0, -1).join('/') + '/',
        destFile: parts[parts.length - 1],
        chips, lines,
        note: 'The orchestrator executes this file on its next session. The previous version is backed up under .cache/schedule_backups/.',
        confirmLabel: errors.length || hitRows.length ? 'Cannot save (errors)' : 'Save',
    });
    if (!ok || errors.length || hitRows.length) {
        if (ok) schSetStatus('Save blocked by guard errors — fix the flagged rows first.', true);
        return;
    }

    let res;
    try {
        res = await api('/api/schedule-save', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ fixture, planSet, mode, rows: schState.rows,
                                   baseMtimeNs: schState.csvMtimeNs,
                                   ackWarnings: true, ackStale: true }),
        });
    } catch (e) {
        if (/CONFLICT/.test(e.message)) {
            const force = await showStudioModal({
                title: 'Schedule changed on disk',
                lines: [{ level: 'warning', text: e.message }],
                note: 'Someone else (another studio window, an editor) rewrote the file since it was loaded.',
                confirmLabel: 'Overwrite anyway', cancelLabel: 'Keep theirs',
            });
            if (!force) { schSetStatus('Save cancelled — reload the schedule to pick up the on-disk version.', true); return; }
            try {
                res = await api('/api/schedule-save', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ fixture, planSet, mode, rows: schState.rows,
                                           force: true, ackWarnings: true, ackStale: true }),
                });
            } catch (e2) { schSetStatus('Save failed: ' + e2.message, true); return; }
        } else { schSetStatus('Save failed: ' + e.message, true); return; }
    }
    if (res.error) {
        schSetStatus('Save refused: ' + (res.guardErrors ? res.guardErrors[0] : res.error), true);
        return;
    }
    schState.dirty = false;
    schState.savedRows = schState.rows.map(r => r.slice());
    schState.csvMtimeNs = res.mtimeNs ?? schState.csvMtimeNs;
    const saveBtn = document.getElementById('schSaveButton');
    if (saveBtn) saveBtn.disabled = true;
    schRenderTimeline();
    schRenderRunInfo();
    schSetStatus(`Saved ${res.saved}`
        + (res.backup ? ` (previous version → ${res.backup})` : '')
        + (res.staleRows && res.staleRows.length ? ` · collision gate silent on row(s) ${res.staleRows.join(', ')}` : ''));
}

async function dacOnEnter() {
    if (!dac.inited) await dacInit();
    // The schedule-pair list is fixture-specific: re-derive it when the
    // fixture changed since it was loaded (dacInit runs once per page).
    else if (dac.pairsFixture !== (currentFixture() || '')) await dacLoadSchedulePairs();
    // The fixture "reality logic" + articulation need the manifest (region lid/seat
    // states + lid/seat meshes). Load it if the user came straight to this tab.
    if (!viewerManifest || !viewerManifest.regions || !Object.keys(viewerManifest.regions).length) {
        const fx = currentFixture();
        if (fx) { try { await loadFixtureForRegions(fx); } catch (e) {} }
    }
    // Playback drives the robot overlay — make sure it is loaded + visible.
    const t = document.getElementById('showRobotToggle');
    if (t && !t.checked) { t.checked = true; await toggleRobot(true); }
    else if (!robotGeometryLoaded) { await loadRobotGeometry('visual'); }
    // Articulate the shared lid/seat for the currently-selected pair (and show its
    // state / any conflict in the log) as soon as the tab is opened.
    const left = document.getElementById('dacLeftPlan')?.value;
    const right = document.getElementById('dacRightPlan')?.value;
    if (left && right && !dac.res) {
        dacSetInfo([...dacFixtureRows(),
            '<div class="info-row"><span>Status</span><code>Pick two plans, then Check.</code></div>']);
        dacPreviewFixture();
    }
}

async function dacInit() {
    dac.inited = true;
    try {
        const d = await api('/api/plans');
        dac.plans = d.plans || [];   // [{path, name, arm}]
    } catch (e) {
        // Transient failure (e.g. the server was just restarted): retry once
        // before surfacing anything, and keep the message non-alarming — an
        // empty plans dir is a normal state on a fresh checkout.
        try {
            await new Promise(resolve => setTimeout(resolve, 1500));
            const d = await api('/api/plans');
            dac.plans = d.plans || [];
        } catch (e2) {
            dac.plans = [];
            setStatus(`Plan list unavailable (${e2.message}) — reload the page once the server is up.`);
        }
    }
    if (!dac.plans.length) {
        dacSetInfo(['<div class="info-row"><span>Plans</span><code>none found under the saved-plan root or alix_core/plans — record a plan with the task node (record_trajectory: true) first</code></div>']);
    }
    dacPopulatePlans();              // fill both pickers (filtered) + best-effort defaults
    const modeSel = document.getElementById('dacPlanMode');
    if (modeSel && !modeSel.options.length) modeSel.innerHTML = planModeOptions(DAC_MODE_DEFAULT);
    // Re-resolving is the whole point of the control: the combination list is a
    // per-mode plan lookup, so the list must be rebuilt, not just re-labelled.
    modeSel?.addEventListener('change', () => { dacLoadSchedulePairs(); });
    // DEFAULT pairing source (2026-07-29): the orchestrator schedule + session
    // phases — the combinations that actually execute concurrently. Picking an
    // entry fills the manual pickers; "Custom" leaves them free-form.
    await dacLoadSchedulePairs();
    document.getElementById('dacSchedulePair')?.addEventListener('change', dacApplySchedulePair);
    document.getElementById('dacCheckButton')?.addEventListener('click', dacRunCheck);
    // Each picker has its OWN search so any left plan can be paired with any right
    // plan — searching one side never constrains the other.
    document.getElementById('dacLeftSearch')?.addEventListener('input', () => dacPopulatePlans());
    document.getElementById('dacRightSearch')?.addEventListener('input', () => dacPopulatePlans());
    // Selecting plans does NOT auto-run — the user clicks "Check Collisions" to
    // confirm the chosen pair, so an unintended pair never kicks off a sweep.
    const onSel = () => dacInvalidate();
    document.getElementById('dacLeftPlan')?.addEventListener('change', onSel);
    document.getElementById('dacRightPlan')?.addEventListener('change', onSel);
    document.getElementById('dacPlayButton')?.addEventListener('click', dacPlay);
    document.getElementById('dacStopButton')?.addEventListener('click', dacStop);
    document.getElementById('dacPrevButton')?.addEventListener('click', () => dacJumpHit(-1));
    document.getElementById('dacNextButton')?.addEventListener('click', () => dacJumpHit(1));
    document.getElementById('dacSlider')?.addEventListener('input', e => dacGoto(parseInt(e.target.value, 10)));
}

// ===== Schedule-derived default pairs (2026-07-29) =========================
// The schedule CSV is the sole source of the execution sequence; its
// concurrent combinations (+ session phases) are the DEFAULT things to check.
async function dacLoadSchedulePairs() {
    const sel = document.getElementById('dacSchedulePair');
    if (!sel) return;
    sel.innerHTML = '<option value="">Custom (manual pickers below)</option>';
    // Pairs are FIXTURE-SPECIFIC. Pass the current fixture and remember which
    // one the list belongs to, so dacOnEnter can re-derive it after a fixture
    // change (this call used to be parameterless, so the server's old
    // commode_c default made the list commode_c for the whole session).
    const pairsFixture = currentFixture();
    dac.pairsFixture = pairsFixture || '';
    if (!pairsFixture) { dac.schedulePairs = []; return; }
    // The mode is the plan-filename suffix the pair resolver globs for. It used to
    // be unsent, so the server's totg_ruckig default silently decided the list.
    const mode = document.getElementById('dacPlanMode')?.value || DAC_MODE_DEFAULT;
    try {
        const d = await api('/api/schedule-pairs?fixture=' + encodeURIComponent(pairsFixture)
            + '&mode=' + encodeURIComponent(mode));
        dac.schedulePairs = d.pairs || [];
        dac.schedulePairs.forEach((pr, i) => {
            const o = document.createElement('option');
            o.value = String(i);
            const flag = pr.missing ? '  (plan missing)' : (!pr.checkable ? '  (no inter-arm overlap)' : '');
            o.textContent = pr.label + flag;
            o.disabled = !pr.checkable;
            if (pr.note || pr.missing) o.title = pr.missing ? 'plan file not generated yet' : pr.note;
            sel.appendChild(o);
        });
    } catch (e) {
        sel.innerHTML = `<option value="">Custom (schedule unavailable: ${escapeHtml(e.message)})</option>`;
        dac.schedulePairs = [];
    }
}

function dacApplySchedulePair() {
    const sel = document.getElementById('dacSchedulePair');
    const idx = sel?.value;
    if (idx === '' || idx == null) return;           // Custom — leave pickers alone
    const pr = (dac.schedulePairs || [])[parseInt(idx, 10)];
    if (!pr || !pr.checkable) return;
    // Fill the manual pickers with the pair's plans (compound/phase entries use
    // the SAME dual plan on both sides — the sweep tests its arms against each
    // other). The pickers stay the operative selection: Check Collisions reads
    // them, so the user can still tweak either side afterwards (which flips the
    // selector back to Custom conceptually — the pickers always win).
    const set = (id, path) => {
        const el = document.getElementById(id);
        if (!el || !path) return;
        if (![...el.options].some(o => o.value === path)) {
            const o = document.createElement('option');
            o.value = path; o.textContent = path.split('/').pop();
            el.appendChild(o);
        }
        el.value = path;
    };
    set('dacLeftPlan', pr.leftPlan);
    set('dacRightPlan', pr.rightPlan);
    dacInvalidate();
}

// Fill the left/right pickers from dac.plans. Each picker filters by ITS OWN
// search box and by arm: LEFT lists left + dual + arm-agnostic; RIGHT lists right
// + dual + arm-agnostic. The two are independent, so any left plan can be paired
// with any right plan. Keeps the current selection if it still qualifies, else
// picks a sensible default. Any shift invalidates a prior result.
function dacPopulatePlans() {
    const fill = (selId, searchId, allowArms, preferToken) => {
        const sel = document.getElementById(selId);
        if (!sel) return;
        const q = (document.getElementById(searchId)?.value || '').trim().toLowerCase();
        const matches = p => !q || p.name.toLowerCase().includes(q) || p.path.toLowerCase().includes(q);
        const prev = sel.value;
        const list = dac.plans.filter(p => allowArms.has(p.arm) && matches(p));
        sel.innerHTML = list.map(p => `<option value="${p.path}">${p.name}</option>`).join('')
            || '<option value="">(no matching plans)</option>';
        if (list.some(p => p.path === prev)) sel.value = prev;
        else { const def = list.find(p => preferToken.test(p.path)) || list[0]; if (def) sel.value = def.path; }
    };
    fill('dacLeftPlan', 'dacLeftSearch', new Set(['left', 'dual', 'neutral']), /left/i);
    fill('dacRightPlan', 'dacRightSearch', new Set(['right', 'dual', 'neutral']), /right/i);
    if (dac.res) dacInvalidate();   // pair may have shifted under the filter
}

// Discard any prior result so a stale sweep can't be played against a newly
// chosen plan pair: stop playback, clear state, disable the playback controls,
// and prompt for an explicit Check.
function dacInvalidate() {
    dacStop();
    dac.res = null; dac.frameIdx = []; dac.hitByIndex = {}; dac.pos = 0;
    dacHighlight(null);
    ['dacPlayButton', 'dacStopButton', 'dacPrevButton', 'dacNextButton', 'dacSlider'].forEach(id => {
        const el = document.getElementById(id); if (el) el.disabled = true;
    });
    if (window.Plotly) { try { Plotly.purge('dacPlot'); } catch (e) {} }
    // Preview the pair's shared fixture state (and articulate it) the moment plans
    // change, so a conflicting pair is flagged before the user even hits Check.
    dacSetInfo([
        ...dacFixtureRows(),
        '<div class="info-row"><span>Status</span><code>Plans changed — click Check Collisions.</code></div>',
    ]);
    dacPreviewFixture();
    dacLogEvents(null);
    dacFrameInfo('Frame', 'Run a check, then scrub/play.');
}

function dacSetInfo(rows) { const el = document.getElementById('dacInfo'); if (el) el.innerHTML = rows.join(''); }
function dacFrameInfo(label, value) {
    const el = document.getElementById('dacFrameInfo');
    if (el) el.innerHTML = `<span>${label}</span> <code>${value}</code>`;
}
// Fill the right-hand log panel with one entry per colliding sample (time + the
// link pairs). null clears it.
function dacLogEvents(res) {
    const el = document.getElementById('dacLog');
    if (!el) return;
    const cols = (res && res.collisions) || [];
    if (!res) { el.innerHTML = ''; return; }
    if (!cols.length) {
        el.innerHTML = '<div class="info-row"><span>Log</span><code>No inter-arm collisions over the whole motion — full motion is playable. ✓</code></div>';
        return;
    }
    const times = res.sample_times || [];
    el.innerHTML = cols.map(c => {
        const t = (times[c.index] !== undefined) ? times[c.index].toFixed(2) : '?';
        const pairs = c.pairs.map(p => `${p[0]} ↔ ${p[1]}`).join('<br>');
        return `<div class="info-row dac-event" data-sample="${c.index}"><span>t=${t}s</span><code>${pairs}</code></div>`;
    }).join('');
    // Click a log entry to jump the playback there.
    el.querySelectorAll('.dac-event').forEach(row => row.addEventListener('click', () => {
        const pos = dac.frameIdx.indexOf(parseInt(row.dataset.sample, 10));
        if (pos >= 0) dacGoto(pos);
    }));
}

// ── Fixture "reality logic" for the collision tab ──────────────────────────────
// The two plans run SIMULTANEOUSLY and share ONE physical lid + ONE physical seat.
// Each plan's region requires a specific lid/seat articulation to be cleanable
// (from the manifest, derived from the configs' commode_fixture_type). If the two
// plans require DIFFERENT lid or seat states they physically cannot run together —
// the lid/seat can't be in two states at once — so the pair is rejected.

function dacRegionForPlan(planRef) {
    if (!planRef) return null;
    // The picker's <option value> is the plan PATH (e.g. "commode_c/hardware/
    // bottomlid_left_ruckig_pro_only.json"); reduce it to the basename so it can be
    // matched against region keys ("bottomlid", "toplid", …).
    const stem = String(planRef).split(/[\\/]/).pop().replace(/\.json$/i, '');
    let best = null;                                   // longest matching region key
    for (const k of Object.keys(viewerManifest?.regions || {})) {
        if (stem === k || stem.startsWith(k + '_')) {
            if (!best || k.length > best.length) best = k;
        }
    }
    return best;
}

// Plan basename (no dir, no .json) — for log labels.
function dacPlanLabel(planRef) {
    return planRef ? String(planRef).split(/[\\/]/).pop().replace(/\.json$/i, '') : '';
}

function dacPlanFixtureState(planName) {
    const region = dacRegionForPlan(planName);
    if (!region) return null;
    const r = viewerManifest.regions[region];
    // SOURCE OF TRUTH = the task config's commode_fixture_type (carried verbatim by
    // the manifest). Derive the per-part states from it with the SAME mapping the
    // rest of the editor uses (fixtureStatesFromType) so there is one definition.
    const fixtureType = r.commodeFixtureType || 'closed';
    return { region, states: fixtureStatesFromType(fixtureType), fixtureType };
}

function dacReconcileFixture(leftName, rightName) {
    const L = dacPlanFixtureState(leftName);
    const R = dacPlanFixtureState(rightName);
    if (!L || !R) return { ok: true, merged: (L || R)?.states || null,
                           mergedType: (L || R)?.fixtureType || null, L, R, unknown: true };
    // Combined fixture (one mesh per state, no articulated parts): the per-part
    // loop below can never conflict, yet two plans demanding different
    // whole-fixture states (closed vs lid_open) are physically unrunnable
    // together. Compare the states themselves.
    if (combinedFixture()) {
        if (L.fixtureType !== R.fixtureType) return { ok: false, L, R, conflicts: ['fixture state'] };
        return { ok: true, merged: {...L.states}, mergedType: L.fixtureType, L, R };
    }
    const conflicts = articulatedFixtureParts()
        .map(p => p.name)
        .filter(name => (L.states[name] || 'closed') !== (R.states[name] || 'closed'));
    if (conflicts.length) return { ok: false, L, R, conflicts };
    return { ok: true, merged: {...L.states}, mergedType: L.fixtureType, L, R };
}

// Draw the shared fixture (every part) in a given articulation on the DAC scene
// via the central renderer — ALL parts at 0.7 alpha. Remembers the state so a
// part toggle can re-render without recomputing the pair.
const DAC_FIXTURE_ALPHA = 0.7;
function dacRenderFixture(states, fixtureType = null) {
    dac.fixtureStates = states || null;
    dac.fixtureType = fixtureType || null;
    const specs = states ? fixtureMeshSpecs(states, {fixtureType}) : [];
    renderFixtureCompanions(specs, DAC_FIXTURE_ALPHA, null);
    renderScene();
}

// Info-panel rows describing the current pair's fixture requirement (or conflict).
function dacFixtureRows() {
    const left = document.getElementById('dacLeftPlan')?.value;
    const right = document.getElementById('dacRightPlan')?.value;
    if (!left || !right) return [];
    const rec = dacReconcileFixture(left, right);
    const fmtStates = s => s ? Object.entries(s).map(([p, st]) => `${p} ${st}`).join(' · ') : 'unknown';
    const fmt = rc => rc ? fmtStates(rc.states || rc) : 'unknown';
    // The tab has seven controls and none of them names the fixture, so the
    // states below read as belonging to nothing in particular.
    const fixtureRow = `<div class="info-row"><span>Fixture</span>`
        + `<code>${escapeHtml(currentFixture() || 'none selected')}</code></div>`;
    if (!rec.ok) {
        const bad = rec.conflicts.map(name =>
            `${name} (${rec.L.states[name] || 'closed'} vs ${rec.R.states[name] || 'closed'})`);
        return [
            fixtureRow,
            `<div class="info-row" style="color:var(--danger)"><span>⚠ Cannot run</span><code>Conflicting fixture states: ${bad.join(', ')}. A part can't be in two states at once — these tasks cannot run together.</code></div>`,
            `<div class="info-row"><span>Left</span><code>${escapeHtml(rec.L.region)}: ${fmt(rec.L)}</code></div>`,
            `<div class="info-row"><span>Right</span><code>${escapeHtml(rec.R.region)}: ${fmt(rec.R)}</code></div>`,
        ];
    }
    if (rec.unknown) {
        const who = rec.L ? `right '${escapeHtml(dacPlanLabel(right))}'` : `left '${escapeHtml(dacPlanLabel(left))}'`;
        return [fixtureRow,
                `<div class="info-row"><span>States</span><code>${fmt(rec.merged)} — ${who} `
                + `region unknown, so the states could NOT be cross-checked.</code></div>`];
    }
    return [fixtureRow,
            `<div class="info-row" style="color:var(--ok)"><span>States ✓</span>`
            + `<code>both tasks share ${fmt(rec.merged)}</code></div>`];
}

// Articulate the scene for the currently-selected pair (compatible pairs only) and
// return the reconcile result. Called on tab-enter and whenever a plan changes.
function dacPreviewFixture() {
    const left = document.getElementById('dacLeftPlan')?.value;
    const right = document.getElementById('dacRightPlan')?.value;
    if (!left || !right) return null;
    const rec = dacReconcileFixture(left, right);
    if (rec.ok && rec.merged) dacRenderFixture(rec.merged, rec.mergedType);
    return rec;
}

async function dacRunCheck() {
    const left = document.getElementById('dacLeftPlan')?.value;
    const right = document.getElementById('dacRightPlan')?.value;
    const dt = parseFloat(document.getElementById('dacDt')?.value || '0.05');
    if (!left || !right) { setStatus('Pick both a left and right plan.', true); return; }
    dacStop();
    // Guarantee the fixture manifest is loaded so the physical-logic gate below can
    // resolve each plan's region (otherwise it would silently pass an unrunnable pair).
    if (!viewerManifest?.regions || !Object.keys(viewerManifest.regions).length) {
        const fx = currentFixture();
        if (fx) { try { await loadFixtureForRegions(fx); } catch (e) { /* gate falls back to 'unknown' */ } }
    }
    // Physical-logic gate: the two plans share one lid + one seat. If they require
    // conflicting articulations the combination is unrunnable — report and stop.
    const fix = dacReconcileFixture(left, right);
    if (!fix.ok) {
        dac.res = null; dac.frameIdx = []; dac.hitByIndex = {}; dac.pos = 0;
        if (window.Plotly) { try { Plotly.purge('dacPlot'); } catch (e) {} }
        ['dacPlayButton', 'dacStopButton', 'dacPrevButton', 'dacNextButton', 'dacSlider']
            .forEach(id => { const el = document.getElementById(id); if (el) el.disabled = true; });
        dacSetInfo(dacFixtureRows());
        dacLogEvents(null);
        dacFrameInfo('Frame', 'Pair cannot run — adjust the plan selection.');
        setStatus('Cannot run these two together — conflicting fixture part states.', true);
        return;
    }
    if (fix.merged) dacRenderFixture(fix.merged, fix.mergedType);   // articulate the shared state
    dacSetInfo(['<div class="info-row"><span>Status</span><code>Checking…</code></div>']);
    setStatus('Running dual-arm collision sweep…');
    let res;
    try {
        res = await api('/api/dual-arm-collisions', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ leftPlan: left, rightPlan: right, dt }),
        });
    } catch (e) {
        setStatus('Collision check failed: ' + e.message, true);
        dacSetInfo([`<div class="info-row"><span>Error</span><code>${escapeHtml(e.message)}</code></div>`]);
        return;
    }
    dac.res = res;
    dac.hitByIndex = {};
    (res.collisions || []).forEach(c => { dac.hitByIndex[c.index] = c.pairs; });
    dac.frameIdx = Object.keys(res.frames || {}).map(Number).sort((a, b) => a - b);
    dac.pos = 0;
    const nHit = (res.collisions || []).length;
    dacSetInfo([
        ...dacFixtureRows(),
        `<div class="info-row"><span>Result</span><code>${nHit ? nHit + ' colliding samples' : 'no inter-arm collisions ✓'}</code></div>`,
        `<div class="info-row"><span>Samples</span><code>${res.num_samples} @ ${res.dt}s${res.cached ? ' (cached)' : ''}</code></div>`,
        `<div class="info-row"><span>Motion</span><code>full motion playable (${dac.frameIdx.length} frames)</code></div>`,
    ]);
    dacLogEvents(res);
    setStatus(nHit ? `${nHit} inter-arm collisions found.` : 'No inter-arm collisions — full motion playable.');
    await dacOnEnter();
    dacRenderPlot();
    // The whole motion is playable whenever there are frames; Prev/Next jump between
    // COLLIDING samples, so they only enable when there are collisions.
    const playable = dac.frameIdx.length > 0;
    ['dacPlayButton', 'dacStopButton', 'dacSlider'].forEach(id => {
        const el = document.getElementById(id); if (el) el.disabled = !playable;
    });
    ['dacPrevButton', 'dacNextButton'].forEach(id => {
        const el = document.getElementById(id); if (el) el.disabled = !(playable && nHit > 0);
    });
    const slider = document.getElementById('dacSlider');
    if (slider) { slider.min = 0; slider.max = Math.max(0, dac.frameIdx.length - 1); slider.value = 0; }
    if (playable) dacGoto(0);
}

function dacRenderPlot() {
    if (!dac.res) return;
    if (!window.Plotly) { ensurePlotly().then(ok => { if (ok) dacRenderPlot(); }); return; }
    const x = dac.res.sample_times || [];
    const y = x.map((_, i) => (dac.hitByIndex[i] ? 1 : 0));
    Plotly.react('dacPlot', [{
        type: 'bar', x, y, width: (dac.res.dt || 0.05) * 0.9,
        marker: { color: y.map(v => (v ? '#ff4d4d' : 'rgba(0,212,255,0.25)')) },
        hovertemplate: 't=%{x:.2f}s — click to scrub<extra></extra>',
    }], {
        paper_bgcolor: 'rgba(0,0,0,0)', plot_bgcolor: 'rgba(0,0,0,0)', font: { color: '#e6edf3', size: 10 },
        margin: { l: 22, r: 8, t: 6, b: 26 },
        yaxis: { showticklabels: false, range: [0, 1.1], gridcolor: 'rgba(139,148,158,0.15)' },
        xaxis: { title: 'time (s) — click the graph to jump the robot there', gridcolor: 'rgba(139,148,158,0.15)' },
    }, { displayModeBar: false, responsive: true }).then(gd => {
        // Click anywhere on the timeline graph to scrub the robot to that instant.
        if (gd.removeAllListeners) gd.removeAllListeners('plotly_click');
        gd.on('plotly_click', ev => { if (ev?.points?.length) dacGotoTime(ev.points[0].x); });
    });
}

// Jump playback to the frame whose sample time is closest to t (used by the
// timeline click handler — clicked samples may not all be recorded frames).
function dacGotoTime(t) {
    if (!dac.res || !dac.frameIdx.length) return;
    const times = dac.res.sample_times || [];
    const dt = dac.res.dt || 0.05;
    let bestPos = 0, bestDist = Infinity;
    dac.frameIdx.forEach((sample, pos) => {
        const ts = (times[sample] !== undefined) ? times[sample] : sample * dt;
        const d = Math.abs(ts - t);
        if (d < bestDist) { bestDist = d; bestPos = pos; }
    });
    dacStop();
    dacGoto(bestPos);
}

function dacGoto(pos) {
    if (!dac.res || !dac.frameIdx.length) return;
    pos = Math.max(0, Math.min(dac.frameIdx.length - 1, pos));
    dac.pos = pos;
    const sample = dac.frameIdx[pos];
    const frame = dac.res.frames[String(sample)];
    if (frame) applyRobotPose(frame);
    const pairs = dac.hitByIndex[sample] || null;
    dacHighlight(pairs);
    const slider = document.getElementById('dacSlider'); if (slider) slider.value = pos;
    const tArr = dac.res.sample_times || [];
    const t = (tArr[sample] !== undefined) ? tArr[sample].toFixed(2) : '?';
    const tag = pairs ? `<span style="color:var(--danger)">COLLIDING: ${pairs.map(p => `${p[0]}↔${p[1]}`).join(', ')}</span>` : 'clear';
    dacFrameInfo(`t=${t}s · ${sample}/${dac.res.num_samples - 1}`, tag);
}

function dacHighlight(pairs) {
    // Restore previously reddened meshes to their OWN base colour (real material).
    dac.recolored.forEach(link => (robotMeshes[link] || []).forEach(m => {
        if (m.material && m.userData.baseColor !== undefined) m.material.color.setHex(m.userData.baseColor);
    }));
    dac.recolored = [];
    if (pairs) {
        const links = new Set();
        pairs.forEach(p => { links.add(p[0]); links.add(p[1]); });
        links.forEach(link => {
            (robotMeshes[link] || []).forEach(m => { if (m.material) m.material.color.copy(DAC_HIT_LINEAR); });
            dac.recolored.push(link);
        });
    }
    renderScene();
}

function dacJumpHit(dir) {
    if (!dac.res) return;
    const hits = (dac.res.collisions || []).map(c => c.index);
    if (!hits.length) return;
    const cur = dac.frameIdx[dac.pos];
    let target;
    if (dir > 0) target = hits.find(h => h > cur);
    else { const before = hits.filter(h => h < cur); target = before.length ? before[before.length - 1] : undefined; }
    if (target === undefined) target = dir > 0 ? hits[0] : hits[hits.length - 1];
    const pos = dac.frameIdx.indexOf(target);
    if (pos >= 0) dacGoto(pos);
}

function dacPlay() {
    if (!dac.frameIdx.length) return;
    // Play is a TOGGLE (F75): clicking mid-play pauses at the current sample
    // (the pose stays applied); Stop is the full reset. The button used to
    // disable itself while playing, which read as "no way to halt this".
    if (dac.playing) { dacPause(); return; }
    // If we're sitting at the end (a previous play finished, or scrubbed to the end),
    // restart from the beginning rather than immediately stopping.
    if (dac.pos >= dac.frameIdx.length - 1) dacGoto(0);
    dac.playing = true;
    dacSetPlayLabel(true);
    const stepMs = Math.max(20, (dac.res.dt || 0.05) * 1000);
    dac.timer = setInterval(() => {
        if (dac.pos >= dac.frameIdx.length - 1) {
            dacStop();
            dacGoto(0);          // motion complete → return the playhead to t=0
            return;
        }
        dacGoto(dac.pos + 1);
    }, stepMs);
}

function dacPause() {
    dac.playing = false;
    if (dac.timer) { clearInterval(dac.timer); dac.timer = null; }
    dacSetPlayLabel(false);
}

function dacStop() {
    dacPause();
    const pb = document.getElementById('dacPlayButton'); if (pb) pb.disabled = !dac.frameIdx.length;
}

function dacSetPlayLabel(playing) {
    const pb = document.getElementById('dacPlayButton');
    if (pb) { pb.textContent = playing ? '⏸ Pause' : '▶ Play'; pb.disabled = false; }
}

// ===== Sequence animation: drive the robot smoothly through the path =========
let animState = null;

// Waypoints (base_link) the arm flows through: pre-start -> start -> sequence pts.
function sequenceWaypoints() {
    const wps = [];
    const cp = activeConfigBlock()?.cartesian_poses || {};
    ['pre_start_pose', 'start_pose'].forEach(key => {
        const p = cp[key];
        if (p && p.length === 7) wps.push({position: refPointToBase(p.slice(0, 3)), orientation: quatToArray(refQuatToBase(quatFromArray(p.slice(3, 7))))});
    });
    orderedSequencePoints().forEach(p => wps.push({position: p.xyz, orientation: p.absoluteQuat || [0, 0, 0, 1]}));
    return wps;
}

function setAnimInfo(rows) { const el = document.getElementById('animateInfo'); if (el) el.innerHTML = rows.join('') || '<div class="info-row"><span>Animation</span><code>—</code></div>'; }

// The poses the animation should follow: the SPLINE SAMPLES when a curve exists,
// otherwise the waypoints.
//
// Newton 2026-09-10: "the animation should use the spline points, not the joint
// interpolation between the knots". Handing `/api/animate-sequence` only the
// knots let it interpolate between them, so the arm cut the corners the fillets
// exist to round — the animation showed a path the runtime does not drive, and
// showed it most wrongly exactly at the corners, which is where the curve
// matters. The samples carry orientation as well as position (`quats` from
// /api/path-compare, which `refreshAuthorSpline` used to discard).
function animationPoses() {
    const g = state.generate;
    const gen = g && g.samples;
    if (gen && gen.p && gen.p.length >= 2 && gen.q && gen.q.length === gen.p.length) {
        return {poses: gen.p.map((xyz, i) => ({position: xyz, orientation: gen.q[i]})),
                source: `generated spline, ${gen.p.length} samples`};
    }
    const a = state.authorSpline;
    if (a && a.positions && a.positions.length >= 2
        && a.quats && a.quats.length === a.positions.length) {
        return {poses: a.positions.map((xyz, i) => ({position: xyz, orientation: a.quats[i]})),
                source: `authored spline, ${a.positions.length} samples`};
    }
    // No curve yet — say so rather than silently animating the chords, because
    // the chords are the thing this change exists to stop showing.
    return {poses: sequenceWaypoints(), source: 'waypoints (no spline built yet — the arm will cut the corners)'};
}

async function animateSequence() {
    stopAnimation();
    const {poses: wps, source: poseSource} = animationPoses();
    if (wps.length < 2) { setStatus('Need a start pose + at least one sequence point to animate.', true); return; }
    // The animation drives the robot overlay — make sure it is loaded + shown.
    const robotToggle = document.getElementById('showRobotToggle');
    if (robotToggle && !robotToggle.checked) { robotToggle.checked = true; await toggleRobot(true); }
    else if (!robotGeometryLoaded) await loadRobotGeometry();
    setStatus(`Building animation along the ${poseSource}…`);
    let d;
    try {
        d = await api('/api/animate-sequence', {method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({poses: wps, tipFrame: reachTipFrame(), arm: ikArmFromFrame(), poleState: poleStateValue()})});
    } catch (e) { setStatus('Animation build failed: ' + e.message, true); return; }
    if (d.error) { setStatus('Animation: ' + d.error, true); setAnimInfo([`<div class="info-row"><span>error</span><code>${d.error}</code></div>`]); return; }
    if (!d.frames || !d.frames.length) { setStatus('Animation produced no frames.', true); return; }
    applyRobotPose(d.staticPose);   // freeze the non-moving links once
    animState = {frames: d.frames, fps: d.fps || 30, count: d.count, t0: performance.now(), raf: 0,
                 loop: document.getElementById('animateLoopToggle')?.checked};
    document.getElementById('animateStopButton').disabled = false;
    setAnimInfo([
        `<div class="info-row"><span>arm</span><code>${d.arm}</code></div>`,
        `<div class="info-row"><span>frames</span><code>${d.count} @ ${d.fps} fps</code></div>`,
        `<div class="info-row"><span>reachable wp</span><code>${d.reachableCount}/${d.waypoints}</code></div>`,
        `<div class="info-row"><span>follows</span><code>${poseSource}</code></div>`,
    ]);
    if (d.reachableCount < d.waypoints) setStatus(`Animating — note ${d.waypoints - d.reachableCount} waypoint(s) were not fully reachable (arm holds best-effort there).`);
    playAnimation();
}

function playAnimation() {
    if (!animState) return;
    const step = () => {
        if (!animState) return;
        let idx = Math.floor((performance.now() - animState.t0) / 1000 * animState.fps);
        if (idx >= animState.count) {
            if (animState.loop) { animState.t0 = performance.now(); idx = 0; }
            else { applyRobotPose(animState.frames[animState.count - 1]); setStatus('Animation complete.'); stopAnimation(); return; }
        }
        applyRobotPose(animState.frames[idx]);
        animState.raf = requestAnimationFrame(step);
    };
    animState.raf = requestAnimationFrame(step);
}

function stopAnimation() {
    if (animState && animState.raf) cancelAnimationFrame(animState.raf);
    animState = null;
    const stopBtn = document.getElementById('animateStopButton');
    if (stopBtn) stopBtn.disabled = true;
}

// ===== Per-point analysis: reachability + dexterity for every cleaning point ==
// ── Fixture board ──────────────────────────────────────────────────────────
// One row per region, one cell per arm; each cell IS a config file. This is
// the first surface in the tool that represents the operator's actual unit of
// work. Before it, "which regions still need a right-arm task" required
// listing a directory in a shell.
//
// It reports only what is on disk. Coverage is not stamped into a config and
// validation state is not persisted, so there are no columns for them —
// inventing one is how a board stops being trusted.
let boardData = null;

async function loadBoard() {
    const host = document.getElementById('boardTable');
    const summary = document.getElementById('boardSummary');
    if (!host) return;
    const fixture = currentFixture();
    if (!fixture) { host.innerHTML = '<div class="hint">No fixture selected.</div>'; return; }
    host.innerHTML = '<div class="hint">Loading…</div>';
    try {
        boardData = await api(`/api/fixture-board?fixture=${encodeURIComponent(fixture)}`);
    } catch (e) {
        // A path generation holds a PROCESS-WIDE read guard over every task
        // config for the length of the run, and this handler used to swallow
        // that and report every config as unreadable — a board full of blanks
        // with no error anywhere. The server now says `generationBusy`; the
        // board must repeat the reason rather than draw the blanks.
        const busy = e.payload && e.payload.generationBusy;
        host.innerHTML = busy
            ? `<div class="hint error">Board unreadable while a path generation is running — `
              + `${escapeHtml(e.hint || e.message)}<br>The configs are fine; they simply cannot be `
              + `read until the run finishes or is cancelled.</div>`
            : `<div class="hint error">Board unavailable: ${escapeHtml(e.message)}</div>`;
        return;
    }
    const s = boardData.summary;
    if (summary) {
        // Chips, not a sentence: each number is a fact the operator scans for.
        const coverage = {RL_PAIRED: 0, RL_SPLIT: 0, R: 0, L: 0};
        boardData.regions.forEach(r => {
            const key = (r.armCoverage || '').toUpperCase();
            if (coverage[key] !== undefined) coverage[key] += 1;
        });
        const chip = (label, value, warn) =>
            `<span class="board-chip${warn ? ' warn' : ''}"><strong>${value}</strong>${escapeHtml(label)}</span>`;
        summary.classList.add('board-chips');
        summary.classList.remove('error');
        summary.innerHTML = chip('fixture', escapeHtml(boardData.fixture))
            + chip('regions', s.regions)
            + chip('configs', `${s.present}/${s.expected}`)
            + (s.missing ? chip('missing', s.missing, true) : chip('complete', '✓'))
            + chip('paired', coverage.RL_PAIRED)
            + chip('split', coverage.RL_SPLIT)
            + chip('single-arm', coverage.R + coverage.L);
    }
    // Progress on the tab itself, replacing the "1 · 2 · 3" ordinals: what an
    // operator wants to know at a glance is how much of the fixture is done,
    // not which step of a story they are on.
    const boardBadge = document.getElementById('tabBoardBadge');
    if (boardBadge) boardBadge.textContent = `${s.present}/${s.expected}`;
    host.innerHTML = renderBoardRows(boardData);
    fillBoardMetrics(host, boardData.fixture);
}

// ── The task object ────────────────────────────────────────────────────────
// The operator's unit of work is one region x one arm -> one deployed config.
// There are 38 of those per commode, and until now NOTHING in the UI
// represented one: the fixture lived in three selects, the region in a
// 20-option dropdown, the arm in a toggle, and Deploy read all three back out
// of the DOM at the moment you pressed it. That is why deploying a commode_c
// task while browsing urinal_a produced a plausible-looking path into the
// wrong fixture directory — filenames carry no fixture token.
//
// `state.task` is that missing object. The workbench's title IS the task, and
// Generate/Deploy read the task rather than the controls.
function currentStudioArm() {
    // Defers to the one authority. It used to read the pressed toggle and then
    // `studio.arm`, so it could answer differently from `activeArm()` — a second
    // opinion on the one question the app must never have two answers to.
    return activeArm() || 'right';
}

function bindTask(region, arm, opts = {}) {
    if (!region || !arm) return null;
    // Binding a different task drops the previous task's guessed-surface
    // caveat: the board opens tasks straight into the workbench, and a warning
    // left standing there would describe a region nobody is looking at.
    // generateFromServer sets it again after its own bind + load.
    state.surfaceWarning = null;
    const previousTask = state.task;
    state.task = {fixture: currentFixture(), region, arm};
    // A placement armed for ANOTHER task must not keep steering the handles.
    // Re-binding the same task (every generation re-binds its own) keeps it.
    if (!previousTask || previousTask.fixture !== state.task.fixture
            || previousTask.region !== region || previousTask.arm !== arm) {
        placingGeneratePose = null;
    }
    const select = document.getElementById('genRegion');
    if (select && [...select.options].some(o => o.value === region)) select.value = region;
    setStudioArm(arm);
    renderTaskHeader();
    refreshTaskDestination();
    if (!opts.silent) {
        setStatus(`Task: ${state.task.fixture} / ${region} [${arm}].`);
    }
    return state.task;
}

function openWorkbench(region, arm, opts = {}) {
    bindTask(region, arm, {silent: true});
    switchTab('workbench');
    if (opts.status) setStatus(opts.status);
    return state.task;
}

// ── Sessions: EDIT and GENERATE never coexist (Newton, 2026-09-15) ──────────
// "When I upload a config file, which I want to edit, and maybe I later think
// of generating a new file ... [they] should not coexist, one has to be done
// with (ended first)."
//
// Before this the two shared one workbench: a loaded file re-targeted the
// Generate panel (bindTask), lent it its ik_frame, decided which pose the
// Start/Pre-start handles edited, drew its gloves beside the picked ones, shared
// one undo history, and was silently replaced by the next Generate unless it
// had unsaved edits.
//
// The session is `body[data-stage]` — the idiom the ribbon already keys on
// (renderTaskHeader) — and it has exactly one source: a config is open (EDIT)
// or it is not (GENERATE). What changes is that crossing over is now an act:
//   * GENERATE -> EDIT: loading a file ends the generation (picked poses,
//     knots and result are cleared) — `requireEditSession`;
//   * EDIT -> GENERATE: generating, or picking/placing a generation pose,
//     closes the file first (Save / Discard / Keep editing) —
//     `requireGenerateSession`. The ONE exception is the generation's own
//     unmodified output (`sessionOrigin === 'generated'` and not dirty): that
//     IS the generation, iterating, and nothing is lost by replacing it.
//   * a run's result opens as an EDIT session of that output.

function sessionKind() {
    return state.config ? 'edit' : 'generate';
}

function generationHasContent() {
    return Boolean(parsePoseField('genStartPose') || parsePoseField('genPreStartPose')
        || pathGenHasKnots() || state.generate.result);
}

function generationJobLive() {
    return ['queued', 'running'].includes(state.generate.job?.state);
}

// A three-way choice in the house modal shell. Resolves to one of the option
// ids, or 'cancel' (Esc, backdrop, ×).
function askSessionChoice(opts) {
    return new Promise(resolve => {
        const overlay = document.createElement('div');
        overlay.className = 'cmd-overlay show';
        const box = document.createElement('div');
        box.className = 'cmd-box';
        box.setAttribute('role', 'dialog');
        box.setAttribute('aria-modal', 'true');
        box.setAttribute('aria-label', opts.title);
        const lines = (opts.lines || []).map(text => '<li class="lv-note">· ' + escapeHtml(text) + '</li>').join('');
        box.innerHTML = `
            <div class="axm-head"><span class="axm-title">${escapeHtml(opts.title)}</span>
                <button type="button" class="axm-close" aria-label="Close">&times;</button></div>
            <div class="axm-body">${lines ? '<ul class="axm-lines">' + lines + '</ul>' : ''}</div>
            <div class="axm-foot">
                <p class="axm-note">${escapeHtml(opts.note || '')}</p>
                <button type="button" class="axm-cancel" data-choice="cancel">${escapeHtml(opts.cancelLabel || 'Keep editing')}</button>
                ${(opts.choices || []).map(c =>
                    '<button type="button" class="' + (c.primary ? 'axm-primary' : 'axm-cancel')
                    + '" data-choice="' + escapeHtml(c.id) + '">' + escapeHtml(c.label) + '</button>').join('')}
            </div>`;
        overlay.appendChild(box);
        document.body.appendChild(overlay);
        const done = choice => {
            document.removeEventListener('keydown', onKey, true);
            overlay.remove();
            resolve(choice);
        };
        const onKey = e => { if (e.key === 'Escape') { e.stopPropagation(); done('cancel'); } };
        document.addEventListener('keydown', onKey, true);
        overlay.addEventListener('pointerdown', e => { if (e.target === overlay) done('cancel'); });
        box.querySelector('.axm-close').addEventListener('click', () => done('cancel'));
        box.querySelectorAll('[data-choice]').forEach(btn =>
            btn.addEventListener('click', () => done(btn.dataset.choice)));
        const primary = box.querySelector('.axm-primary');
        if (primary) primary.focus();
    });
}

// Close the open file: the EDIT session ends and the workbench is empty of it.
// Everything that belonged to the document goes with it — its points, its
// poses, its destination, its refusal, its undo history.
function closeEditSession(opts = {}) {
    if (!state.config) return;
    const name = state.fileName || 'the config';
    state.config = null;
    state.points = [];
    state.sequence = [];
    state.sequenceDraft = [];
    state.selectedIndex = -1;
    state.startPoseSelected = false;
    state.originalYamlText = null;
    state.fileName = null;
    state.fileHandle = null;
    state.loadedMtimeNs = null;
    state.pairFiles = null;
    state.deployPath = null;
    state.strokeGateRefusal = null;
    state.surfaceWarning = null;
    state.compoundArm = null;
    state.sessionOrigin = null;
    state.undoStack = [];
    state.redoStack = [];
    placingGeneratePose = null;
    genDropGeneratedPath();
    invalidateValidation();
    markDirty(false);
    populateEditPoseFields();
    renderTaskHeader();
    updateHistoryButtons();
    buildStartPoseMarker();
    updateAll();
    renderScene();
    if (!opts.silent) setStatus(`${name} closed — the workbench is ready to generate.`);
}

// End the GENERATION: picked poses, knots and the last result are cleared, the
// fields go back to "the generator chooses". A live run cannot be ended from
// here — it owns the server's configs until it finishes or is cancelled.
function clearGenerateSession() {
    ['genStartPose', 'genPreStartPose'].forEach(id => {
        const field = document.getElementById(id);
        if (field) field.value = '';
    });
    const linked = document.getElementById('genPreStartLinked');
    if (linked) linked.checked = true;
    pickingStartPose = false;
    placingGeneratePose = null;
    genDropGeneratedPath();
    state.generate.result = null;
    state.undoStack = [];
    state.redoStack = [];
    genSyncPreStart();
    renderStartPoseTexts();
    buildStartPoseMarker();
    updateHistoryButtons();
}

// Before anything that GENERATES (or picks/places a generation pose): close the
// open file. Resolves true when the workbench is in a generate session.
async function requireGenerateSession(action) {
    if (!state.config) return true;
    const name = state.fileName || 'the open config';
    if (state.sessionOrigin === 'generated' && !state.dirty) {
        // The generation's own unmodified output: iterating, not abandoning.
        closeEditSession({silent: true});
        return true;
    }
    const choices = state.dirty
        ? [{id: 'discard', label: 'Discard & close'}, {id: 'save', label: 'Save & close', primary: true}]
        : [{id: 'close', label: `Close ${name}`, primary: true}];
    const choice = await askSessionChoice({
        title: `Close ${name} to ${action}?`,
        lines: [
            `${name} is open for editing. Editing a file and generating a new one are separate sessions — one ends before the other starts.`,
            state.dirty ? 'It has unsaved edits.' : 'It has no unsaved edits.',
            'Closing clears its points, poses, destination and undo history from the workbench. The file on disk is untouched unless you save.',
        ],
        note: 'Nothing from the file carries into the generation: not its frame, its poses or its undo.',
        choices,
    });
    if (choice === 'cancel') {
        setStatus(`${action} cancelled — ${name} stays open for editing.`);
        return false;
    }
    if (choice === 'save') {
        await saveChanges();
        if (state.dirty) {
            setStatus(`${name} was not saved, so it stays open — ${action} cancelled.`, true);
            return false;
        }
    }
    closeEditSession({silent: true});
    setStatus(`${name} closed — ${action}.`);
    return true;
}

// Before opening a FILE for editing: end the generation. Resolves true when the
// file may be loaded. `label` names what is being opened.
async function requireEditSession(label) {
    if (generationJobLive()) {
        setStatus(`A generation is running — cancel it or let it finish before opening ${label}.`, true);
        return false;
    }
    if (state.config && state.dirty) {
        const name = state.fileName || 'the open config';
        const choice = await askSessionChoice({
            title: `Replace ${name} with ${label}?`,
            lines: [`${name} has unsaved edits.`],
            choices: [{id: 'discard', label: 'Discard edits'}, {id: 'save', label: 'Save first', primary: true}],
        });
        if (choice === 'cancel') return false;
        if (choice === 'save') {
            await saveChanges();
            if (state.dirty) return false;
        }
        return true;
    }
    if (state.config || !generationHasContent()) return true;
    const choice = await askSessionChoice({
        title: `End the generation to open ${label}?`,
        lines: [
            'A generation is in progress on the workbench (picked start / pre-start poses, knots or a result).',
            'Opening a file starts an EDIT session; the two never share the workbench.',
            'Ending the generation clears the picked poses, the knots and the last result.',
        ],
        cancelLabel: 'Keep generating',
        choices: [{id: 'end', label: 'End generation', primary: true}],
    });
    if (choice !== 'end') {
        setStatus(`${label} not opened — the generation continues.`);
        return false;
    }
    clearGenerateSession();
    return true;
}

// The session readout in the task strip: what the workbench IS doing, loudly.
function renderSessionChip() {
    const chip = document.getElementById('taskSession');
    const close = document.getElementById('taskCloseFile');
    const kind = sessionKind();
    if (chip) {
        chip.dataset.kind = kind;
        chip.textContent = kind === 'edit'
            ? `EDITING ${state.fileName || 'config'}${state.dirty ? ' •' : ''}`
            : 'GENERATING';
        chip.title = kind === 'edit'
            ? 'An edit session: the open file is what every tool acts on. Close it to generate.'
            : 'A generation session: no file is open. Opening one ends the generation.';
    }
    if (close) close.disabled = kind !== 'edit';
}

async function closeFileFromStrip() {
    if (!state.config) return;
    if (state.dirty) {
        const name = state.fileName || 'the open config';
        const choice = await askSessionChoice({
            title: `Close ${name}?`,
            lines: [`${name} has unsaved edits.`],
            choices: [{id: 'discard', label: 'Discard & close'}, {id: 'save', label: 'Save & close', primary: true}],
        });
        if (choice === 'cancel') return;
        if (choice === 'save') {
            await saveChanges();
            if (state.dirty) return;
        }
    }
    closeEditSession();
}

// ── One band height for every canvas tab (F60) ─────────────────────────────
// One camera is shared across tabs, so the chrome above the canvas must be the
// same height or the canvas resizes on every switch. But pinning the band to
// its 170px CAP wastes space on whichever tab needs least — measured 85px of
// empty band on the workbench at 2560px wide, which is exactly the complaint
// this redesign began with.
//
// So MEASURE instead: let each canvas tab lay out naturally at the current
// width, take the tallest, and share that. Constant top, minimum emptiness,
// and it re-adapts on resize because the answer depends on the width.
const CANVAS_TABS = ['regions', 'workbench', 'collisions', 'schedule', 'workspace', 'gizmo'];

function equaliseCanvasBands() {
    const band = document.querySelector('.ribbon-body');
    if (!band) return;
    const pages = CANVAS_TABS
        .map(tab => document.querySelector(`.tab-page[data-page="${tab}"]`))
        .filter(Boolean);
    if (!pages.length) return;
    // Measure without showing: each page is laid out off-screen AT THE REAL
    // WIDTH, so the numbers match what the operator will actually get.
    //
    // The width has to be forced. `position:absolute` with no width shrinks to
    // fit, so every page was measured at a width it will never have — the
    // workbench at 2194px (where its seven groups fit ONE row and it measured
    // 96px instead of 169), regions at 834px, the gizmo tab at 522px. The
    // tallest of those fictions became the shared floor, so the busiest tab
    // rose above it on its own and the viewport top split 357/360. The comment
    // here claimed "at the real width" while the code did no such thing.
    document.documentElement.style.setProperty('--cmdbar-shared', '0px');
    const active = pages.find(p => p.classList.contains('active'));
    const width = Math.round((active || band).getBoundingClientRect().width);
    const previous = pages.map(p => [p, p.style.cssText, p.classList.contains('active')]);
    let tallest = 0;
    pages.forEach(page => {
        const wasActive = page.classList.contains('active');
        if (!wasActive) {
            // `.active` carries the real padding/gap/flow — measuring without it
            // came out 1px short, so the floor sat just under what the busiest
            // tab actually renders and the tops split 358/359.
            page.classList.add('active');
            page.style.cssText += ';position:absolute;visibility:hidden;'
                                + `left:-99999px;top:0;height:auto;max-height:none;width:${width}px;`;
        }
        tallest = Math.max(tallest, page.getBoundingClientRect().height);
        if (!wasActive) {
            page.classList.remove('active');
            page.style.cssText = previous.find(entry => entry[0] === page)[1];
        }
    });
    const cap = parseFloat(getComputedStyle(document.documentElement)
        .getPropertyValue('--cmdbar-h')) || 170;
    // +1px of headroom: `min-height` is a FLOOR, so a page whose natural height
    // is 168.4 still renders 168.4 and the tops split 358/359. Rounding up past
    // every page's fractional height makes the floor bind for all of them. The
    // cap still clamps, so this can never exceed 170.
    document.documentElement.style.setProperty(
        '--cmdbar-shared', `${Math.min(Math.ceil(tallest) + 1, cap)}px`);
}

function renderTaskHeader() {
    // Stage-aware ribbon (option A): CSS keys off this to lead with Generate
    // before a config exists and collapse it once one is loaded.
    document.body.dataset.stage = state.config ? 'edit' : 'generate';
    renderSessionChip();
    const crumb = document.getElementById('taskCrumb');
    const badge = document.getElementById('tabTaskBadge');
    if (!crumb) return;
    const task = state.task;
    // The strip now shows on every canvas tab (F60), so it must say something
    // true on each. A tab that is not editing a task states what it IS working
    // on — a blank crumb beside a Back button would be worse than no strip.
    const CONTEXT = {
        regions:    () => `${currentFixture() || 'no fixture'} › regions`,
        collisions: () => `${currentFixture() || 'no fixture'} › dual-arm check`,
        schedule:   () => `${currentFixture() || 'no fixture'} › schedule`,
        workspace:  () => `${currentFixture() || 'no fixture'} › workspace analysis`,
        gizmo:      () => 'tool frame calibration',
    };
    if (!task || state.activeTab !== 'workbench') {
        const context = CONTEXT[state.activeTab];
        crumb.textContent = context ? context()
            : 'No task open — pick a cell on the Board';
        crumb.classList.toggle('empty', !context);
        if (badge) badge.textContent = '';   // the strip carries the task name
        return;
    }
    crumb.classList.remove('empty');
    crumb.innerHTML = `<span class="crumb-fixture">${escapeHtml(task.fixture)}</span>`
        + `<span class="crumb-sep">›</span><span class="crumb-region">${escapeHtml(task.region)}</span>`
        + `<span class="crumb-sep">›</span><span class="crumb-arm arm-${task.arm}">${task.arm.toUpperCase()}</span>`;
    if (badge) badge.textContent = '';   // see above: it wrapped the tab row
}

// The destination is DISPLAYED, never typed. The window.prompt this replaces
// asked for a path whose default was wrong (`cleaning_tasks/config/...`), so
// every first deploy of a session failed with PermissionError and the operator
// had to work out that it meant `ros/orchestration/alix_tasks/config`.
// The rare override. Deliberately a separate, named action rather than a
// prompt on the happy path.
let deployOverride = null;

function editDeployDestination() {
    const current = deployOverride || state.deployPath || '';
    const next = window.prompt('Deploy to (path relative to repo root):', current);
    if (next === null) return;
    deployOverride = next.trim() || null;
    const host = document.getElementById('taskDest');
    if (host && deployOverride) {
        host.textContent = deployOverride;
        host.classList.add('overridden');
        host.title = `Deploy writes here (OVERRIDDEN): ${deployOverride}`;
    }
    setStatus(deployOverride ? `Destination overridden: ${deployOverride}`
                             : 'Destination override cleared.');
}

async function refreshTaskDestination() {
    const host = document.getElementById('taskDest');
    if (!host) return;
    const task = state.task;
    deployOverride = null;          // must not survive into a different task
    host.classList.remove('overridden');
    if (!task || !studio.enabled) { host.textContent = ''; return; }
    const filename = taskFilename(task.region, task.arm);
    try {
        const data = await api(`/api/deploy-path?fixture=${encodeURIComponent(task.fixture)}`
                             + `&filename=${encodeURIComponent(filename)}`);
        // Filename on the bar, full path in the title and in the Deploy
        // confirm. A 70-character repo-relative path cannot share a 44px row
        // with the task's own name.
        host.textContent = data.deployPath.split('/').pop();
        host.title = `Deploy writes here:\n${data.deployPath}`;
        state.deployPath = data.deployPath;
    } catch (err) {
        host.textContent = '';
        host.title = '';
    }
}

// The server owns this rule (regions.py:output_filename); this mirrors it only
// to show the destination BEFORE the task is generated. The path actually
// written always comes back from the server.
function taskFilename(region, arm) {
    return `${region}_${arm}_cleaning_points.yaml`;
}

function renderBoardRows(data) {
    const cell = (row, arm) => {
        const c = row.arms[arm] || {};
        if (!c.applicable) {
            const why = c.reason === 'generate-false'
                ? 'generate: false in models/regions.yaml — this region\'s coverage belongs to another task; no config is expected'
                : c.reason === 'mechanism'
                    ? 'RL_compound in models/regions.yaml — a mechanism op, not a cleaning config'
                    : `declared ${row.armCoverage} in models/regions.yaml — this arm is not meant to clean this region`;
            return `<td class="board-cell" data-state="na" title="${escapeHtml(why)}">`
                 + `<span class="pill pill-na">—</span></td>`;
        }
        if (c.exists) {
            // WHICH generator made the file (STUDIO_SEAMS_PLAN §3): two still
            // write configs and their artefacts are not interchangeable, so the
            // cell says so — in words, with the gate verdict the file carries.
            const by = c.producedBy || {};
            const ROUTE = {'cspace-pipeline': 'C-space', 'raster-legacy': 'raster',
                           'hand-authored': 'hand', unknown: '?', unreadable: '?'};
            const gate = by.strokeGateOk === true ? ' · gate ✓'
                       : by.strokeGateOk === false ? ' · gate REFUSED' : '';
            const routeTip = by.route === 'cspace-pipeline'
                ? 'written by the C-space pipeline (stroke gate stamped in provenance)'
                : by.route === 'raster-legacy'
                    ? 'written by the legacy raster generator — never stroke-gated'
                    : by.route === 'hand-authored' ? 'hand-authored' : 'producer not recorded in the file';
            return `<td class="board-cell" data-state="present" data-region="${escapeHtml(row.key)}"`
                 + ` data-arm="${arm}" data-route="${escapeHtml(by.route || 'unknown')}" title="${escapeHtml(c.path)}\n${escapeHtml(routeTip)}">`
                 + `<span class="pill pill-ok">✓ ${c.points === null ? '?' : c.points} pts</span>`
                 + `<span class="pill pill-route" data-route="${escapeHtml(by.route || 'unknown')}">${ROUTE[by.route] || '?'}${gate}</span>`
                 + `<span class="pill-metrics" title="computing coverage + validation…">…</span></td>`;
        }
        return `<td class="board-cell" data-state="missing" data-region="${escapeHtml(row.key)}"`
             + ` data-arm="${arm}" title="no config yet — click to generate it">`
             + `<span class="pill pill-missing">· generate</span></td>`;
    };
    // Relative age of the NEWER arm config — the freshness question the
    // operator actually asks ("did I regenerate this after the mesh changed?").
    const age = row => {
        const stamps = ['right', 'left']
            .map(arm => (row.arms[arm] || {}).mtimeNs || 0)
            .filter(Boolean);
        if (!stamps.length) return '';
        const seconds = (Date.now() - Math.max(...stamps) / 1e6) / 1000;
        if (seconds < 90) return 'just now';
        if (seconds < 5400) return `${Math.round(seconds / 60)} min ago`;
        if (seconds < 129600) return `${Math.round(seconds / 3600)} h ago`;
        return `${Math.round(seconds / 86400)} d ago`;
    };
    // The REGION-ROW cell of a paired region (plan/P16 section 4): the union
    // of both arm configs over the whole marked region, filled in like the
    // arm cells from /api/board-cell?arm=pair. Advisory only (R6 stands).
    const pairCell = row => {
        const both = ['right', 'left'].every(arm => (row.arms[arm] || {}).exists);
        if (row.armCoverage !== 'RL_PAIRED' || !both) {
            const why = row.armCoverage !== 'RL_PAIRED'
                ? 'not a paired region: the arm cell is the whole score'
                : 'the union needs both arm configs on disk';
            return `<td class="board-pair" data-state="na" title="${escapeHtml(why)}"><span class="pill pill-na">—</span></td>`;
        }
        return `<td class="board-pair" data-state="present" data-region="${escapeHtml(row.key)}"`
             + ` title="union of both arms over the whole marked region (board estimate)">`
             + `<span class="pill-metrics" title="computing the union…">…</span></td>`;
    };
    return '<table class="board"><thead><tr>'
         + '<th>region</th><th>component</th><th>right</th><th>left</th><th>pair</th>'
         + '<th>updated</th><th>description</th>'
         + '</tr></thead><tbody>'
         + data.regions.map(r =>
             `<tr><th scope="row">${escapeHtml(r.key)}</th>`
             + `<td class="board-meta">${escapeHtml(r.component)}</td>`
             + cell(r, 'right') + cell(r, 'left') + pairCell(r)
             + `<td class="board-age">${age(r)}</td>`
             + `<td class="board-meta" title="${escapeHtml(r.description)}">${escapeHtml(r.description)}</td></tr>`).join('')
         + '</tbody></table>';
}
// ── Board metrics: coverage % + validation, filled in asynchronously ───────
// The board renders instantly from what is on disk; these two columns are
// COMPUTED (a cold cell costs the server a dry-run surface rebuild), so each
// present cell is fetched separately and the pills fill in as answers arrive.
// The server caches per (path, mtime), so a revisit is free.
let boardMetricsRun = 0;   // stale-fill token: a reload or fixture switch supersedes the sweep

async function fillBoardMetrics(host, fixture) {
    if (!studio.enabled) return;
    const run = ++boardMetricsRun;
    // the arm cells first, then the pair cells (a union costs two surface
    // rebuilds; the arm figures are what the operator reads first)
    const cells = Array.from(host.querySelectorAll('.board-cell[data-state="present"]'))
        .concat(Array.from(host.querySelectorAll('.board-pair[data-state="present"]')));
    const worker = async () => {
        while (cells.length) {
            if (run !== boardMetricsRun) return;   // superseded — stop, don't paint stale cells
            const td = cells.shift();
            const isPair = td.classList.contains('board-pair');
            try {
                const m = await api(`/api/board-cell?fixture=${encodeURIComponent(fixture)}`
                                  + `&region=${encodeURIComponent(td.dataset.region)}`
                                  + `&arm=${encodeURIComponent(isPair ? 'pair' : td.dataset.arm)}`);
                if (run !== boardMetricsRun) return;
                if (isPair) renderPairMetrics(td, m); else renderCellMetrics(td, m);
            } catch (e) {
                const slot = td.querySelector('.pill-metrics');
                const busy = e.payload && e.payload.generationBusy;
                if (slot) {
                    slot.textContent = busy ? 'busy' : '';
                    slot.title = busy
                        ? 'A path generation is running and holds the process-wide task-config read '
                          + 'guard. This cell is NOT empty — it cannot be read right now.'
                        : `metrics unavailable: ${e.message}`;
                }
                if (busy) return;    // the whole sweep is blocked; stop asking 31 more times
            }
        }
    };
    // Two lanes: enough to hide latency, few enough that a cold 32-cell sweep
    // does not saturate the server's CPU while someone is generating.
    await Promise.all([worker(), worker()]);
}

function renderCellMetrics(td, m) {
    const slot = td.querySelector('.pill-metrics');
    if (!slot) return;
    const bits = [];
    if (typeof m.coveragePct === 'number') {
        // [N-11]: judged against the region's target when THIS config's
        // requirement block carries one (do_board_cell copies it), else the 95 contract
        const t = coverageTargetOf({provenance: {stroke: {requirements: {
            coverageTarget: m.coverageTarget, coverageTargetSource: m.coverageTargetSource,
            coverageTargetCitation: m.coverageTargetCitation, taskType: m.taskType}}}});
        // [N-1]: a PAIRED task is judged on the union in the region's pair cell
        // (renderPairMetrics); its arm cell shows the share neutrally
        const paired = t.fromBlock && t.taskType === 'paired';
        const ok = m.coveragePct >= t.pct;
        // the tooltip is built HERE, not as a template nested in the template: the
        // test/ delimiter guard's stripper cannot parse a nested backtick with an
        // apostrophe inside (test_editor_js_integrity, 2 unclosed '(' since 5980991)
        const covTitle = paired
            ? 'this arm\'s share (board estimate); the task is judged on the UNION in the region\'s pair cell against '
              + coverageTargetNote(t)
            : 'coverage vs ' + coverageTargetNote(t) + ' (board estimate, this arm\'s share)';
        bits.push(`<span class="pill ${paired ? 'pill-na' : ok ? 'pill-ok' : 'pill-warn'}"`
                + ` title="${escapeHtml(covTitle)}">`
                + `${paired || ok ? '' : '! '}${m.coveragePct}%</span>`);
    } else if (m.coverageError) {
        bits.push(`<span class="pill pill-na" title="coverage unavailable: ${escapeHtml(m.coverageError)}">cov ?</span>`);
    }
    // passes per point beside the percentage (plan/P16 section 3): how many
    // times, not only how much. Display only.
    const pp = m.passesPerPoint;
    if (pp && pp.mean != null) {
        bits.push(`<span class="pill ${m.overCoveredPasses ? 'pill-warn' : 'pill-ok'}"`
                + ` title="passes per point over this arm's covered share (board estimate): mean ${pp.mean}, p10 ${pp.p10}, p90 ${pp.p90}`
                + `${m.seamPassesMean != null ? '; seam ' + m.seamPassesMean : ''}${m.overCoveredPasses ? ' — over-passed' : ''}">`
                + `${pp.mean}×</span>`);
    }
    if (m.validationPass === true) {
        bits.push(`<span class="pill pill-ok" title="all config checks pass">✓</span>`);
    } else if (m.validationPass === false) {
        bits.push(`<span class="pill pill-warn" title="failed: ${escapeHtml((m.checksFailed || []).join(', '))}">⚠</span>`);
    } else if (m.validationError) {
        bits.push(`<span class="pill pill-na" title="validation unavailable: ${escapeHtml(m.validationError)}">val ?</span>`);
    }
    slot.innerHTML = bits.join('');
    slot.removeAttribute('title');
}

// The pair cell (plan/P16 section 4): THE score of a paired task is the union
// of both arms over the whole marked region; the arm cells are its sub-figures.
// Judged against the region's own coverageTarget when the block carries one
// ([N-11]: the 95 contract stays the fallback). Advisory only: R6 stands.
function renderPairMetrics(td, m) {
    const slot = td.querySelector('.pill-metrics');
    if (!slot) return;
    if (m.applicable === false) {
        slot.innerHTML = `<span class="pill pill-na" title="${escapeHtml(m.note || 'no union')}">—</span>`;
        slot.removeAttribute('title');
        return;
    }
    if (typeof m.unionPct !== 'number') {
        const why = m.coverageError || m.error || 'union unavailable';
        slot.innerHTML = `<span class="pill pill-na" title="${escapeHtml(why)}">∪ ?</span>`;
        slot.removeAttribute('title');
        return;
    }
    const targetPct = m.coverageTarget != null ? Math.round(m.coverageTarget * 1000) / 10 : COVERAGE_TARGET_PCT;
    const ok = m.unionPct >= targetPct;
    const pct = v => (v == null ? '?' : `${Math.round(v * 1000) / 10}%`);
    const art = m.artefact || {};
    const artNote = !art.exists ? 'no pair artefact beside the configs'
        : art.fresh ? `pair artefact fresh (${pct(art.coveredFractionOfRegion)} at ${art.samples} samples)`
        : `pair artefact STALE (${(art.stale || []).join(', ')} changed since it was written)`;
    const title = `union ${m.unionPct}% of the whole region vs the ${targetPct}% target (board estimate, advisory)`
        + `\nboth ${pct(m.coveredBoth)} · left only ${pct(m.coveredLeftOnly)} · right only ${pct(m.coveredRightOnly)} · neither ${pct(m.coveredByNeither)}`
        + `\nshares: left ${pct(m.leftShareCovered)}, right ${pct(m.rightShareCovered)}`
        + `\nseam realised by both: ${m.seamRealised == null ? 'no shared geometry' : pct(m.seamRealised)} (band ${m.seamOverlapM} m)`
        + `\n${artNote}`;
    slot.innerHTML = `<span class="pill ${ok ? 'pill-ok' : 'pill-warn'}" title="${escapeHtml(title)}">`
                   + `${ok ? '' : '! '}∪ ${m.unionPct}%</span>`;
    slot.removeAttribute('title');
}

function initBoard() {
    const host = document.getElementById('boardTable');
    if (!host) return;
    document.getElementById('boardRefresh')?.addEventListener('click', loadBoard);
    document.getElementById('boardGenerateMissing')?.addEventListener('click', generateMissingOnPipeline);
    document.getElementById('boardRasterSweep')?.addEventListener('click', generateMissingFromBoard);
    document.getElementById('boardBulkCancel')?.addEventListener('click', async () => {
        if (!boardBulk) return;
        try {
            const out = await api('/api/bulk-generate-cancel', {method: 'POST', headers: {'Content-Type': 'application/json'},
                                                               body: JSON.stringify({jobId: boardBulk.jobId})});
            setStatus(`Generate missing: cancel requested — ${out.note || 'stops before the next cell'}.`);
        } catch (e) { setStatus(`Cancel failed: ${e.message}`, true); }
    });
    document.getElementById('boardBatch')?.addEventListener('click', async event => {
        const btn = event.target.closest('.board-open');
        if (btn && btn.dataset.bulkIdx !== undefined) { openBulkCell(Number(btn.dataset.bulkIdx)); return; }
        if (!btn || !boardBatch) return;
        if (btn.dataset.region) {              // "pick start pose"
            const sel = document.getElementById('genRegion');
            if (sel && [...sel.options].some(o => o.value === btn.dataset.region)) {
                sel.value = btn.dataset.region;
            }
            openWorkbench(btn.dataset.region, btn.dataset.arm);
            setStatus(`${btn.dataset.region} [${btn.dataset.arm}] has never been authored — `
                    + `use "Pick start pose" on the surface, then Generate.`);
            return;
        }
        const r = boardBatch[Number(btn.dataset.idx)];
        if (!r || !r.ok) return;
        if (!(await requireEditSession(`${r.region} [${r.arm}]`))) return;
        // Load the generated YAML into the editor exactly as Generate does,
        // so the gates and Deploy apply to it unchanged.
        loadYamlText(r.yamlText, r.deployPath.split('/').pop(), null, 'generated');
        state.deployPath = r.deployPath;
        studio.lastTask = {fixture: boardData.fixture, region: r.region, arm: r.arm};
        openWorkbench(r.region, r.arm);
        setStatus(`${r.region} [${r.arm}] loaded — ${r.points} points, `
                + `${r.coverage}% coverage. Review, then Deploy.`);
    });
    // A cell is a control: it takes you to the task it represents, with the
    // region and arm already set. That is the whole reason the board exists —
    // otherwise it is a report you still have to act on by hand.
    host.addEventListener('click', event => {
        const td = event.target.closest('.board-cell');
        if (!td || !td.dataset.region) return;
        const region = td.dataset.region;
        const arm = td.dataset.arm;
        openWorkbench(region, arm, {status: td.dataset.state === 'missing'
            ? `${region} [${arm}] has no config — press Generate.`
            : `${region} [${arm}] opened; press Generate to rebuild it.`});
    });
}

// ── Generate the missing tasks ─────────────────────────────────────────────
// The board knows exactly which region x arm cells have no config; the loop to
// fill them was 6 UI actions each, run 6-38 times, with nothing showing
// progress. This runs them back to back and reports per cell.
//
// It does NOT deploy. Generation is cheap and reversible; writing 12 configs
// unattended is neither, and the coverage/reach gates exist precisely because
// a generated task is not automatically a good one. The operator opens the
// rows they care about and deploys them individually.
// F72: the whole-fixture sweep, two-phase. Phase 1 (write:false) is the PLAN —
// the server places the fixture per the 250 mm standard, generates every
// expected region x arm with self-derived start poses, and gates each one;
// nothing lands on disk. The styled modal restates the plan (placement
// provenance, failures, low-coverage rows), and only a confirmed phase 2
// (write:true) writes — configs at/above the warn floor, existing files kept.
// This replaced the generate-only batch whose commonest failure was "needs a
// start pose — the generator cannot derive one yet": F61 made derivation
// real, so the honest blocker list is now whatever the server report says.
// ── Generate missing, on the PRODUCT route (STUDIO_SEAMS_PLAN §3) ──────────
// The bulk button used to drive the legacy raster sweep below while the
// Workbench's Generate drove the C-space pipeline: two generators behind one
// verb, and the bulk artefact was never stroke-gated. It now runs the SAME
// pipeline per cell as a server JOB (start / poll / cancel), shows every cell's
// verdict as it lands, and writes only what the operator applies — without
// regenerating anything. The raster sweep stays reachable as the reference
// route (`generateMissingFromBoard`, the two-phase sweep, unchanged) while the
// pipeline is still proving itself on some families; the board says which
// generator wrote each file.
let boardBulk = null;

async function generateMissingOnPipeline() {
    if (!boardData) { setStatus('Load the board first.', true); return; }
    const fixture = boardData.fixture;
    const btn = document.getElementById('boardGenerateMissing');
    if (btn) btn.disabled = true;
    let started;
    try {
        started = await api('/api/bulk-generate', {method: 'POST', headers: {'Content-Type': 'application/json'},
                                                  body: JSON.stringify({fixture})});
    } catch (e) {
        setStatus(`Generate missing: ${e.message}${e.hint ? ' — ' + e.hint : ''}`, true);
        if (btn) btn.disabled = false;
        return;
    }
    boardBulk = {jobId: started.jobId, fixture, status: null};
    setStatus(`Generate missing (C-space pipeline): ${started.toGenerate} of ${started.cells} cells to generate `
        + '— each takes 20-180 s; the other routes pause while it runs.');
    const cancel = document.getElementById('boardBulkCancel');
    if (cancel) cancel.hidden = false;
    let st = null;
    for (;;) {
        try {
            st = await api(`/api/bulk-generate-status?jobId=${encodeURIComponent(started.jobId)}`);
        } catch (e) {
            setStatus(`Generate missing: lost the job status (${e.message}) — the job keeps running on the server.`, true);
            break;
        }
        boardBulk.status = st;
        renderBoardBulk(st);
        if (['done', 'cancelled', 'failed'].includes(st.state)) break;
        await new Promise(r => setTimeout(r, st.pollMs || 3000));
    }
    if (cancel) cancel.hidden = true;
    if (btn) btn.disabled = false;
    if (!st || !['done', 'cancelled'].includes(st.state)) return;
    const s = st.summary;
    const atFloor = st.cells.filter(c => c.gateOk === true && c.meetsFloor === true && !c.written);
    const belowFloor = st.cells.filter(c => c.gateOk === true && c.meetsFloor !== true && !c.written);
    const choice = await askSessionChoice({
        title: `Write the generated ${fixture} configs?`,
        lines: [
            `${s.gatePass} of ${s.cells} cells passed their own stroke gate; ${s.gatePassAtFloor} of those meet the region's coverage floor.`,
            `${s.gateRefused} were REFUSED by the gate and ${s.noConfig} produced no config — neither is ever written.`,
            'Existing configs were kept (they can carry hand calibration). Written configs still face the deploy gates.',
        ],
        cancelLabel: 'Write nothing',
        note: 'Nothing is regenerated: the configs shown are the ones written.',
        choices: [
            ...(belowFloor.length ? [{id: 'all', label: `Write ${atFloor.length + belowFloor.length} (incl. below floor)`}] : []),
            {id: 'floor', label: `Write ${atFloor.length} at floor`, primary: true},
        ],
    });
    if (choice === 'cancel' || (choice === 'floor' && !atFloor.length)) {
        setStatus('Generate missing: nothing written — open any cell from the list to review it.');
        return;
    }
    const cells = (choice === 'all' ? [...atFloor, ...belowFloor] : atFloor).map(c => ({region: c.region, arm: c.arm}));
    try {
        const out = await api('/api/bulk-generate-apply', {method: 'POST', headers: {'Content-Type': 'application/json'},
                                                          body: JSON.stringify({jobId: started.jobId, cells})});
        setStatus(`Generate missing: ${out.written} written, ${out.refused} not written`
            + (out.refused ? ' — see the list for why' : '') + '. Each still faces the deploy gates.', out.refused > 0);
        renderBoardBulk(await api(`/api/bulk-generate-status?jobId=${encodeURIComponent(started.jobId)}`));
    } catch (e) {
        setStatus(`Generate missing: write failed — ${e.message}`, true);
    }
    loadBoard();
}

// A Board cell's CLEARANCE text (review E19, display only): the gate's all-links minimum -- the hands included --
// with its pair and s, then Newton's 2026-09-29 clearance floor (ruling 1: the arm + mount/camera links REFUSE below
// the region's floor) with its source and what the arm/camera held.  The parts are JOINED, never prefixed: a gate the
// floor refused measures no all-links record, and its cell used to read " · floor 5 mm (default) REFUSED · ..."
// with a leading separator (2026-10-01 Studio check, "Left open" 4; test_studio_clearance_display.py).
function boardClearanceText(c) {
    const all = c.gateClearanceMm == null ? ''
        : `${Number(c.gateClearanceMm).toFixed(1)} mm`
          + (c.gateClearancePair ? ` (${[].concat(c.gateClearancePair).join(' / ')})` : '')
          + (c.gateClearanceSM != null ? ` at s=${Number(c.gateClearanceSM).toFixed(3)} m` : '');
    const floor = c.gateClearanceFloorMm == null ? ''
        : `floor ${Number(c.gateClearanceFloorMm).toFixed(0)} mm (${c.gateClearanceFloorSource || '?'})`
          + (c.gateClearanceFloorRefused ? ' REFUSED' : '')
          + (c.gateClearanceFloorMinMm != null ? ` · arm/camera ${Number(c.gateClearanceFloorMinMm).toFixed(1)} mm` : '');
    const parts = [all, floor].filter(Boolean);
    return parts.length ? parts.join(' · ') : '—';
}

function renderBoardBulk(st) {
    const host = document.getElementById('boardBatch');
    if (!host || !st) return;
    const pct = v => (v == null ? '—' : `${(Number(v) * 100).toFixed(1)}%`);
    const gate = c => c.sectioned ? 'SECTIONED' : c.gateOk === true ? '✓ pass'
        : c.gateOk === false ? `⛔ ${c.failureClass || 'refused'}` : '—';
    // plan/P17 L5 (review S1): a sealed set counts as a deployed config; both forms is a conflict
    const report = c => c.writeError || (c.written ? `written → ${c.written}` : '')
        || c.error || c.detail
        || (c.state === 'conflict' ? 'CONFLICT: a single config AND a sealed section set are deployed — retire one'
            : c.state === 'kept' ? (c.form === 'sectioned' ? 'a sealed section set is deployed — kept'
                                                           : 'a config exists — kept') : '');
    // review E19 (display only): tier · ladder rate · tracked max step, and the clearance
    const design = c => c.acceptanceTier == null ? '—'
        : `${c.acceptanceTier}${c.ladderRateDegPerM != null ? ` · ${c.ladderRateDegPerM} deg/m` : ''}`
          + `${c.trackedMaxStepDeg != null ? ` · max step ${Number(c.trackedMaxStepDeg).toFixed(1)}°` : ''}`;
    const clearance = boardClearanceText;
    host.innerHTML = `<div class="hint">C-space pipeline · job ${escapeHtml(st.jobId)} · ${escapeHtml(st.state)}`
        + ` · ${st.elapsedS}s · ${st.summary.gatePass} gate pass (${st.summary.gatePassAtFloor} at floor),`
        + ` ${st.summary.gateRefused} refused, ${st.summary.noConfig} no config</div>`
        + '<table class="board"><thead><tr><th>region</th><th>arm</th><th>state</th><th>gate</th>'
        + '<th>coverage (region)</th><th>reachable covered</th><th>knots</th>'
        + '<th title="plan/P17 L4 acceptance tier · the ladder rate it was designed at · the step the tracker measured (display only)">design</th>'
        + '<th title="the gate\u2019s minimum non-allowed clearance: the arm + mount/camera links REFUSE below the region\u2019s floor (Newton 2026-09-29; 5 mm default, 10 mm bowl inside); the all-links figure (hands included) is display only">clearance</th>'
        + '<th>report</th><th></th></tr></thead><tbody>'
        + st.cells.map((c, i) =>
            `<tr><th scope="row">${escapeHtml(c.region)}</th><td>${escapeHtml(c.arm)}</td>`
            + `<td class="board-cell" data-state="${c.state === 'done' && c.gateOk ? 'present' : 'missing'}">${escapeHtml(c.state)}</td>`
            + `<td>${escapeHtml(gate(c))}</td>`
            + '<td>' + pct(c.coveredFractionOfRegion)
            // [N-1]: a paired cell's verdict is the pair's UNION once the pair step measured
            // it (floorScope 'union'); until then its own share is only a proxy for it
            + (c.meetsFloor === false
                ? ' <span class="hint">' + (c.floorScope === 'union' ? 'union below ' : c.floorScope === 'share-proxy'
                    ? 'share below the union target ' : 'below ') + c.regionFloorPct + '%</span>'
                : c.meetsFloor === true && c.floorScope === 'share-proxy'
                    ? ' <span class="hint">union unmeasured (target ' + c.regionFloorPct + '%)</span>' : '')
            + '</td>'
            // the GENERATION TARGET beside the score: how much of what the arm can
            // reach the path covers (aim 100 %), and how much of the region is reachable
            + '<td>' + pct(c.coveredFractionOfReachable)
            + (c.reachableFractionOfRegion == null ? '' : ' <span class="hint">of ' + pct(c.reachableFractionOfRegion) + ' reachable</span>')
            + '</td>'
            + '<td>' + (c.knots ?? '—') + '</td>'
            + '<td' + (c.acceptanceTier === 'unaccepted' ? ' class="bad"' : '') + '>' + escapeHtml(design(c)) + '</td>'
            + '<td>' + escapeHtml(clearance(c)) + '</td>'
            + '<td>' + escapeHtml(String(report(c)).slice(0, 220)) + '</td>'
            + '<td>' + (c.state === 'done' ? '<button class="board-open" data-bulk-idx="' + i + '">Open</button>' : '')
            + '</td></tr>').join('')
        + '</tbody></table>';
}

async function openBulkCell(index) {
    const st = boardBulk && boardBulk.status;
    const cell = st && st.cells[index];
    if (!cell) return;
    if (!(await requireEditSession(`${cell.region} [${cell.arm}]`))) return;
    try {
        const got = await api(`/api/bulk-generate-config?jobId=${encodeURIComponent(st.jobId)}`
            + `&region=${encodeURIComponent(cell.region)}&arm=${encodeURIComponent(cell.arm)}`);
        loadYamlText(got.configYaml, `${cell.region}_${cell.arm}_cleaning_points.yaml`, null, 'generated');
        state.deployPath = got.deployPath || null;
        state.strokeGateRefusal = got.gateOk === false
            ? `stroke gate REFUSED this config (${cell.failureClass || 'refused'}): ${cell.detail || ''}` : null;
        openWorkbench(cell.region, cell.arm);
        setStatus(`${cell.region} [${cell.arm}] opened from the bulk job — gate ${cell.gateOk ? 'pass' : 'REFUSED'}, `
            + `coverage ${cell.coveredFractionOfRegion == null ? '—' : (cell.coveredFractionOfRegion * 100).toFixed(1) + '%'}.`);
    } catch (e) {
        setStatus(`Could not open ${cell.region} [${cell.arm}]: ${e.message}`, true);
    }
}

// The REFERENCE route: the legacy raster sweep, unchanged. Kept runnable while
// the C-space pipeline is still proving itself on some families (29-cell
// commode_c estate, 2026-09-15: 10 gate passes) — no longer the Board's default
// button, which is `generateMissingOnPipeline`.
async function generateMissingFromBoard() {
    if (!boardData) { setStatus('Load the board first.', true); return; }
    const fixture = boardData.fixture;
    const btn = document.getElementById('boardGenerateMissing');
    if (btn) btn.disabled = true;
    const call = write => api('/api/auto-generate', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ fixture, write }),
    });
    let plan;
    setStatus(`Auto-generate: planning ${fixture} (placement + every expected config)…`);
    try { plan = await call(false); }
    catch (e) { setStatus('Auto-generate plan failed: ' + e.message, true); if (btn) btn.disabled = false; return; }
    if (plan.error) { setStatus('Auto-generate: ' + plan.error, true); if (btn) btn.disabled = false; return; }
    boardBatch = plan;
    renderBoardBatchResults(plan);

    const s = plan.summary;
    // 'ok' in the plan = at/above the warn floor = what a write would land;
    // 'low' stays on the review bench, 'kept' already exists.
    const writable = plan.configs.filter(c => c.status === 'ok').length;
    const chips = [
        { cls: s.failed ? 'g-bad' : 'g-ok', glyph: s.failed ? '⛔' : '✓', label: 'generation',
          val: `${s.ok} ok · ${s.low} low · ${s.failed} failed` },
        { cls: '', glyph: '±', label: 'writes', val: `${writable} new · ${s.kept} kept` },
    ];
    const lines = [];
    if (plan.placement.source === 'derived') {
        lines.push({ level: 'warning',
                     text: `scene.yaml has no pose — the derived bring-up pose `
                         + `[${plan.placement.pose.join(', ')}] will be written (${plan.placement.sentence}).` });
    }
    plan.configs.filter(c => c.status === 'failed').slice(0, 4).forEach(c =>
        lines.push({ level: 'error', text: `${c.region} (${c.arm}): ${c.sentence}` }));
    plan.configs.filter(c => c.status === 'low').slice(0, 3).forEach(c =>
        lines.push({ level: 'warning', text: `${c.region} (${c.arm}): ${c.sentence}` }));

    const proceed = await showStudioModal({
        title: 'Auto-generate fixture',
        destLabel: 'Writes into',
        destDir: `config/${fixture.split('_')[0]}_cleaning/`,
        destFile: fixture + '/',
        chips, lines,
        note: 'Existing configs are kept — they carry hand calibration. Written tasks still face the deploy gates individually.',
        confirmLabel: writable ? `Write ${writable} config(s)` : 'Nothing to write',
    });
    if (!proceed || !writable) {
        setStatus(writable ? 'Auto-generate: plan reviewed, nothing written.'
                           : 'Auto-generate: nothing new to write.', false);
        if (btn) btn.disabled = false;
        return;
    }
    setStatus(`Auto-generate: writing ${fixture}…`);
    let report;
    try { report = await call(true); }
    catch (e) { setStatus('Auto-generate write failed: ' + e.message, true); if (btn) btn.disabled = false; return; }
    if (btn) btn.disabled = false;
    if (report.error) { setStatus('Auto-generate: ' + report.error, true); return; }
    boardBatch = report;
    renderBoardBatchResults(report);
    const rs = report.summary;
    setStatus(`Auto-generate: ${rs.written} written · ${rs.kept} kept · ${rs.failed} failed`
        + (report.placement.wrote ? ` · scene pose written ${JSON.stringify(report.placement.pose)}` : '')
        + ' — each written task still faces the deploy gates.', rs.failed > 0);
    loadBoard();   // the board reflects what now exists on disk
}

let boardBatch = null;

function renderBoardBatchResults(report) {
    const host = document.getElementById('boardBatch');
    if (!host) return;
    const configs = report.configs || [];
    const pl = report.placement || {};
    const STATE = { written: 'present', ok: 'present', kept: 'present',
                    low: 'missing', skipped: 'missing', failed: 'missing' };
    host.innerHTML = `<div class="hint">${report.write ? 'written' : 'plan (dry run — nothing on disk)'}`
        + ` · placement ${escapeHtml(pl.source || '?')}${pl.wrote ? ' (pose written)' : ''}</div>`
        + '<table class="board"><thead><tr><th>region</th><th>arm</th><th>status</th>'
        + '<th>points</th><th>coverage</th><th>report</th></tr></thead><tbody>'
        + configs.map(c =>
            `<tr><th scope="row">${escapeHtml(c.region)}</th><td>${escapeHtml(c.arm)}</td>`
            + `<td class="board-cell" data-state="${STATE[c.status] || 'missing'}">${escapeHtml(c.status)}</td>`
            + `<td>${c.points ?? '—'}</td>`
            + `<td>${c.coveragePct != null ? c.coveragePct + '%' : '—'}</td>`
            + `<td>${escapeHtml(c.sentence || '')}</td></tr>`).join('')
        + '</tbody></table>';
}

// ── Deploy gates ───────────────────────────────────────────────────────────
// Deploy used to enable the moment any config existed. Validation runs four
// STRUCTURAL checks, and validator.py says outright that coverage, point count
// and IK are skipped — so "✓ valid — 4 checks passed" was compatible with 40 %
// coverage and half the points unreachable.
//
// Newton's rule (2026-08-12): warn and allow — EXCEPT an IK failure with the
// pole in the correct position, which must never validate. That exception is
// the whole point: with the pole pinned to the state the task will run at, an
// unreachable point is not "we did not check properly", it is a motion the
// robot cannot make. With no pole pinned the same failure is inconclusive,
// because the solver was free to place the sliding plate anywhere.
let lastValidation = null;

function gateState() {
    const g = {
        coverage: { state: 'unrun', detail: 'not computed yet — press Coverage' },
        reach: { state: 'unrun', detail: 'not analysed yet — press Analyze' },
        checks: { state: 'unrun', detail: 'not validated yet — press Validate' },
    };

    if (lastCoverage && typeof lastCoverage.coverage_pct === 'number') {
        const pct = lastCoverage.coverage_pct;
        const tgt = coverageTarget();        // [N-11]: the region's target when the config carries one
        const v = coverageVerdict(pct, tgt, state.config, {edited: state.dirty});   // [N-1]: paired = the union's
        g.coverage = {
            state: v.state,
            label: `${pct}%`,
            targetPct: tgt.pct,
            scope: v.scope,
            detail: v.state === 'info' ? `coverage ${v.note}`
                  : `coverage ${v.scope === 'union' ? v.note : `${pct}% against ${v.note}`}`
                  + (v.met ? '' : ' — click to fly to the largest gap'),
        };
    }

    if (lastAnalysis && Array.isArray(lastAnalysis.results)) {
        const rs = lastAnalysis.results;
        const unreachable = rs.filter(r => !r.reachable);
        const failing = rs.filter(_analysisFailing);
        // The pole state THIS analysis ran with, echoed by the server — not
        // whatever the dropdown says now.
        const pinned = lastAnalysis.poleState;
        if (!failing.length) {
            g.reach = { state: 'pass', label: `${rs.length}/${rs.length}`,
                        detail: `every point reachable${pinned ? ` (pole pinned to "${pinned}")` : ''}` };
        } else if (unreachable.length && pinned) {
            g.reach = {
                state: 'fail', blocking: true,
                label: `${rs.length - unreachable.length}/${rs.length}`,
                detail: `${unreachable.length} point(s) have NO IK solution with the pole `
                      + `pinned to "${pinned}" — the robot cannot make this motion. `
                      + `Deploy is blocked; fix the points or the pole state.`,
            };
        } else {
            g.reach = {
                state: 'warn',
                label: `${rs.length - failing.length}/${rs.length}`,
                detail: unreachable.length
                    ? `${unreachable.length} point(s) unreachable, but NO pole state was `
                      + `pinned — re-run Analyze with a pole state for a conclusive answer`
                    : `${failing.length} point(s) fail orientation or collision`,
            };
        }
    }

    if (lastValidation) {
        const entries = Object.entries(lastValidation);
        const failed = entries.filter(([, c]) => !c.pass);
        g.checks = {
            state: failed.length ? 'warn' : 'pass',
            label: `${entries.length - failed.length}/${entries.length}`,
            detail: failed.length
                ? `failing: ${failed.map(([n]) => n).join(', ')}`
                : `all ${entries.length} structural checks pass (coverage and IK are NOT among them)`,
        };
    }

    // The SURFACE gate. A region the fixture never labelled has its cleaning
    // patch GUESSED — the largest connected world-up (+Z within 25 deg) patch
    // of the whole component mesh, matched against a fabricated [0,0,1]
    // placeholder rather than any per-region or per-family normal (there is no
    // family expected normal in this codebase; see _load_meta). It can select
    // the wrong face entirely, and every other number on this strip is then
    // computed against that guess — so the caveat has to survive for as long
    // as the task is loaded, not for the 12 seconds a toast lasts.
    //
    // The verdict comes from the REGION's provenance, not from
    // `state.surfaceWarning` alone. That field only ever describes THIS
    // session's generate — loadYamlText and bindTask both clear it — so keying
    // the gate off it made every task opened from disk claim a green
    // "✓ labeled" on no evidence whatever, including a config generated months
    // ago on a guessed surface, which is precisely the case this gate exists
    // to expose. Unknown is a real answer and says so: a legacy config whose
    // region the picker no longer offers lands there by design, because after
    // the fixture-scoped picker (server.py `_region_offered`) a guessed region
    // is not in `studio.regions` at all.
    //
    // Deliberately NOT blocking: Newton's standing rule for unlabelled regions
    // is warn-don't-refuse, and `blocking` disables Deploy. This gate exists to
    // make the operator's decision informed, not to make it for them.
    const boundRegion = state.task && state.task.region;
    const boundProv = (studio.regions || []).find(r => r.key === boundRegion)?.provenance;
    if (state.surfaceWarning || (boundProv && boundProv !== 'labeled')) {
        g.surface = { state: 'warn', label: 'guessed',
            detail: state.surfaceWarning
                || `${boundRegion} is not labelled on ${(state.task && state.task.fixture) || 'this fixture'}`
                   + ' — its cleaning surface was guessed from the component mesh and may be the'
                   + ' wrong face. Paint the region on the Regions tab for a real one.' };
    } else if (boundProv === 'labeled') {
        g.surface = { state: 'pass', label: 'labeled',
            detail: 'the cleaning surface came from labelled geometry on this fixture' };
    } else {
        g.surface = { state: 'unrun', label: '',
            detail: 'not known for a task loaded from disk — regenerate to check which face this'
                  + ' path was planned on' };
    }
    return g;
}

function renderCoverageBanner(g) {
    const banner = document.getElementById('coverageBanner');
    if (!banner) return;
    const c = g.coverage;
    // Nothing computed yet says nothing — an empty banner is better than a
    // confident "0%", which reads as a task that wipes nothing.
    if (c.state === 'unrun') { banner.hidden = true; banner.textContent = ''; return; }
    banner.hidden = false;
    // A coverage number scored against a GUESSED surface is not evidence: the
    // path is planned on the guessed patch and then scored against that same
    // patch, so the measurement is self-referential. Measured, 2026-08-19:
    // commode_front on commode_c reports 100.0% at redundancy x5.15 on a patch
    // nobody ever labelled. Reporting that as a confident pass is the banner
    // telling its most convincing lie, so it says what the number is worth.
    // Follows g.surface, not `state.surfaceWarning`: a task loaded from disk
    // whose region the picker reports as unlabelled deserves the same caveat as
    // one just generated, and that field is cleared on every load.
    if (g.surface && g.surface.state === 'warn') {
        banner.dataset.state = 'warn';
        banner.textContent = `⚠ Coverage ${c.label} on a GUESSED surface — not evidence: `
            + 'the path was planned on the guessed patch and scored against that same patch. '
            + 'Label the region on the Regions tab for a real number.';
        banner.title = g.surface.detail || '';
        return;
    }
    banner.dataset.state = c.state;
    if (c.state === 'info') {
        // [N-1]: a paired task's share is not judged against the union's target
        banner.textContent = `ⓘ Coverage ${c.label} — this arm's share; the ${c.targetPct}% target is the pair's union`;
        banner.title = c.detail || '';
        return;
    }
    const met = c.state === 'pass';
    banner.textContent = `${met ? '✓' : '⚠'} Coverage ${c.label} — `
        + `${met ? `meets the ${c.targetPct ?? COVERAGE_TARGET_PCT}% target` : `below the ${c.targetPct ?? COVERAGE_TARGET_PCT}% target`}`;
    banner.title = c.detail || '';
}

function renderGates() {
    const host = document.getElementById('deployGates');
    const g = gateState();
    renderCoverageBanner(g);
    if (!host) return;
    const glyphs = { pass: '✓', warn: '△', fail: '✗', unrun: '·', info: 'ⓘ' };
    host.innerHTML = ['coverage', 'reach', 'checks', 'surface'].map(key => {
        const s = g[key];
        return `<button class="gate-chip" data-gate="${key}" data-state="${s.state}"`
             + ` title="${escapeHtml(s.detail || '')}">`
             + `${glyphs[s.state]} ${key}${s.label ? ' ' + escapeHtml(String(s.label)) : ''}</button>`;
    }).join('');

    const deployBtn = document.getElementById('finishDeployButton');
    const blocker = Object.values(g).find(s => s.blocking);
    if (deployBtn) {
        deployBtn.disabled = !state.config || Boolean(blocker);
        deployBtn.title = blocker ? blocker.detail
            : 'Write this config to the destination the server chose for it.';
    }
}

// A chip is a control, not a badge: it takes you to the thing it is judging.
function initGates() {
    const host = document.getElementById('deployGates');
    if (!host) return;
    host.addEventListener('click', event => {
        const chip = event.target.closest('.gate-chip');
        if (!chip) return;
        if (chip.dataset.gate === 'coverage') {
            // The report argument was missing here since the chip was wired —
            // focusLargestCoverageGap(undefined) early-returns on its first
            // line, so clicking this chip did nothing. Focus the LAST
            // report's largest gap; with no report yet, compute one
            // (recomputeCoverage paints + focuses when below target), so the
            // chip acts on click like its reach/checks siblings.
            if (lastCoverage?.samplePoints?.length) focusLargestCoverageGap(lastCoverage);
            else recomputeCoverage();
        }
        else if (chip.dataset.gate === 'reach') analyzeAllPoints();
        else if (chip.dataset.gate === 'checks') validateFromServer();
        // A chip takes you to the thing it judges, and the only cure for a
        // guessed surface is painting the region on the Regions tab.
        else if (chip.dataset.gate === 'surface') switchTab('regions');
    });
    renderGates();
}

async function analyzeAllPoints() {
    const btn = document.getElementById('analyzePointsButton');
    if (!state.points.length) { setStatus('No cleaning points to analyse.', true); return; }
    const pts = state.points.map(p => ({name: p.name, position: p.xyz, orientation: p.absoluteQuat || [0, 0, 0, 1]}));
    const includeCollision = document.getElementById('analyzeCollisionToggle')?.checked;
    try {
        if (btn) btn.disabled = true;
        setStatus(`Analysing ${pts.length} points${includeCollision ? ' (with collision — slower)' : ''}…`);
        const d = await api('/api/analyze-points', {method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({points: pts, tipFrame: reachTipFrame(), arm: ikArmFromFrame(),
                poleState: poleStateValue(), includeCollision,
                fixture: viewerManifest?.fixtureName, meshKeys: visibleMeshKeys(),
                ugvStandoff: effectiveTaskStandoff() ?? undefined})});
        if (d.error) { setStatus('Analysis: ' + d.error, true); return; }
        renderPointAnalysis(d);
    } catch (e) {
        setStatus('Analysis failed: ' + e.message, true);
    } finally {
        if (btn) btn.disabled = false;
    }
}

// Problems-first analysis loop: the failing-points filter turns the results
// list into a to-do list — clicking a failure focuses the point AND presents
// the fixes (align-to-normal, re-check IK) in place, no dock-hopping.
let lastAnalysis = null;
let analyzeProblemsOnly = false;
const _analysisFailing = r => !r.reachable || !r.orientationOk || r.collision;

function renderPointAnalysis(d, quiet = false) {
    lastAnalysis = d;
    renderGates();
    const byName = new Map(state.points.map((p, i) => [p.name, i]));
    // recolour every point marker by its analysis status
    state.points.forEach(p => { delete p.ikStatus; });
    const wmax = Math.max(1e-9, ...d.results.map(r => r.manipulability || 0));
    const failingCount = d.results.filter(_analysisFailing).length;
    const rowFor = r => {
        const idx = byName.get(r.name);
        const status = !r.reachable ? 'bad' : (r.orientationOk ? 'ok' : 'orient');
        if (idx != null) state.points[idx].ikStatus = status;
        const col = _hex(IK_STATUS_COLORS[status]);   // one source, not a second literal map
        const wrel = r.manipulability != null ? (r.manipulability / wmax) : 0;
        const tag = !r.reachable ? 'unreachable' : (r.orientationOk ? 'reachable' : 'pos-only');
        const w = r.manipulability != null ? `w=${r.manipulability.toFixed(4)} (${Math.round(wrel * 100)}%) · cond=${r.conditionNumber}` : '—';
        const coll = r.collision ? ` · <span style="color:var(--danger)">collision×${r.collisionFaces}</span>` : '';
        // With a generated path loaded, EVERY row here is a DERIVED cleaning
        // sample (413-444 of them), and re-orienting one is erased by the next
        // regeneration -- so the align fix is not offered on a sample. Re-check
        // stays: reading a sample is always legitimate, only re-orienting is not.
        const derivedSamples = pathGenHasKnots();
        const fixes = _analysisFailing(r) && idx != null
            ? '<div class="analyze-fixes">'
              + (derivedSamples
                    ? `<span class="hint" title="This row is one of the ${state.generate.samples.count || state.points.length} samples the generator derived from the knots. Orientation is authored on the KNOTS; an edit here would not survive a regeneration.">derived sample &mdash; re-orient the knot</span>`
                    : `<button data-fix="align" data-idx="${idx}" title="Re-derive this point's rotation from the surface normal, then re-check">Align to normal</button>`)
              + `<button data-fix="recheck" data-idx="${idx}" title="Re-run IK + collision for this point">Re-check</button></div>`
            : '';
        return `<div class="sequence-item" data-idx="${idx ?? -1}" style="cursor:pointer;border-left:3px solid ${col};padding-left:6px">
            <strong>${r.name ?? '(point)'}</strong> <span style="opacity:.7">${r.best || '—'} · ${tag}</span><br>
            <code style="font-size:11px">${w}${coll}</code>${fixes}</div>`;
    };
    const shown = analyzeProblemsOnly ? d.results.filter(_analysisFailing) : d.results;
    const list = document.getElementById('analyzeList');
    if (list) {
        list.innerHTML = shown.map(rowFor).join('')
            || (analyzeProblemsOnly ? '<div class="hint">No failing points 🎉</div>' : 'No results.');
        list.querySelectorAll('.sequence-item').forEach(el => el.addEventListener('click', () => {
            const i = Number(el.dataset.idx);
            if (i >= 0) { selectPoint(i); focusSelected(); }
        }));
        list.querySelectorAll('.analyze-fixes button').forEach(btn => btn.addEventListener('click', async event => {
            event.stopPropagation();   // don't double-trigger the row click
            const i = Number(btn.dataset.idx);
            if (i < 0) return;
            selectPoint(i);
            focusSelected();
            // Belt and braces with the markup above: the align button is not
            // rendered for a derived sample, and if one is ever reached anyway
            // it must not silently re-orient the selected KNOT instead.
            if (btn.dataset.fix === 'align' && !pathGenHasKnots()) alignSelectedToNormal();
            checkSelectedPointIK();    // live re-check (robot poses to the point)
        }));
    }
    const s = d.summary || {};
    const sum = document.getElementById('analyzeSummary');
    if (sum) {
        sum.innerHTML =
            `<div class="info-row"><span>reachable</span><code>${s.reachable}/${s.total}</code></div>` +
            `<div class="info-row"><span>min manipulability</span><code>${s.minManipulability ?? '—'}</code></div>` +
            (s.collisions ? `<div class="info-row"><span>collisions</span><code>${s.collisions}</code></div>` : '') +
            `<label class="toggle"><input id="analyzeProblemsToggle" type="checkbox"${analyzeProblemsOnly ? ' checked' : ''}>` +
            `<span>problems only (${failingCount})</span></label>`;
        document.getElementById('analyzeProblemsToggle')?.addEventListener('change', event => {
            analyzeProblemsOnly = event.target.checked;
            if (lastAnalysis) renderPointAnalysis(lastAnalysis, true);
        });
    }
    updateSceneObjects();   // repaint markers by status
    if (!quiet) setStatus(`Analysed ${s.total} points: ${s.reachable} reachable, ${s.unreachable} not${s.collisions ? `, ${s.collisions} colliding` : ''}.`);
}

async function toggleRobot(on) {
    if (on) {
        if (!(await loadRobotGeometry())) { const t = document.getElementById('showRobotToggle'); if (t) t.checked = false; return; }
        robotGroup.visible = true;
        // If a point is selected, snap the robot to its IK config.
        if (state.selectedIndex >= 0) checkSelectedPointIK();
    } else if (robotGroup) {
        robotGroup.visible = false;
    }
    renderScene();
}

function toggleCoveragePaint(on) {
    if (on) {
        if (lastCoverage && lastCoverage.samplePoints) refreshCoveragePaint();
        else { setStatus('Generate or recompute coverage first to show the coverage paint.'); if (coverageGroup) coverageGroup.visible = false; }
    } else {
        if (coverageGroup) coverageGroup.visible = false;
        renderScene();
    }
}

async function recomputeCoverage() {
    if (!studio.enabled || !studio.lastTask || !state.config) {
        setStatus('Coverage recompute needs a server-generated task.', true);
        return;
    }
    try {
        setLoading(true, 'Computing coverage…');
        const result = await api('/api/coverage', {method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({...studio.lastTask, yamlText: editedYamlText()})});
        renderCoverage(result.coverage);
        const tgt = coverageTarget();        // [N-11]: the region's target when the config carries one
        const v = coverageVerdict(result.coverage.coverage_pct, tgt, state.config, {edited: state.dirty});
        if (v.state === 'info') {
            // [N-1]: this arm's SHARE of a paired task -- the target is the union's, so no
            // "below target" is said and nothing is auto-painted (the paint toggle still shows the gaps)
            setStatus(`Coverage ${result.coverage.coverage_pct}% of this arm's share — the ${tgt.pct}% target is the `
                + 'pair\'s union (the Board\'s pair cell); turn on the coverage paint to see this share\'s gaps.');
            return;
        }
        if (v.met === false) {
            // Below the gate: auto-show the missed-face paint and land the
            // camera on the largest gap so the fix starts immediately.
            const toggle = document.getElementById('coveragePaintToggle');
            if (toggle && !toggle.checked) toggle.checked = true;
            renderCoveragePaint(result.coverage, Infinity);
            focusLargestCoverageGap(result.coverage);
            setStatus((v.scope === 'union'
                    ? `Coverage ${result.coverage.coverage_pct}% of this arm's share; the pair's recorded union ${v.judgedPct}% is below the ${tgt.pct}% region target. `
                    : `Coverage ${result.coverage.coverage_pct}% — below the ${tgt.pct}% ${tgt.fromBlock ? 'region ' : ''}target. `)
                + 'Missed areas painted red; camera centred on the largest gap.', true);
            return;
        }
        const pp = result.coverage.passesPerPoint;
        setStatus(`Coverage ${result.coverage.coverage_pct}%, redundancy ×${result.coverage.redundancy}`
            + (pp && pp.mean != null ? `, passes per point ${pp.mean}` : '')
            + (result.coverage.over_covered ? ' — over-covered (unnecessary moves).' : '.')
            + (result.coverage.over_covered_passes
                ? ` Over-passed: ${(result.coverage.overPassedShare * 100).toFixed(0)}% of the share ≥ ${result.coverage.passesTarget + 2} passes.` : ''));
    } catch (error) {
        setStatus(`Coverage failed: ${error.message}`, true);
    } finally {
        setLoading(false);
    }
}

// --- Start-pose picking (Generate tab): click the component surface to set a
// valid start_pose, so generation needs no hand-created config. ---
function parsePoseField(id) {
    const raw = (document.getElementById(id)?.value || '').trim();
    if (!raw) return null;
    // Accept space, comma and semicolon (mixed) as separators; ignore empties
    // from consecutive/leading/trailing delimiters.
    const nums = raw.split(/[\s,;]+/).filter(Boolean).map(Number);
    return (nums.length === 7 && nums.every(Number.isFinite)) ? nums : null;
}

// EE/ik_frame quaternion (base frame) with Z pressed into the surface (-normal).
function startQuatFromNormalBase(normalBase) {
    const z = vec(normalBase).normalize().multiplyScalar(-1);
    let x = Math.abs(z.x) < 0.9 ? new THREE.Vector3(1, 0, 0) : new THREE.Vector3(0, 1, 0);
    x.sub(z.clone().multiplyScalar(x.dot(z))).normalize();
    const y = new THREE.Vector3().crossVectors(z, x).normalize();
    return new THREE.Quaternion().setFromRotationMatrix(new THREE.Matrix4().makeBasis(x, y, z)).normalize();
}

function componentMeshKeyForComponent(component) {
    return componentStateMeshKey(component, defaultFixtureStates());
}

// Which FIELD PAIR a picked start pose is written into. Both now sit on the
// workbench (they were on tabs 2 and 3); these are control names, not tabs.
let pickStartTarget = 'generate';   // 'generate' (#genStartPose) | 'prestart' (#genPreStartPose) | 'edit' (pose fields)
// `placingGeneratePose` — which picked pose the gizmo is placing — is declared
// with the gizmo state at the top of the file.

// The start pose behaves like a selected point: highlighted, movable in `move`
// mode, cleared by Clear. `selectedIndex` is dropped so the two selections are
// mutually exclusive.
function selectStartPose(on) {
    state.startPoseSelected = Boolean(on);
    if (state.startPoseSelected) state.selectedIndex = -1;
    updateAll();
}

// "User should be able to see the arm at the selected pose" (Newton 2026-09-08).
// The overlay is switched ON if it is off rather than the arm silently not
// appearing: before today the arm showed only when `assistEnabled()` happened
// to be true, so the default experience of picking a start pose showed no arm
// at all. `runIK` is issued LAST so its sequence number beats any request
// `toggleRobot` fired for a previously selected point.
async function showArmAtStartPose(posBase, quatBase) {
    const toggle = document.getElementById('showRobotToggle');
    if (toggle && !toggle.checked) {
        toggle.checked = true;
        try { await toggleRobot(true); }
        catch (failure) { console.warn('[ALIX Studio] robot overlay:', failure); }
    }
    return runIK(posBase, quatBase, {label: 'start pose'});
}

// The two poses are shown as TEXT, not as raw seven-number fields. A pose is
// something the operator places on the mesh and reads back to confirm; the
// field is still there (hidden) because everything downstream reads it, and a
// second source of truth for the same value is how the two silently disagree.
function renderStartPoseTexts() {
    const fmt = id => {
        const raw = (document.getElementById(id)?.value || '').trim();
        if (!raw) return null;
        const n = raw.split(/[\s,]+/).map(Number);
        if (n.length < 3 || n.some(v => !Number.isFinite(v))) return raw;
        return `${n[0].toFixed(3)} ${n[1].toFixed(3)} ${n[2].toFixed(3)}`
             + (n.length >= 7 ? `  ·  q ${n[3].toFixed(3)} ${n[4].toFixed(3)} ${n[5].toFixed(3)} ${n[6].toFixed(3)}` : '');
    };
    const start = fmt('genStartPose');
    const pre = fmt('genPreStartPose');
    const st = document.getElementById('genStartPoseText');
    if (st) { st.textContent = start || 'not set — the generator will choose'; st.classList.toggle('set', Boolean(start)); }
    const pt = document.getElementById('genPreStartPoseText');
    if (pt) {
        // WHO decides the pre-start, in words. A placed one overrides (Newton,
        // 2026-09-15); a blank one is derived — the pipeline retreats along the
        // press normal (start orientation first, then the guided orientations)
        // and its stage-5 search picks the arm's configuration there.
        pt.textContent = pre
            ? `${pre}   (placed — used exactly where placed; refused, never moved, if blocked)`
            : 'derived by the generator — retreat along the press normal, stage-5 search for the arm';
        pt.classList.toggle('set', Boolean(pre));
    }
    const sec = document.getElementById('genStartSection');
    if (sec) sec.dataset.picking = pickingStartPose ? '1' : '0';
}

// The PRE-START, picked on the mesh. The archive says what it is: the same
// orientation, pulled straight back off the surface — 30 to 190 mm, median 69,
// and along the press axis on tops and lids, sideways on the rim and hinge
// regions (32 commode_c configs, read as historical evidence of what was
// emitted). It is a function of the start pose, the surface and the world, so
// the derived default is offered and the operator may override it here.
async function beginPickPreStartPose() {
    if (!(await beginPickStartPose())) return;
    pickStartTarget = 'prestart';
    const linked = document.getElementById('genPreStartLinked');
    if (linked) linked.checked = false;      // placing one by hand unlinks it
    setStatus('Pick the PRE-START on the surface — where the arm stands off before it comes in.');
    renderStartPoseTexts();
}

// THE TASK'S SCENE, built once and used by everything that needs it.
//
// This was the body of `beginPickStartPose`, which meant the region's surface
// appeared only when the operator pressed *Pick on mesh* — bind a fixture and a
// region and the viewport showed nothing, so there was nothing to pick on and
// no way to see whether the target was the intended one. Binding a target is
// the moment the scene is known; showing it then is what makes the panel
// reactive.
//
// The fixture-IDENTITY guard below is kept verbatim and is not a formality: a
// non-empty manifest for the WRONG fixture let a start pose be picked against
// commode_a's fused STL while commode_c was selected, and the generator then
// trusted that pose uncorrected.
async function showTaskScene() {
    const region = document.getElementById('genRegion').value;
    if (studio.enabled) {
        // Ensure the fixture meshes are loaded, then show the region's FULL task
        // surface (all spanned components, each in its cleaning pose) to pick on.
        // The old guard — `if (!viewerManifest || !viewerManifest.meshes)` —
        // could never fire. The page boots with
        // `{"refFrame":…, "regions":{}, "meshes":{}}`, and `{}` is truthy. Worse,
        // after boot the manifest is not empty but WRONG: defaultFixture is the
        // first fixture with a region manifest over a sorted walk and all three
        // commodes ship models/regions.yaml, so it is commode_a — while changing
        // #genFixture calls setFixture(v, {loadMeshes:false}), which moves
        // state.fixture and never touches viewerManifest. Picking a start pose
        // for commode_c/commode_front therefore SUCCEEDED against commode_a's
        // fused closed STL (bbox z 0–0.817 against commode_c's 0.022–0.425), and
        // the generator then trusted that pose uncorrected.
        //
        // So test IDENTITY as well as contents. `fixtureName` is a first-class
        // manifest field that the boot index manifest does not carry, which is
        // what makes this reload correctly at boot too.
        if (!viewerManifest || viewerManifest.fixtureName !== currentFixture()
                || !Object.keys(viewerManifest.meshes || {}).length) {
            await loadFixtureForRegions(currentFixture());
            // And HONOUR the result. loadFixtureForRegions returns false when
            // the paint-discard confirm is declined and undefined when the
            // fetch throws; falling through on either is exactly the silent
            // wrong pick above, so re-check the manifest itself rather than
            // trusting the call to have worked.
            if (viewerManifest?.fixtureName !== currentFixture()) {
                setStatus(`Cannot pick a start pose: ${currentFixture()} meshes are not loaded, so the `
                    + `pick would land on another fixture's surface. Open ${currentFixture()} on the `
                    + `Regions tab (saving or discarding any painted regions first), then pick again.`, true);
                return;
            }
        }
        loadMeshForRegion(region);
    }
    if (!meshObject) { setStatus('No component mesh available to pick on. Load a fixture in the Regions tab first.', true); return; }
    meshObject.visible = true;
    // The scene the TASK will run in, not the one the viewer happens to hold:
    // the fixture sits at the task's UGV standoff (`taskStandoffDeltaX`) and the
    // robot at the task's pole. Newton's screenshot had a start pose picked
    // against a scene with neither applied — a pose that looks right there can
    // be unreachable in the run, which is the whole reason to pick it visually.
    syncViewerToTask({quiet: true});
    applyMeshPlacementMode();
    // THE ROBOT, BY DEFAULT (Newton, 2026-09-09). The pole height and the UGV
    // standoff are already decided by the time a region is bound, and a start
    // pose picked against a scene without them can look reasonable and be
    // unreachable in the run. The overlay carries the whole robot — UGV, both
    // poles, the sliding plates, both hands — and the server poses the fingers
    // from the tool frame, so what is on screen is the world the reach and
    // collision tests are actually run in.
    const robotToggle = document.getElementById('showRobotToggle');
    if (robotToggle && !robotToggle.checked) {
        robotToggle.checked = true;
        try { await toggleRobot(true); }
        catch (failure) {
            // never block the pick on the overlay: the surface is what is being
            // picked, and the robot is context
            robotToggle.checked = false;
            console.warn('[ALIX Studio] robot overlay:', failure);
        }
    }
    // FRAME WHAT WAS JUST BOUND. The robot is 218 meshes tall and the fixture
    // sits beside it; on the camera the previous target left behind, the poles
    // and the hands are clipped off the top edge and the operator is asked to
    // pick a start pose on a surface they cannot see in context.
    fitCameraToScene();
    renderScene();
    return true;
}

async function beginPickStartPose() {
    if (!(await requireGenerateSession('pick a start pose for a generation'))) return false;
    if (pickStartTarget === 'prestart') cancelStartPosePick();   // restores the link if nothing was placed
    pickStartTarget = 'generate';
    if (!(await showTaskScene())) return false;
    pickingStartPose = true;
    renderStartPoseTexts();
    setStatus('Pick start pose: click the surface where the glove should start (Z presses into the surface).');
    return true;
}

// Edit tab: re-pick the start pose on the loaded mesh. Picking the start moves
// the whole (delta-based) path with it; Apply commits the new poses.
function beginEditPickStartPose() {
    pickStartTarget = 'edit';
    if (!meshObject) { setStatus('Load a config (its mesh) first to pick a start pose.', true); return; }
    pickingStartPose = true;
    meshObject.visible = true;
    setStatus('Pick start pose on the surface, then press Apply.');
}

function applyPickedStartPose(hit) {
    const posBase = arr(hit.point);
    const normalBase = hit.face.normal.clone().transformDirection(meshObject.matrixWorld).normalize();
    const quatBase = quatToArray(startQuatFromNormalBase(arr(normalBase)));
    const posRef = basePointToRef(posBase);
    const quatRef = baseQuatToRef(quatFromArray(quatBase));
    let pose = [...roundVector(posRef, 4), ...roundVector(quatToArray(quatRef), 5)];
    pickingStartPose = false;
    // A picked PRE-START starts at the START's orientation (Newton, 2026-09-15:
    // "start orientation == pre-start orientation is the starting point"), not
    // the raw face frame, which ignores the glove frame's own press axis.
    if (pickStartTarget === 'prestart' && !state.config) {
        const startNow = parsePoseField('genStartPose');
        if (startNow) pose = [...pose.slice(0, 3), ...startNow.slice(3, 7)];
    }
    // Verify the start pose with IK and POSE THE ARM THERE, always — not only
    // when `assistEnabled()` happened to be on (Newton 2026-09-08: the operator
    // must see the arm at the pose they picked).
    if (pickStartTarget === 'prestart' && !state.config) {
        runIK(refPointToBase(pose.slice(0, 3)), quatToArray(refQuatToBase(quatFromArray(pose.slice(3, 7)))),
              {label: 'pre-start', quiet: true});
    } else {
        showArmAtStartPose(posBase, quatBase);
    }
    if (state.config && pickStartTarget !== 'edit') {
        // EDIT SESSION: a move-click with the file's start marker selected moves
        // THE FILE's start pose. It used to write the Generate panel's field (a
        // generation input, while a file was open) and, before 2026-09-14,
        // cartesian_poses.start_pose too — with no undo entry, no dirty flag and
        // the delta-based points left un-re-derived.
        applyConfigStartPose(pose);
        return;
    }
    if (pickStartTarget === 'edit') {
        document.getElementById('editStartPose').value = pose.join(' ');
        document.getElementById('editPreStartPose').value = defaultPreStart(pose).join(' ');
        setStatus(`Start pose picked: ${pose.map(v => v.toFixed(3)).join(', ')}. `
            + 'Orienting the pad the generator’s way and checking…');
        // A click gives a POSITION; the face frame it also gives knows nothing
        // about the glove frame's own press axis (frame_1 presses along ±x, not
        // z). The Generate side has replaced that frame with the generator's
        // nominal orientation since 2026-09-15 and the Edit side did not, so the
        // same click produced two different orientations depending on which
        // stage the operator was in.
        editAdoptNominalOrientation(pose);
        return;
    }
    if (pickStartTarget === 'prestart') {
        document.getElementById('genPreStartPose').value = pose.join(' ');
        pickStartTarget = 'generate';
        renderStartPoseTexts();
        buildStartPoseMarker();          // the picked pre-start's glove: it had none
        renderScene();
        setStatus(`Pre-start placed: ${pose.slice(0, 3).map(v => v.toFixed(3)).join(', ')}.`
            + ' It is used EXACTLY where placed; a blocked one is refused with the reason, never replaced.');
        return;
    }
    document.getElementById('genStartPose').value = pose.join(' ');
    // Setting .value in script fires no 'change', so the linked pre_start would
    // silently keep the PREVIOUS pose — the two fields disagreeing without a
    // single edit is exactly how pre_start == start_pose came to be trusted.
    genSyncPreStart();
    // The picked pose lives in the FIELD, which is what both generators read,
    // and it is DRAWN from the field (buildPickedPoseMarkers). It used to be
    // copied into cartesian_poses.start_pose here just to get a marker — a
    // second source of truth the gizmo did not edit (the glove stayed behind
    // on a drag), and a silent overwrite of a LOADED config's start pose.
    buildStartPoseMarker();
    renderScene();
    setStatus(`Start pose set: ${pose.slice(0, 3).map(v => v.toFixed(3)).join(', ')}. `
        + 'It is used EXACTLY when every start guard passes (else the nearest designed start, and '
        + 'the result says why). Orienting the pad the generator’s way and checking…');
    genAdoptNominalOrientation(pose);
}

// A click gives a POSITION; the face frame it also gives ignores the glove
// frame's own press axis (frame_1 presses along ±x, not z) and the wipe
// convention. The generator's NOMINAL orientation at that point — the pad
// pressing along the local normal, the default wipe alignment, for the frame
// the run resolves — is taken instead, then the pose is checked by the same
// guards Verify runs. Place turns it from there.
async function genAdoptNominalOrientation(pose) {
    const field = document.getElementById('genStartPose');
    let d;
    try {
        d = await genStartCheck(pose, genPlacedPreStart());
    } catch (e) {
        if (!e.busy) {
            setStatus(`Start pose set at the face frame — the generator’s orientation could not be fetched `
                + `(${genBriefError(e.message, 90)}). Verify when the server answers.`, true);
        }
        return;
    }
    if (!field || field.value !== pose.join(' ')) return;          // the operator moved on
    const nominal = d.start && d.start.nominalPose7;
    let used = pose;
    if (Array.isArray(nominal) && nominal.length === 7) {
        used = [...pose.slice(0, 3), ...roundVector(nominal.slice(3, 7).map(Number), 5)];
        field.value = used.join(' ');
        genSyncPreStart();
        renderStartPoseTexts();
        buildStartPoseMarker();
        renderScene();
        showArmAtStartPose(refPointToBase(used.slice(0, 3)),
                           quatToArray(refQuatToBase(quatFromArray(used.slice(3, 7)))));
        try {
            d = await genStartCheck(used, genPlacedPreStart());
        } catch (e) {
            if (!e.busy) setStatus(`Start pose oriented; the check failed: ${genBriefError(e.message, 90)}`, true);
            return;
        }
    }
    const sentence = genStartCheckSentence(d);
    setStatus(`Start pose set, oriented the generator’s way for ${d.resolved.ikFrame} — ${sentence.text}.`,
              sentence.bad);
}

// The Edit stage's half of `genAdoptNominalOrientation`: same endpoint, same
// generator guards, different fields. It writes the two Edit-stage inputs and
// leaves the commit to Apply, so a pick is still one reviewable step.
async function editAdoptNominalOrientation(pose) {
    const field = document.getElementById('editStartPose');
    let d;
    try {
        d = await genStartCheck(pose, null);
    } catch (e) {
        if (!e.busy) {
            setStatus('Start pose picked at the face frame — the generator’s orientation could not '
                + `be fetched (${genBriefError(e.message, 90)}). Press Verify when the server answers.`, true);
        }
        return;
    }
    if (!field || field.value !== pose.join(' ')) return;          // the operator moved on
    const nominal = d.start && d.start.nominalPose7;
    let used = pose;
    if (Array.isArray(nominal) && nominal.length === 7) {
        used = [...pose.slice(0, 3), ...roundVector(nominal.slice(3, 7).map(Number), 5)];
        field.value = used.join(' ');
        const pre = document.getElementById('editPreStartPose');
        if (pre) pre.value = defaultPreStart(used).join(' ');
        showArmAtStartPose(refPointToBase(used.slice(0, 3)),
                           quatToArray(refQuatToBase(quatFromArray(used.slice(3, 7)))));
        renderScene();
    }
    const sentence = genStartCheckSentence(d);
    setStatus(`Start pose picked, oriented the generator’s way for ${d.resolved.ikFrame} — `
        + `${sentence.text}. Press Apply to commit.`, sentence.bad);
}

// Verify the Edit stage's start / pre-start with the SAME endpoint and the same
// generator guards the Generate panel's Verify uses. The Edit panel had none, so
// `applyEditedPoses` committed a start pose nothing had judged — and the two
// poses it writes are exactly the ones a run refuses over.
async function verifyEditedPoses() {
    const start = parsePoseField('editStartPose');
    const pre = parsePoseField('editPreStartPose');
    if (!start && !pre) {
        setStatus('Nothing to verify: neither the start nor the pre-start field holds a pose.', true);
        return;
    }
    const button = document.getElementById('editVerifyPosesButton');
    try {
        if (button) button.disabled = true;
        setStatus('Checking the start pose against the generator’s own guards…');
        const d = await genStartCheck(start, pre);
        const sentence = genStartCheckSentence(d);
        setStatus(`Start/pre-start for ${d.resolved.ikFrame} — ${sentence.text}`, sentence.bad);
    } catch (e) {
        if (!e.busy) setStatus(`The check failed: ${genBriefError(e.message, 110)}`, true);
    } finally {
        if (button) button.disabled = false;
    }
}

// Move a LOADED config's start pose (ref frame, 7 numbers) the way a point is
// moved: one undo entry, dirty, and the points re-derived — they are deltas from
// start_pose, so the path moves with it, exactly as the Edit tab's Apply does.
// The pre-start rides along RIGIDLY, so the approach it describes (its retreat
// off the surface) is kept rather than left behind at the old corner.
function applyConfigStartPose(pose) {
    const poses = activeConfigBlock()?.cartesian_poses;
    if (!poses) { setStatus('This config has no cartesian_poses to move.', true); return; }
    pushHistory();
    const old = poses.start_pose;
    const pre = poses.pre_start_pose;
    if (Array.isArray(old) && old.length === 7 && Array.isArray(pre) && pre.length === 7) {
        const turn = quatFromArray(pose.slice(3, 7)).multiply(quatFromArray(old.slice(3, 7)).invert());
        const offset = vec(pre.slice(0, 3)).sub(vec(old.slice(0, 3))).applyQuaternion(turn);
        const position = vec(pose.slice(0, 3)).add(offset);
        const orientation = turn.clone().multiply(quatFromArray(pre.slice(3, 7)));
        poses.pre_start_pose = [...roundVector(arr(position), 4),
                                ...roundVector(quatToArray(orientation), 5)];
    }
    poses.start_pose = pose.slice();
    state.points = recoverPoints(state.config);
    refreshGeneratedDeltas();
    populateEditPoseFields();
    buildStartPoseMarker();
    markDirty(true, `Start pose moved to ${pose.slice(0, 3).map(v => v.toFixed(3)).join(', ')} — `
        + 'the path and the pre-start moved with it (points are deltas from start_pose).');
    updateAll();
    renderScene();
}

// The pre-start is a RETREAT from the start along the press axis — never the
// start itself.
//
// This used to be `startPose.slice()`, i.e. pre_start == start_pose exactly,
// with a comment calling that "yaml_assembler.assemble's default". It is the
// defect the Generate side was rebuilt to prevent (Newton, 2026-09-15: a placed
// pre-start is ABSOLUTE and a derived one is a real retreat), and the server
// refuses a gap below PRE_START_MIN_OFFSET_M = 1 mm — so the Edit stage's own
// "Pre-start = start" button was seeding a value the run would reject, and
// `applyEditedPoses` wrote it into `cartesian_poses` without a check.
//
// ONE derivation now, shared with the Generate panel: the generator's own
// answer when `/api/start-pose-check` has given one for this start, else the
// same 35 mm retreat along the frame's press axis.
function defaultPreStart(startPose) {
    return genDerivedRetreat(startPose);
}

// Populate the Edit-tab start/pre-start fields from the loaded config and
// enable the controls.
function populateEditPoseFields() {
    const startEl = document.getElementById('editStartPose');
    const preEl = document.getElementById('editPreStartPose');
    const has = !!activeConfigBlock()?.cartesian_poses;
    const start = activeConfigBlock()?.cartesian_poses?.start_pose;
    const pre = activeConfigBlock()?.cartesian_poses?.pre_start_pose;
    if (startEl) startEl.value = start ? start.join(' ') : '';
    if (preEl) preEl.value = pre ? pre.join(' ') : '';
    ['editPickStartButton', 'editApplyPosesButton', 'editRetreatPreStartButton',
     'editVerifyPosesButton'].forEach(id => {
        const el = document.getElementById(id); if (el) el.disabled = !has;
    });
}

function setPreStartFromStart() {
    const start = parsePoseField('editStartPose');
    if (!start) { setStatus('Enter a valid start_pose (7 numbers) first.', true); return; }
    document.getElementById('editPreStartPose').value = defaultPreStart(start).join(' ');
    setStatus('Pre-start set to the start pose — edit it as needed, then press Apply.');
}

function applyEditedPoses() {
    if (!activeConfigBlock()?.cartesian_poses) { setStatus('No config loaded.', true); return; }
    const start = parsePoseField('editStartPose');
    const pre = parsePoseField('editPreStartPose');
    if (!start) { setStatus('start_pose must be 7 numbers: x y z qx qy qz qw.', true); return; }
    // The band the server enforces, enforced here too — otherwise the panel
    // commits a pair the run refuses and the operator finds out at Deploy. 1 mm
    // is PRE_START_MIN_OFFSET_M: a pre-start ON the start is not an approach,
    // it is the start twice.
    if (pre) {
        const gap = Math.hypot(pre[0] - start[0], pre[1] - start[1], pre[2] - start[2]);
        if (gap < PRE_START_MIN_OFFSET_M || gap > PRE_START_MAX_OFFSET_M) {
            setStatus(`pre_start_pose is ${(gap * 1000).toFixed(1)} mm from start_pose; it must be `
                + `${(PRE_START_MIN_OFFSET_M * 1000).toFixed(0)}–${(PRE_START_MAX_OFFSET_M * 1000).toFixed(0)} mm. `
                + 'A pre-start on the start is not an approach; one far away is not one either.', true);
            return;
        }
    }
    pushHistory();
    activeConfigBlock().cartesian_poses.start_pose = start;
    if (pre) activeConfigBlock().cartesian_poses.pre_start_pose = pre;
    // Cleaning points are deltas from start_pose, so re-deriving keeps them
    // pinned to the surface as the start pose moves.
    state.points = recoverPoints(state.config);
    refreshGeneratedDeltas();
    markDirty(true, 'Start / pre-start pose updated.');
    updateAll();
    renderScene();
}

// Check names are snake_case identifiers; the list reads as a sentence.
// Unknown checks fall back to their own name with the underscores opened out,
// so a new server-side check still renders as prose rather than as a token.
const CHECK_SENTENCES = {
    structure: 'point names, arrays and the anchor are well formed',
    contact_axis_harmony: 'every contact axis faces the surface',
    orientation_continuity: 'the wrist turn between waypoints stays within the limit',
    minimum_segment_length: 'no sequence edge is shorter than the minimum',
};
function _checkSentence(name) {
    return CHECK_SENTENCES[name] || String(name).replace(/_/g, ' ');
}

// WHERE a gate failed, as a sentence an operator can act on. Every field here
// is one the gate already computed and the old plumbing threw away: `GateVerdict`
// kept none of pointIndex / section / joint / stepDeg / the collision block, and
// the save path then flattened what survived into a single message string.
function genCheckWhere(check) {
    if (!check || check.ok) return '';
    const bits = [];
    if (check.pointName || Number.isFinite(check.pointIndex)) {
        bits.push(`at ${check.pointName || `point ${check.pointIndex + 1}`}`
            + (Number.isFinite(check.pointIndex) && check.pointName ? ` (index ${check.pointIndex})` : ''));
    }
    if (Number.isFinite(check.sFailM)) bits.push(`${(check.sFailM * 1000).toFixed(1)} mm along the path`);
    if (Number.isFinite(check.joint)) {
        bits.push(`joint ${check.joint}`
            + (Number.isFinite(check.stepDeg) ? ` stepping ${Number(check.stepDeg).toFixed(2)}°` : ''));
    }
    if (check.section) bits.push(`section ${check.section}`);
    const pairs = (check.collision && check.collision.pairs) || check.startBlockedBy;
    if (pairs && pairs.length) bits.push(`colliding: ${pairs.slice(0, 3).join(', ')}`);
    if (check.collision && Number.isFinite(check.collision.sM)) {
        bits.push(`first contact ${(check.collision.sM * 1000).toFixed(1)} mm in`);
    }
    return bits.join(' · ');
}

// The one-line version for the ribbon headline: the gate that refused and the
// single most locating fact about it.
function genValidationWhere(result) {
    const rows = Array.isArray(result && result.checks) ? result.checks : [];
    const first = rows.find(c => !c.ok);
    if (!first) return '';
    const site = genCheckWhere(first);
    return `${first.gate}${site ? ` — ${site}` : ''}`;
}

// An edit that changed the path makes the config's `swivel_plan` describe the OLD
// path (it is keyed to arc length, and the runtime checks the length to 1 mm).
// Validate and Deploy now derive it again for the edited path and gate THAT
// (Newton, 2026-09-17: his toplid_right sequence edit was refused on the stale
// checksum while the edited path passed every gate). The screen must then hold
// the plan that was verified, or the next Save writes the stale one back.
//
// The validation verdict is NOT invalidated by this: it was computed on exactly
// this config — the edit plus the re-derived plan — so it still describes it.
// Returns the sentence for the status line, or '' when nothing was re-derived.
function adoptRederivedPlan(rederived) {
    if (!state.config || !rederived || !rederived.swivelPlan) return '';
    state.config.swivel_plan = rederived.swivelPlan;
    const params = state.config.task_parameters || {};
    (rederived.ceilingsDropped || []).forEach(key => { delete params[key]; });
    state.dirty = true;
    document.getElementById('saveChangesButton').disabled = false;
    document.getElementById('statDirty').classList.toggle('active', true);
    renderSessionChip();
    const from = Number(rederived.fromPathLengthM);
    const to = Number(rederived.toPathLengthM);
    return `swivel plan re-derived for the edited path (${Number.isFinite(from) ? from.toFixed(4) : '?'} → `
        + `${Number.isFinite(to) ? to.toFixed(4) : '?'} m, ${rederived.knots ?? '?'} knots) — Save or Deploy writes it`;
}

async function validateFromServer() {
    if (!state.config) return;
    // Validate reads `editedYamlText()`, so an unapplied knot edit would have it
    // checking the PREVIOUS path and reporting a pass about a file the operator
    // is not looking at.
    if (genRefuseUnappliedEdits('Validating')) return;
    const headline = document.getElementById('finishResult');
    const detail = document.getElementById('finishResultDetail');
    const vBtn = document.getElementById('finishValidateButton');
    if (vBtn) vBtn.disabled = true;
    setLoading(true, 'Validating…');
    try {
        const result = await api('/api/validate', {method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({yamlText: editedYamlText(), minSegmentLength: MIN_SEGMENT_LENGTH_M})});
        // The server answers with a LIST of rows now, each naming its gate and
        // where it failed — an arc length, a point index and name, a joint and
        // its step in degrees, the colliding link pairs. It used to answer with a
        // {name: {pass, detail}} map, which had nowhere to put any of that, so a
        // gate that knew exactly where it failed reported a sentence.
        const rows = Array.isArray(result.checks) ? result.checks : [];
        lastValidation = Object.fromEntries(rows.map(c => [c.gate, {pass: c.ok, detail: c.detail}]));
        const failed = rows.filter(c => !c.ok);
        const summary = rows.map(c => `${c.ok ? '✓' : '✗'} ${c.gate}`).join('  ·  ');
        if (headline) {
            headline.textContent = result.allPass
                ? `✓ valid — ${rows.length} gates passed`
                + (result.collisionChecked ? ' (collision checked)' : '')
                : `✗ ${genValidationWhere(result) || failed.map(c => c.gate).join(', ')} — see Properties`;
            headline.classList.toggle('ok', Boolean(result.allPass));
            headline.classList.toggle('bad', !result.allPass);
        }
        if (detail) {
            detail.innerHTML =
                `<div class="val-head"><span>${rows.length - failed.length}/${rows.length} gates passed</span>`
              + `<span class="val-when">checked ${new Date().toLocaleTimeString([], {hour: '2-digit', minute: '2-digit'})}`
              + `${failed.length ? ` · ${failed.length} failing` : ' · 0 failing'}`
              + `${result.cached ? ' · cached (the config has not changed)' : ''}</span></div>`
              + rows.map(c => {
                    // A severity ICON then a full sentence. A check that passed
                    // with something to say — an advisory hold, a near-duplicate —
                    // is INFO, not silence: those are the rows an operator acts on
                    // before the run.
                    const level = !c.ok ? 'error'
                        : (c.advisoryFailed || /advisory/.test(c.gate) ? 'warn' : 'ok');
                    const glyph = {error: '⛔', warn: '⚠', ok: '✓'}[level];
                    const word = {error: 'Error', warn: 'Warning', ok: 'Pass'}[level];
                    const site = genCheckWhere(c);
                    return `<div class="val-row" data-state="${level}">`
                      + `<span class="val-glyph" aria-hidden="true">${glyph}</span>`
                      + `<span class="val-body"><span class="val-name">${word}: ${escapeHtml(c.gate)}</span>`
                      + `<span class="val-detail">${escapeHtml(String(c.detail || (c.ok ? 'ok' : 'failed')))}</span>`
                      + (site ? `<span class="val-where">${escapeHtml(site)}</span>` : '')
                      + `</span></div>`;
                }).join('');
        }
        const deployBtn = document.getElementById('finishDeployButton');
        if (deployBtn) deployBtn.classList.toggle('validated', Boolean(result.allPass));
        const adopted = result.allPass ? adoptRederivedPlan(result.rederived) : '';
        renderGates();
        setStatus(`Validation: ${summary}${adopted ? ` — ${adopted}` : ''}`, !result.allPass);
    } catch (error) {
        if (headline) { headline.textContent = `validate failed: ${error.message}`; headline.classList.add('bad'); }
        setStatus(`Validate failed: ${error.message}`, true);
    } finally {
        setLoading(false);
        if (vBtn) vBtn.disabled = false;
    }
}

async function deployToConfig() {
    if (!state.config) return;
    if (genRefuseUnappliedEdits('Deploying')) return;
    // Guard against a cross-fixture deploy: `studio.lastTask.fixture` is the
    // fixture this config was GENERATED for, recorded at generate time. Reading
    // #genFixture here instead meant that browsing another fixture mid-session
    // re-aimed Deploy at it — and because filenames carry no fixture token
    // (`regions.py: {region}_{arm}_cleaning_points.yaml`), the wrong path looks
    // entirely plausible.
    // The task's own fixture, not whatever the fixture selector shows now.
    const taskFixture = (state.task && state.task.fixture)
        || (studio.lastTask && studio.lastTask.fixture);
    const shownFixture = currentFixture();
    if (taskFixture && shownFixture && taskFixture !== shownFixture
        && !(await showStudioModal({
            title: 'Fixture mismatch',
            lines: [{ level: 'warning',
                      text: `This task was generated for ${taskFixture}, but the Generate tab now shows ${shownFixture}.` }],
            note: 'Filenames carry no fixture token, so the wrong destination looks entirely plausible.',
            confirmLabel: `Deploy as ${taskFixture}`,
        }))) {
        return;
    }
    // The destination always comes from the server now — for mechanism tasks via
    // /api/mechanism-exemplar, for cleaning tasks via /api/generate. The client
    // no longer derives the family folder itself; that is what went stale.
    // THE STROKE GATE (Newton R6, 2026-09-07). The generator proves
    // traceability BEFORE emitting; a config whose own gate refused is emitted
    // so the refusal can be read, marked `ok: false` in provenance.stroke.gate,
    // and given no destination. Deploying it anyway is a decision, so it takes
    // a destination the operator names and a confirmation that quotes the
    // refusal — never the same one press as a path that passed.
    if (state.strokeGateRefusal) {
        if (!deployOverride) {
            // The bar clamps to two lines and this sentence is ~380 characters
            // (it carries the failure class, the arc length and the detail), so
            // the full text goes on the tooltip the way the surface warning's
            // does — the reason must stay re-readable after the toast.
            const statusEl = document.getElementById('status');
            if (statusEl) statusEl.title = state.strokeGateRefusal;
            setStatus(`Deploy refused: ${state.strokeGateRefusal} Name a destination with `
                    + '“edit destination…” if you are deploying it deliberately.', true);
            return;
        }
        if (!(await showStudioModal({
                title: 'This stroke failed its own gate',
                lines: [{level: 'error', text: state.strokeGateRefusal}],
                note: 'The config is marked ok: false under provenance.stroke.gate; that '
                    + 'marker travels with the file and refuses nothing by itself.',
                confirmLabel: 'Deploy the refused stroke',
              }))) {
            return;
        }
    }
    if (!state.deployPath && !deployOverride) {
        // No invented fallback. The previous one pointed at `cleaning_tasks/`,
        // which /api/save rejects — so the default offered to the operator was
        // guaranteed to fail. Better to say why than to pre-fill a wrong answer.
        setStatus('Deploy needs a destination from the server — regenerate this '
                + 'task (or load it from its file) so the Studio knows where it belongs.', true);
        return;
    }
    // The destination is SHOWN in the task header, not typed. This used to be a
    // window.prompt pre-filled with a path the server rejects, so the terminal
    // action of the tool asked the operator to retype something before it could
    // work. Confirm what it will do; "edit destination…" stays for the rare
    // override rather than being the only way through.
    const rel = deployOverride || state.deployPath;
    // Show the GATES at the moment of committing, per the approved deploy
    // frame. A blocking gate already disables the button, but a WARNING one
    // does not — you can deploy a task at 83.8% coverage and never be told,
    // because the only place that number appears is a panel you may not have
    // open. The confirmation is the last point where saying it changes the
    // decision. Also states whether this REPLACES a file or creates one:
    // `state.loadedMtimeNs` is set only for a file the Studio actually opened.
    const gates = gateState();
    const GATE_WORD = {pass: 'OK', warn: 'WARNING', fail: 'FAILING', unrun: 'not run'};
    const GATE_CLS = {pass: 'g-ok', warn: 'g-warn', fail: 'g-bad', unrun: 'g-stale'};
    const GATE_GLYPH = {pass: '✓', warn: '⚠', fail: '⛔', unrun: '↻'};
    // `surface` is in this list because Deploy is the LAST point at which
    // knowing the path was planned on a guessed face can change the decision —
    // it is a warning gate, so nothing else stops the operator here.
    const gateChips = ['coverage', 'reach', 'checks', 'surface'].map(key => {
        const g = gates[key];
        return { cls: GATE_CLS[g.state], glyph: GATE_GLYPH[g.state], label: key,
                 val: `${GATE_WORD[g.state]}${g.label ? ' ' + g.label : ''}` };
    });
    const unrun = ['coverage', 'reach', 'checks', 'surface'].filter(k => gates[k].state === 'unrun');
    const warned = ['coverage', 'reach', 'checks', 'surface'].filter(k => gates[k].state === 'warn');
    const action = state.loadedMtimeNs != null ? 'REPLACE the existing file' : 'create a new file';
    const cautions = [
        warned.length ? { level: 'warning', text: `${warned.join(', ')} ${warned.length > 1 ? 'are' : 'is'} below target — deploying anyway.` } : null,
        unrun.length ? { level: 'warning', text: `${unrun.join(', ')} never ran, so ${unrun.length > 1 ? 'those gates say' : 'that gate says'} nothing about this task.` } : null,
    ].filter(Boolean);
    const relParts = rel.split('/');
    if (!(await showStudioModal({
        title: 'Deploy this task',
        destLabel: `Will ${action}`,
        destDir: relParts.slice(0, -1).join('/') + '/',
        destFile: relParts[relParts.length - 1],
        chips: gateChips, lines: cautions,
        note: 'Deploy is the only action in the Studio that asks. The gates above are read at this moment, not from when they last ran.',
        confirmLabel: 'Deploy',
    }))) return;
    // `deploy: true` — Deploy checks collision too (Newton, 2026-09-17: "Validate +
    // Deploy only"); a plain server save does not.
    const post = force => api('/api/save', {method: 'POST', headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({path: rel, yamlText: editedYamlText(),
                              baseMtimeNs: state.loadedMtimeNs ?? null, force, deploy: true})});
    // The file on disk is what the server VERIFIED: with a re-derived swivel plan
    // that is not the text we sent, so adopt it before calling the config clean.
    const adoptWritten = result => {
        const note = adoptRederivedPlan(result.rederived);
        if (result.yamlText) state.originalYamlText = result.yamlText;
        return note;
    };
    setLoading(true, `Deploying to ${rel} (reach, continuity and collision)…`);
    try {
        const result = await post(false);
        state.loadedMtimeNs = result.mtimeNs;
        const note = adoptWritten(result);
        markDirty(false, `Deployed to ${result.saved}.${note ? ` ${note.replace(' — Save or Deploy writes it', ' and written')}.` : ''}`);
        await maybeDeployMirroredPair(rel);
    } catch (error) {
        if (String(error.message).startsWith('CONFLICT')
            && await showStudioModal({
                title: 'File changed on disk',
                lines: [{ level: 'warning', text: error.message }],
                note: 'Someone else rewrote this file since it was loaded.',
                confirmLabel: 'Overwrite anyway', cancelLabel: 'Keep theirs',
            })) {
            try {
                const result = await post(true);
                state.loadedMtimeNs = result.mtimeNs;
                adoptWritten(result);
                markDirty(false, `Deployed to ${result.saved} (overwrote newer on-disk version).`);
                return;
            } catch (retryError) {
                setStatus(`Deploy failed: ${retryError.message}`, true);
                return;
            }
        }
        setStatus(`Deploy failed: ${error.message}`, true);
    } finally {
        // `finally`, not a trailing call: the CONFLICT branch returns from
        // inside the catch, so anything after the try/catch would be skipped
        // and the spinner would stay on for the rest of the session.
        setLoading(false);
    }
}

// Synchronized dual-arm tasks deploy as a matched *_right/*_left pair for
// dual_arm_cleaning_node (right_config/left_config). The twin is SERVER-built
// (/api/generate-mechanism): each side clones its own exemplar, and a side whose
// exemplar exists only for the other arm is mirrored there — guarded by [N-8]
// and stamped (mechanism_assembler.clone_from_exemplar). A refusal comes back as
// HTTP 422 and is shown; the twin is not written. There is no in-browser mirror.
// Compound tasks are ONE file (both arm blocks inside — lid_open.yaml shape)
// and emit nothing extra.
async function maybeDeployMirroredPair(primaryRel) {
    const sel = state.mechSelection;
    if (state.taskMode !== 'mechanism' || sel?.shape !== 'dual_sync') return;
    const twinRel = primaryRel.includes('_right') ? primaryRel.replace('_right', '_left')
        : primaryRel.includes('_left') ? primaryRel.replace('_left', '_right') : null;
    if (!twinRel) {
        setStatus('Twin not emitted: the deploy path needs _left/_right in its name.', true);
        return;
    }
    try {
        // The server clones the twin side's OWN exemplar with the SAME deltas
        // (the carried object is rigid — deltas identical, never mirrored;
        // each side keeps its calibrated start/pre-start/retract).
        const gen = await api('/api/generate-mechanism', {method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({category: sel.category, op: sel.op, shape: 'dual_sync',
                arm: sel.arm, fixture: sel.fixture,
                venue: document.getElementById('atlasVenue')?.value || undefined,
                points: state.points.map(p => ({position: p.xyz, orientation: p.absoluteQuat || [0, 0, 0, 1]}))})});
        const twin = (gen.files || []).find(f => f.path.endsWith(twinRel.split('/').pop()))
            || (gen.files || [])[1];
        if (!twin) { setStatus('Twin not emitted: server returned no pair file.', true); return; }
        const res = await api('/api/save', {method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({path: twinRel, yamlText: twin.yamlText, force: true})});
        setStatus(`Synchronized pair saved: ${primaryRel} + ${res.saved} — run via dual_arm_cleaning_node (right_config / left_config).`);
    } catch (error) {
        if (error.payload?.reflectionRefused) {
            await showMirrorRefusal(error.payload);        // [N-8]: the twin is not written
            return;
        }
        setStatus(`Twin file save failed: ${error.message}`, true);
    }
}


// ═════════════════════════════════════════════════════════════════════════════
// THE C-SPACE PATH GENERATOR — the Generate panel's second pipeline
//
// One module, in THIS file. A second classic <script> would need a
// `__GENERATE_JS__` placeholder in template.html, a `.replace()` in
// scripts/visualize_generated_config.py and its name added to the server's
// `_web_asset_stamp()` list — three files across two lanes — and editing it
// without the third would serve a STALE page silently. Worse, a top-level
// `const`/`let` in a second script that reuses any of editor.js's ~139
// top-level names is a SyntaxError that kills the whole new script at parse
// time, uncaught by the page's global error listener: the page looks normal
// and the feature is simply absent. One file, one scope, one parser.
//
// The named module surface is `window.PathGen` (assigned at the end of this
// section). The functions themselves are declared at top level rather than
// closed over inside an IIFE, because every other caller in this file — the
// Escape handler, `updateSceneObjects`, `generateFromServer` — calls its
// collaborators as bare globals, and eight wrapper functions to preserve a
// closure boundary would be more surface, not less. Every name below is
// prefixed `pathGen*` / `gen*` and was grepped against the existing top-level
// names before being added.
//
// WHAT THIS PANEL DOES NOT DO, and why:
//   * It never invents a number. `null` from the server means NOT MEASURED and
//     renders as an em-dash — never as 0, and never as a default.
//   * It shows no speed and no R*. Newton 2026-09-07 (R1/R4): the timing is
//     the runtime's ONE parameterisation and its limits are the channel's, so
//     there is no v in a task config and nothing here to evaluate `R* = c v^2`
//     at. The turn radius is the runtime's own geometry
//     (`geometric_path._size_cut`) and every readout in group C is geometric.
//   * It never writes a task config. The endpoint returns `configYaml` and the
//     server-composed `deployPath`; persistence is the existing Save/Deploy
//     click.
//   * Seconds never appear as a PATH quantity. The job's elapsed clock is the
//     job's, not the stroke's.
// ═════════════════════════════════════════════════════════════════════════════

// The eleven stages a run reports, in the order `generate` calls them. A status
// bar must never name a stage the generator does not run.
const PATHGEN_STAGES = ['surface', 'coverable', 'entry', 'layout', 'knots', 'build_path',
                        'swivel', 'emit', 'score', 'emit-config', 'gate'];
// MEASURED end to end, 2026-09-15: p10-p90 of the 31 commode_c runs of the gen6
// estate (tilt profile, anchorability gate, map and geometry ladders included;
// four runs in parallel), 36-347 s, max 478 s. A single Studio run of side_left
// took 154 s. The server sends its own range (`studio_generate.ETA_SECONDS_RANGE`);
// this is the fallback. The 2026-09-10 figure (64-83 s, four regions) predates
// every stage added since and told the operator a healthy run was overdue.
const PATHGEN_ETA_RANGE_S = [40, 350];
// Deficit of the inboard turn against the ideal, PLAN-MEASURED anchor points.
// Rendered as the nearest anchor with its radius, never interpolated into a
// number the plan did not measure.
const PATHGEN_DEFICIT_ANCHORS = [[0.0175, 0.0], [0.020, 1.2], [0.030, 13.6],
                                 [0.040, 24.8], [0.081, 48.5]];
// path_generator.NU_HUMAN_BAND is a SCALAR CEILING of 3.0 — not the 1.5-2.5
// band that appears in the literature. The panel judges nu against the code's
// ceiling and prints the literature band beside it, labelled as context, so it
// cannot invent a band the generator does not use.
const PATHGEN_NU_CEILING = 3.0;
const PATHGEN_NU_LITERATURE_BAND = [1.5, 2.5];
// constants.py:65 GLOVE_FOOTPRINT_M — the DEFAULT pad width, and only that.
// The pad is per-IK-frame (glove_frames.yaml), so every readout that can reach
// a run prefers `surface.footprintM` and names which of the two it used.
const PATHGEN_GLOVE_FOOTPRINT_W_M = 0.035;
// A run is declared LOST only after BOTH this many consecutive failed polls AND
// PATHGEN_LOST_AFTER_S of silence. Ten polls at 2 s (~20 s) alone gave up on
// Newton's runs d38b947af618 / a79878ef26fe in the entry stage, and both were
// still on the server with a real answer (Reattach found the refusal). While
// polls fail the note counts the silence and names the last error, the poll
// slows to PATHGEN_FAILING_POLL_MS, and the first answer resumes normally.
const PATHGEN_MAX_POLL_FAILURES = 10;
const PATHGEN_LOST_AFTER_S = 150;
const PATHGEN_FAILING_POLL_MS = 5000;

const pathGenJob = {timer: null, runId: null, polling: false, cancelRequested: false};
const pathGenCache = {tube: null, ghost: null, knotGeometry: null, knotMaterials: new Map()};

function pathGenState() { return state.generate; }

// Set for the duration of the ONE loadYamlText call that adopts a generated
// config; every other load drops the knots (see loadYamlText).
// `var`, not `let`, deliberately: loadYamlText is defined ~9000 lines EARLIER
// and a `let` would leave this binding in the temporal dead zone for any call
// that beat this line, throwing a ReferenceError instead of loading a file.
// Hoisted `undefined` is falsy, so the pre-initialisation answer is the SAFE
// one — drop the previous task's knots.
var genAdoptingGeneratedConfig = false;

// Drop the generated path when the workbench moves to a different task. The
// job, the dialog geometry and the parameter values are NOT dropped: they are
// the panel's own chrome, not the previous task's geometry.
function genDropGeneratedPath() {
    const generate = state.generate;
    if (!generate || (!generate.knots.length && !generate.result)) return;
    generate.knots = [];
    generate.pathWaypoints = [];
    generate.samples = {s: [], p: [], q: [], dsM: null, count: 0, pathLengthM: null};
    generate.selection.knotIndex = -1;
    generate.result = null;
    generate.reasons = [];
    generate.gate = null;
    generate.scorecard = null;
    generate.policyResolved = null;
    generate.configYaml = null;
    generate.deployPath = null;
    generate.startPose = {pose7: null, cornerTag: null, preStartLinked: true};
    generate.preview = {active: false, positions: null};
    generate.dirty = false;
    generate.stale = false;
    // The READOUTS go with the data. A coverage figure, a gate chip and seven
    // reason rows left standing over a task they were not measured on is the
    // readout-outliving-its-config defect this file has paid for before, and
    // it is exactly what loadYamlText already clears the gate verdicts for.
    ['genReasons', 'genGateChips', 'genNotesList', 'genFailure'].forEach(id => {
        const el = document.getElementById(id);
        if (el) { el.textContent = ''; el.children.length = 0; }
    });
    const failure = document.getElementById('genFailure');
    if (failure) failure.hidden = true;
    ['genTargetResolved', 'genEntryPsi', 'genStartPoseInfo'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.textContent = '\u2014 (no run for the task now on the workbench)';
    });
    const coverage = document.getElementById('genCoverageInfo');
    if (coverage) { coverage.textContent = ''; coverage.dataset.placeholder = ''; }
    genRenderCounts();
    genRenderEmptyStates();
}

// A run is live when the panel has a job id and the job has not reached a
// terminal state. Used by the Escape handler: closing the panel mid-run hides
// the only surface that says what is happening.
function pathGenJobLive() {
    const job = state.generate && state.generate.job;
    return Boolean(job && job.runId && (job.state === 'queued' || job.state === 'running'));
}

function pathGenHasKnots() {
    return Boolean(state.generate && state.generate.knots.length);
}

// Has a GENERATION actually produced a curve to draw?
//
// Both spline call sites used to ask `state.generate` / `!generate` instead —
// but `state.generate` is a permanent object literal (:79), never null, so one
// guard returned on every call and the other never took its branch. Between
// them the authored spline could not be drawn AT ALL: not on a config opened
// from disk, and not on one being edited. The panel had a Spline group, a
// visibility layer and a material, and nothing ever reached them.
function pathGenHasGeneratedCurve() {
    const g = state.generate;
    if (!g) return false;
    if (g.knots && g.knots.length) return true;
    const p = g.samples && g.samples.p;
    return Boolean(p && p.length >= 2);
}

function genNum(id) {
    const el = document.getElementById(id);
    if (!el) return null;
    const raw = String(el.value ?? '').trim();
    if (raw === '') return null;
    const value = Number(raw);
    return Number.isFinite(value) ? value : null;
}

function genStr(id) {
    const el = document.getElementById(id);
    const raw = el ? String(el.value ?? '').trim() : '';
    return raw === '' ? null : raw;
}

function genTouched(id) {
    const el = document.getElementById(id);
    return Boolean(el && el.dataset.touched === '1');
}

function genChecked(id) {
    const el = document.getElementById(id);
    return el ? Boolean(el.checked) : null;
}

// Em-dash, never zero. `null` on the wire means NOT MEASURED / not applicable,
// and a panel that renders it as 0 is a panel that lies about a missing number.
// `Number(null)` is 0, and `Number.isFinite(0)` is true — so the obvious
// `Number.isFinite(Number(x))` test admits every `null` on the wire as a
// perfectly good zero. That is the ONE failure mode this whole panel is
// written against: null means NOT MEASURED, and rendering it as 0 is worse
// than rendering nothing. Every numeric read goes through here.
function genFinite(value) {
    if (value === null || value === undefined || value === '') return null;
    const number = Number(value);
    return Number.isFinite(number) ? number : null;
}

function genFmt(value, digits, unit) {
    const number = genFinite(value);
    if (number === null) return '—';
    return `${number.toFixed(digits === undefined ? 3 : digits)}${unit ? ` ${unit}` : ''}`;
}

// The §3.1 policy, flat, exactly the wire names. ABSENT means "the generator's
// own default" — nothing here is defaulted client-side, because a knob the
// panel silently supplies is a knob the panel lies about having sent.
// The pole heights the arm base fouls the bin's lid covers at while the bin is
// STOWED, metres, margin included. A COPY of `studio_generate.STOWED_POLE_FOUL_BAND_M`,
// which is itself a copy of the orchestrator's measured band -- three copies because
// neither the panel nor taskgen may import the orchestrator (taskgen is ROS-free and
// mac-portable). `test_the_panel_names_the_same_pole_band` pins this one to the server's.
const STOWED_POLE_FOUL_BAND_M = [0.153, 0.282];

// A UI-only sentinel. It never reaches the wire: `genPolicyFromPanel` turns it
// into a `poleM` in metres.
const GEN_POLE_CUSTOM = '__custom__';

//: metres for each SRDF rung the panel offers (poles_group_states.yaml). Used
//: ONLY to warn about the foul band before a run; the generator resolves the
//: authoritative height from the SRDF itself.
const GEN_POLE_NAMED_M = {quarter_length: 0.075, half_length: 0.15,
                          three_quarter_length: 0.225, full_length: 0.30};

function genPoleIsCustom() {
    const el = document.getElementById('genPoleState');
    return Boolean(el && el.value === GEN_POLE_CUSTOM);
}

// Show the metres field only when it is the answer, and say -- BEFORE a 40-350 s
// run rather than after it -- when the chosen height cannot be run with the bin
// stowed. It checks the RESOLVED height, not just the custom one, because the
// named rung `three_quarter_length` (0.225) sits inside the band as well.
function genRenderPoleFields() {
    const custom = genPoleIsCustom();
    const field = document.getElementById('genPoleM');
    if (field) field.style.display = custom ? '' : 'none';
    const metres = custom ? genNum('genPoleM') : GEN_POLE_NAMED_M[genStr('genPoleState') || ''];
    const warn = document.getElementById('genPoleBandWarn');
    if (!warn) return;
    const lo = STOWED_POLE_FOUL_BAND_M[0], hi = STOWED_POLE_FOUL_BAND_M[1];
    const fouls = metres !== null && metres !== undefined && metres >= lo && metres <= hi;
    warn.style.display = fouls ? '' : 'none';
    if (fouls) {
        warn.textContent = `\u26a0 ${metres.toFixed(3)} m is inside the STOWED-bin foul band `
            + `${lo.toFixed(3)}\u2013${hi.toFixed(3)} m: the arm base fouls the bin lid covers `
            + `(worst \u221261.8 mm measured), and base_link moves with the pole alone, so no arm `
            + `pose avoids it. Generating is allowed \u2014 the config carries no bin state \u2014 `
            + `but this task may only be RUN with the bin deployed.`;
    }
}

function genPolicyFromPanel() {
    const policy = {};
    const put = (key, value) => { if (value !== null && value !== undefined) policy[key] = value; };
    put('ikFrame', genStr('genIkFrame'));
    put('fixtureType', genStr('genFixtureType'));
    // THE POLE, one field or the other, never both -- the server refuses a
    // request that names the height twice. `__custom__` is a UI-only sentinel:
    // what goes on the wire is `poleM`, the metres, which the generator emits as
    // the pose name `custom_length` with its value in joint_space_poses because
    // there is no SRDF rung at an arbitrary height.
    if (genPoleIsCustom()) put('poleM', genNum('genPoleM'));
    else put('poleState', genStr('genPoleState'));
    put('standoffM', genNum('genUgvStandoff'));
    // A slider always has a value, so it cannot express "let the generator
    // decide" — and for these two `null` is not a missing number, it is a
    // DIFFERENT ANSWER: row pitch falls back to the glove's own wipe width and
    // the turn radius to R* at the declared speed. Sending the slider's resting
    // position would silently overrule both. Only a slider the operator has
    // actually moved is sent.
    put('rowPitchM', genTouched('genRowPitch') ? genNum('genRowPitch') : null);
    put('blendRadiusM', genNum('genBlendRadius'));
    put('maxOffsetM', genNum('genMaxOffset'));
    put('collinearDeg', genNum('genCollinearDeg'));
    put('reversalDeg', genNum('genReversalDeg'));
    put('sampleDsM', genNum('genSampleDs'));
    // R5's ONE spacing parameter and the connection shape. Blank / (auto) send
    // NOTHING, which is how this panel says "the generator's own default" —
    // stroke_passes 2.0 and the layout's own choice between the two shapes. A
    // value typed here is an override, and it is the operator's, not ours.
    put('strokePasses', genNum('genStrokePasses'));
    put('strokeConnection', genStr('genStrokeConnection'));
    // What the pad does along each row (Newton, 2026-09-17). (region) sends
    // nothing: the region's declared action, else raster.
    put('cleaningAction', genStr('genCleaningAction'));
    put('strokeSwivelMode', genStr('genPsiPolicy') === 'designed' ? 'authored' : genStr('genPsiPolicy'));
    // The channel the stroke is authored for (Newton R3/R7). It picks the
    // TIMING mode at plan time and is never written into the config; the
    // select is populated with the server's own enum, so `track` is a value the
    // policy table declares rather than a literal this panel invented.
    put('channel', genStr('genChannel'));
    return policy;
}

function autoPathRequestBody(region) {
    const generate = state.generate;
    const body = {
        fixture: currentFixture(),
        region,
        arm: activeArm(),          // the bound task's side, not a stray toggle
        // Phase B always. It used to be derived from the contact-speed field:
        // blank meant phase A, because `config_from_generated` would otherwise
        // write 0.45 into the config. Newton 2026-09-07 (R7) removed the speed
        // from the config and reversed that refusal, and there is no field left
        // to derive a phase from. A phase-A run (map + entry + knots, no config
        // and no gate) stays available on the wire for anyone who wants it.
        phase: 'B',
        policy: genPolicyFromPanel(),
        write: false,
    };
    // The picked pose pins the entry CORNER (and with it the row direction and
    // the pad alignment). It does NOT become cartesian_poses.start_pose: the
    // pipeline anchors the start on knot 0 three stages later, because the
    // runtime refuses the 50-65 mm the entry node sits away from it.
    const picked = parsePoseField('genStartPose');
    if (picked) body.startPose = picked;
    // A PLACED pre-start overrides the one the pipeline would derive (Newton,
    // 2026-09-15). It is sent as placed; the server keeps its OFFSET from the
    // picked start and re-applies it at the knot-0 start, and refuses — with the
    // reason — rather than fall back to a derived retreat when it is blocked.
    // A linked pre-start is blank and sends nothing: the generator derives it.
    const placedPre = parsePoseField('genPreStartPose');
    const linked = document.getElementById('genPreStartLinked');
    if (picked && placedPre && !(linked && linked.checked)) body.preStartPose = placedPre;
    if (generate) generate.params = body.policy;
    return body;
}

// ── The job: start, poll, cancel ────────────────────────────────────────────
// Re-enter the poll loop for a run this client stopped watching. The run lives
// on the SERVER, not in this page: giving up on polling never cancelled it, so
// the only thing that was ever lost is the client's attention.
function genOfferReattach(runId, runLabel) {
    if (!runId) return;
    state.generate.lastLostRunId = runId;
    state.generate.lastLostLabel = runLabel || 'run';
    const btn = document.getElementById('reattachRunButton');
    if (btn) { btn.hidden = false; btn.dataset.runId = runId; }
}

// A FINISHED C-space run, taken into the workbench: the panel's result, the
// task, the emitted config as an edit session of generated output, its
// destination and its gate refusal. ONE function for Generate and Reattach —
// Reattach used to return the result to a click handler that dropped it, so a
// run that finished while the page was not watching never reached the panel.
function adoptAutoPathRun(run) {
    applyAutoPathResult(run);
    bindTask(run.region, run.arm, {silent: true});
    if (run.configYaml) {
        // THIS load is the generation's own output, so the knots it
        // was built from survive it; every other load drops them.
        genAdoptingGeneratedConfig = true;
        try {
            loadYamlText(run.configYaml, `${run.region}_${run.arm}_cleaning_points.yaml`, null, 'generated');
        } finally {
            genAdoptingGeneratedConfig = false;
        }
        // AFTER loadYamlText, which resets deployPath. The SERVER
        // decides where a generated task belongs, because the server is
        // what enforces the save roots.
        state.deployPath = run.deployPath || null;
        // ...and whether it belongs anywhere at all yet: a stroke its
        // own gate refused comes back so it can be READ (the run cost
        // 4-11 minutes), marked `ok: false` in provenance.stroke.gate,
        // with no destination. Deploy asks for an explicit destination
        // before it will write one of these.
        state.strokeGateRefusal = run.deployBlockedWhy || null;
        // Auto-verify the emitted points with the same per-point
        // machinery the Workbench's Analyze All Points uses.
        analyzeAllPoints();
    } else {
        // Phase A emits NO config, so there is nothing new to analyse —
        // running it here would paint the PREVIOUS task's verdicts over
        // a run that never produced points.
        setStatus(`Phase A complete: map, entry and knots only. No config was emitted and `
            + `no gate was run — that is what phase A is. Run phase B to emit and gate one.`);
    }
}

// One line for the top bar out of a run's error: the panel carries the account.
function genBriefError(message, limit = 160) {
    const oneLine = String(message || 'the run refused').replace(/\s+/g, ' ').trim();
    return oneLine.length > limit ? `${oneLine.slice(0, limit - 1)}…` : oneLine;
}

async function reattachToLostRun() {
    const runId = state.generate.lastLostRunId;
    if (!runId) { setStatus('No run to reattach to.', true); return; }
    const btn = document.getElementById('reattachRunButton');
    const label = state.generate.lastLostLabel;
    let answered = false;
    try {
        if (btn) btn.disabled = true;
        setStatus(`Reattaching to run ${runId}…`);
        const st = await api(`/api/auto-path-status?runId=${encodeURIComponent(runId)}`);
        answered = true;
        if (btn) btn.hidden = true;
        state.generate.lastLostRunId = null;
        if (st.state === 'failed' || st.state === 'cancelled' || st.state === 'done') {
            state.generate.job = {...(state.generate.job || {}), runId, state: st.state,
                                  progress: st.progress || null, elapsedS: st.elapsedS ?? null};
            genRenderJob();
        }
        if (st.state === 'failed') {
            // The server ANSWERED: the run is over and it refused. That is a
            // result, not a network problem — it used to be printed as
            // "Reattach failed: <the run's own error>. The server is still not
            // answering" (Newton's screenshot, 2026-09-15 15:39), a sentence
            // that sent the operator to look at the network.
            genSetFailure(st);
            const stage = st.failure && st.failure.stage ? ` at stage '${st.failure.stage}'` : '';
            setStatus(`Reattached — run ${runId} had already FAILED${stage}: ${genBriefError(st.error)}`
                + `${genPanelOnScreen() ? ' — full detail in the Generate panel.' : ''}`, true);
            return null;
        }
        if (st.state === 'cancelled') {
            genSetFailure(null);
            setStatus(`Reattached — run ${runId} had been cancelled.`);
            return null;
        }
        let run;
        if (st.state === 'done') {
            genSetFailure(null);
            run = genTerminalResult(st, label);
        } else {
            // still running: resume watching it exactly as the original loop did
            state.generate.job = {...(state.generate.job || {}), runId, state: st.state,
                                  phase: st.phase, progress: st.progress || null,
                                  pollMs: state.generate.job?.pollMs || 2000};
            genSetFailure(null);
            setStatus(`Reattached — run ${runId} is still ${st.state}.`);
            run = await pollRunUntilTerminal(label);
        }
        if (run) {
            adoptAutoPathRun(run);
            setStatus(`Reattached — run ${runId} finished; its result is in the panel.`);
        }
        return run;
    } catch (e) {
        if (e && e.payload && e.payload.state === 'failed') {
            // the resumed watch ended in a refusal: the panel has it already
            const stage = e.payload.failure && e.payload.failure.stage ? ` at stage '${e.payload.failure.stage}'` : '';
            setStatus(`Run ${runId} FAILED${stage}: ${genBriefError(e.message)}`
                + `${genPanelOnScreen() ? ' — full detail in the Generate panel.' : ''}`, true);
            return null;
        }
        // Two different failures wearing one sentence. "no such run" means the
        // server ANSWERED and has forgotten the run (it keeps only the last
        // few); anything else means it is still unreachable. Saying "the server
        // is not answering" when it just answered sends the operator to look at
        // the wrong thing.
        const forgotten = /no such run/i.test(e.message || '');
        if (forgotten) {
            setStatus(`Run ${runId} is no longer on the server — it keeps only the most recent runs. Start a new one.`, true);
            state.generate.lastLostRunId = null;
            if (btn) btn.hidden = true;
        } else if (answered) {
            setStatus(`Reattach: ${genBriefError(e.message)}`, true);
        } else {
            state.generate.lastLostRunId = runId;
            if (btn) btn.hidden = false;
            setStatus(`Reattach failed — the server did not answer (${genBriefError(e.message, 90)}). `
                + 'The run may still be going; try Reattach again.', true);
        }
    } finally {
        if (btn) btn.disabled = false;
    }
}

// A generation is MINUTES. It is started, polled every 2 s and cancelled — not
// awaited on one HTTP/1.0 socket with no request timeout.
async function runAutoPathJob(body, runLabel, route = '/api/auto-path') {
    const generate = state.generate;
    generate.job = {runId: null, state: 'queued', phase: body.phase, progress: null,
                    partials: null, startedAt: Date.now(), cancelPending: false};
    pathGenJob.cancelRequested = false;
    genSetFailure(null);
    genShowJobRow(true);
    genRenderJob();
    const started = await api(route, {
        method: 'POST', headers: {'Content-Type': 'application/json'},
        body: JSON.stringify(body)});
    generate.job.runId = started.runId || null;
    generate.job.state = started.state || 'queued';
    generate.job.pollMs = Number(started.pollMs) || 2000;
    generate.job.etaSecondsRange = started.etaSecondsRange || PATHGEN_ETA_RANGE_S;
    generate.job.cancelMayTakeUntilS = started.cancelMayTakeUntilS ?? null;
    if (!generate.job.runId) {
        // `sync: true` (the debug path) answers with the terminal status
        // payload itself rather than a run id.
        return genTerminalResult(started, runLabel);
    }
    return pollRunUntilTerminal(runLabel);
}

// THE poll loop, shared by the first watch and by Reattach. Extracted rather
// than duplicated: a second copy is how the two would drift, and this one holds
// the give-up rule, the final-answer fetch and the liveness reset.
async function pollRunUntilTerminal(runLabel) {
    const generate = state.generate;
    genSetCancelEnabled(true);
    let consecutiveFailures = 0;
    let failingSince = null;
    let lastPollError = '';
    try {
        for (;;) {
            await genSleep(consecutiveFailures >= 3
                ? Math.max(PATHGEN_FAILING_POLL_MS, Number(generate.job.pollMs) || 0)
                : generate.job.pollMs);
            let status;
            try {
                status = await api(`/api/auto-path-status?runId=${encodeURIComponent(generate.job.runId)}`);
                if (consecutiveFailures) genSetJobNote('');
                consecutiveFailures = 0;
                failingSince = null;
            } catch (error) {
                // A poll that fails is not a run that failed — the usual cause
                // is a momentary refusal while the worker holds the
                // process-wide read guard. But an unreachable server must not
                // be polled forever in silence: after PATHGEN_MAX_POLL_FAILURES
                // in a row AND PATHGEN_LOST_AFTER_S of silence the loop gives up
                // and says WHICH run it lost and the last error it saw, so the
                // operator can go and find it rather than watch a dead clock.
                consecutiveFailures += 1;
                if (failingSince === null) failingSince = Date.now();
                lastPollError = String(error.message || error);
                const silentS = Math.round((Date.now() - failingSince) / 1000);
                genSetJobNote(`no answer for ${silentS} s — poll ${consecutiveFailures} failed `
                            + `(${lastPollError}); still watching, the run lives on the server`);
                if (consecutiveFailures >= PATHGEN_MAX_POLL_FAILURES && silentS >= PATHGEN_LOST_AFTER_S) {
                    // BEFORE declaring anything, ask ONE more time. The banner
                    // used to say "lost contact ... poll /api/auto-path-status
                    // once the server answers" and then never did it itself —
                    // so a run that had FAILED with a real, actionable error
                    // (measured 2026-09-10: run 4bd7f6e23f82, `build_path`: no
                    // start pose within the approach-leg budget of knot 0, every
                    // rung refused) was reported to the operator as a network
                    // problem. The server still had the answer the whole time.
                    genSetJobNote('polls failed — asking the server once more for the final state');
                    try {
                        const last = await api(
                            `/api/auto-path-status?runId=${encodeURIComponent(generate.job.runId)}`);
                        if (last && (last.state === 'done' || last.state === 'failed'
                                     || last.state === 'cancelled')) {
                            generate.job.state = last.state;
                            generate.job.progress = last.progress || null;
                            genRenderJob();
                            return genTerminalResult(last, runLabel);
                        }
                    } catch (ignored) { /* still unreachable — fall through and say so */ }
                    genOfferReattach(generate.job.runId, runLabel);
                    throw new Error(`lost contact with the server while run ${generate.job.runId} `
                        + `was still running: no answer for ${silentS} s (last error: ${lastPollError}), `
                        + `and it did not answer a final request either. The run `
                        + `may still be going — use Reattach, or poll `
                        + `/api/auto-path-status?runId=${generate.job.runId}.`);
                }
                continue;
            }
            generate.job.state = status.state;
            generate.job.phase = status.phase || generate.job.phase;
            generate.job.progress = status.progress || null;
            generate.job.partials = status.partials || null;
            generate.job.cancelPending = Boolean(status.cancelPending);
            generate.job.cancelMayTakeUntilS = status.cancelMayTakeUntilS ?? generate.job.cancelMayTakeUntilS;
            generate.job.elapsedS = status.elapsedS ?? null;
            genRenderJob();
            if (status.state === 'done' || status.state === 'failed' || status.state === 'cancelled') {
                return genTerminalResult(status, runLabel);
            }
        }
    } finally {
        genSetCancelEnabled(false);
        // LIVENESS ENDS WITH THE LOOP, whichever way the loop ends. A run that
        // exits by THROW — the lost-contact path above — used to leave
        // `job.state` at 'running' with a runId set, so pathGenJobLive() stayed
        // true and the Escape handler refused to close ANY dialog for the rest
        // of the session, telling the operator to "use Cancel" while the line
        // above had just disabled Cancel. The advice was not available and the
        // only cure was a reload. `lost` is terminal for the CLIENT and says
        // exactly that: the client stopped watching, the server may not have
        // stopped working.
        if (generate.job.state === 'queued' || generate.job.state === 'running') {
            generate.job.state = 'lost';
            genSetJobNote(`stopped watching run ${generate.job.runId} — it may still be running. `
                        + 'Use Reattach.');
            genRenderJob();
        }
    }
}

function genTerminalResult(status, runLabel) {
    const generate = state.generate;
    generate.job.state = status.state || 'done';
    genRenderJob();
    if (status.state === 'cancelled') {
        setStatus(`${runLabel}: cancelled.`);
        return null;
    }
    if (status.state === 'failed') {
        genSetFailure(status);
        const failure = new Error(status.error || 'the generation failed');
        failure.hint = status.hint || null;
        failure.payload = status;
        throw failure;
    }
    if (!status.result) throw new Error('the run reported done with no result');
    return status.result;
}

function genSleep(ms) {
    return new Promise(resolve => setTimeout(resolve, Math.max(250, Number(ms) || 2000)));
}

// Cancel is COOPERATIVE and COARSE, and the button says so. The only hook
// inside a stage is the coverable map's node callback (every 25 nodes); the
// entry sweep is 231-289 s with no hook at all, so a cancel can sit unhonoured
// for minutes. Claiming it is instant would be the lie.
async function cancelAutoPathJob() {
    const job = state.generate.job;
    if (!job || !job.runId) return;
    pathGenJob.cancelRequested = true;
    try {
        const answer = await api('/api/auto-path-cancel', {
            method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({runId: job.runId})});
        job.cancelPending = Boolean(answer.cancelPending);
        job.cancelMayTakeUntilS = answer.mayTakeUntilS ?? job.cancelMayTakeUntilS;
        genSetJobNote(answer.note || 'cancel requested');
    } catch (error) {
        genSetJobNote(`cancel refused: ${error.message}`);
    }
    genRenderJob();
}

// ── Rendering the job ───────────────────────────────────────────────────────
function genShowJobRow(visible) {
    const row = document.getElementById('genJobRow');
    if (row) row.hidden = !visible;
}

function genSetCancelEnabled(enabled) {
    const button = document.getElementById('cancelPathButton');
    if (button) button.disabled = !enabled;
}

function genSetJobNote(text) {
    const note = document.getElementById('genJobNote');
    if (note) note.textContent = text || '';
}

function genRenderJob() {
    const job = state.generate.job;
    const stageEl = document.getElementById('genJobStage');
    const elapsedEl = document.getElementById('genJobElapsed');
    const subEl = document.getElementById('genJobSub');
    if (!stageEl || !elapsedEl || !subEl) return;
    const progress = job.progress;
    if (progress && progress.stage) {
        stageEl.textContent = `${progress.stage} (${(progress.stageIndex ?? 0) + 1} of ${progress.of ?? PATHGEN_STAGES.length}) — ${job.state}`;
    } else {
        stageEl.textContent = job.state;
    }
    const seconds = job.elapsedS ?? (job.startedAt ? (Date.now() - job.startedAt) / 1000 : 0);
    const range = job.etaSecondsRange || PATHGEN_ETA_RANGE_S;
    elapsedEl.textContent = `${Math.floor(seconds / 60)}:${String(Math.floor(seconds % 60)).padStart(2, '0')}`
        + ` of ${Math.round(range[0])}–${Math.round(range[1])} s measured`;
    // NO fake percentage. A real sub-count exists in exactly two places — the
    // coverable map's node callback and the entry screen's shortlist — and
    // during `sweep_entries` (231-289 s, half the run) nothing is observable at
    // all. That is said in words rather than drawn as a bar that is not moving
    // because nothing is measuring it.
    const sub = progress && progress.sub;
    if (sub && Number.isFinite(sub.done) && Number.isFinite(sub.total)) {
        subEl.textContent = `${sub.kind}: ${sub.done} of ${sub.total}`;
    } else if (sub && Number.isFinite(sub.done) && sub.kind) {
        subEl.textContent = `${sub.kind}: ${sub.done}`;     // a count with no honest total
    } else if (progress && progress.stage === 'entry') {
        subEl.textContent = Number.isFinite(progress.stageElapsedS)
            ? `entry sweep — ${progress.stageElapsedS.toFixed(1)} s (no finer progress inside this stage)`
            : 'entry sweep — no finer progress inside this stage';
    } else if (progress && Number.isFinite(progress.stageElapsedS)) {
        subEl.textContent = `stage elapsed ${progress.stageElapsedS.toFixed(1)} s`;
    } else {
        subEl.textContent = '';
    }
    if (job.cancelPending) {
        genSetJobNote(`cancel requested — checked between stages and every 25 lattice nodes; `
            + `during the entry sweep it may not be honoured for up to `
            + `${genFmt(job.cancelMayTakeUntilS, 0)} s`);
    }
}

// A thrown REFUSAL, rendered the same way a failed job is. `api()` carries
// `hint` and `payload` on the Error (the whole point of widening it), and
// genSetFailure is the only place that prints the hint, opens the failing
// group and puts the danger treatment on the offending field. Everything that
// throws out of a generate request comes through here so that a validation
// refusal at second 0 reads exactly like a stage failure at minute 9 — and
// neither is a bare toast that is gone in 12 s.
function genReportRequestFailure(error) {
    if (!error) return;
    const payload = error.payload || {};
    genSetFailure({
        error: error.message || payload.error || 'the request was refused',
        hint: error.hint || payload.hint || null,
        failure: payload.failure || {},
    });
}

// Is the Generate panel actually visible? The top bar's wording depends on it:
// pointing at a panel that is closed is worse than saying nothing.
function genPanelOnScreen() {
    const panel = document.getElementById('generatePanel');
    if (!panel) return false;
    if (panel.style.display === 'none' || panel.hidden) return false;
    return Boolean(panel.getClientRects().length);
}

function genSetFailure(status) {
    const box = document.getElementById('genFailure');
    if (!box) return;
    if (!status) { box.hidden = true; box.textContent = ''; return; }
    const failure = status.failure || {};
    const parts = [];
    parts.push(`FAILED — ${status.error || 'no reason reported'}`);
    if (status.hint) parts.push(`hint: ${status.hint}`);
    if (failure.stage) parts.push(`stage: ${failure.stage}`);
    if (failure.class) parts.push(`class: ${failure.class}`);
    if (failure.detail && failure.detail !== status.error) parts.push(failure.detail);
    box.textContent = parts.join('\n');
    box.hidden = false;
    // The failing GROUP opens and the offending field takes the danger
    // treatment WITH the word — never a bare toast that is gone in 12 s.
    genOpenGroupForFailure(failure.stage || '', status.error || '');
}

const PATHGEN_STAGE_GROUP = {
    surface: 'genGroupA', coverable: 'genGroupA', entry: 'genGroupE', layout: 'genGroupB',
    knots: 'genGroupD', build_path: 'genGroupD', swivel: 'genGroupE',
    emit: 'genGroupF', score: 'genGroupC', 'emit-config': 'genGroupF', gate: 'genGroupC',
};

function genOpenGroupForFailure(stage, message) {
    // The two speed regexes are gone with the speed (Newton R1/R4): there is no
    // `cleaning_line_speed_mps` to name and no `#genVTcp` to mark. A spacing
    // refusal opens the group that now owns the stroke instead.
    const id = PATHGEN_STAGE_GROUP[stage]
        || (/strokePasses|strokeConnection|pitch/i.test(message) ? 'genGroupC' : '');
    const group = id && document.getElementById(id);
    if (group) group.open = true;
    if (/strokePasses/i.test(message)) {
        const field = document.getElementById('genStrokePasses');
        if (field) field.classList.add('gen-field-danger');
    }
}

// ── The result ──────────────────────────────────────────────────────────────
function applyAutoPathResult(run) {
    const generate = state.generate;
    // Clear the empty-state placeholders FIRST. "No fixture and region bound
    // yet" sitting above a finished run's coverage numbers is the readout
    // outliving what it described, one more time.
    const coverage = document.getElementById('genCoverageInfo');
    if (coverage && coverage.dataset.placeholder === '1') {
        coverage.textContent = '';
        coverage.dataset.placeholder = '';
    }
    ['genGroupB', 'genGroupC', 'genGroupD', 'genGroupE', 'genGroupF'].forEach(id => {
        const group = document.getElementById(id);
        if (group) group.classList.remove('gen-dimmed');
    });
    generate.result = run;
    generate.policyResolved = run.policyResolved || null;
    generate.reasons = Array.isArray(run.reasons) ? run.reasons : [];
    generate.gate = run.gate || null;
    generate.scorecard = run.scorecard || null;
    generate.configYaml = run.configYaml || null;
    generate.deployPath = run.deployPath || null;
    // R6: a run whose own stroke gate REFUSED proposes no destination, and the
    // reason travels with the absence instead of leaving a blank to guess at.
    generate.deployBlockedWhy = run.deployBlockedWhy || null;
    generate.stale = false;
    generate.preview = {active: false, positions: null};
    // KNOTS and SAMPLES, as two arrays that never merge. The knots are the
    // authored geometry (8 on both measured side regions — BELOW the 20-30
    // target, not above it); the samples are 413-444 derived points that
    // nothing on this panel lets a pointer touch.
    const knots = run.knots || {};
    const poses = knots.poses || [];
    const names = knots.names || [];
    const normals = knots.normals || null;
    // The artefact's poses are in the REFERENCE frame (`alix_ref_frame`); the
    // scene, and every xyz on state.points, is the BASE frame. Storing the ref
    // numbers and drawing them with vec() would put every knot in the wrong
    // place by the whole ref-frame offset — and the error would look like a
    // plausible path, which is the worst kind. Both are kept: `xyz`/`absoluteQuat`
    // for the scene, `refPose7` for anything that writes back to a YAML.
    generate.knots = poses.map((pose, index) => ({
        name: names[index] || `k${String(index).padStart(2, '0')}`,
        refPose7: pose.slice(0, 7),
        xyz: refPointToBase(pose.slice(0, 3)),
        absoluteQuat: quatToArray(refQuatToBase(quatFromArray(pose.slice(3, 7)))),
        normal: normals && normals[index] ? normals[index] : null,
        kind: (knots.kinds || [])[index] || null,
        manualRotation: false,
        source: 'generated',
    }));
    const samples = run.samples || {};
    generate.samples = {
        s: samples.s || [],
        p: (samples.positions || []).map(xyz => refPointToBase(xyz)),
        q: samples.quats || [],
        dsM: samples.dsM ?? null, count: samples.count ?? (samples.positions || []).length,
        pathLengthM: samples.pathLengthM ?? null,
    };
    generate.selection.knotIndex = generate.knots.length ? 0 : -1;
    generate.startPose = {
        pose7: (run.startPose && run.startPose.pose7) || null,
        cornerTag: (run.entryPsi && run.entryPsi.pin && run.entryPsi.pin.corner) || null,
        source: (run.startPose && run.startPose.source) || null,
        preStartLinked: genChecked('genPreStartLinked') !== false,
    };
    // THE CHAIN IS NOT THE KNOTS. The curve the generator built starts at
    // `startPose.pose7` and then runs through the knots: MEASURED on
    // side_right, 9 waypoints, 7 corners, 0.75448 m, minimum radius 0.00978 m
    // at the START-LEG corner — while the 8 knots alone give 6 corners,
    // 0.73417 m and a minimum radius of 0.01799 m, 84 % larger. It is the
    // start-leg corner that BINDS R*, so a panel that drops it shows a
    // radius, a deviation and a turn count that disagree with the scorecard
    // printed beside them, and hides the corner that decides v_turn.
    // `result.pathWaypoints` is preferred when the server sends it; composing
    // it here is the fallback, never a second definition of the curve.
    generate.pathWaypoints = Array.isArray(run.pathWaypoints) && run.pathWaypoints.length
        ? run.pathWaypoints.map(w => ({
            name: w.name || null,
            kind: w.kind || null,
            refPose7: Array.isArray(w.pose7) ? w.pose7.slice(0, 7) : null,
            xyz: Array.isArray(w.pose7) ? refPointToBase(w.pose7.slice(0, 3)) : null,
        })).filter(w => w.xyz)
        : genComposeChain(generate);
    genRenderResolvedTarget(run);
    genRenderEntryPsi(run);
    genRenderReasons(run);
    genRenderGate(run);
    genRenderNotes(run);
    genRenderStartPose(run);
    genRenderCounts();
    updateGenReadouts();
    updateAll();
    setStatus(`Path generated: ${generate.knots.length} knots, ${generate.samples.count} samples`
        + (run.gate ? ` — gate ${run.gate.ok ? 'PASS' : `REFUSED (${run.gate.failureClass || 'unclassified'})`}` : '')
        + '. Every number on the panel is the run’s own; blanks are NOT MEASURED.');
}

function genRenderResolvedTarget(run) {
    const el = document.getElementById('genTargetResolved');
    if (!el) return;
    const surface = run.surface || {};
    const resolved = run.policyResolved || {};
    const rows = [
        `ik_frame       ${resolved.ikFrame ?? surface.ikFrame ?? '—'}`,
        `pole           ${resolved.poleState ?? surface.poleState ?? '—'} (${genFmt(resolved.poleM ?? surface.poleM, 3, 'm')})`,
        `standoff       ${genFmt(resolved.standoffM ?? surface.standoffM, 3, 'm')}`
            + (resolved.standoffClamped ? '  CLAMPED to the 0.25 m floor — the request was below it' : ''),
        `wipe yaw       ${genFmt(resolved.wipeYawDeg, 2, 'deg')} (${resolved.wipeYawSource || 'source not reported'})`,
        `turn primitive ${resolved.turnPrimitive || '—'} (stated, never offered)`,
    ];
    el.textContent = rows.join('\n');
    // The read-only fields in groups B and E carry the RESOLVED value, not the
    // request: stage 0 can override the pole state and stage 2 overwrites the
    // wipe yaw from the start pose.
    const footprint = document.getElementById('genPadFootprint');
    if (footprint && Array.isArray(surface.footprintM)) {
        footprint.value = `${surface.footprintM.map(v => Number(v).toFixed(3)).join(' \u00d7 ')} m (this run)`;
    }
    const yaw = document.getElementById('genWipeYaw');
    if (yaw) {
        yaw.value = resolved.wipeYawDeg === null || resolved.wipeYawDeg === undefined
            ? '\u2014 (not reported)'
            : `${Number(resolved.wipeYawDeg).toFixed(2)}\u00b0 \u2014 ${resolved.wipeYawSource || 'source not reported'}`;
    }
    // The gate the run's map was certified at and its source (plan/P17 L0: the
    // region's declaration, else 15, or an operator's number) -- never a stale
    // value from an earlier run and never the old fixed 20.
    const gate = document.getElementById('genGateDeg');
    if (gate) {
        const gateDeg = genFinite(resolved.singularityGateDeg);
        gate.value = gateDeg === null
            ? '\u2014 (not reported)'
            : `${gateDeg.toFixed(1)}\u00b0` + (resolved.singularityGateSource
                ? ` \u2014 ${resolved.singularityGateSource}` : '');
    }
}

// All FOUR values of the entry arm angle. The screen CHOOSES one and the
// start-at-path stage rewrites it up to three times; on the measured side_right
// they are -50.0 / -45.0 / 150.0 / 153.459 deg, so showing only the screen's
// choice is wrong by 203 degrees.
function genRenderEntryPsi(run) {
    const el = document.getElementById('genEntryPsi');
    const chip = document.getElementById('genPsiChip');
    if (!el) return;
    const psi = run.entryPsi || {};
    el.textContent = [
        `chosen at the entry node      ${genFmt(psi.chosenAtEntryNodeDeg, 3, 'deg')}`,
        `achievable at the path start  ${genFmt(psi.achievableAtPathStartDeg, 3, 'deg')}`,
        `designed psi(0) after stage 5 ${genFmt(psi.designedPsi0Deg, 3, 'deg')}`,
        `the artefact's own psi_entry  ${genFmt(psi.artefactPsiEntryDeg, 3, 'deg')}`,
        `residual                      ${genFmt(psi.residualDeg, 3, 'deg')}`,
        `designed from                 ${psi.designedFrom || '—'}`,
        `band_deg                      ${genFmt(psi.bandDeg, 1, 'deg')}`,
    ].join('\n');
    if (chip) {
        chip.textContent = `ψ ${genFmt(psi.artefactPsiEntryDeg, 1, 'deg')}`;
    }
    const notes = document.getElementById('genPsiNotes');
    if (!notes) return;
    const region = `${run.region || ''}_${run.arm || ''}`;
    const lines = [];
    if (genFinite(psi.bandDeg) !== null && genFinite(psi.bandDeg) >= 5) {
        lines.push('At this band the plan never clamps: the C++ loader’s own default is '
                 + 'kSwivelPlanDefaultBandDeg = 5.0, at which an authored plan is byte-identical to free.');
    }
    if (region === 'side_right' || region === 'seat_ring_right') {
        lines.push(`${region}: no piecewise-linear ψ has been made to work here at any window size `
                 + 'down to 40 mm (O6). This group falls back to free + a guard schedule at band_deg 10-20, '
                 + 'and is saying so rather than reporting a plan it does not have.');
    }
    notes.textContent = lines.join('\n');
}

function genRenderReasons(run) {
    const host = document.getElementById('genReasons');
    if (!host) return;
    host.textContent = '';
    (run.reasons || []).forEach(reason => {
        const box = document.createElement('div');
        box.className = 'gen-reason';
        const title = document.createElement('h4');
        title.textContent = reason.title || reason.id || 'reason';
        const value = document.createElement('div');
        value.className = 'gen-reason-value';
        value.textContent = genReasonValueText(reason);
        const rule = document.createElement('div');
        rule.className = 'gen-reason-rule';
        // The RULE that produced the number, in the server's own words. A bare
        // number with no rule is the readout this panel exists to replace.
        rule.textContent = reason.rule || '(no rule text was sent with this row)';
        box.append(title, value, rule);
        host.appendChild(box);
    });
    if (!(run.reasons || []).length) {
        host.textContent = 'The run reported no reason rows.';
    }
}

// The headline value AND the fields. Showing only the headline is how a row
// like `coverage 0.843` reaches the operator with neither denominator named —
// and both denominators are the thing that makes 0.843 mean anything.
function genReasonValueText(reason) {
    const lines = [];
    const headline = reason.value;
    if (headline !== null && headline !== undefined && typeof headline !== 'object') {
        lines.push(`= ${headline}`);
    }
    const fields = reason.fields || (typeof headline === 'object' ? headline : null) || {};
    Object.keys(fields).forEach(key => lines.push(...genFieldLines(key, fields[key], 0)));
    return lines.join('\n') || '—';
}

// One level of nesting is expanded rather than JSON-dumped: `uncoveredAreaM2`
// is a dict of AREA BY REASON, and the reasons are the answer.
function genFieldLines(key, value, depth) {
    const pad = '  '.repeat(depth);
    if (value === null || value === undefined) return [`${pad}${key.padEnd(26 - pad.length)} — (not measured)`];
    if (Array.isArray(value)) return [`${pad}${key.padEnd(26 - pad.length)} [${value.join(', ')}]`];
    if (typeof value === 'object') {
        if (depth >= 1) return [`${pad}${key.padEnd(26 - pad.length)} ${JSON.stringify(value)}`];
        const lines = [`${pad}${key}`];
        Object.keys(value).forEach(inner => lines.push(...genFieldLines(inner, value[inner], depth + 1)));
        return lines;
    }
    return [`${pad}${key.padEnd(26 - pad.length)} ${value}`];
}

function genRenderGate(run) {
    const host = document.getElementById('genGateChips');
    if (!host) return;
    host.textContent = '';
    const chip = (label, chipState) => {
        const el = document.createElement('span');
        el.dataset.state = chipState;
        el.textContent = label;
        host.appendChild(el);
    };
    const surface = run.surface || {};
    const resolved = run.policyResolved || {};
    const gate = run.gate;
    // plan/P17 L5 (review S1): a SECTIONED region comes back with NO config and NO
    // destination -- said first, in the verdict row, not only in the notes
    if (run.sectioned) {
        const sec = run.sectioned;
        chip(`SECTIONED — ${sec.of || '?'} section(s)${sec.certified ? ', a certified set' : ''}`
             + `${sec.tag ? ` (set ${sec.tag})` : ''}: no config, no deploy — a set deploys only whole`, 'bad');
    }
    // review E19 (DISPLAY ONLY): the design's L4 acceptance and the gate's clearance
    const acc = run.acceptance;
    if (acc && acc.tier) {
        chip(`design ${acc.tier}`
             + (genFinite(acc.rateDegPerM) !== null ? ` · ${genFmt(acc.rateDegPerM, 0, 'deg/m')}` : '')
             + (genFinite(acc.trackedMaxStepDeg) !== null ? ` · tracked max step ${genFmt(acc.trackedMaxStepDeg, 1, 'deg')}` : ''),
             acc.tier === 'preference' ? 'ok' : (acc.tier === 'unaccepted' ? 'bad' : 'warn'));
    }
    const clr = run.gateClearance;
    // Newton 2026-09-29 (ruling 1): the ARM + MOUNT/CAMERA links REFUSE below the region's clearance
    // floor (shown with its source); the all-links minimum -- the hands included -- stays display only
    const pairTxt = pr => (pr ? ` (${[].concat(pr).join(' / ')})` : '');
    // ON A PASS the arm/camera minimum carries its link pair and s, as Validate's row says it ("clearance floor 5 mm
    // (default): arm/camera min 5.60 mm (bin_link<->camera_link) at s = 0.000 m") -- the chip gave the figure alone
    // (2026-10-01 Studio check, "Left open" 4; test_studio_clearance_display.py)
    const floorAtTxt = () => pairTxt(clr.floorPair)
        + (genFinite(clr.floorSM) !== null ? ` at s = ${genFmt(clr.floorSM, 3, 'm')}` : '');
    const floorTxt = !clr || genFinite(clr.floorMm) === null ? ' — no clearance-floor record'
        : ` — arm/camera floor ${genFmt(clr.floorMm, 0, 'mm')} (${clr.floorSource || '?'})`
          + (clr.floorRefused
              ? `: REFUSED${genFinite(clr.floorMinMm) !== null ? ` at ${genFmt(clr.floorMinMm, 2, 'mm')}${pairTxt(clr.floorPair)}` : ''}`
              : genFinite(clr.floorMinMm) !== null ? `: held — arm/camera min ${genFmt(clr.floorMinMm, 2, 'mm')}${floorAtTxt()}`
              : clr.floorMeasured === false ? `: not checked${clr.floorWhy ? ` (${clr.floorWhy})` : ''}` : ': held');
    if (clr && genFinite(clr.mm) !== null) {
        chip(`min clearance ${genFmt(clr.mm, 1, 'mm')}`
             + pairTxt(clr.pair)
             + (genFinite(clr.sM) !== null ? ` at s = ${genFmt(clr.sM, 3, 'm')}` : '')
             + floorTxt + '; hand links display only', clr.floorRefused ? 'bad' : 'warn');
    } else if (clr && genFinite(clr.floorMinMm) !== null) {
        // a gate the floor refused measures no all-links record: the floor's own figure is the chip
        chip(`arm/camera clearance ${genFmt(clr.floorMinMm, 2, 'mm')}` + pairTxt(clr.floorPair)
             + (genFinite(clr.floorSM) !== null ? ` at s = ${genFmt(clr.floorSM, 3, 'm')}` : '')
             + ` — floor ${genFmt(clr.floorMm, 0, 'mm')} (${clr.floorSource || '?'})`
             + (clr.floorRefused ? ': REFUSED' : ': held'), clr.floorRefused ? 'bad' : 'ok');
    } else if (clr && clr.measured === false) {
        chip(`clearance not measured${clr.why ? ` (${clr.why})` : ''}` + floorTxt, 'warn');
    } else if (clr && clr.withinCutoff === false && genFinite(clr.cutoffMm) !== null) {
        chip(`min clearance ≥ ${genFmt(clr.cutoffMm, 0, 'mm')} (no non-allowed pair within the cutoff)` + floorTxt,
             clr.floorRefused ? 'bad' : 'ok');
    }
    // plan/P18 (Newton 2026-09-29), RECORDS of this generation, display only: the clearance floor the MAP admitted
    // nodes under (provenance.stroke.mapFloors) and the entry corner the stroke starts from, with the corners a
    // swivel refusal made the entry retry (provenance.stroke.entryCorner). Until 2026-10-01 nothing in Studio read
    // either (server `_p18_records_block`; test_studio_p18_records_readout.py).
    const p18 = run.p18Records || {};
    if (p18.mapFloor) {
        const m = p18.mapFloor;
        chip(`map floor ${genFmt(m.floorMm, 0, 'mm')} (${m.source || '?'}): ${m.nodesRefused ?? '?'} node(s) refused`
             + (Number(m.cellsBlocked) > 0
                 ? ` · ${m.cellsBlocked} screened cell(s) blocked`
                   + (genFinite(m.closestMm) !== null
                       ? `, closest ${genFmt(m.closestMm, 2, 'mm')}${m.closestPair ? ` (${m.closestPair})` : ''}` : '')
                 : ' · no screened cell inside the floor'),
             Number(m.nodesRefused) > 0 ? 'warn' : 'ok');
    }
    if (p18.entryCorner) {
        const e = p18.entryCorner;
        const by = {trueScore: 'the true score', maxStepDeg: 'the smallest worst step',
                    proxyKey: 'the proxy key'}[e.decidedBy] || e.decidedBy;
        chip(`entry corner ${e.corner || '?'}`
             + (genFinite(e.trueScore) !== null ? ` (true ${genFmt(e.trueScore, 3)})` : '')
             + (by ? ` · decided by ${by}` : '')
             + (e.changedByTrueScore ? ` · the true score changed it (the step rule took ${e.previousRuleWinner || '?'})` : ''),
             'ok');
    }
    if (p18.cornerRetry) {
        const r = p18.cornerRetry;
        chip(`corner retry: ${r.refusedCorner || '?'} refused at the swivel stage → `
             + (r.kept ? `kept ${r.kept}${genFinite(r.keptTrueScore) !== null ? ` (true ${genFmt(r.keptTrueScore, 3)})` : ''}`
                       : 'no remaining corner passed')
             + ` · tried ${(r.tried || []).join(', ') || '—'}`, r.kept ? 'warn' : 'bad');
    }
    if (!gate) {
        // Phase A ran the map, the entry and the knots; it did NOT emit a
        // config and did NOT gate one, because that is what phase A IS. It was
        // never about a contact speed (that refusal is reversed — Newton R7):
        // A is the cheap half of the run. A state, not a failure. (A SECTIONED
        // result has no single gate either: its chip above says why.)
        if (!run.sectioned) chip('GATE not run — phase A', 'warn');
    } else {
        chip(gate.ok ? 'GATE PASS' : `GATE REFUSED · ${gate.failureClass || 'unclassified'}`,
             gate.ok ? 'ok' : 'bad');
        if (!gate.ok && genFinite(gate.sFailM) !== null) {
            chip(`fails at s = ${genFmt(gate.sFailM, 4, 'm')}${gate.pointName ? ` (${gate.pointName})` : ''}`, 'bad');
        }
        if (genFinite(gate.singularMarginMinDeg) !== null) {
            const margin = genFinite(gate.singularMarginMinDeg);
            // The GATE the run used, never a literal 20. `singularityGateDeg`
            // is in this same payload; a hard-coded threshold still says "ok"
            // at 21 deg after the policy raised the gate to 25, which is the
            // panel deciding a verdict the server already decided. And a gate
            // that was NOT reported is not a pass — it is not judged, and says
            // so, because null rendered as ok is the failure this panel exists
            // to stop.
            const gateDeg = genFinite(resolved.singularityGateDeg);
            // Newton 2026-09-29 (ruling 2): ALONG THE STROKE the gate refuses below the 5 deg path singular floor
            // (singularity.GATE_FLOOR_DEG); the region's gate certifies the MAP's nodes, and a dip below it but above
            // the floor between them "stays recorded" (his ruling names front L 11.7 vs its declared 20). So that dip
            // is amber with the floor named -- never the red of a refusal the gate did not make (2026-10-01 check).
            const floorDeg = genFinite(run.config?.provenance?.stroke?.gate?.singularFloor?.floorDeg) ?? 5;
            const recorded = gateDeg !== null && margin < gateDeg && margin >= floorDeg;
            chip(`min singularity margin ${margin.toFixed(2)} deg`
                 + (gateDeg === null
                        ? ' — the run reported no singularityGateDeg, so this is NOT JUDGED'
                        : ` vs the run’s gate ${gateDeg.toFixed(1)} deg`)
                 + (recorded ? ` — below the map’s gate between its nodes, above the ${floorDeg} deg path singular `
                               + 'floor: recorded, not refused' : ''),
                 gateDeg === null ? 'warn' : (margin >= gateDeg ? 'ok' : (recorded ? 'warn' : 'bad')));
        }
        if (genFinite(gate.swivelTvDeg) !== null) {
            chip(`swivel tv ${genFmt(gate.designedTvDegPerM, 2, 'deg/m')}`
               + ` · reversals ${genFmt(gate.designedReversalsPerM, 3, '/m')}`, 'warn');
        }
        if (gate.headline) chip(gate.headline, gate.ok ? 'ok' : 'bad');
        // R6 turned the gate into a precondition of emission, so the refusal
        // has a CONSEQUENCE and the panel states it where the verdict is —
        // not only in the status bar, which the next message overwrites.
        if (run.deployBlockedWhy) {
            chip('no deploy destination — the gate refused this path; Deploy needs an '
               + 'explicit destination (“edit destination…”) to write it anyway', 'bad');
        }
    }
    // The CHANNEL the RUN was authored for, not the value sitting in the select:
    // the operator may have changed it since, and a chip beside a verdict must
    // describe the verdict. `channelSource` says which of the two it was. The
    // timing mode beside it is the one the policy table maps that channel to;
    // when the table could not be read it says NOT REPORTED rather than naming
    // a mode this panel guessed.
    const channel = resolved.channel || run.channel;
    const timing = resolved.timingMode;
    chip(channel
            ? `channel ${channel} (${resolved.channelSource || 'source not reported'})`
              + ` → timing ${timing || 'NOT REPORTED — the policy table was not read'}`
            : 'channel not reported by the run',
         channel ? (timing ? 'ok' : 'warn') : 'warn');
    chip(`ik_frame ${resolved.ikFrame ?? surface.ikFrame ?? '—'}`, 'warn');
    // NOT SCREENED is not the same as "nothing hit". A verdict read without
    // this chip lets reach and corridor results pass for a clearance the arm
    // was never checked against — the walls, the bin and the partner arm.
    if (resolved.includeCollision === false) {
        chip('!! collision screening OFF — reach and corridor only, NOT cleared of the walls, '
           + 'the bin or the partner arm', 'bad');
    }
}

function genRenderNotes(run) {
    const host = document.getElementById('genNotesList');
    if (!host) return;
    const notes = Array.isArray(run.notes) ? run.notes.slice() : [];
    const knotCount = (run.knots || {}).count ?? state.generate.knots.length;
    // N1: the knot budget is a CEILING, never a gate — above it is a note with
    // its reason and the run proceeds. BELOW the target needs its own sentence,
    // and it is the case that actually occurs: both measured side regions emit
    // 8 knots against a 20-30 target.
    const target = (run.policyResolved || {}).knotTarget || [20, 30];
    const alreadySaid = notes.some(note => /knot.budget/i.test(String(note)));
    if (!alreadySaid && Number.isFinite(knotCount) && knotCount < target[0]) {
        notes.unshift(`knot budget: ${knotCount} knots is BELOW the ${target[0]}-${target[1]} target. `
            + 'That is not a refusal and not an error — the structural floor is what the region’s '
            + 'own corners give, and nothing invented more.');
    }
    (run.resultWarnings || []).forEach(warning => notes.push(`WARNING — ${warning}`));
    host.textContent = notes.length ? notes.map(note => `· ${note}`).join('\n')
                                    : 'No notes reported for this run.';
}

function genRenderStartPose(run) {
    const el = document.getElementById('genStartPoseInfo');
    if (!el) return;
    const start = run.startPose || {};
    const pre = run.preStartPose || {};
    const pin = (run.entryPsi && run.entryPsi.pin) || {};
    // The pre-start's rung, in words: whose it is (placed / derived), which rung
    // passed, how far its orientation departs from the start's, and whether the
    // move_to_start line was clear. A turned or refused pre-start must never be
    // a surprise found in the YAML.
    const preLine = pre.pose7
        ? `${pre.source === 'placed' ? 'PLACED (operator)' : 'derived'} — ${pre.rung || pre.note || '—'}`
          + (pre.orientationChangeDeg ? ` · turned ${Number(pre.orientationChangeDeg).toFixed(1)}° from the start` : '')
          + (pre.refusedRungs ? ` · ${pre.refusedRungs} rung(s) refused first` : '')
        : '—';
    // THE PICK'S FATE, in words (Newton, 2026-09-15: "Exact, else fall back").
    const picked = start.pickedStart || null;
    const layoutPick = start.pickedLayout || null;
    const pickLines = [];
    if (picked && picked.used) {
        pickLines.push(`your picked start     USED EXACTLY — ${genFmt(picked.legM, 4, 'm')} leg to knot 0, `
            + `${genFmt(picked.knot0GapDeg, 1, '°')} turn into it`);
    } else if (picked) {
        pickLines.push(`your picked start     REFUSED by ${picked.refusedBy}: ${picked.why}`);
        pickLines.push(`                      the designed start is ${genFmt(1000 * Number(picked.movedM || 0), 0, 'mm')} `
            + `and ${genFmt(picked.movedDeg, 1, '°')} from it`);
    } else if (/picked start was dropped/.test(start.source || '')) {
        pickLines.push('your picked start     DROPPED before the start stage — see the map / geometry ladder');
    }
    if (layoutPick) {
        pickLines.push(`layout for the pick   knot 0 ${genFmt(layoutPick.knot0DistanceM, 4, 'm')} from it `
            + `(${layoutPick.withinApproachLeg ? 'inside' : 'OUTSIDE'} the ${genFmt(layoutPick.approachLegM, 3, 'm')} leg)`
            + (Number(layoutPick.coverageCostFraction) > 0
                ? ` · costs ${(100 * Number(layoutPick.coverageCostFraction)).toFixed(1)} % of the swept area`
                : ''));
    }
    el.textContent = [
        `entry corner pinned   ${pin.corner || '(not pinned — the screen scored all four)'}`,
        ...pickLines,
        `start_pose            ${(start.pose7 || []).map(v => Number(v).toFixed(4)).join(' ') || '—'}`,
        `source                ${start.source || '—'}`,
        `pre-start             ${preLine}`,
        `approach line         ${pre.approachLineWarning ? 'WARNING — ' + pre.approachLineWarning : (pre.approachLine || '—')}`,
        `start → knot 0        ${genFmt(start.startToKnot0M, 4, 'm')} (START_LEG_MAX_M ${genFmt(start.startLegMaxM, 3, 'm')})`,
        // THE CHAIN, stated. `result.knots` is NOT the path: the built curve is
        // start_pose followed by the knots, and its first leg carries the
        // tightest corner on both measured side regions. Anyone reading this
        // panel — or posting to /api/path-compare — needs the composition in
        // words, not a 20 mm length discrepancy to work it out from.
        `waypoints             ${(state.generate.pathWaypoints || []).length || '—'}`
            + ` = start_pose + ${state.generate.knots.length} knots.`
            + ' The START LEG is part of the curve; `knots` alone is a different,'
            + ' shorter path with one fewer corner.',
    ].join('\n');
}

function genRenderCounts() {
    const el = document.getElementById('genCounts');
    if (!el) return;
    const generate = state.generate;
    // WHICH count. One number becomes ambiguous the moment both exist.
    el.textContent = `waypoints ${(generate.pathWaypoints || []).length || '\u2014'}`
        + ` (start_pose + knots) · knots ${generate.knots.length} · samples ${generate.samples.count}`
        + ` · ds ${genFmt(generate.samples.dsM, 6, 'm')}`
        + ` · path ${genFmt(generate.samples.pathLengthM, 4, 'm')}`;
}

// ── The closed-form readouts. Client side, ZERO server calls. ───────────────
function updateGenReadouts() {
    const generate = state.generate;
    const pitch = genNum('genRowPitch') ?? 0.020;
    // The turn-radius slider was REPORTING-ONLY (path_layout: "NOT a design
    // input any more" — it only bit the `spiral` pattern, which no request can
    // select) and is gone. The radius this readout derives from is the one the
    // law actually caps with: blend_radius_m.
    const radius = genNum('genBlendRadius') ?? 0.020;
    const collinear = genNum('genCollinearDeg') ?? 10;
    const resolved = generate.policyResolved || {};

    const pitchOut = document.getElementById('genRowPitchVal');
    if (pitchOut) pitchOut.textContent = pitch.toFixed(3);

    // EVERYTHING BELOW IS GEOMETRIC. Newton 2026-09-07 (R1/R4): the speed left
    // the config, so there is no v on this panel — and with it went a_lin
    // (max(1.6, 3v + 0.01)), R_min (v²/a_lat), v_turn (sqrt(a_lat·R)) and
    // R* (c·v²). What survives is what the shape alone decides.
    const k = Math.max(1, Math.ceil((2 * radius) / pitch));
    const rGeom = (pitch * k) / 2;
    // R_cap is what this readout NAMES as the binding clamp, so it may not come
    // from a literal. The pad footprint is per-IK-frame (glove_frames.yaml) and
    // the run reports its own in `surface.footprintM`; GLOVE_FOOTPRINT_M is the
    // fallback for a panel with no run yet, and the readout says which of the
    // two it used rather than printing a clamp the operator cannot place.
    const runSurface = (generate.result && generate.result.surface) || {};
    const measuredW = Array.isArray(runSurface.footprintM) ? genFinite(runSurface.footprintM[0]) : null;
    const footprintW = measuredW === null ? PATHGEN_GLOVE_FOOTPRINT_W_M : measuredW;
    const footprintSource = measuredW === null
        ? 'the GLOVE_FOOTPRINT_M default \u2014 no run has reported a pad yet'
        : 'this run\u2019s pad';
    // Border lap was a legacy-raster knob (this pipeline takes an overlap
    // FRACTION, not a seam width) and is gone with it, so the cap is the bare
    // half-pad — the conservative of the two it used to switch between.
    const lap = false;
    const rCap = lap ? footprintW : footprintW / 2;
    // Name the binding clamp — a clamped radius with no name is a number the
    // operator cannot act on. The requested radius is what is clamped now:
    // there is no speed-derived R* to clamp any more.
    let binding = 'the requested R (neither clamp binds)';
    if (radius < rGeom) binding = `R_geom = pitch·k/2 = ${rGeom.toFixed(4)} m`;
    else if (radius > rCap) binding = `R_cap = ${lap ? 'w' : 'w/2'} = ${rCap.toFixed(4)} m`;

    const turn = document.getElementById('genTurnReadouts');
    if (turn) {
        turn.textContent = [
            `law     R = min(blend_radius_m, max_offset_m / (sec(φ/2) − 1), 0.45 · min(seg_in, seg_out))`
                + '  — the RUNTIME’s own geometry (geometric_path._size_cut). No speed: there is none in the config.',
            `binding ${binding}`,
            `k       ${k} = ceil(2R / pitch)   ·   R_geom ${rGeom.toFixed(4)} m   ·   R_cap ${rCap.toFixed(4)} m`
                + ` (pad w ${footprintW.toFixed(4)} m from ${footprintSource})`,
            `deficit ${genDeficitText(radius, lap, footprintW)}`,
            `passes  ${genPassesText()}`,
            'topology inboard — outboard is retired; an inboard turn whose backtrack'
                + ' exceeds osc_tol_m becomes a STOP, which the generator decides, not the panel.',
            `nu      ${genNuText()}`,
        ].join('\n');
    }
    const rows = document.getElementById('genRowsReadout');
    if (rows) {
        // The LATTICE row pitch above and the LAYOUT's pitch are two different
        // numbers (0.065 nominal -> 0.068 -> 0.065 effective was measured), and
        // the layout's pair lives on the `pitch` reason row, not in the policy.
        const layout = ((state.generate.reasons || [])
            .find(reason => reason.id === 'pitch') || {}).fields || {};
        rows.textContent = `k ${k} · lattice row pitch ${pitch.toFixed(3)} m`
            + ` · layout pitch_nominal → pitch_effective `
            + `${genFmt(layout.pitch_nominal_m, 4, 'm')} → ${genFmt(layout.pitch_effective_m, 4, 'm')}`
            + ` · rows ${layout.n_rows ?? '—'} (two different pitches, on purpose)`;
    }
    // The sampling law, prominently: it is a GENERATOR SETTING, not a
    // diagnostic. 2 sin(10 deg / 2) = 0.174311.
    const lawCoeff = 2 * Math.sin((collinear * Math.PI / 180) / 2);
    const ds = lawCoeff * radius;
    const spline = document.getElementById('genSplineReadouts');
    if (spline) {
        spline.textContent = [
            `ds <= 2 R sin(collinear/2) = ${lawCoeff.toFixed(6)} R = ${(ds * 1000).toFixed(3)} mm at R = ${(radius * 1000).toFixed(1)} mm`,
            `chord error = ds² / (8R) = ${((ds * ds) / (8 * radius) * 1000).toFixed(4)} mm`,
            `points per turn ~ ${Math.max(1, Math.round(360 / collinear / 2))}`,
            `samples this run ${generate.samples.count || '—'} `
                + '(the legacy DEFAULT_MAX_POINTS = 250 cap does NOT apply to this pipeline)',
        ].join('\n');
    }
}

// `footprintW` is the RUN's pad width where one has been reported (see
// updateGenReadouts): the free-radius boundary is w with the lap and w/2 bare,
// and a literal 0.035 here made the same claim about a per-frame pad that R_cap
// made — the two must agree, and they agree by sharing the one number.
function genDeficitText(radius, lap, footprintW) {
    const width = genFinite(footprintW) === null ? PATHGEN_GLOVE_FOOTPRINT_W_M : footprintW;
    const free = lap ? width : width / 2;
    if (radius <= free) return `0.0 % at R <= ${(free * 1000).toFixed(1)} mm ${lap ? 'with the lap' : 'bare'}`;
    // Nearest PLAN-MEASURED anchor, quoted as an anchor. Interpolating between
    // them would print a figure the plan never measured.
    let best = PATHGEN_DEFICIT_ANCHORS[0];
    PATHGEN_DEFICIT_ANCHORS.forEach(anchor => {
        if (Math.abs(anchor[0] - radius) < Math.abs(best[0] - radius)) best = anchor;
    });
    return `~${best[1].toFixed(1)} % (nearest measured anchor, R = ${(best[0] * 1000).toFixed(1)} mm)`;
}

// Replaces `genSavingText`, which reported the inboard turn's cost saving as a
// function of a_lin — a SPEED quantity, and there is no speed on this panel any
// more (Newton R1/R4). What the operator can still act on is the spacing: the
// pitch the passes-per-point they typed implies, against the pitch the run
// actually laid the rows at.
function genPassesText() {
    const resolved = state.generate.policyResolved || {};
    const asked = genNum('genStrokePasses');
    const used = genFinite(resolved.strokePasses);
    const shape = resolved.strokeConnection || genStr('genStrokeConnection') || '(the layout chooses)';
    const action = resolved.cleaningAction || genStr('genCleaningAction') || '(the region\u2019s, else raster)';
    const layout = ((state.generate.reasons || [])
        .find(reason => reason.id === 'pitch') || {}).fields || {};
    const passes = used === null ? asked : used;
    return `${asked === null ? '(generator default)' : asked}`
         + (used === null ? '' : ` · run used ${used}`)
         + ` · connection ${shape}`
         + ` · action ${action}`
         + ` · pitch = pad swath / passes → ${genFmt(layout.pitch_nominal_m, 4, 'm')} nominal`
         + `, ${genFmt(layout.pitch_effective_m, 4, 'm')} effective`
         + (passes === null ? '' : '');
}

function genNuText() {
    // The generator ships its own ceiling; read it rather than the constant
    // above whenever a run has reported one.
    const ceiling = genFinite((state.generate.policyResolved || {}).nuHumanBandCeiling);
    const shipped = ceiling === null ? PATHGEN_NU_CEILING : ceiling;
    const reasons = state.generate.reasons || [];
    const row = reasons.find(reason => reason.id === 'knots');
    const fields = (row && (row.fields || row.value)) || {};
    // TWO nu values over TWO different populations — the knot polyline's
    // interior waypoints, and the emitted curve against the coverable map.
    // They are close on the measured regions and that is not a reason to print
    // one of them unlabelled.
    const human = fields.humanLikeness || {};
    const sweep = fields.sweepEfficiency || {};
    const nu = genFinite(human.nu);
    const ceilingText = `generator ceiling ${genFinite(human.humanBandNu) === null ? shipped : human.humanBandNu}`
        + ` · literature band ${PATHGEN_NU_LITERATURE_BAND[0]}–${PATHGEN_NU_LITERATURE_BAND[1]} (context, not a gate)`
        + ` · legacy corpus median ${genFmt(human.legacyCorpusMedianNu, 2)}`;
    if (nu === null) {
        return `— (measured from a run’s corners; ${ceilingText})`;
    }
    const sweepNu = genFinite(sweep.nu);
    // THREE states, not two. `withinHumanBand === undefined/null` is NOT
    // MEASURED; rendering it as "within the ceiling" is exactly the null-as-a-
    // pass this panel is written against, and it is the state that actually
    // occurs (the server sends the flag one level down on some payloads).
    const verdict = human.withinHumanBand === false ? 'ABOVE the ceiling'
        : human.withinHumanBand === true ? 'within the ceiling'
        : 'NOT JUDGED — the run reported no withinHumanBand';
    return `${nu.toFixed(3)} over ${human.population || fields.nuPopulation || 'an unnamed population'}`
         + (sweepNu === null ? ''
             : ` · ${sweepNu.toFixed(3)} over ${sweep.population || 'a second, unnamed population'}`)
         + ` · ${ceilingText}`
         + ` · ${verdict} — `
         + 'reported and minimised, never gated';
}

// ── The three scene layers ─────────────────────────────────────────────────
// splineTube over the SAMPLES, ghostPolyline over the KNOTS, knot markers as
// the ONLY pickable geometry. Never THREE.Line for the spline: buildPathLine
// asks for `linewidth: 2` and gets 1 px on ANGLE, and the fat-line addon is not
// vendored. `atlasTubeRibbon` is preferred over THREE.TubeGeometry because it
// keeps an EXACT station-to-waypoint mapping — TubeGeometry resamples by arc
// length, which is precisely the knot/sample correspondence that must not be
// lost — and it parallel-transports, so the tube does not spin about its axis.
// ── The authored config's own spline ───────────────────────────────────────
// `pathLine` draws the CHORDS between waypoints. The runtime runs a G2 curve
// with a rounded fillet at every corner, so the chords hide every fillet and
// hide which corners the blend radius binds. The samples come from
// /api/path-compare, whose PathParams defaults are documented as "the shipped
// runtime's" (geometric_path.py:244), so what is drawn is the curve the robot
// builds and not an approximation of it.
function authorSplineKey(points) {
    return points.map(point => point.xyz.map(v => v.toFixed(6)).join(',')
                               + '|' + (point.absoluteQuat || []).map(v => v.toFixed(6)).join(','))
                 .join(';');
}

function buildAuthorSplineLayer() {
    const positions = state.authorSpline.positions;
    if (!positions || positions.length < 2) return;
    const points = positions.map(xyz => vec(xyz));
    const tint = new THREE.Color(colors.spline);
    const mesh = new THREE.Mesh(atlasTubeRibbon(points, SPLINE_TUBE_R, points.map(() => tint), 8),
                                pathGenTubeMaterial('spline'));
    mesh.userData.pathGenLayer = 'spline';
    mesh.name = `authored path — G2 curve the runtime builds, ${positions.length} samples`
        + ' (the straight chords beside it are the waypoint polyline)';
    pathGenGroup.add(mesh);
}

// Fire-and-forget from updateSceneObjects. Keyed on the posed chain, so moving
// a point re-asks and everything else does not; `pending` stops a second call
// while one is in flight.
async function refreshAuthorSpline() {
    if (pathGenHasGeneratedCurve()) return;  // the generate flow carries its own samples
    const points = orderedSequencePoints().filter(p => p && p.xyz && p.absoluteQuat);
    if (points.length < 2) {
        state.authorSpline = {positions: null, quats: null, key: '', pending: false, error: null};
        return;
    }
    const key = authorSplineKey(points);
    if (key === state.authorSpline.key || state.authorSpline.pending) return;
    state.authorSpline.pending = true;
    try {
        const data = await api('/api/path-compare', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                points: points.map(point => ({name: point.name, position: point.xyz,
                                              orientation: point.absoluteQuat})),
                constructions: ['geometric'],
                reports: ['grid'],
            }),
        });
        const samples = data && data.byConstruction && data.byConstruction.geometric
            ? data.byConstruction.geometric.samples : null;
        // Keep the quaternions too. They were being thrown away, which is why
        // the animation had nothing to follow but the knots.
        state.authorSpline = {positions: (samples && samples.positions) || [],
                              quats: (samples && samples.quats) || [], key,
                              pending: false, error: null};
    } catch (failure) {
        // Keep the chords and say why ONCE. A refusal here means the curve
        // cannot be built on this chain (duplicate consecutive waypoints, a
        // decimated chain), which is itself worth knowing — a silent fallback
        // to straight lines is how the chords came to be read as the path.
        state.authorSpline = {positions: [], quats: [], key, pending: false,
                              error: failure.message || String(failure)};
        console.warn('path-compare refused the authored chain:', failure.message,
                     failure.hint || '');
    }
    buildPathGenLayers();
    applyPathGenLayerVisibility();   // a freshly built layer obeys its toggle at once
    renderScene();
}

// The spline and the polyline are separate objects with separate toggles
// (Newton 2026-09-10). `pathGenGroup` still gates them both — it carries the
// authoring rule — but WITHIN it each layer answers to its own checkbox:
// 'spline' to Spline, 'ghost' (the chords) and 'knot' to Path.
function applyPathGenLayerVisibility() {
    if (!pathGenGroup) return;
    const splineOn = document.getElementById('showSplineToggle')?.checked ?? true;
    const pathOn = document.getElementById('showPathToggle')?.checked ?? true;
    pathGenGroup.traverse(child => {
        const layer = child.userData && child.userData.pathGenLayer;
        if (!layer) return;
        child.visible = layer === 'spline' ? splineOn : pathOn;
    });
}

function buildPathGenLayers() {
    if (!pathGenGroup) return;
    pathGenReleaseLayers();
    const generate = state.generate;
    // No GENERATE state: this is a config opened from disk, so the layer to
    // draw is the same spline over the authored points (buildAuthorSplineLayer).
    // It goes in `pathGenGroup` rather than beside it because that group is
    // already registered in all three visibility owners; a second scene child
    // would be a fourth place to forget.
    if (!pathGenHasGeneratedCurve()) { buildAuthorSplineLayer(); return; }
    const preview = generate.preview.active ? generate.preview.positions : null;
    const samplePositions = preview || generate.samples.p;
    if (samplePositions && samplePositions.length >= 2) {
        const points = samplePositions.map(xyz => vec(xyz));
        const tint = new THREE.Color(preview ? colors.selected : colors.spline);
        // atlasTubeRibbon returns a GEOMETRY, not a mesh (see its callers in
        // the atlas). Vertex colours, because that is what it writes.
        const mesh = new THREE.Mesh(atlasTubeRibbon(points, SPLINE_TUBE_R, points.map(() => tint), 8),
                                    pathGenTubeMaterial('spline'));
        mesh.userData.pathGenLayer = 'spline';
        mesh.name = preview ? 'generated path (PREVIEW — the knots moved)' : 'generated path (samples)';
        pathGenGroup.add(mesh);
    }
    const knots = generate.knots;
    // The ghost is drawn over the CHAIN, start pose first — that leg is a real
    // segment of the built curve and its corner is the one that binds R* on
    // both measured side regions. Drawing only the knots left the tightest
    // corner on the path invisible.
    const chain = genChainPositions();
    if (chain.length >= 2) {
        const ghost = chain.map(xyz => vec(xyz));
        const tint = new THREE.Color(colors.companion);
        const mesh = new THREE.Mesh(atlasTubeRibbon(ghost, POLYLINE_TUBE_R, ghost.map(() => tint), 4),
                                    pathGenTubeMaterial('ghost'));
        mesh.userData.pathGenLayer = 'ghost';
        mesh.name = `waypoint polyline before the fillets — ${chain.length} waypoints: `
            + `start_pose then ${knots.length} knots`;
        pathGenGroup.add(mesh);
    }
    // The knot markers, and NOTHING ELSE, are hit-tested. A sample-level view
    // is a readout — a count, a strip — not geometry a pointer can grab.
    knots.forEach((knot, index) => {
        const selected = index === generate.selection.knotIndex;
        const marker = new THREE.Mesh(pathGenKnotGeometry(selected),
                                      pathGenKnotMaterial(selected));
        marker.position.copy(vec(knot.xyz));
        marker.userData.knotIndex = index;
        marker.userData.pathGenLayer = 'knot';
        pathGenGroup.add(marker);
    });
}

// REMOVE without disposing — THREE.Group.clear(), the same primitive
// updateSceneObjects uses on pointGroup, and the reason markerGeometry /
// markerMaterial work at all. clearGroup() here ran disposeObject over every
// child, which called geometry.dispose() AND material.dispose() on the SHARED
// cached tube/ghost materials, the cached knot SphereGeometry and the cached
// unselected knot materials — and then handed those very objects straight back
// out of the cache. Since this runs from updateSceneObjects inside updateAll,
// ~30 times a second while an arrow key repeats (the code's own justification
// for the caches), it forced a shader teardown and rebuild plus a full geometry
// re-upload on every one of those frames, and the caches bought nothing.
// Only what THIS refresh allocated — the two tube geometries — is disposed.
function pathGenReleaseLayers() {
    pathGenGroup.children.forEach(child => {
        const layer = child.userData.pathGenLayer;
        if ((layer === 'spline' || layer === 'ghost') && child.geometry) child.geometry.dispose();
    });
    pathGenGroup.clear();
}

// Two shared materials, allocated once. The GEOMETRY is rebuilt per refresh
// (the curve changes), but a material per rebuild is the same leak the marker
// caches exist to stop — updateAll() runs ~30 times a second while an arrow key
// repeats.
function pathGenTubeMaterial(layer) {
    if (!pathGenCache.tube) {
        pathGenCache.tube = new THREE.MeshBasicMaterial({vertexColors: true});
        pathGenCache.ghost = new THREE.MeshBasicMaterial({vertexColors: true, transparent: true, opacity: 0.55});
    }
    return layer === 'ghost' ? pathGenCache.ghost : pathGenCache.tube;
}

// Cached exactly the way markerGeometry/markerMaterial are: updateAll() runs
// ~30 times a second while an arrow key repeats, and a tube plus N markers
// allocated per frame is the leak those caches were written to stop.
function pathGenKnotGeometry(selected) {
    const key = selected ? 'sel' : 'plain';
    if (!pathGenCache.knotGeometry) pathGenCache.knotGeometry = new Map();
    if (!pathGenCache.knotGeometry.has(key)) {
        pathGenCache.knotGeometry.set(key, new THREE.SphereGeometry(selected ? 0.010 : 0.006, 14, 10));
    }
    return pathGenCache.knotGeometry.get(key);
}

function pathGenKnotMaterial(selected) {
    // The selected POINT marker must allocate its own material because
    // `flagOccludedSelection` sets depthTest = false on it IN PLACE and a
    // cached material would carry that mutation into the next rebuild. That
    // hazard does not reach here: MEASURED, flagOccludedSelection indexes
    // `pointGroup.children` only (editor.js, `function flagOccludedSelection`)
    // and never touches pathGenGroup, and no other code mutates a knot
    // material. So the selected knot is cached too — with the group now
    // .clear()ed rather than disposed, a per-refresh material would be an
    // unreferenced allocation ~30 times a second and nothing would free it.
    const base = selected ? colors.selected : STATE_COLOR.reachDot;
    const key = `${selected ? 'sel' : 'plain'}:${base}`;
    if (!pathGenCache.knotMaterials.has(key)) {
        pathGenCache.knotMaterials.set(key, new THREE.MeshStandardMaterial(
            {color: base, emissive: base, emissiveIntensity: selected ? 0.45 : 0.25}));
    }
    return pathGenCache.knotMaterials.get(key);
}

// The chain the generator actually built: waypoint 0 is the START POSE, then
// every knot in order. Composed here only when the server did not send
// `pathWaypoints` itself. Both halves are in the SCENE (base) frame; the ref
// pose7 is kept beside them because anything writing back to a YAML needs it.
function genComposeChain(generate) {
    const chain = [];
    const start = generate.startPose && generate.startPose.pose7;
    if (Array.isArray(start) && start.length >= 3) {
        chain.push({name: 'start_pose', kind: 'startLeg', refPose7: start.slice(0, 7),
                    xyz: refPointToBase(start.slice(0, 3))});
    }
    generate.knots.forEach(knot => chain.push({name: knot.name, kind: knot.kind || 'knot',
                                               refPose7: knot.refPose7 || null, xyz: knot.xyz}));
    return chain;
}

// The positions the ghost polyline and the drag preview both draw. One helper,
// because a preview drawn over a DIFFERENT chain from the ghost is two curves
// claiming to be one.
function genChainPositions() {
    const generate = state.generate;
    const chain = generate.pathWaypoints;
    if (Array.isArray(chain) && chain.length >= 2 && !generate.dirty) return chain.map(w => w.xyz);
    // Dirty (a knot moved): recompose from the CURRENT knots, keeping the start
    // pose in front — the start leg does not move when a knot does.
    return genComposeChain(generate).map(w => w.xyz);
}

// ── Knot selection: the §4.4 rebinding, on the knots only ──────────────────
// The RULE: anything that can delete, move or re-orient a path point operates
// on KNOTS. Anything that merely reports may show samples, as text or as a
// strip, never as something a pointer can grab.
function selectKnot(index) {
    const generate = state.generate;
    if (!generate.knots.length) { generate.selection.knotIndex = -1; return; }
    // The clamp the point path already has and the knot path needs: without it
    // arrowing past the last knot silently selects nothing.
    generate.selection.knotIndex = clamp(index, 0, generate.knots.length - 1);
    updateAll();
}

function focusSelectedKnot() {
    const knot = state.generate.knots[state.generate.selection.knotIndex];
    if (!knot) return false;
    controls.target.copy(vec(knot.xyz));
    controls.update();
    requestRender();
    return true;
}

function deleteSelectedKnot() {
    const generate = state.generate;
    const index = generate.selection.knotIndex;
    if (index < 0 || !generate.knots[index]) return false;
    // A spline needs at least two knots, and this one is filleted, so a
    // two-knot path has no corner left to round. Refuse rather than produce a
    // shape the generator could not have made. MIN_BAND_POINTS is the BAND's
    // floor and does not apply here.
    if (generate.knots.length <= 3) {
        setStatus(`Refusing: ${generate.knots.length} knots is the floor for a filleted spline `
                + '(2 for the curve, a third for a corner to round). Regenerate instead.', true);
        return true;
    }
    pushHistory();
    const removed = generate.knots.splice(index, 1)[0];
    generate.selection.knotIndex = Math.min(index, generate.knots.length - 1);
    genMarkKnotsDirty(`${removed.name} deleted from the knot chain.`);
    return true;
}

function moveSelectedKnot(hit) {
    const generate = state.generate;
    const knot = generate.knots[generate.selection.knotIndex];
    if (!knot) return false;
    pushHistory();
    knot.xyz = snapHitPoint(hit);
    knot.normal = hitNormal(hit);
    knot.manualRotation = true;
    knot.source = 'mesh';
    knot.refPose7 = [...basePointToRef(knot.xyz),
                     ...quatToArray(baseQuatToRef(quatFromArray(knot.absoluteQuat || [0, 0, 0, 1])))];
    genMarkKnotsDirty(`${knot.name} moved.`);
    return true;
}

// Insert a knot at the nearest SEGMENT of the chain, not at the end. The knot
// order IS the stroke order, so appending would move the new knot to after the
// last one wherever it was clicked. Returns true when it owned the gesture.
function insertKnotFromHit(hit) {
    const generate = state.generate;
    const knots = generate.knots;
    if (knots.length < 2) return false;
    const point = vec(snapHitPoint(hit));
    let best = 0;
    let bestDistance = Infinity;
    for (let i = 0; i + 1 < knots.length; i++) {
        const a = vec(knots[i].xyz);
        const b = vec(knots[i + 1].xyz);
        const ab = b.clone().sub(a);
        const denominator = ab.lengthSq();
        const t = denominator < 1e-12 ? 0 : clamp(point.clone().sub(a).dot(ab) / denominator, 0, 1);
        const distance = a.clone().addScaledVector(ab, t).distanceTo(point);
        if (distance < bestDistance) { bestDistance = distance; best = i; }
    }
    pushHistory();
    const inserted = {
        name: `k${String(knots.length).padStart(2, '0')}i`,
        xyz: arr(point),
        absoluteQuat: (knots[best].absoluteQuat || [0, 0, 0, 1]).slice(),
        normal: hitNormal(hit),
        manualRotation: false,
        source: 'mesh',
    };
    inserted.refPose7 = [...basePointToRef(inserted.xyz),
                         ...quatToArray(baseQuatToRef(quatFromArray(inserted.absoluteQuat)))];
    knots.splice(best + 1, 0, inserted);
    generate.selection.knotIndex = best + 1;
    genMarkKnotsDirty(`${inserted.name} inserted between ${knots[best].name} and `
        + `${knots[best + 2] ? knots[best + 2].name : 'the end'}. The curve is NOT re-fitted here — `
        + 're-run the generation to refit the fillets and resample.');
    return true;
}

// Any input change invalidates the verdict. It routes through the existing
// staleness path — a second invalidation mechanism is how two of them come to
// disagree.
function genMarkKnotsDirty(message) {
    const generate = state.generate;
    generate.dirty = true;
    generate.stale = true;
    // The samples are DERIVED. They belonged to the last server answer, and
    // that answer no longer describes these knots, so they are dropped rather
    // than left on screen as a curve through points that have moved.
    generate.samples = {s: [], p: [], q: [], dsM: null, count: 0, pathLengthM: null};
    generate.gate = null;
    // The chain is composed FROM the knots, so it follows them immediately —
    // otherwise the waypoint count on screen describes the previous shape.
    generate.pathWaypoints = genComposeChain(generate);
    // PREVIEW, not a stale answer. The curve on screen is now the client's own
    // polyline through the moved knots; every number that described the server's
    // curve is HIDDEN rather than left on screen describing a path that no
    // longer exists.
    // The preview is the same CHAIN the ghost draws — start pose then knots —
    // so the two never disagree about which curve is on screen.
    generate.preview = {active: true, positions: generate.pathWaypoints.map(w => w.xyz)};
    genHideNumbersForPreview();
    genRenderCounts();
    genRenderStaleness();
    genApplyRowVisible();
    // ONE invalidation mechanism. markDirty(true, …) already calls
    // invalidateValidation(); a second call here would be a second path to the
    // same state, and two of those disagreeing is the defect that rule exists
    // to prevent.
    markDirty(true, message);
    updateAll();
}

// Hidden, never stale. The alternative — leaving the last run's coverage,
// gate and reason rows on screen beside a curve they were not measured on — is
// the readout-outliving-its-config defect this app has already paid for once.
function genHideNumbersForPreview() {
    const reasons = document.getElementById('genReasons');
    if (reasons) {
        reasons.textContent = 'PREVIEW — the knots have moved. Every measured number is hidden '
            + 'rather than shown against a curve it was not measured on. Re-run to get them back.';
    }
    const chips = document.getElementById('genGateChips');
    if (chips) chips.textContent = '';
    ['genTargetResolved', 'genEntryPsi', 'genStartPoseInfo'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.textContent = '— (preview: not measured for these knots)';
    });
}

function genRenderStaleness() {
    const chips = document.getElementById('genGateChips');
    if (!chips || !state.generate.stale) return;
    const chip = document.createElement('span');
    chip.dataset.state = 'warn';
    chip.textContent = '!! STALE — the knots changed since this verdict';
    chips.prepend(chip);
}

// ── Applying a knot edit ───────────────────────────────────────────────────
// Moving a knot changed the PICTURE and not the FILE: `knot.refPose7` had no
// reader outside the viewport, so an edit lit the dirty dot, armed Deploy, and
// `editedYamlText()` then wrote the original 400-odd samples. It could not be
// fixed by splicing the samples either — they are the emitted points BETWEEN
// the knots, and a spliced set has no swivel plan, no pre-start seed and no
// gate. So the edit goes back to the generator, which re-runs from the knots
// and re-gates what comes out.
function genApplyRowVisible() {
    const row = document.getElementById('genApplyRow');
    if (!row) return;
    const editable = pathGenHasKnots() && Boolean(state.generate.job.runId);
    row.hidden = !(editable && state.generate.dirty);
    const note = document.getElementById('genApplyNote');
    if (note && !row.hidden) {
        note.textContent = 'the config still holds the previous samples until you apply';
    }
}

async function applyKnotEdits() {
    const generate = state.generate;
    if (!pathGenHasKnots()) {
        setStatus('There are no generated knots to apply.', true);
        return;
    }
    const runId = generate.job.runId;
    if (!runId) {
        setStatus('This path has no run behind it any more, so its knots cannot be re-authored. '
            + 'Generate again, or edit the points and press Validate.', true);
        return;
    }
    const region = (state.task && state.task.region) || document.getElementById('genRegion')?.value;
    const body = autoPathRequestBody(region);
    body.reauthorOf = runId;
    // The WHOLE path, in order — never a diff. One list says move, add, delete
    // and reorder identically, and it cannot describe an edit the viewport is
    // not showing.
    body.knots = generate.knots.map(knot => ({
        pose7: knot.refPose7,
        // An orientation the operator turned by hand is THEIRS and is carried
        // through; one they did not is re-taken from the rotation the map
        // certified at the knot's new position, tilt and all. A rebuilt-from-
        // normal rotation is not the same rotation — that is the q4 = 10.9 vs
        // 23.9 deg failure in KnotLane's own docstring.
        manualRotation: Boolean(knot.manualRotation),
    }));
    const missing = body.knots.findIndex(k => !Array.isArray(k.pose7) || k.pose7.length !== 7);
    if (missing >= 0) {
        setStatus(`Knot ${missing + 1} has no pose to send — re-generate this path.`, true);
        return;
    }
    const button = document.getElementById('genApplyKnotsButton');
    try {
        if (button) button.disabled = true;
        const run = await runAutoPathJob(body, `Re-authoring ${body.knots.length} knots`,
                                         '/api/auto-path-reauthor');
        if (!run) return;                      // cancelled; runAutoPathJob said so
        adoptAutoPathRun(run);
        generate.dirty = false;
        generate.stale = false;
        const edit = run.knotEdit || {};
        const moved = edit.moved || 0;
        const delta = (edit.knotsAfter || 0) - (edit.knotsBefore || 0);
        setStatus(`Re-authored: ${moved} knot(s) moved`
            + (delta ? `, ${Math.abs(delta)} ${delta > 0 ? 'added' : 'deleted'}` : '')
            + `. ${run.gate && run.gate.ok ? 'The stroke gate PASSED.' : 'The stroke gate REFUSED — see the panel.'}`
            + (edit.coverageStale ? ' Coverage is the pre-edit sweep.' : ''));
    } catch (error) {
        genReportRequestFailure(error);
        setStatus(`Applying the knot edits failed: ${String(error.message || error)}`, true);
    } finally {
        if (button) button.disabled = false;
        genApplyRowVisible();
        updateAll();
    }
}

// ── Start pose: pick, then PLACE with the gizmo that already exists ────────
// `resolveRotateTarget` already returns {kind:'start', allowMove:true} on the
// workbench, and the panel lives on that exact tab — so "place" is: move mode,
// start target. Shift already snaps 5 mm / 5 deg; X already flips the frame.
async function placePickedStartPose() {
    if (!(await requireGenerateSession('place the generation start pose'))) return;
    if (!parsePoseField('genStartPose')) {
        setStatus('Pick a start pose on the mesh first — there is nothing to place.', true);
        return;
    }
    placingGeneratePose = 'start';       // the gizmo edits the PICKED pose, not the config's
    setMode('move');
    setRotateTarget('start');
    updatePoseGizmo();
    setStatus('Start pose: drag to move, rings to rotate. Shift snaps 5 mm / 5 deg. Edits land immediately.');
}

async function placePickedPreStartPose() {
    if (!(await requireGenerateSession('place the generation pre-start'))) return;
    // Placing a pre-start by hand means it is no longer the derived retreat, so
    // say so by unlinking rather than letting the next start edit silently
    // overwrite what was just placed. A linked pre-start has no pose on the
    // client (the generator derives it), so placing starts FROM the start pose.
    const linked = document.getElementById('genPreStartLinked');
    if (!parsePoseField('genPreStartPose')) {
        if (!parsePoseField('genStartPose')) {
            setStatus('No pre-start to place — pick a start pose first, or pick a pre-start on the mesh.', true);
            return;
        }
        if (linked) linked.checked = false;
        onGenPreStartLinkedChange();          // seeds it at the start pose
    } else if (linked && linked.checked) {
        linked.checked = false;
        genSyncPreStart();
    }
    placingGeneratePose = 'prestart';
    setMode('move');
    setRotateTarget('prestart');
    updatePoseGizmo();
    renderStartPoseTexts();
    setStatus('Pre-start: drag the gizmo back off the surface, the rings to rotate. Edits land immediately.'
        + ' A placed pre-start overrides the derived one; if it is blocked the run is refused with the reason.');
}

// ONE action for BOTH poses (Newton 2026-09-10). Picking and dragging already
// commit on the spot, so what the operator wants from it is whether the poses
// are USABLE — and since 2026-09-15 that is answered by the GENERATOR'S OWN
// start guards (`/api/start-pose-check`), for the ik_frame, pole and standoff
// the run resolves. It used to read `r.ok` from /api/ik, which returns
// `reachable` and never `ok`, so it said "start NOT reachable" for every pose
// while the arm overlay — posed from the same reply — snapped to it (Newton's
// screenshot, 2026-09-15 15:37). The arm is still posed at the start: that is
// the picture; the verdict is the generator's.
function genPlacedPreStart() {
    return genChecked('genPreStartLinked') ? null : parsePoseField('genPreStartPose');
}

function genStartCheckBody(start, pre) {
    const policy = {};
    const put = (key, value) => { if (value !== null && value !== undefined && value !== '') policy[key] = value; };
    put('ikFrame', genStr('genIkFrame'));
    // Verify has to resolve the pole the RUN will resolve -- a check at a
    // different arm-base height is a check of a different robot.
    if (genPoleIsCustom()) put('poleM', genNum('genPoleM'));
    else put('poleState', genStr('genPoleState'));
    put('standoffM', genNum('genUgvStandoff'));
    put('fixtureType', genStr('genFixtureType'));
    const body = {fixture: currentFixture(), region: document.getElementById('genRegion')?.value,
                  arm: activeArm(), policy};
    if (start) body.startPose = start;
    if (pre) body.preStartPose = pre;
    return body;
}

async function genStartCheck(start, pre) {
    const d = await api('/api/start-pose-check', {method: 'POST', headers: {'Content-Type': 'application/json'},
                                                   body: JSON.stringify(genStartCheckBody(start, pre))});
    state.generate.lastStartCheck = {...d, forStart: start ? start.join(' ') : null};
    genSyncViewerToResolved(d.resolved);
    genRenderStartCheck(d);
    return d;
}

// THE ARM IS DRAWN WITH THE HAND THE RUN WILL USE. With the Generate panel's
// frame and pole at (auto) the viewer kept its own (glove_frame_2 at
// full_length in a fresh session) while the run resolved L_glove_frame_1 at
// quarter_length, so the overlay posed a different hand at a different pole
// height from the one the start was being judged for. `syncViewerToTask`
// already follows an EXPLICIT choice; the check's `resolved` answers (auto).
function genSyncViewerToResolved(resolved) {
    if (!resolved) return;
    const moved = [];
    const follow = (selectId, value, taskFieldId) => {
        const to = document.getElementById(selectId);
        if (!to || !value) return;
        if (genStr(taskFieldId)) return;                    // an explicit task choice already rules the viewer
        if (![...(to.options || [])].some(o => o.value === value) || to.value === value) return;
        to.value = value;
        to.dispatchEvent(new Event('change', {bubbles: true}));
        moved.push(`${selectId} → ${value}`);
    };
    follow('reachFrameSelect', String(resolved.ikFrame || '').replace(/^[RL]_/, ''), 'genIkFrame');
    follow('poleStateSelect', resolved.poleState, 'genPoleState');
    if (moved.length) renderHandStates();
    return moved;
}

function genStartCheckSentence(d) {
    const parts = [];
    let bad = false;
    const s = d.start;
    if (s) {
        const failed = (s.checks || []).filter(c => !c.ok);
        if (failed.length) {
            bad = true;
            parts.push(`start REFUSED — ${failed.map(c => `${c.guard}: ${c.detail}`).join('; ')}`);
        } else {
            parts.push(`start usable — every start guard passes for ${d.resolved.ikFrame} at ${d.resolved.poleState}`);
        }
    }
    const pre = d.preStart || {};
    if (pre.clear === false) {
        bad = true;
        parts.push(`${pre.source === 'placed' ? 'placed pre-start REFUSED' : 'no clear pre-start'}: ${pre.note}`);
    } else if (pre.source === 'placed') {
        parts.push(pre.clear ? 'placed pre-start clear — used exactly where placed' : `placed pre-start: ${pre.note}`);
    } else if (s) {
        parts.push(`pre-start derived: ${pre.note || 'retreat along the press normal'}`);
    }
    parts.push('the leg to knot 0 and the branch family are decided by the run');
    return {text: parts.join('; '), bad};
}

function genRenderStartCheck(d) {
    const el = document.getElementById('genStartPoseInfo');
    if (!el || !d) return;
    const r = d.resolved || {};
    const lines = [`verified for           ${r.ikFrame} · ${r.poleState} (${genFmt(r.poleM, 3, 'm')}) · `
                   + `standoff ${genFmt(r.standoffM, 3, 'm')} · ${r.surfaceClass} surface`];
    if (d.start) {
        (d.start.checks || []).forEach(c => lines.push(`${c.ok ? '✓' : '✗'} ${String(c.guard).padEnd(46)} ${c.detail}`));
        lines.push(`  orientation          ${genFmt(d.start.orientationFromNominalDeg, 1, '°')} from the generator's own`
                   + ` (wipe yaw ${genFmt(d.start.wipeYawDeg, 1, '°')})`);
    }
    if (d.preStart) lines.push(`  pre-start            ${d.preStart.source} — ${d.preStart.note || '—'}`);
    (d.decidedByTheRun || []).forEach(t => lines.push(`  decided by the run:  ${t}`));
    el.textContent = lines.join('\n');
}

async function verifyPickedStartPoses() {
    const start = parsePoseField('genStartPose');
    const pre = genPlacedPreStart();
    if (!start && !pre) {
        setStatus('Nothing to verify — pick a start pose (or place a pre-start) first.', true);
        return;
    }
    genSyncPreStart();                    // a linked pre-start follows the CURRENT start
    renderStartPoseTexts();
    buildStartPoseMarker();
    if (start) {
        showArmAtStartPose(refPointToBase(start.slice(0, 3)),
                           quatToArray(refQuatToBase(quatFromArray(start.slice(3, 7)))));
    }
    setStatus('Verifying with the generator’s own start guards…');
    let d;
    try {
        d = await genStartCheck(start, pre);
    } catch (e) {
        if (!e.busy) setStatus(`Verify failed: ${genBriefError(e.message)}`, true);
        return;
    }
    const sentence = genStartCheckSentence(d);
    setStatus(`Verified — ${sentence.text}.`, sentence.bad);
}

// pre_start is DERIVED and linked by default: the generator emitting
// pre_start == start_pose exactly was a real defect, so the link is explicit
// and so is unlinking it.
//
// LINKED means the GENERATOR derives it, so a linked field is BLANK. It used to
// hold `defaultPreStart(start)` — and that function is `start.slice()`, the
// Edit tab's "start from the start pose, then edit" seed — so the "derived"
// pre-start was the start pose exactly: the defect the link exists to prevent,
// shown as "(derived)", verified by IK as if it were a retreat, and sent by the
// legacy request as preStartPose. Blank is honest on all three counts: the text
// names who derives it, Verify says so instead of solving a copy, and a blank
// field is not sent, so the server's derive_pre_start_pose (pre_start.py) runs.
function genSyncPreStart() {
    const linked = genChecked('genPreStartLinked');
    const field = document.getElementById('genPreStartPose');
    if (!field) return;
    field.readOnly = Boolean(linked);
    if (linked) field.value = '';
    positionPickedPoseMarkers();
}

// Unlinking is the start of placing one by hand, so it SEEDS the pre-start at
// the start pose — there is then something for the gizmo to drag back off the
// surface. A pre-start already placed is kept.
// The DERIVED retreat for a start pose, as the seed a placed pre-start starts
// from: the check's own derived pre-start when it was computed for this start,
// else the start backed off 35 mm along the resolved frame's press axis.  It
// used to be `defaultPreStart(start)` — `start.slice()` — so unlinking put the
// pre-start glove exactly on the start glove (Newton, 2026-09-15: the two
// "still merged").
function genDerivedRetreat(start) {
    const check = state.generate.lastStartCheck;
    if (check && check.forStart === start.join(' ') && check.preStart
            && check.preStart.source === 'derived' && Array.isArray(check.preStart.pose7)) {
        return check.preStart.pose7.map(v => Number(v));
    }
    const frame = (check && check.resolved && check.resolved.ikFrame) || genStr('genIkFrame') || ikFrameName();
    const press = contactVec(frame).applyQuaternion(quatFromArray(start.slice(3, 7))).normalize();
    const position = vec(start.slice(0, 3)).sub(press.multiplyScalar(0.035));
    return [...roundVector(arr(position), 4), ...start.slice(3, 7)];
}

function onGenPreStartLinkedChange() {
    const linked = genChecked('genPreStartLinked');
    const field = document.getElementById('genPreStartPose');
    const start = parsePoseField('genStartPose');
    if (!linked && field && !parsePoseField('genPreStartPose') && start) {
        field.value = genDerivedRetreat(start).join(' ');
    }
    genSyncPreStart();
    renderStartPoseTexts();
    buildStartPoseMarker();
    renderScene();
}

// The panel drives ONE generator (Newton, 2026-09-16), so there is no mode to
// apply any more — the legacy-only fields that used to be rendered-and-disabled
// with a reason are gone from the markup instead. What is left is the refresh
// the mode switch used to trigger, which the panel still needs on open and
// after a run.
function genRefreshPanel() {
    genRenderPoleFields();
    // "Auto-generate path" was REMOVED (2026-09-10): it bound to
    // `generateFromServer` with no argument, exactly as Generate does, so the two
    // primaries ran the identical action. The panel could not say what
    // distinguished them because nothing did, and two equal-weight primaries
    // side by side is a choice the operator has to make and cannot.
    genRenderEmptyStates();
    updateGenReadouts();
    renderStartPoseTexts();    // who chooses the pre-start depends on the pipeline
}

// The empty states, each said in words. NEVER a 0 %: a coverable map that has
// not been computed is not a map that found nothing, and the two look identical
// once one of them is rendered as a number.
function genRenderEmptyStates() {
    const bound = Boolean(currentFixture()) && Boolean(document.getElementById('genRegion')?.value);
    // TARGET folds itself away ONCE, the first time a fixture and region are
    // bound. It is ten fields, seven of them `(auto)`, and open it pushes the
    // start pose — the next thing the operator does, and the reason the panel
    // is docked beside a live mesh — off the bottom of the column. Folded, the
    // start pose is the first thing under it. Once only, and a manual toggle
    // afterwards is never fought: a panel that re-closes what you opened is
    // worse than one that never helped.
    const target = document.getElementById('genGroupA');
    if (target && bound && !target.dataset.autoFolded) {
        target.dataset.autoFolded = '1';
        target.open = false;
    }
    if (target && !bound) delete target.dataset.autoFolded;
    ['genGroupB', 'genGroupC', 'genGroupD', 'genGroupE', 'genGroupF'].forEach(id => {
        const group = document.getElementById(id);
        if (group) group.classList.toggle('gen-dimmed', !bound);
    });
    if (state.generate.result) return;
    const coverage = document.getElementById('genCoverageInfo');
    if (coverage && (!coverage.textContent.trim() || coverage.dataset.placeholder === '1')) {
        coverage.dataset.placeholder = '1';
        // A LIVE RUN outranks both empty states. Newton's screenshot had this
        // panel saying "No fixture and region bound yet" with a run eight
        // minutes into its coverable stage — the placeholder describing a
        // condition the running job disproves. A panel contradicting itself is
        // worse than a panel saying nothing.
        const job = (state.generate && state.generate.job) || {};
        if (pathGenJobLive()) {
            const phase = job.phase || job.stage || 'running';
            coverage.textContent = `Running — ${phase}. Coverage is measured when the run finishes; `
                + 'nothing here is a coverage of zero.';
        } else {
            coverage.textContent = bound
                ? 'Coverable map not computed yet — it is the second stage of a run (41-48 s). '
                  + 'Nothing here is a coverage of zero.'
                : 'No fixture and region bound yet. Pick them in TARGET; the rest of the panel is '
                  + 'dimmed until then.';
        }
    }
    const counts = document.getElementById('genCounts');
    if (counts && !state.generate.knots.length) {
        counts.textContent = pathGenJobLive()
            ? 'knots — · samples — (run in progress)'
            : 'knots — · samples — (no run yet)';
    }
}

// ── Wiring ────────────────────────────────────────────────────────────────
function wireGeneratePath() {
    // what the task will use is what the viewport shows
    bind('genApplyKnotsButton', 'click', applyKnotEdits);
    bind('genPoleState', 'change', genRenderPoleFields);
    bind('genPoleM', 'input', genRenderPoleFields);
    ['genIkFrame', 'genPoleState'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.addEventListener('change', () => syncViewerToTask());
    });
    bind('cancelPathButton', 'click', cancelAutoPathJob);
    bind('placeStartPoseButton', 'click', placePickedStartPose);
    bind('genPreStartLinked', 'change', onGenPreStartLinkedChange);
    bind('genStartPose', 'change', genSyncPreStart);
    ['genStrokePasses', 'genStrokeConnection', 'genCleaningAction', 'genChannel',
     'genRowPitch', 'genCollinearDeg', 'genReversalDeg', 'genBlendRadius',
     'genMaxOffset', 'genSampleDs', 'genPsiPolicy'].forEach(id => bind(id, 'input', event => {
        if (event.target) event.target.dataset.touched = '1';
        state.generate.stale = Boolean(state.generate.result);
        updateGenReadouts();
    }));
    genRefreshPanel();
    genSyncPreStart();
}

// The named module surface. Everything the rest of the file calls is a bare
// global (this file's convention); this is the boundary a reader can grep for.
window.PathGen = {
    stages: PATHGEN_STAGES,
    etaSecondsRange: PATHGEN_ETA_RANGE_S,
    requestBody: autoPathRequestBody,
    run: runAutoPathJob,
    cancel: cancelAutoPathJob,
    jobLive: pathGenJobLive,
    hasKnots: pathGenHasKnots,
    apply: applyAutoPathResult,
    readouts: updateGenReadouts,
    selectKnot,
    state: pathGenState,
};


// Surface any uncaught error (e.g. thrown inside a button handler) to the status
// bar so failures are visible instead of silently dead controls.
window.addEventListener('error', event => {
    console.error('[ALIX Studio] uncaught:', event.error || event.message);
    try { setStatus(`Error: ${event.message} (see console)`, true); } catch (_) {}
});
window.addEventListener('unhandledrejection', event => {
    console.error('[ALIX Studio] unhandled promise rejection:', event.reason);
    // Same treatment as 'error' above. Nearly every failure in this app is
    // async — a fetch, a mesh load, a generate — so the handler that said
    // nothing was the one covering the common case: the spinner stayed up and
    // the status bar still read whatever was true before the request.
    try { setStatus(`Error: ${event.reason?.message || event.reason} (see console)`, true); } catch (_) {}
    try { setLoading(false); } catch (_) {}
});

// Resilient bootstrap: each step is isolated so a failure in one (e.g. WebGL /
// three.js init) can't cascade and leave the ribbon + buttons unwired. The
// failing step is logged to the console and shown in the status bar.
const bootFailures = runSteps([
    ['initThree', initThree],
    ['initViewCube', initViewCube],
    ['initUi', initUi],
    ['initTabs', initTabs],
    ['initSpacePathControls', initSpacePathControls],
    ['updateAll', updateAll],
    ['updateIkPanel', updateIkPanel],
    ['switchTab', () => switchTab(state.activeTab)],   // apply the default (Regions) tab's mode coupling
    ['initStudioServer', initStudioServer],
], 'init');
if (bootFailures.length) {
    try { setStatus(`Init error in ${bootFailures.join(', ')} (see console)`, true); } catch (_) {}
}


// ─────────────────────────────────────────────────────────────────────────────
// Simulate view — live emulated robot in the shared viewport
//
// Every pose the Studio has ever drawn goes through applyRobotPose({link: 4x4}),
// already fed by four independent producers (IK preview, sequence animation,
// plan replay, dual-arm collision playback). Live simulation is a fifth
// producer and nothing more: no new rendering path, no second notion of where
// the robot is.
//
// Polling rather than WebSockets is deliberate. The server is a stdlib
// ThreadingHTTPServer with no dependencies, and the whole tool is vendored to
// work offline; adding a socket layer for a 5 Hz readout would trade that for
// nothing. If this ever needs to be smooth, SSE is the next step and stays
// stdlib-compatible.
// ─────────────────────────────────────────────────────────────────────────────

const simState = { timer: null, live: false, lastError: null };

function setView(view) {
    document.body.dataset.view = view;
    document.querySelectorAll('.view-btn').forEach((b) => {
        const on = b.dataset.view === view;
        b.classList.toggle('active', on);
        b.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    // Leaving Simulate stops the poll: a hidden view must not keep issuing
    // requests, and coming back should start from a fresh reading.
    if (view !== 'simulate') simStopLive();
    else simRefreshStatus();
    if (typeof onResize === 'function') onResize();
}

function simSetDot(state, label, hint) {
    const dot = document.getElementById('simDot');
    if (dot) dot.dataset.state = state;
    const s = document.getElementById('simState');
    if (s) s.textContent = label;
    const h = document.getElementById('simHint');
    if (h) h.textContent = hint || '';
}

async function simRefreshStatus() {
    try {
        const res = await fetch('/api/sim/status');
        const data = await res.json();
        if (!data.running && !(data.external && data.external.present)) {
            simSetDot('off', 'Emulator not running',
                      'Run an emulated task, or POST /api/sim/joints.');
            simRenderReadout(null);
            return false;
        }
        const arms = (data.arms || []).map((a) => a.side).join(' + ') || 'external';
        simSetDot(simState.live ? 'live' : 'ready',
                  simState.live ? `Live — ${arms}` : `Ready — ${arms}`,
                  simState.live ? '' : 'Press Go live to follow the emulator.');
        simRenderReadout(data);
        return true;
    } catch (err) {
        simSetDot('off', 'Studio server unreachable', String(err));
        return false;
    }
}

function simRenderReadout(data) {
    const el = document.getElementById('simReadout');
    if (!el) return;
    if (!data || !data.arms || !data.arms.length) { el.innerHTML = ''; return; }
    el.innerHTML = data.arms.map((a) => {
        const j = (a.joints_deg || []).map((v) => v.toFixed(1)).join(', ');
        return `<span><b>${a.side}</b> [${j}] lift <b>${a.lift_hw_mm}</b> mm</span>`;
    }).join('');
}

async function simTick() {
    const source = (document.getElementById('simSource') || {}).value || 'auto';
    try {
        const res = await fetch('/api/sim/pose', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            // No `config` key: the server resolves its own default workspace
            // config. Inventing one here would silently diverge from the
            // config every other endpoint uses.
            body: JSON.stringify({ source }),
        });
        const data = await res.json();
        if (data.error) {
            // Report once, then keep polling: the usual cause is "nothing has
            // connected yet", which resolves on its own.
            if (simState.lastError !== data.error) {
                simState.lastError = data.error;
                simSetDot('off', 'No simulation source', data.error);
            }
            return;
        }
        simState.lastError = null;
        if (data.pose && typeof applyRobotPose === 'function') applyRobotPose(data.pose);
        simRefreshStatus();
    } catch (err) {
        simSetDot('off', 'Studio server unreachable', String(err));
    }
}

function simStartLive() {
    simStopLive();
    const rate = parseInt((document.getElementById('simRate') || {}).value || '200', 10);
    simState.live = true;
    const btn = document.getElementById('simLive');
    if (btn) { btn.textContent = 'Stop'; btn.classList.add('danger'); }
    simTick();
    if (rate > 0) simState.timer = setInterval(simTick, rate);
}

function simStopLive() {
    if (simState.timer) { clearInterval(simState.timer); simState.timer = null; }
    simState.live = false;
    const btn = document.getElementById('simLive');
    if (btn) { btn.textContent = 'Go live'; btn.classList.remove('danger'); }
}

function initSimulateView() {
    document.querySelectorAll('.view-btn').forEach((b) => {
        b.addEventListener('click', () => setView(b.dataset.view));
    });
    const live = document.getElementById('simLive');
    if (live) live.addEventListener('click', () => (simState.live ? simStopLive() : simStartLive()));
    const once = document.getElementById('simOnce');
    if (once) once.addEventListener('click', simTick);
    const rate = document.getElementById('simRate');
    if (rate) rate.addEventListener('change', () => { if (simState.live) simStartLive(); });
    setView('author');
}

// Bootstrapped separately from the list above: `simState` is a `const` declared
// in this block, so it is in the temporal dead zone while that list executes.
// Same isolation, so a failure here cannot unwire the rest of the UI.
try {
    initSimulateView();
} catch (error) {
    console.error('[ALIX Studio] init step "initSimulateView" failed:', error);
}
